window.CDAL_EXAMPLES=[{"category":"Cookbook Recipes","description":"Saves exact XYZ (plus optional time/weather) to disk and CoSave, guards map fast-travel via e.follows_save, and hides teleport/terrain streaming behind a FastLoad-safe bsx.draw + bsx.tween fade curtain.","featured":true,"files":[{"code":"-- Resume Anywhere: save exact XYZ/world state and restore seamlessly on save loads / restarts.\n-- Covers loading hand-off + terrain streaming hover with a FastLoad-safe fade curtain.\n\nlocal STATE_FILE = \"last_location.json\"\nlocal COSAVE_KEY = \"ra.state\"\n\nlocal auto_save = config.bool(\"ResumeAnywhere\", \"AutoSave\", false)\nlocal auto_resume = config.bool(\"ResumeAnywhere\", \"AutoResume\", true)\nlocal snap_to_ground = config.bool(\"ResumeAnywhere\", \"SnapToGround\", true)\nlocal fade_curtain = config.bool(\"ResumeAnywhere\", \"FadeCurtain\", true)\nlocal restore_time = config.bool(\"ResumeAnywhere\", \"RestoreTime\", false)\nlocal restore_weather = config.bool(\"ResumeAnywhere\", \"RestoreWeather\", false)\nlocal interval_sec = math.max(2, math.min(30, config.int(\"ResumeAnywhere\", \"IntervalSec\", 5)))\n\nlocal world_up = false\nlocal load_gen = 0\nlocal last_poll_clock = 0.0\nlocal last_ui_clock = 0.0\nlocal last_saved = nil\nlocal last_source = \"none\"\n\nlocal curtain_state = \"off\" -- \"off\" | \"loading\" | \"settling\" | \"fading\"\nlocal curtain_alpha = 0\nlocal curtain_tween = nil\nlocal curtain_started = 0.0\nlocal curtain_label = \"Resuming saved location...\"\nlocal settle_start = 0.0\nlocal settle_min = 0.9\nlocal settle_max = 5.8\nlocal settle_target = nil\nlocal stable_since = nil\nlocal last_y = nil\n\nlocal panel = bsx.ui and bsx.ui.panel(\"Resume Anywhere\") or nil\nlocal status_id, cur_lbl_id, saved_lbl_id\n\nlocal function set_status(msg)\n    if panel and status_id then\n        panel:set_text(status_id, tostring(msg):sub(1, 120))\n    end\nend\n\nlocal function is_finite(v)\n    return type(v) == \"number\" and v == v and math.abs(v) \u003c math.huge\nend\n\nlocal function dist3(a, b)\n    if not a or not b then return math.huge end\n    local dx = (a.x or 0) - (b.x or 0)\n    local dy = (a.y or 0) - (b.y or 0)\n    local dz = (a.z or 0) - (b.z or 0)\n    return math.sqrt(dx * dx + dy * dy + dz * dz)\nend\n\nlocal function toast(msg, level)\n    if bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(tostring(msg):sub(1, 120), { level = level or \"info\", duration_ms = 2400 })\n    end\nend\n\nlocal function persist_cfg(key, value)\n    config.set(\"ResumeAnywhere\", key, value)\n    pcall(config.save)\nend\n\nlocal function draw_curtain(alpha, subtitle)\n    if not bsx.draw then return end\n    local a = math.max(0, math.min(255, math.floor((alpha or 0) + 0.5)))\n    if a \u003c= 0 then\n        pcall(bsx.draw.clear)\n        return\n    end\n    local bg = string.format(\"#0D1015%02X\", a)\n    local fg = string.format(\"#E8EAED%02X\", a)\n    pcall(bsx.draw.clear)\n    pcall(bsx.draw.rect, 0, 0, 7680, 4320, bg, true)\n    if subtitle and subtitle ~= \"\" then\n        pcall(bsx.draw.text, 48, 48, subtitle, fg, 1.3)\n    end\nend\n\nlocal function clear_curtain()\n    if curtain_tween then\n        pcall(function() curtain_tween:off() end)\n        curtain_tween = nil\n    end\n    curtain_state = \"off\"\n    curtain_alpha = 0\n    if bsx.draw then pcall(bsx.draw.clear) end\nend\n\nlocal function start_loading_curtain(subtitle)\n    if not fade_curtain or not bsx.draw then return end\n    if curtain_tween then\n        pcall(function() curtain_tween:off() end)\n        curtain_tween = nil\n    end\n    curtain_state = \"loading\"\n    curtain_alpha = 255\n    curtain_started = os.clock()\n    curtain_label = subtitle or \"Resuming saved location...\"\n    draw_curtain(255, curtain_label)\nend\n\nlocal function fade_out_curtain(dur)\n    if curtain_state == \"off\" then return end\n    if not bsx.tween or not bsx.draw or curtain_alpha \u003c= 4 then\n        clear_curtain()\n        return\n    end\n    if curtain_tween then\n        pcall(function() curtain_tween:off() end)\n        curtain_tween = nil\n    end\n    curtain_state = \"fading\"\n    local h = bsx.tween.to(curtain_alpha, 0, dur or 0.5, {\n        ease = \"out_cubic\",\n        on_update = function(val)\n            if curtain_state ~= \"fading\" then return end\n            curtain_alpha = val\n            draw_curtain(val, \"\")\n        end,\n        on_done = function()\n            if curtain_state == \"fading\" then\n                clear_curtain()\n            end\n        end,\n    })\n    if h then\n        curtain_tween = h\n    else\n        clear_curtain()\n    end\nend\n\nlocal function decode_state(raw)\n    if type(raw) ~= \"string\" or raw == \"\" then return nil end\n    local obj = bsx.json.decode(raw)\n    if type(obj) ~= \"table\" then return nil end\n    if not is_finite(obj.x) or not is_finite(obj.y) or not is_finite(obj.z) then return nil end\n    return obj\nend\n\nlocal function update_coord_labels(pos)\n    if not panel then return end\n    if cur_lbl_id then\n        if pos then\n            panel:set_text(cur_lbl_id, string.format(\"Current: (%.1f, %.1f, %.1f)\", pos.x, pos.y, pos.z))\n        else\n            panel:set_text(cur_lbl_id, \"Current: waiting for world...\")\n        end\n    end\n    if saved_lbl_id then\n        if last_saved then\n            local d_str = \"\"\n            if pos then\n                d_str = string.format(\" | dist=%.1fm\", dist3(pos, last_saved))\n            end\n            panel:set_text(saved_lbl_id, string.format(\"Saved [%s]: (%.1f, %.1f, %.1f)%s\",\n                last_source, last_saved.x, last_saved.y, last_saved.z, d_str))\n        else\n            panel:set_text(saved_lbl_id, \"Saved: none yet\")\n        end\n    end\nend\n\nlocal function load_saved()\n    local cs, df = nil, nil\n    if bsx.save and bsx.save.get then\n        local ok_c, cosave_raw = pcall(bsx.save.get, COSAVE_KEY)\n        if ok_c then cs = decode_state(cosave_raw) end\n    end\n    if bsx.fs and bsx.fs.exists(STATE_FILE) then\n        local ok_f, file_raw = pcall(bsx.fs.read, STATE_FILE)\n        if ok_f then df = decode_state(file_raw) end\n    end\n\n    if cs and df then\n        local ts_cs = tonumber(cs.ts) or 0\n        local ts_df = tonumber(df.ts) or 0\n        if ts_cs > ts_df then\n            last_saved = cs\n            last_source = \"CoSave\"\n            return cs, \"CoSave\"\n        else\n            last_saved = df\n            last_source = \"Disk\"\n            return df, \"Disk\"\n        end\n    elseif df then\n        last_saved = df\n        last_source = \"Disk\"\n        return df, \"Disk\"\n    elseif cs then\n        last_saved = cs\n        last_source = \"CoSave\"\n        return cs, \"CoSave\"\n    end\n    return nil, \"none\"\nend\n\nlocal function build_weather_override(w)\n    if type(w) ~= \"table\" then return nil end\n    local out = {}\n    if is_finite(w.rain_base) then out.rain = w.rain_base end\n    if is_finite(w.snow_base) then out.snow = w.snow_base end\n    if is_finite(w.precipitation) then out.precipitation = w.precipitation end\n    if is_finite(w.humidity) then out.humidity = w.humidity end\n    if is_finite(w.cloudiness) then out.cloudiness = w.cloudiness end\n    if is_finite(w.wind_direction) then out.wind_direction = w.wind_direction end\n    if is_finite(w.wind_speed) then out.wind_speed = w.wind_speed end\n    return out\nend\n\nlocal function save_now(manual)\n    local pos, p_err = game.player_position()\n    if not pos or not is_finite(pos.x) or not is_finite(pos.y) or not is_finite(pos.z) then\n        if manual then\n            local msg = \"Position unavailable: \" .. tostring(p_err)\n            set_status(msg)\n            toast(msg, \"warn\")\n        end\n        return false\n    end\n\n    local ps = game.player_state and game.player_state() or nil\n    if not manual and ps and (not ps.world_ready or ps.dead or ps.in_cutscene or ps.in_movie) then\n        return false\n    end\n    if not manual and last_saved and dist3(pos, last_saved) \u003c 2.0 then\n        return true\n    end\n\n    local snap = {\n        x = pos.x,\n        y = pos.y,\n        z = pos.z,\n        yaw_deg = is_finite(pos.yaw_deg) and pos.yaw_deg or nil,\n        ts = os.time(),\n    }\n    local tm = game.time and game.time() or nil\n    if tm and is_finite(tm.hour) then\n        snap.hour = tm.hour\n        snap.minute = tm.minute or 0\n        snap.second = tm.second or 0\n    end\n    local w = game.weather and game.weather() or nil\n    local wo = build_weather_override(w)\n    if wo then\n        snap.weather = wo\n    end\n\n    local payload, enc_err = bsx.json.encode(snap)\n    if not payload then\n        if manual then\n            set_status(\"Encode failed: \" .. tostring(enc_err))\n        end\n        return false\n    end\n\n    local wrote_disk = false\n    if bsx.fs and bsx.fs.write then\n        local ok_fs, fs_res = pcall(bsx.fs.write, STATE_FILE, payload)\n        wrote_disk = ok_fs and fs_res == true\n    end\n    local wrote_cosave = false\n    if bsx.save and bsx.save.set then\n        local ok_cs, cs_res = pcall(bsx.save.set, COSAVE_KEY, payload)\n        wrote_cosave = ok_cs and cs_res == true\n    end\n\n    last_saved = snap\n    last_source = wrote_cosave and \"CoSave+Disk\" or (wrote_disk and \"Disk\" or \"Memory\")\n    update_coord_labels(pos)\n\n    if manual then\n        local msg = string.format(\"Saved (%s): %.1f, %.1f, %.1f\", last_source, snap.x, snap.y, snap.z)\n        set_status(msg)\n        toast(msg, \"ok\")\n        bsx.log(\"RESUME_ANYWHERE_SAVED \" .. msg)\n    else\n        set_status(string.format(\"Auto-tracked (%s) at %.1f, %.1f, %.1f\", last_source, snap.x, snap.y, snap.z))\n    end\n    return true\nend\n\n-- Returns: \"ok\", use_snap, saved  |  \"skip\", false, why  |  \"retry\", false, err\nlocal function restore_now(from_load)\n    local saved, src = load_saved()\n    if not saved then\n        if not from_load then\n            set_status(\"No saved coordinates yet (press Ctrl+F6 first)\")\n            toast(\"No saved coordinates yet\", \"warn\")\n        end\n        return \"skip\", false, \"no saved spot\"\n    end\n\n    local pos = game.player_position()\n    if from_load then\n        local cut = game.in_cutscene and game.in_cutscene()\n        if cut then\n            set_status(\"Auto-resume skipped (cutscene active)\")\n            return \"skip\", false, \"cutscene\"\n        end\n        local ps = game.player_state and game.player_state() or nil\n        if ps and (ps.dead or ps.in_cutscene or ps.in_movie) then\n            set_status(\"Auto-resume skipped (player dead or in cutscene)\")\n            return \"skip\", false, \"dead or movie\"\n        end\n        if pos and dist3(pos, saved) \u003c 5.0 then\n            set_status(\"Already within 5m of saved spot (\" .. src .. \")\")\n            return \"skip\", false, \"already there\"\n        end\n    end\n\n    local hdist = math.huge\n    if pos and is_finite(pos.x) and is_finite(pos.z) then\n        local dx = pos.x - saved.x\n        local dz = pos.z - saved.z\n        hdist = math.sqrt(dx * dx + dz * dz)\n    end\n    local use_snap = snap_to_ground and ((not pos) or (hdist > 120.0))\n    local target_y = use_snap and saved.y or (saved.y + 0.15)\n\n    local ok, err = game.world.teleport(saved.x, target_y, saved.z, saved.yaw_deg, use_snap)\n    if not ok then\n        local msg = \"Teleport blocked: \" .. tostring(err)\n        set_status(msg)\n        if not from_load then toast(msg, \"fail\") end\n        bsx.log(\"Resume Anywhere: \" .. msg)\n        return \"retry\", use_snap, msg\n    end\n\n    if restore_time and is_finite(saved.hour) then\n        pcall(game.world.set_time, saved.hour, saved.minute or 0, saved.second or 0, true)\n    end\n    if restore_weather and type(saved.weather) == \"table\" then\n        pcall(game.world.set_weather, saved.weather)\n    end\n\n    local msg = string.format(\"Resumed (%s, snap=%s) -> (%.1f, %.1f, %.1f)\",\n        src, tostring(use_snap), saved.x, target_y, saved.z)\n    set_status(msg)\n    if not from_load or not fade_curtain then\n        toast(msg, \"ok\")\n    end\n    bsx.log(string.format(\"RESUME_ANYWHERE_RESTORED source=%s snap=%s xyz=(%.2f, %.2f, %.2f)\",\n        src, tostring(use_snap), saved.x, target_y, saved.z))\n    return \"ok\", use_snap, saved\nend\n\nlocal function begin_settle(use_snap, saved)\n    if not fade_curtain or not bsx.draw then return end\n    curtain_state = \"settling\"\n    curtain_alpha = 255\n    curtain_label = \"Settling terrain at saved spot...\"\n    settle_start = os.clock()\n    settle_min = use_snap and 1.6 or 0.9\n    settle_max = use_snap and 5.8 or 2.8\n    settle_target = saved\n    stable_since = nil\n    last_y = nil\n    draw_curtain(255, curtain_label)\nend\n\nlocal function clear_saved()\n    last_saved = nil\n    last_source = \"none\"\n    clear_curtain()\n    if bsx.fs and bsx.fs.exists(STATE_FILE) then\n        pcall(bsx.fs.delete, STATE_FILE)\n    end\n    if bsx.save and bsx.save.set then\n        pcall(bsx.save.set, COSAVE_KEY, \"\")\n    end\n    update_coord_labels(game.player_position())\n    set_status(\"Cleared saved coordinates\")\n    toast(\"Cleared saved location\", \"info\")\nend\n\nif panel then\n    panel:set_theme({ accent = \"#D7263D\", child_bg = \"#141318\" })\n    status_id = panel:text(\"Waiting for world_ready...\")\n    cur_lbl_id = panel:text(\"Current: waiting for world...\")\n    saved_lbl_id = panel:text(\"Saved: none yet\")\n    panel:separator()\n    panel:button(\"Save Now (Ctrl+F6)\", function() save_now(true) end)\n    panel:same_line()\n    panel:button(\"Teleport Now (Ctrl+F7)\", function() restore_now(false) end)\n    panel:same_line()\n    panel:button(\"Clear Saved\", clear_saved)\n    panel:separator()\n    panel:checkbox(\"Auto-track position on interval (overwrites saved spot)\", auto_save, function(v)\n        auto_save = (v == true)\n        persist_cfg(\"AutoSave\", auto_save)\n    end)\n    panel:checkbox(\"Auto-resume on save load / restart only\", auto_resume, function(v)\n        auto_resume = (v == true)\n        persist_cfg(\"AutoResume\", auto_resume)\n    end)\n    panel:checkbox(\"Seamless fade curtain while resuming\", fade_curtain, function(v)\n        fade_curtain = (v == true)\n        persist_cfg(\"FadeCurtain\", fade_curtain)\n        if not fade_curtain then clear_curtain() end\n    end)\n    panel:checkbox(\"Terrain snap on far jumps (>120m)\", snap_to_ground, function(v)\n        snap_to_ground = (v == true)\n        persist_cfg(\"SnapToGround\", snap_to_ground)\n    end)\n    panel:checkbox(\"Also restore saved time of day\", restore_time, function(v)\n        restore_time = (v == true)\n        persist_cfg(\"RestoreTime\", restore_time)\n    end)\n    panel:checkbox(\"Also restore saved weather\", restore_weather, function(v)\n        restore_weather = (v == true)\n        persist_cfg(\"RestoreWeather\", restore_weather)\n    end)\n    panel:slider(\"Auto-track interval (seconds)\", 2, 30, interval_sec, function(v)\n        interval_sec = math.floor(v)\n        persist_cfg(\"IntervalSec\", interval_sec)\n    end)\nend\n\npcall(bsx.hotkey, \"Ctrl+F6\", function() save_now(true) end)\npcall(bsx.hotkey, \"Ctrl+F7\", function() restore_now(false) end)\n\nbsx.on(\"save_load\", function()\n    if auto_resume and fade_curtain and load_saved() then\n        start_loading_curtain(\"Resuming saved location...\")\n    end\nend)\n\nbsx.on(\"save_loaded\", function()\n    if auto_resume and fade_curtain and curtain_state == \"off\" and load_saved() then\n        start_loading_curtain(\"Resuming saved location...\")\n    end\n    update_coord_labels(game.player_position())\nend)\n\nbsx.on(\"world_ready\", function(e)\n    world_up = true\n    load_gen = load_gen + 1\n    local my_gen = load_gen\n    last_poll_clock = os.clock()\n    local is_save_load = (type(e) == \"table\" and e.follows_save == true)\n    bsx.log(string.format(\"RESUME_ANYWHERE_WORLD_READY gen=%s follows_save=%s\",\n        tostring(e and e.generation), tostring(is_save_load)))\n\n    load_saved()\n    update_coord_labels(game.player_position())\n    if not is_save_load then\n        clear_curtain()\n        set_status(\"Fast-travel/zone load (auto-resume skipped)\")\n        return\n    end\n\n    if not auto_resume then\n        fade_out_curtain(0.3)\n        return\n    end\n\n    local status, use_snap, saved_or_why = restore_now(true)\n    if status == \"ok\" then\n        begin_settle(use_snap, saved_or_why)\n    elseif status == \"retry\" then\n        if fade_curtain and curtain_state == \"off\" then\n            start_loading_curtain(\"Resuming saved location...\")\n        end\n        bsx.after(300, function()\n            if not world_up or load_gen ~= my_gen then return end\n            local st2, snap2, arg2 = restore_now(true)\n            if st2 == \"ok\" then\n                begin_settle(snap2, arg2)\n            else\n                fade_out_curtain(0.3)\n            end\n        end)\n    else\n        fade_out_curtain(0.3)\n    end\nend)\n\nbsx.on(\"title_screen\", function()\n    world_up = false\n    clear_curtain()\n    set_status(\"At title screen\")\nend)\n\nbsx.on(\"frame\", function()\n    local now = os.clock()\n    if curtain_state == \"loading\" then\n        draw_curtain(curtain_alpha, curtain_label)\n        if now - curtain_started >= 25.0 then\n            bsx.log(\"Resume Anywhere: loading curtain failsafe timeout\")\n            fade_out_curtain(0.4)\n        end\n    elseif curtain_state == \"settling\" then\n        draw_curtain(curtain_alpha, curtain_label)\n        local elapsed = now - settle_start\n        local pos = game.player_position()\n        local settled = false\n        if pos and settle_target and is_finite(pos.y) then\n            local dx = pos.x - settle_target.x\n            local dz = pos.z - settle_target.z\n            local near_xz = (dx * dx + dz * dz) \u003c (15.0 * 15.0)\n            if near_xz and last_y and math.abs(pos.y - last_y) \u003c 0.08 then\n                stable_since = stable_since or now\n                if elapsed >= settle_min and (now - stable_since) >= 0.65 then\n                    settled = true\n                end\n            else\n                stable_since = nil\n            end\n            last_y = pos.y\n        end\n        if settled or elapsed >= settle_max then\n            toast(\"Resumed saved location\", \"ok\")\n            fade_out_curtain(0.5)\n        end\n    end\n\n    if not world_up then return end\n    if now - last_ui_clock >= 0.5 then\n        last_ui_clock = now\n        update_coord_labels(game.player_position())\n    end\n    if auto_save and (now - last_poll_clock >= interval_sec) then\n        last_poll_clock = now\n        save_now(false)\n    end\nend)\n\nload_saved()\nupdate_coord_labels(nil)\nbsx.log(\"RESUME_ANYWHERE_LOADED auto_save=\" .. tostring(auto_save) .. \" auto_resume=\" .. tostring(auto_resume))\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Resume Anywhere\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 5,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"world\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"},{"code":"[ResumeAnywhere]\nAutoSave=false\nAutoResume=true\nSnapToGround=true\nFadeCurtain=true\nRestoreTime=false\nRestoreWeather=false\nIntervalSec=5\n","lang":"ini","name":"settings.ini"}],"id":"recipe_resume_anywhere","kind":"lua","lua_api":5,"path":"bsx/lua/cookbook/resume_anywhere","tier":"changes","title":"Recipe: Resume Anywhere (Save Location & Auto-Teleport)","uses":["ui","player","snapshots","positions","world","server_commands"]},{"category":"Cookbook Recipes","description":"Zero-address Safe Lua mod that trims cold pages cleanly after loads (world_ready), on title screen, after Alt-Tab idle, or above a configurable RAM threshold out of combat, with a live F10 RAM meter and Ctrl+F8 manual trigger.","featured":true,"files":[{"code":"-- Smart Memory Trim (Safe-tier, Lua API 7+, zero game addresses)\n-- Trims cold pages asynchronously off the FRAME thread at low-impact moments:\n-- load completion (world_ready), title screen entry, Alt-Tab idle, or out-of-combat high RAM.\n\nlocal SECTION = \"SmartMemoryTrim\"\n\nlocal enabled = config.bool(SECTION, \"Enabled\", true)\nlocal trim_world_ready = config.bool(SECTION, \"TrimOnWorldReady\", true)\nlocal trim_title = config.bool(SECTION, \"TrimOnTitleScreen\", true)\nlocal trim_alt_tab = config.bool(SECTION, \"TrimOnAltTab\", true)\nlocal alt_tab_delay = math.max(5, math.min(120, config.int(SECTION, \"AltTabDelaySec\", 15)))\nlocal auto_threshold = config.bool(SECTION, \"AutoThresholdTrim\", true)\nlocal threshold_mb = math.max(2048, math.min(32768, config.int(SECTION, \"ThresholdMB\", 8192)))\nlocal auto_cooldown = math.max(60, math.min(1800, config.int(SECTION, \"AutoCooldownSec\", 300)))\nlocal show_toast = config.bool(SECTION, \"ShowToast\", true)\n\nlocal last_auto_trim_clock = -9999.0\nlocal unfocused_since = nil\nlocal alt_tab_trimmed = false\nlocal title_trimmed = false\nlocal total_freed_mb = 0.0\nlocal trim_count = 0\nlocal last_seen_seq = 0\nlocal last_summary = \"No trims run yet\"\nlocal pending_trim = nil\n\nlocal panel = bsx.ui and bsx.ui.panel(\"Smart Memory Trim\") or nil\nlocal ws_txt_id, ws_bar_id, sys_txt_id, last_txt_id, cd_txt_id\n\nlocal function persist_cfg(key, value)\n    config.set(SECTION, key, value)\n    pcall(config.save)\nend\n\nlocal function notify(msg, level)\n    if show_toast and bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(tostring(msg):sub(1, 150), { level = level or \"info\", duration_ms = 2400 })\n    end\nend\n\nlocal function in_combat_or_cutscene()\n    if type(game) ~= \"table\" or type(game.player_state) ~= \"function\" then\n        return false\n    end\n    local ok, st = pcall(game.player_state)\n    return ok and type(st) == \"table\" and (st.in_battle == true or st.in_cutscene == true)\nend\n\nlocal function refresh_ui(info)\n    if not panel or not bsx.memory then return end\n    info = info or bsx.memory.info()\n    if not info then return end\n\n    if not pending_trim and (info.last_trim_seq or 0) > last_seen_seq then\n        last_seen_seq = info.last_trim_seq\n    end\n\n    local ws = info.working_set_mb or 0\n    local peak = info.peak_working_set_mb or 0\n    local priv = info.private_mb or 0\n    local sys_tot = info.system_total_mb or 0\n    local sys_avail = info.system_avail_mb or 0\n    local sys_pct = info.system_load_pct or 0\n    local rem = info.cooldown_remaining_sec or 0\n    local focus_str = info.window_focused and \"focused\" or \"unfocused\"\n\n    if ws_txt_id then\n        panel:set_text(ws_txt_id, string.format(\"Working Set: %.0f MB  |  Peak: %.0f MB  |  Private: %.0f MB\", ws, peak, priv):sub(1, 120))\n    end\n    if ws_bar_id then\n        local frac = (sys_tot > 0) and math.max(0.0, math.min(1.0, ws / sys_tot)) or 0.0\n        panel:set_value(ws_bar_id, frac)\n        panel:set_text(ws_bar_id, string.format(\"%.0f / %.0f MB (Threshold %d MB)\", ws, sys_tot, threshold_mb):sub(1, 120))\n    end\n    if sys_txt_id then\n        panel:set_text(sys_txt_id, string.format(\"System RAM: %d%% used (%.0f MB free)  |  Window: %s\", sys_pct, sys_avail, focus_str):sub(1, 120))\n    end\n    if last_txt_id then\n        panel:set_text(last_txt_id, string.format(\"Last: %s  |  Total: %.0f MB (%d runs)\", last_summary, total_freed_mb, trim_count):sub(1, 120))\n    end\n    if cd_txt_id then\n        if info.trim_in_progress then\n            panel:set_text(cd_txt_id, \"Host cooldown: trimming in background...\")\n        elseif rem > 0.05 then\n            panel:set_text(cd_txt_id, string.format(\"Host cooldown: %.1fs remaining\", rem))\n        else\n            panel:set_text(cd_txt_id, \"Host cooldown: ready\")\n        end\n    end\nend\n\nlocal function poll_pending_trim()\n    if not pending_trim or not bsx.memory then return end\n    local info = bsx.memory.info()\n    if info and (info.last_trim_seq or 0) > pending_trim.seen_seq and not info.trim_in_progress then\n        last_seen_seq = info.last_trim_seq\n        local b = info.last_trim_before_mb or pending_trim.before_mb or 0\n        local a = info.last_trim_after_mb or b\n        local freed = info.last_trim_freed_mb or math.max(0, b - a)\n        trim_count = trim_count + 1\n        total_freed_mb = total_freed_mb + freed\n        last_auto_trim_clock = os.clock()\n        last_summary = string.format(\"[%s] %.0f -> %.0f MB (-%.0f MB)\", pending_trim.cause, b, a, freed)\n        bsx.log(last_summary)\n        if pending_trim.manual or pending_trim.cause ~= \"title_screen\" then\n            notify(string.format(\"RAM trimmed (%s): -%.0f MB (now %.0f MB)\", pending_trim.cause, freed, a), \"ok\")\n        end\n        pending_trim = nil\n        refresh_ui(info)\n        return\n    end\n\n    pending_trim.polls = pending_trim.polls + 1\n    if pending_trim.polls \u003c 40 then\n        bsx.after(200, poll_pending_trim)\n    else\n        last_summary = string.format(\"[%s] background trim timed out\", pending_trim.cause)\n        pending_trim = nil\n        refresh_ui(info)\n    end\nend\n\nlocal function do_trim(cause, manual)\n    if not bsx.memory then return false end\n    if pending_trim ~= nil then\n        if manual then notify(\"Memory trim already running...\", \"warn\") end\n        return false\n    end\n\n    local pre = bsx.memory.info()\n    if pre then\n        last_seen_seq = math.max(last_seen_seq, pre.last_trim_seq or 0)\n    end\n\n    local res, err = bsx.memory.trim()\n    if not res then\n        if manual then\n            notify(\"Memory trim skipped: \" .. tostring(err or \"cooldown\"), \"warn\")\n        end\n        if trim_count == 0 then\n            last_summary = string.format(\"%s skipped (%s)\", cause, tostring(err or \"unavailable\"))\n        end\n        refresh_ui()\n        return false\n    end\n\n    pending_trim = {\n        cause = cause,\n        manual = manual == true,\n        seen_seq = last_seen_seq,\n        polls = 0,\n        before_mb = res.before_mb or 0,\n    }\n    last_summary = string.format(\"[%s] trimming from %.0f MB...\", cause, res.before_mb or 0)\n    refresh_ui()\n    bsx.after(200, poll_pending_trim)\n    return true\nend\n\nif panel then\n    ws_txt_id = panel:text(\"Working Set: reading...\")\n    ws_bar_id = panel:progress(0, \"Reading memory...\")\n    sys_txt_id = panel:text(\"System RAM: reading...\")\n    last_txt_id = panel:text(\"Last: none\")\n    cd_txt_id = panel:text(\"Host cooldown: ready\")\n    panel:button(\"Trim RAM Now (Ctrl+F8)\", function()\n        do_trim(\"manual\", true)\n    end)\n    panel:separator()\n\n    panel:checkbox(\"Enable auto memory trimming\", enabled, function(v)\n        enabled = v\n        persist_cfg(\"Enabled\", v)\n    end)\n    panel:checkbox(\"Trim after load / fast travel (world_ready)\", trim_world_ready, function(v)\n        trim_world_ready = v\n        persist_cfg(\"TrimOnWorldReady\", v)\n    end)\n    panel:checkbox(\"Trim once on title screen\", trim_title, function(v)\n        trim_title = v\n        persist_cfg(\"TrimOnTitleScreen\", v)\n    end)\n    panel:checkbox(\"Trim when Alt-Tabbed / unfocused\", trim_alt_tab, function(v)\n        trim_alt_tab = v\n        persist_cfg(\"TrimOnAltTab\", v)\n    end)\n    panel:slider(\"Alt-Tab idle delay (sec)\", 5, 120, alt_tab_delay, function(v)\n        alt_tab_delay = math.floor(v + 0.5)\n        persist_cfg(\"AltTabDelaySec\", alt_tab_delay)\n    end)\n    panel:checkbox(\"Auto-trim above high RAM threshold (out of combat)\", auto_threshold, function(v)\n        auto_threshold = v\n        persist_cfg(\"AutoThresholdTrim\", v)\n    end)\n    panel:slider(\"High RAM threshold (MB)\", 2048, 32768, threshold_mb, function(v)\n        threshold_mb = math.floor(v + 0.5)\n        persist_cfg(\"ThresholdMB\", threshold_mb)\n        refresh_ui()\n    end)\n    panel:slider(\"Min auto-trim interval (sec)\", 60, 1800, auto_cooldown, function(v)\n        auto_cooldown = math.floor(v + 0.5)\n        persist_cfg(\"AutoCooldownSec\", auto_cooldown)\n    end)\n    panel:checkbox(\"Show toast notifications\", show_toast, function(v)\n        show_toast = v\n        persist_cfg(\"ShowToast\", v)\n    end)\nend\n\nbsx.on(\"world_ready\", function()\n    title_trimmed = false\n    if not (enabled and trim_world_ready) then return end\n    bsx.after(300, function()\n        if enabled and trim_world_ready then\n            do_trim(\"world_ready\", false)\n        end\n    end)\nend)\n\nbsx.on(\"title_screen\", function()\n    if enabled and trim_title and not title_trimmed then\n        if do_trim(\"title_screen\", false) then\n            title_trimmed = true\n        end\n    end\nend)\n\nlocal ok_hk, hk_err = pcall(bsx.hotkey, \"ctrl+f8\", function()\n    do_trim(\"hotkey\", true)\nend)\nif not ok_hk then\n    bsx.log(\"Smart Memory Trim hotkey Ctrl+F8 unavailable: \" .. tostring(hk_err))\nend\n\nlocal function poll_loop()\n    if not bsx.memory then return end\n    local info = bsx.memory.info()\n    if not info then return end\n\n    local now = os.clock()\n    if info.window_focused then\n        unfocused_since = nil\n        alt_tab_trimmed = false\n    elseif enabled and trim_alt_tab and not alt_tab_trimmed then\n        unfocused_since = unfocused_since or now\n        if (now - unfocused_since) >= alt_tab_delay then\n            if do_trim(\"alt_tab\", false) then\n                alt_tab_trimmed = true\n            end\n        end\n    end\n\n    if enabled and auto_threshold and info.working_set_mb >= threshold_mb then\n        if not info.trim_in_progress and (info.cooldown_remaining_sec or 0) \u003c= 0 and (now - last_auto_trim_clock) >= auto_cooldown then\n            if not in_combat_or_cutscene() then\n                do_trim(\"threshold\", false)\n            end\n        end\n    end\n\n    refresh_ui(info)\nend\n\nrefresh_ui()\nbsx.every(2000, poll_loop)\nbsx.log(\"Smart Memory Trim loaded (Safe tier, async worker, Ctrl+F8 manual trim)\")\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Smart Memory Trim\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7\n}\n","lang":"json","name":"script.json"},{"code":"[SmartMemoryTrim]\nEnabled=true\nTrimOnWorldReady=true\nTrimOnTitleScreen=true\nTrimOnAltTab=true\nAltTabDelaySec=15\nAutoThresholdTrim=true\nThresholdMB=8192\nAutoCooldownSec=300\nShowToast=true\n","lang":"ini","name":"settings.ini"}],"id":"recipe_smart_memory_trim","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/smart_memory_trim","tier":"safe","title":"Recipe: Smart Auto Memory Trimmer (Safe Lua)","uses":[]},{"category":"Cookbook Recipes","description":"Patch-proof native BSX API 3 plugin (zero CDAL IDs) that trims cold working-set pages at world_ready, title_screen, Alt-Tab idle, and high-RAM thresholds behind a 30s cooldown, logging exact before/after MB to BSX/bsx.log.","featured":true,"files":[{"code":"#include \u003cbsx/bsx.h>\n#include \u003cwindows.h>\n#include \u003cpsapi.h>\n#include \u003calgorithm>\n#include \u003catomic>\n#include \u003ccstdio>\n\nstatic const bsx_interface* g_bsx = nullptr;\nstatic std::atomic\u003cULONGLONG> g_last_trim_ms{0};\nstatic ULONGLONG g_unfocused_since_ms = 0;\nstatic bool g_alt_tab_trimmed = false;\n\nstatic constexpr ULONGLONG kCooldownMs = 30000;\nstatic constexpr ULONGLONG kAltTabDelayMs = 15000;\nstatic constexpr ULONGLONG kAutoThresholdIntervalMs = 300000;\nstatic constexpr SIZE_T kThresholdMb = 8192;\n\nstatic bool window_is_focused() {\n    HWND fg = GetForegroundWindow();\n    if (!fg) return false;\n    DWORD pid = 0;\n    GetWindowThreadProcessId(fg, &pid);\n    return pid == GetCurrentProcessId();\n}\n\nstatic bool query_ws_mb(double& out_mb) {\n    PROCESS_MEMORY_COUNTERS_EX pmc{};\n    pmc.cb = sizeof(pmc);\n    if (!K32GetProcessMemoryInfo(GetCurrentProcess(), reinterpret_cast\u003cPROCESS_MEMORY_COUNTERS*>(&pmc), sizeof(pmc))) {\n        return false;\n    }\n    out_mb = static_cast\u003cdouble>(pmc.WorkingSetSize) / (1024.0 * 1024.0);\n    return true;\n}\n\nstatic void trim_now(const char* cause, ULONGLONG min_interval_ms) {\n    const ULONGLONG now = GetTickCount64();\n    const ULONGLONG prev = g_last_trim_ms.load();\n    if (prev != 0 && (now - prev) \u003c std::max(min_interval_ms, kCooldownMs)) return;\n\n    double before_mb = 0.0, after_mb = 0.0;\n    if (!query_ws_mb(before_mb)) return;\n    if (!SetProcessWorkingSetSize(GetCurrentProcess(), static_cast\u003cSIZE_T>(-1), static_cast\u003cSIZE_T>(-1))) return;\n    if (!query_ws_mb(after_mb)) after_mb = before_mb;\n    g_last_trim_ms.store(now);\n\n    char msg[160];\n    std::snprintf(msg, sizeof msg, \"[%s] Working set %.0f -> %.0f MB (released %.0f MB)\",\n                  cause, before_mb, after_mb, std::max(0.0, before_mb - after_mb));\n    g_bsx->log(g_bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void on_world_ready(uint32_t, const void*, void*) { trim_now(\"world_ready\", kCooldownMs); }\nstatic void on_title_screen(uint32_t, const void*, void*) { trim_now(\"title_screen\", kCooldownMs); }\n\nstatic ULONGLONG g_last_poll_ms = 0;\n\nstatic void on_frame(uint32_t, const void*, void*) {\n    const ULONGLONG now = GetTickCount64();\n    if (g_last_poll_ms != 0 && (now - g_last_poll_ms) \u003c 2000) return;\n    g_last_poll_ms = now;\n    if (window_is_focused()) {\n        g_unfocused_since_ms = 0;\n        g_alt_tab_trimmed = false;\n    } else if (!g_alt_tab_trimmed) {\n        if (g_unfocused_since_ms == 0) g_unfocused_since_ms = now;\n        if ((now - g_unfocused_since_ms) >= kAltTabDelayMs) {\n            trim_now(\"alt_tab\", kCooldownMs);\n            g_alt_tab_trimmed = true;\n            return;\n        }\n    }\n\n    double ws_mb = 0.0;\n    if (query_ws_mb(ws_mb) && ws_mb >= static_cast\u003cdouble>(kThresholdMb)) {\n        trim_now(\"threshold\", kAutoThresholdIntervalMs);\n    }\n}\n\nstatic const bsx_plugin_info g_info = {\n    sizeof(bsx_plugin_info), BSX_API_VERSION, \"Smart Memory Trim\", \"1.0.0\", \"CDAL Cookbook\",\n    nullptr, 0, nullptr, nullptr, 0, BSX_API_VERSION\n};\n\nBSX_EXPORT const bsx_plugin_info* bsx_plugin_query(void) { return &g_info; }\n\nBSX_EXPORT int bsx_plugin_load(const bsx_interface* iface) {\n    g_bsx = iface;\n    iface->subscribe(iface->self, BSX_EVENT_WORLD_READY, on_world_ready, nullptr);\n    iface->subscribe(iface->self, BSX_EVENT_TITLE_SCREEN, on_title_screen, nullptr);\n    iface->subscribe(iface->self, BSX_EVENT_FRAME, on_frame, nullptr);\n    iface->log(iface->self, BSX_LOG_INFO, \"Smart Memory Trim loaded (zero CDAL IDs, 30s cooldown)\");\n    return 1;\n}","lang":"cpp","name":"smart_memory_trim.cpp"}],"id":"recipe_smart_memory_trim_cpp","kind":"native_cpp","lua_api":0,"path":"cookbook/smart_memory_trim_cpp","tier":"native_sdk","title":"Recipe: Smart Auto Memory Trimmer (C++ BSX Plugin)","uses":["bsx.h"]},{"category":"Cookbook Recipes","description":"Bind a safe global hotkey, trigger a styled corner toast notification, and play a WAV chime from data/chime.wav.","featured":true,"files":[{"code":"-- Hotkey + Corner Toast + Audio Chime (Safe tier, Lua API 4+)\nbsx.hotkey(\"Ctrl+F8\", function()\n    bsx.ui.toast(\"Quick check triggered!\", { level = \"ok\", duration_ms = 2200 })\n    local voice, err = bsx.audio.play(\"chime.wav\", { volume = 0.85 })\n    if not voice then\n        bsx.log(\"Audio skipped: \" .. tostring(err))\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Hotkey Toast Recipe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": false,\n  \"uses\": [\"ui\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_hotkey_toast","kind":"lua","lua_api":4,"path":"cookbook/hotkey_toast","tier":"safe","title":"Recipe: Hotkey + Corner Toast + Chime","uses":["ui"]},{"category":"Cookbook Recipes","description":"Build a dark crimson ImGui panel with live English/Korean substring search (game.items.search), category filtering, and one-click item spawning.","featured":true,"files":[{"code":"-- Themed Searchable Item Browser + Spawner (Lua API 5 / BSX.Lua.UI/5)\nlocal panel = bsx.ui.panel(\"Item Spawner\")\npanel:set_theme({ accent = \"#D7263D\", child_bg = \"#141318\" })\n\nlocal query, grant_qty = \"\", 1\nlocal matches, labels = {}, {}\nlocal list_id\n\nlocal function refresh()\n    matches = game.items.search(query, 60, 0) or {}\n    labels = {}\n    for _, it in ipairs(matches) do\n        labels[#labels + 1] = string.format(\"%d | %s\", it.id, it.name)\n    end\n    if list_id then panel:set_items(list_id, labels, 1) end\nend\n\npanel:input_text(\"Filter\", query, function(v)\n    query = v or \"\"\n    refresh()\nend)\npanel:slider(\"Quantity\", 1, 50, grant_qty, function(v) grant_qty = math.floor(v) end)\nlist_id = panel:listbox(\"Matching Items\", labels, { height = 220 }, function(idx)\n    local item = matches[idx]\n    if not item then return end\n    local ok, err = game.inventory.add(item.id, grant_qty)\n    bsx.ui.toast(ok and (\"Added \" .. item.name) or tostring(err), { level = ok and \"ok\" or \"warn\" })\nend)\n\nbsx.on(\"world_ready\", refresh)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Searchable Item Spawner\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 5,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"definitions\", \"inventory\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_item_spawner","kind":"lua","lua_api":5,"path":"cookbook/item_spawner","tier":"changes","title":"Recipe: Searchable Item Spawner UI","uses":["ui","definitions","inventory","server_commands"]},{"category":"Cookbook Recipes","description":"Override stack sizes, stamina drain, gathering drops, and parry timing hooks declaratively using tweaks.json schema_version 2 without writing Lua.","featured":true,"files":[{"code":"{\n  \"schema_version\": 2,\n  \"description\": \"QoL stack & stamina balance preset\",\n  \"items\": {\n    \"1980\": {\n      \"name\": \"Healing Potion Stack\",\n      \"max_stack\": 999\n    }\n  },\n  \"gameplay\": {\n    \"stamina_cost_scale\": 0.65,\n    \"craft_cost_scale\": 0.5,\n    \"gather_multiplier\": 2,\n    \"ammo_saving\": true\n  },\n  \"hooks\": [\n    {\n      \"channel\": \"on_parry_window\",\n      \"mult\": 1.35,\n      \"add\": 0.0,\n      \"priority\": 0,\n      \"enabled\": true\n    }\n  ]\n}","lang":"json","name":"tweaks.json"},{"code":"{\n  \"name\": \"Data-Only QoL Preset\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 5,\n  \"data_only\": true,\n  \"changes\": true,\n  \"uses\": [\"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_tweak_pack","kind":"data_only","lua_api":5,"path":"cookbook/data_only_tweak_pack","tier":"data_only","title":"Recipe: Data-Only Balance Pack","uses":["server_commands"]},{"category":"Cookbook Recipes","description":"Full screenshot controller with toggleable Free Cam, FOV/Roll sliders, world pause/time-of-day sliders, and weather reset.","featured":true,"files":[{"code":"-- Photo Mode Controller (Lua API 4+, Changes tier)\nlocal p = bsx.ui.panel(\"Photo Studio\")\n\np:checkbox(\"Enable Free Cam\", game.camera.free_cam() or false, function(on)\n    game.camera.set_free_cam(on)\nend)\np:slider(\"Camera Speed\", 1, 80, game.camera.free_cam_speed() or 12, function(v)\n    game.camera.set_free_cam_speed(v)\nend)\np:slider(\"Field of View\", 35, 110, game.camera.fov() or 60, function(v)\n    game.camera.set_fov(v)\nend)\np:slider(\"Camera Roll (deg)\", -45, 45, game.camera.roll() or 0, function(v)\n    game.camera.set_roll(v)\nend)\np:separator()\np:slider(\"Hour of Day\", 0, 23, 12, function(h)\n    game.world.set_time(math.floor(h), 0, 0, true)\nend)\np:button(\"Clear Weather\", function()\n    game.world.set_weather({ rain = 0.0, snow = 0.0, dust = 0.0 })\nend)\np:same_line()\np:button(\"Reset All\", function()\n    game.camera.set_free_cam(false)\n    game.camera.set_fov()\n    game.camera.set_roll(0)\n    game.world.reset_weather()\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Photo Studio Recipe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"world\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_photo_mode","kind":"lua","lua_api":4,"path":"cookbook/photo_mode","tier":"changes","title":"Recipe: Photo Studio (Free Cam, FOV, Time)","uses":["ui","world","server_commands"]},{"category":"Cookbook Recipes","description":"Pinned HUD widget counting player hits/defeats across save reloads using bsx.save (CoSave) and BSX combat events.","featured":true,"files":[{"code":"-- Pinned Combat Tally HUD persisted in CoSave (Safe tier, Lua API 4+)\nlocal hud = bsx.ui.hud(\"Combat Tally\", { x = 24, y = 24, alpha = 0.85 })\nlocal lbl = hud:text(\"Hits: 0  |  Defeats: 0\")\nlocal hits, kills = 0, 0\n\nlocal function sync_ui()\n    hud:set_text(lbl, string.format(\"Hits: %d  |  Defeats: %d\", hits, kills))\nend\n\nbsx.on(\"save_loaded\", function()\n    hits = tonumber(bsx.save.get(\"hits\")) or 0\n    kills = tonumber(bsx.save.get(\"kills\")) or 0\n    sync_ui()\nend)\n\nbsx.on(\"hit\", function(e)\n    local player = game.player()\n    if player and tostring(e.attacker_key) == tostring(player) then\n        hits = hits + 1\n        bsx.save.set(\"hits\", hits)\n        sync_ui()\n    end\nend)\n\nbsx.on(\"death\", function(e)\n    local player = game.player()\n    if player and tostring(e.source_key) == tostring(player) then\n        kills = kills + 1\n        bsx.save.set(\"kills\", kills)\n        sync_ui()\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Combat Tally HUD\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": false,\n  \"uses\": [\"ui\", \"player\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_combat_hud","kind":"lua","lua_api":4,"path":"cookbook/combat_hud_cosave","tier":"safe","title":"Recipe: Pinned Combat Tally HUD + CoSave","uses":["ui","player"]},{"category":"Cookbook Recipes","description":"Build a schema-driven settings menu that automatically reads and persists choices losslessly to your mod's settings.ini via config.save().","featured":true,"files":[{"code":"-- Declarative Mod Settings Menu + Persistent settings.ini\nlocal mcm = bsx.ui.mcm({ title = \"My Mod Options\", section = \"General\" }, {\n    { type = \"section\", label = \"Behavior\", open = true },\n    { type = \"checkbox\", key = \"Enabled\", label = \"Enable Mod\", default = true },\n    { type = \"slider\", key = \"Scale\", label = \"Effect Scale\", min = 0.5, max = 3.0, default = 1.0 },\n    { type = \"hotkey\", key = \"ToggleKey\", label = \"Toggle Hotkey\", default = \"F7\" },\n    { type = \"button\", label = \"Save to settings.ini\", on_click = function()\n        local ok, err = config.save()\n        bsx.ui.toast(ok and \"Saved settings.ini\" or tostring(err), { level = ok and \"ok\" or \"fail\" })\n    end }\n})","lang":"lua","name":"main.lua"},{"code":"[General]\nEnabled=true\nScale=1.0\nToggleKey=F7\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"MCM Settings Recipe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"ui\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_mcm_settings","kind":"lua","lua_api":4,"path":"cookbook/mcm_settings","tier":"safe","title":"Recipe: Mod Configuration Menu (bsx.ui.mcm)","uses":["ui"]},{"category":"Cookbook Recipes","description":"Publish typed messages between scripts via bsx.bus, expose synchronous providers with bsx.bus.provide, and export helper APIs via bsx.export.","featured":true,"files":[{"code":"-- Cross-Mod Event Bus + Exported Function API (Lua API 4+)\nbsx.bus.provide(\"my_mod.get_version\", function(req)\n    return { api = 4, tag = (req and req.tag) or \"release\" }\nend)\n\nbsx.bus.on(\"weather_preset:applied\", function(payload)\n    bsx.log(\"Another mod changed weather preset -> \" .. tostring(payload and payload.name))\nend)\n\nbsx.export(\"ping\", function(caller)\n    return \"pong from my_mod -> \" .. tostring(caller)\nend)\n\n-- Calling from another script:\n-- local ok, info = bsx.bus.call(\"my_mod.get_version\", { tag = \"check\" })\n-- local other = bsx.mods.get(\"my_mod\")","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Cross-Mod Bus Recipe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"bus\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_cross_mod_bus","kind":"lua","lua_api":4,"path":"cookbook/cross_mod_bus","tier":"safe","title":"Recipe: Cross-Mod Event Bus & Service Export","uses":["bus"]},{"category":"Cookbook Recipes","description":"Register priority-ordered additive/multiplicative gameplay hooks with game.hooks.add so multiple mods combine cleanly without overwriting.","featured":true,"files":[{"code":"-- Composable Priority Hook via game.hooks (Lua API 4+, Changes tier)\nlocal parry_hook\nlocal active = false\n\nlocal panel = bsx.ui.panel(\"Gameplay Hook Demo\")\npanel:checkbox(\"Widen Parry Window (+35%)\", active, function(on)\n    active = on\n    if parry_hook then\n        parry_hook:off()\n        parry_hook = nil\n    end\n    if on then\n        local h, err = game.hooks.add(\"on_parry_window\", { mult = 1.35, add = 0.0, priority = 10 })\n        if h then\n            parry_hook = h\n        else\n            bsx.ui.toast(\"Hook failed: \" .. tostring(err), { level = \"fail\" })\n        end\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Gameplay Hook Recipe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_gameplay_hook","kind":"lua","lua_api":4,"path":"cookbook/gameplay_hook","tier":"changes","title":"Recipe: Composable Gameplay Multiplier Hook","uses":["ui","server_commands"]},{"category":"Cookbook Recipes","description":"Toggle Free Fly with configurable speed and teleport safely to the active map marker snapped cleanly to terrain height.","featured":true,"files":[{"code":"-- Free Fly & Map Marker Ground-Snap Teleport (Lua API 4+, Changes tier)\nlocal p = bsx.ui.panel(\"Traversal Controls\")\n\np:checkbox(\"Free Fly\", game.movement.free_fly() or false, function(on)\n    game.movement.set_free_fly(on)\nend)\np:slider(\"Fly Speed\", 5, 120, game.movement.fly_speed() or 25, function(v)\n    game.movement.set_fly_speed(v)\nend)\np:slider(\"Sprint / Move Scale\", 0.5, 4.0, game.movement.speed() or 1.0, function(v)\n    game.movement.set_speed(v)\nend)\np:button(\"Teleport to Map Marker\", function()\n    local mk, err = game.world.map_marker()\n    if not mk or not mk.active then\n        bsx.ui.toast(\"Place a map waypoint first: \" .. tostring(err), { level = \"warn\" })\n        return\n    end\n    local ok, terr = game.world.teleport(mk.x, mk.y or 0, mk.z, 0, true)\n    bsx.ui.toast(ok and \"Teleported cleanly\" or tostring(terr), { level = ok and \"ok\" or \"fail\" })\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Free Fly & Teleport\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"positions\", \"world\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_free_fly","kind":"lua","lua_api":4,"path":"cookbook/free_fly_teleport","tier":"changes","title":"Recipe: Free Fly & Ground-Snap Teleport","uses":["ui","positions","world","server_commands"]},{"category":"Cookbook Recipes","description":"Read active quests, inspect learned skill tables, toggle Dragon Summon Anywhere, and display structured results in a tabbed panel.","featured":true,"files":[{"code":"-- API 6-7 World & Definition Inspector\nlocal p = bsx.ui.panel(\"World Systems (API 7)\")\n\np:begin_tab_bar(\"sys_tabs\")\nif p:tab(\"Quests & Skills\") then\n    local qtext = p:text(\"Click refresh to read active quests\")\n    p:button(\"Refresh Active Quests\", function()\n        local list = game.quests.active() or {}\n        p:set_text(qtext, string.format(\"Tracked active quests: %d\", #list))\n    end)\n    p:end_tab()\nend\nif p:tab(\"Mounts\") then\n    p:checkbox(\"Allow Dragon Summon Anywhere\", game.mounts.dragon_anywhere() or false, function(on)\n        game.mounts.set_dragon_anywhere(on)\n    end)\n    p:checkbox(\"Lock Mount Display Stamina\", game.mounts.display_stamina_lock() or false, function(on)\n        game.mounts.set_display_stamina_lock(on)\n    end)\n    p:end_tab()\nend\np:end_tab_bar()","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"API 7 World Explorer\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"definitions\", \"snapshots\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_world_explorer","kind":"lua","lua_api":7,"path":"cookbook/world_explorer_api7","tier":"changes","title":"Recipe: Quests, Skills & Mounts Inspector (API 7)","uses":["ui","definitions","snapshots","server_commands"]},{"category":"Cookbook Recipes","description":"Animate smooth progress bars and custom screen-space DX12 primitives cleanly on frame using bsx.tween.to and bsx.draw.rect.","featured":true,"files":[{"code":"-- Animated Eased HUD Meter (Safe tier, Lua API 4+)\nlocal p = bsx.ui.panel(\"Tween Meter\")\nlocal progress = 0.0\nlocal bar_id = p:progress(0.0, \"Idle\")\n\np:button(\"Animate Charge (1.2s)\", function()\n    bsx.tween.to(0.0, 1.0, 1.2, {\n        ease = \"out_cubic\",\n        on_update = function(val)\n            progress = val\n            p:set_value(bar_id, val)\n            p:set_text(bar_id, string.format(\"%.0f%%\", val * 100))\n            bsx.draw.clear()\n            bsx.draw.rect(30, 90, 220 * val, 10, \"#D7263DFF\", true)\n        end,\n        on_done = function()\n            bsx.ui.toast(\"Charge complete!\", { level = \"ok\" })\n        end\n    })\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Animated Tween Meter\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"ui\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_animated_hud","kind":"lua","lua_api":4,"path":"cookbook/animated_hud_tween","tier":"safe","title":"Recipe: Eased Overlay Bar (bsx.tween + bsx.draw)","uses":["ui"]},{"category":"Cookbook Recipes","description":"Project nearby non-controlled actors onto the screen using game.actors(), game.camera.world_to_screen(), and bsx.draw.world_label() markers.","featured":true,"files":[{"code":"-- 3D World-Space Actor Radar (Safe tier, Lua API 4+)\nlocal enabled = config.bool(\"Radar\", \"Enabled\", true)\nlocal max_actors = 12\nlocal world_up = false\n\nlocal panel = bsx.ui.panel(\"Actor Radar\")\npanel:checkbox(\"Draw 3D Actor Labels\", enabled, function(v)\n    enabled = (v == true)\n    if not enabled then bsx.draw.clear() end\nend)\n\nbsx.on(\"world_ready\", function() world_up = true end)\nbsx.on(\"title_screen\", function() world_up = false bsx.draw.clear() end)\n\nbsx.on(\"frame\", function()\n    if not world_up or not enabled then return end\n    bsx.draw.clear()\n    local actors = game.actors(max_actors)\n    if not actors then return end\n    for _, a in ipairs(actors) do\n        if not a.controlled and not a.dead and a.x and a.y and a.z then\n            local sp = game.camera.world_to_screen(a.x, a.y + 1.8, a.z)\n            if sp and sp.on_screen then\n                local label = string.format(\"%s (%.0fm)\", a.display_name or \"Actor\", a.distance or 0)\n                bsx.draw.circle(sp.x, sp.y, 4, \"#D7263DFF\", true)\n                bsx.draw.world_label(a.x, a.y + 2.0, a.z, label, \"#FFFFFFE0\", 1.0)\n            end\n        end\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"3D Actor Radar\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"snapshots\", \"positions\", \"ui\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_3d_actor_radar","kind":"lua","lua_api":4,"path":"cookbook/actor_radar_3d","tier":"safe","title":"Recipe: 3D Actor Radar (world_to_screen + bsx.draw)","uses":["snapshots","positions","ui"]},{"category":"Cookbook Recipes","description":"Use game.player_state() flags (in_town, in_battle) to apply a safe movement speed boost and zero stamina drain while exploring out of combat.","featured":true,"files":[{"code":"-- Contextual Town Explorer Boost (Lua API 5, Changes tier)\nlocal enabled = true\nlocal boost_active = false\nlocal last_check = 0\n\nlocal panel = bsx.ui.panel(\"Smart Town Sprint\")\npanel:checkbox(\"Enable Town Out-of-Combat Boost\", enabled, function(v)\n    enabled = (v == true)\n    if not enabled and boost_active then\n        game.movement.set_speed(1.0)\n        game.gameplay.set_stamina_cost_scale(1.0)\n        boost_active = false\n    end\nend)\n\nbsx.on(\"frame\", function()\n    if not enabled then return end\n    local now = os.clock()\n    if now - last_check \u003c 0.25 then return end\n    last_check = now\n\n    local ps = game.player_state()\n    local want = (ps ~= nil) and (ps.in_town == true) and (not ps.in_battle)\n    if want ~= boost_active then\n        boost_active = want\n        game.movement.set_speed(want and 1.35 or 1.0)\n        game.gameplay.set_stamina_cost_scale(want and 0.0 or 1.0)\n        bsx.ui.toast(want and \"Town sprint active\" or \"Normal combat speed\", { level = \"info\" })\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Smart Town Sprint\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 5,\n  \"changes\": true,\n  \"uses\": [\"player\", \"snapshots\", \"ui\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_smart_sprint","kind":"lua","lua_api":5,"path":"cookbook/smart_town_sprint","tier":"changes","title":"Recipe: Out-of-Combat Sprint & Zero Stamina in Towns","uses":["player","snapshots","ui","server_commands"]},{"category":"Cookbook Recipes","description":"Hide or force-show equipment/costume parts by key and save/apply JSON appearance presets to data/ via bsx.fs.","featured":true,"files":[{"code":"-- Wardrobe & Part Visibility Presets (Lua API 6, Changes tier)\nlocal p = bsx.ui.panel(\"Wardrobe Presets\")\nlocal parts, labels = {}, {}\nlocal list_id\n\nlocal function refresh_parts()\n    parts = game.appearance.parts() or {}\n    labels = {}\n    for _, pt in ipairs(parts) do\n        labels[#labels + 1] = string.format(\"%s (%d) mode=%d\", pt.name or \"Part\", pt.key, pt.override_mode)\n    end\n    if list_id then p:set_items(list_id, labels, 1) end\nend\n\nlist_id = p:listbox(\"Visible Parts\", labels, { height = 180 }, function(idx)\n    local pt = parts[idx]\n    if pt then\n        local next_mode = (pt.override_mode == 0) and -1 or 0\n        game.appearance.set_part_visibility(pt.key, next_mode)\n        refresh_parts()\n    end\nend)\np:button(\"Save Appearance Preset\", function()\n    local preset = game.appearance.export_preset()\n    if preset then\n        bsx.fs.write(\"preset_slot1.json\", bsx.json.encode(preset, { pretty = true }))\n        bsx.ui.toast(\"Saved preset_slot1.json\", { level = \"ok\" })\n    end\nend)\np:same_line()\np:button(\"Clear Overrides\", function()\n    game.appearance.clear_part_overrides()\n    refresh_parts()\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Wardrobe Presets\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 6,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_wardrobe_presets","kind":"lua","lua_api":6,"path":"cookbook/wardrobe_presets","tier":"changes","title":"Recipe: Part Visibility & Appearance Presets","uses":["ui","player","server_commands"]},{"category":"Cookbook Recipes","description":"Read the in-game clock and weather snapshot cleanly and bind Dawn/Noon/Dusk/Storm presets plus time-scale multipliers.","featured":true,"files":[{"code":"-- Time-of-Day & Weather Studio (Lua API 4+, Changes tier)\nlocal p = bsx.ui.panel(\"Time & Weather\")\nlocal clock_id = p:text(\"Time: --:--\")\n\np:button(\"Dawn 06:00\", function() game.world.set_time(6, 0, 0, true) end)\np:same_line()\np:button(\"Noon 12:00\", function() game.world.set_time(12, 0, 0, true) end)\np:same_line()\np:button(\"Midnight 00:00\", function() game.world.set_time(0, 0, 0, true) end)\np:slider(\"Time Scale\", 0.0, 10.0, 1.0, function(s) game.world.set_time_scale(s) end)\np:button(\"Heavy Storm\", function()\n    game.world.set_weather({ rain = 1.0, cloudiness = 1.0, wind_speed = 24 })\nend)\np:same_line()\np:button(\"Snowfall\", function()\n    game.world.set_weather({ snow = 0.9, rain = 0.0, cloudiness = 0.85 })\nend)\np:same_line()\np:button(\"Native Weather\", function() game.world.reset_weather() end)\n\nbsx.on(\"frame\", function()\n    local tm = game.time()\n    if tm then p:set_text(clock_id, string.format(\"Day %d - %02d:%02d:%02d\", tm.day, tm.hour, tm.minute, tm.second)) end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Weather & Time Presets\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"world\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_weather_time_cycle","kind":"lua","lua_api":4,"path":"cookbook/weather_time_cycle","tier":"changes","title":"Recipe: Time-of-Day, Time Scale & Weather Controls","uses":["ui","world","server_commands"]},{"category":"Cookbook Recipes","description":"Split larger Lua mods cleanly across helper modules with require('helpers.store') and manage JSON presets inside data/ via bsx.fs.","featured":true,"files":[{"code":"-- Modular Multi-File Script Entrypoint (Safe tier, Lua API 4+)\nlocal store = require(\"helpers.store\")\n\nlocal presets = store.load_or_default(\"presets/user.json\", {\n    accent = \"#D7263D\",\n    scale = 1.0,\n    favorites = {}\n})\n\nlocal p = bsx.ui.panel(\"Modular Pack\")\np:text(\"Files under data/presets: \" .. store.list_summary(\"presets\"))\np:button(\"Save JSON Config\", function()\n    local ok, err = store.save_json(\"presets/user.json\", presets)\n    bsx.ui.toast(ok and \"Saved data/presets/user.json\" or tostring(err), { level = ok and \"ok\" or \"fail\" })\nend)","lang":"lua","name":"main.lua"},{"code":"-- helpers/store.lua: safe JSON + folder helper\nlocal M = {}\n\nfunction M.save_json(rel_path, tbl)\n    local dir = rel_path:match(\"^(.+)/[^/]+$\")\n    if dir and not bsx.fs.exists(dir) then bsx.fs.mkdir(dir) end\n    local encoded, err = bsx.json.encode(tbl, { pretty = true })\n    if not encoded then return false, err end\n    return pcall(bsx.fs.write, rel_path, encoded)\nend\n\nfunction M.load_or_default(rel_path, fallback)\n    if not bsx.fs.exists(rel_path) then return fallback end\n    local ok, raw = pcall(bsx.fs.read, rel_path)\n    if not ok then return fallback end\n    return bsx.json.decode(raw) or fallback\nend\n\nfunction M.list_summary(dir)\n    if not bsx.fs.exists(dir) then return \"(empty)\" end\n    return table.concat(bsx.fs.list(dir) or {}, \", \")\nend\n\nreturn M","lang":"lua","name":"helpers/store.lua"},{"code":"{\n  \"name\": \"Multi-File Module Template\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"ui\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_multi_file_modules","kind":"lua","lua_api":4,"path":"cookbook/multi_file_modules","tier":"safe","title":"Recipe: Multi-File Modules & Sandboxed JSON Storage","uses":["ui"]},{"category":"Cookbook Recipes","description":"Subscribe to API 3-7 gameplay events (loot_pickup, quick_slot_use_after, zone_changed, weather_changed) and render a scrolling log in an ImGui panel.","featured":true,"files":[{"code":"-- Live Event Stream Monitor (Safe tier, Lua API 7)\nlocal p = bsx.ui.panel(\"Gameplay Event Log\")\nlocal ring = {}\nlocal list_id\n\nlocal function push_line(line)\n    table.insert(ring, 1, line)\n    if #ring > 24 then table.remove(ring) end\n    if list_id then p:set_items(list_id, ring, 1) end\nend\n\nlist_id = p:listbox(\"Recent Events\", ring, { height = 220 })\n\nbsx.on(\"loot_pickup\", function(e)\n    push_line(string.format(\"[LOOT] kind=%s target=%d result=%d\", e.kind, e.target_key, e.result))\nend)\nbsx.on(\"quick_slot_use_after\", function(e)\n    push_line(string.format(\"[SLOT] idx=%d amount=%d result=%d\", e.index, e.amount, e.result))\nend)\nbsx.on(\"zone_changed\", function(e)\n    push_line(string.format(\"[ZONE] safe=%s town=%s\", tostring(e.in_safe_zone), tostring(e.in_town)))\nend)\nbsx.on(\"weather_changed\", function(e)\n    push_line(string.format(\"[WEATHER] mask=0x%X precip=%.2f\", e.weather_mask, e.precipitation))\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Event Stream Monitor\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"uses\": [\"ui\", \"player\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_loot_pet_guard","kind":"lua","lua_api":7,"path":"cookbook/event_monitor","tier":"safe","title":"Recipe: Event Stream Monitor (Loot, Quick-Slot & Zones)","uses":["ui","player"]},{"category":"Cookbook Recipes","description":"C++23 ASI boilerplate following every CDAL rule: process guard, worker thread init, cdal::Feature lookup, and shared FunctionHook\u003cFn>.","featured":true,"files":[{"code":"#define CDAL_SHARED\n#include \u003ccdal/cdal.hpp>\n#include \u003ccdal/hooks.hpp>\n#include \u003ccdal/ids.hpp>\n#include \u003cwindows.h>\n\nusing UpdateFn = void (*)(void*);\nstatic cdal::hooks::FunctionHook\u003cUpdateFn> g_update_hook;\nstatic cdal::Feature g_feat{\"My Mod\", \"Core Tick\"};\n\nstatic void hk_update(void* self) {\n    g_update_hook.original()(self);\n}\n\nstatic bool in_game_process() {\n    wchar_t path[MAX_PATH]{};\n    GetModuleFileNameW(nullptr, path, MAX_PATH);\n    return wcsstr(path, L\"CrimsonDesert.exe\") != nullptr;\n}\n\nstatic DWORD WINAPI worker(LPVOID) {\n    if (!cdal::init()) {\n        OutputDebugStringA(cdal::last_error().c_str());\n        return 0;\n    }\n    std::string missing, err;\n    if (!g_feat.require({cdal::ids::Game::Update}, &missing)) {\n        g_feat.off(\"Missing IDs on build \" + cdal::build() + \": \" + missing);\n        return 0;\n    }\n    if (!g_update_hook.install(cdal::ids::Game::Update, &hk_update, {\"My Mod\", 0}, &err)) {\n        g_feat.off(err);\n    }\n    return 0;\n}\n\nBOOL APIENTRY DllMain(HMODULE mod, DWORD reason, LPVOID) {\n    if (reason == DLL_PROCESS_ATTACH && in_game_process()) {\n        DisableThreadLibraryCalls(mod);\n        if (HANDLE t = CreateThread(nullptr, 0, worker, nullptr, 0, nullptr)) CloseHandle(t);\n    }\n    return TRUE;\n}","lang":"cpp","name":"plugin.cpp"}],"id":"recipe_cpp_asi_hooks","kind":"native_cpp","lua_api":0,"path":"cookbook/cpp_asi_template","tier":"native_sdk","title":"Recipe: Complete C++23 ASI Mod (FunctionHook)","uses":["cdal.lib"]},{"category":"Cookbook Recipes","description":"Install a conflict-free MidHook via cdal::hooks::MidHook::create to inspect or adjust registers safely at a CDAL code ID (e.g., ItemDurability::ApplyDelta_Hook).","featured":true,"files":[{"code":"#define CDAL_SHARED\n#include \u003ccdal/cdal.hpp>\n#include \u003ccdal/hooks.hpp>\n#include \u003ccdal/ids.hpp>\n#include \u003ccstdint>\n\nstatic cdal::hooks::MidHook g_no_wear;\nstatic cdal::Feature g_no_wear_feat{\"My Mod\", \"No durability wear\"};\n\nvoid install_no_wear() {\n    std::string missing, err;\n    if (!g_no_wear_feat.require({cdal::ids::ItemDurability::ApplyDelta_Hook}, &missing)) {\n        return;\n    }\n    g_no_wear = cdal::hooks::MidHook::create(\n        cdal::ids::ItemDurability::ApplyDelta_Hook,\n        [](cdal_context& ctx) {\n            if (static_cast\u003cstd::int16_t>(ctx.r12) \u003c 0) ctx.r12 = 0; // r12w = signed delta\n        },\n        {\"My Mod\", 0}, &err);\n    if (!g_no_wear) g_no_wear_feat.off(err);\n}","lang":"cpp","name":"midhook.cpp"}],"id":"recipe_cpp_midhook","kind":"native_cpp","lua_api":0,"path":"cookbook/cpp_midhook","tier":"native_sdk","title":"Recipe: C++23 Register MidHook (cdal_context)","uses":["cdal.lib"]},{"category":"Cookbook Recipes","description":"Resolution-aware FPS, 1% low, frame time, and RAM corner HUD built with bsx.every, bsx.system.info, bsx.memory.info, bsx.draw, Ctrl+F9 toggle, and clipboard benchmark export.","featured":true,"files":[{"code":"-- Performance HUD (Safe-tier, Lua API 7+, zero game addresses)\n-- Resolution-aware FPS / 1% low / frame time / RAM corner overlay + clipboard benchmark export.\n\nlocal SECTION = \"PerfHud\"\nlocal CORNERS = { \"TopLeft\", \"TopRight\", \"BottomLeft\", \"BottomRight\" }\n\nlocal visible = config.bool(SECTION, \"Visible\", true)\nlocal corner_name = config.string(SECTION, \"Corner\", \"TopRight\")\nlocal show_ram = config.bool(SECTION, \"ShowRam\", true)\nlocal show_low = config.bool(SECTION, \"Show1PctLow\", true)\nlocal show_ms = config.bool(SECTION, \"ShowFrameTime\", true)\nlocal opacity = math.max(0.2, math.min(1.0, config.float(SECTION, \"Opacity\", 0.82)))\n\nlocal corner_idx = 2\nfor i, name in ipairs(CORNERS) do\n    if name == corner_name then corner_idx = i; break end\nend\n\nlocal panel = bsx.ui and bsx.ui.panel(\"Performance HUD\") or nil\nlocal fps_lbl_id, sys_lbl_id, ram_lbl_id\nlocal last_sys, last_mem = nil, nil\n\nlocal function persist(key, val)\n    config.set(SECTION, key, val)\n    pcall(config.save)\nend\n\nlocal function toast(msg, level)\n    if bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(tostring(msg):sub(1, 150), { level = level or \"info\", duration_ms = 2200 })\n    end\nend\n\nlocal function rgba_hex(rgb_hex, alpha01)\n    local a = math.max(0, math.min(255, math.floor(alpha01 * 255 + 0.5)))\n    return string.format(\"#%s%02X\", rgb_hex, a)\nend\n\nlocal function format_fps_line(sys)\n    local parts = { string.format(\"FPS %.1f\", sys.fps or 0) }\n    if show_low then\n        parts[#parts + 1] = string.format(\"1%% low %.1f\", sys.fps_1pct_low or 0)\n    end\n    if show_ms then\n        parts[#parts + 1] = string.format(\"%.1f ms\", sys.frame_ms or 0)\n    end\n    return table.concat(parts, \"  |  \")\nend\n\nlocal function render_hud(sys, mem_info)\n    if not bsx.draw then return end\n    if not visible or not sys then\n        pcall(bsx.draw.clear)\n        return\n    end\n\n    local vw = math.max(640, sys.viewport_w or 1920)\n    local vh = math.max(480, sys.viewport_h or 1080)\n    local line1 = format_fps_line(sys)\n    local line2 = nil\n    if show_ram and mem_info then\n        line2 = string.format(\"RAM %.0f MB (Peak %.0f)  |  Sys %d%%\",\n            mem_info.working_set_mb or 0, mem_info.peak_working_set_mb or 0, mem_info.system_load_pct or 0)\n    end\n\n    local box_w = math.max(255, (#line1 * 8) + 28)\n    if line2 then box_w = math.max(box_w, (#line2 * 8) + 28) end\n    local box_h = line2 and 54 or 32\n    local pad = 18\n\n    local c = CORNERS[corner_idx] or \"TopRight\"\n    local x = (c == \"TopRight\" or c == \"BottomRight\") and (vw - box_w - pad) or pad\n    local y = (c == \"BottomLeft\" or c == \"BottomRight\") and (vh - box_h - pad) or pad\n\n    local fps = sys.fps or 0\n    local fps_col = (fps >= 55 or fps \u003c= 0.1) and \"#6CC08AFF\" or (fps >= 30 and \"#D9A92BFF\" or \"#F07A6AFF\")\n\n    pcall(bsx.draw.clear)\n    pcall(bsx.draw.rect, x, y, box_w, box_h, rgba_hex(\"0D1015\", opacity), true)\n    pcall(bsx.draw.rect, x, y, 3, box_h, \"#D7263DFF\", true)\n    pcall(bsx.draw.rect, x, y, box_w, box_h, \"#2F3540AA\", false, 1.0)\n    pcall(bsx.draw.text, x + 12, y + 7, line1:sub(1, 120), fps_col, 1.0)\n    if line2 then\n        pcall(bsx.draw.text, x + 12, y + 29, line2:sub(1, 120), \"#E8EAEDEE\", 0.95)\n    end\nend\n\nlocal function update_all()\n    if not bsx.system then return end\n    last_sys = bsx.system.info()\n    last_mem = bsx.memory and bsx.memory.info() or nil\n    render_hud(last_sys, last_mem)\n\n    if panel and last_sys then\n        if fps_lbl_id then\n            panel:set_text(fps_lbl_id, format_fps_line(last_sys):sub(1, 120))\n        end\n        if sys_lbl_id then\n            panel:set_text(sys_lbl_id, string.format(\"Viewport: %dx%d @ %d Hz  |  Frames: %d\",\n                last_sys.viewport_w or 0, last_sys.viewport_h or 0, last_sys.monitor_hz or 0,\n                last_sys.frame_count or 0):sub(1, 120))\n        end\n        if ram_lbl_id and last_mem then\n            panel:set_text(ram_lbl_id, string.format(\"RAM: %.0f MB  |  Peak: %.0f MB  |  Private: %.0f MB\",\n                last_mem.working_set_mb or 0, last_mem.peak_working_set_mb or 0,\n                last_mem.private_mb or 0):sub(1, 120))\n        end\n    end\nend\n\nlocal function copy_benchmark_snapshot()\n    local s = last_sys or (bsx.system and bsx.system.info())\n    local m = last_mem or (bsx.memory and bsx.memory.info())\n    if not s or not bsx.system then return end\n    local text = string.format(\n        \"Crimson Desert Perf Snapshot | %dx%d @ %dHz | FPS %.1f (1%% low %.1f, %.1f ms) | RAM %.0f MB (Peak %.0f MB, Private %.0f MB, Sys %d%%) | Uptime %.0fs\",\n        s.viewport_w or 0, s.viewport_h or 0, s.monitor_hz or 0,\n        s.fps or 0, s.fps_1pct_low or 0, s.frame_ms or 0,\n        m and (m.working_set_mb or 0) or 0, m and (m.peak_working_set_mb or 0) or 0,\n        m and (m.private_mb or 0) or 0, m and (m.system_load_pct or 0) or 0,\n        s.uptime_sec or 0)\n    local ok, err = bsx.system.copy_text(text)\n    if ok then\n        toast(\"Benchmark snapshot copied to clipboard!\", \"ok\")\n    else\n        toast(\"Copy failed: \" .. tostring(err or \"clipboard busy\"), \"warn\")\n    end\nend\n\nif panel then\n    fps_lbl_id = panel:text(\"FPS: waiting for samples...\")\n    sys_lbl_id = panel:text(\"Viewport: reading...\")\n    ram_lbl_id = panel:text(\"RAM: reading...\")\n    panel:button(\"Copy Benchmark Snapshot\", copy_benchmark_snapshot)\n    panel:same_line()\n    panel:button(\"Trim RAM Now\", function()\n        if not bsx.memory then return end\n        local res, err = bsx.memory.trim()\n        toast(res and \"Background RAM trim queued!\" or tostring(err or \"cooldown\"), res and \"ok\" or \"warn\")\n    end)\n    panel:separator()\n\n    panel:checkbox(\"Show Corner HUD (Ctrl+F9)\", visible, function(v)\n        visible = v\n        persist(\"Visible\", v)\n        render_hud(last_sys, last_mem)\n    end)\n    panel:combo(\"Corner Anchor\", CORNERS, corner_idx, function(idx, label)\n        corner_idx = idx\n        persist(\"Corner\", label)\n        render_hud(last_sys, last_mem)\n    end)\n    panel:checkbox(\"Show RAM & Peak row\", show_ram, function(v)\n        show_ram = v\n        persist(\"ShowRam\", v)\n        render_hud(last_sys, last_mem)\n    end)\n    panel:checkbox(\"Show 1% Low FPS\", show_low, function(v)\n        show_low = v\n        persist(\"Show1PctLow\", v)\n        render_hud(last_sys, last_mem)\n    end)\n    panel:checkbox(\"Show Frame Time (ms)\", show_ms, function(v)\n        show_ms = v\n        persist(\"ShowFrameTime\", v)\n        render_hud(last_sys, last_mem)\n    end)\n    panel:slider(\"HUD Opacity\", 0.2, 1.0, opacity, function(v)\n        opacity = v\n        persist(\"Opacity\", v)\n        render_hud(last_sys, last_mem)\n    end)\nend\n\nlocal ok_hk, hk_err = pcall(bsx.hotkey, \"ctrl+f9\", function()\n    visible = not visible\n    persist(\"Visible\", visible)\n    render_hud(last_sys, last_mem)\n    toast(visible and \"Performance HUD shown\" or \"Performance HUD hidden\", \"info\")\nend)\nif not ok_hk then\n    bsx.log(\"Performance HUD hotkey Ctrl+F9 unavailable: \" .. tostring(hk_err))\nend\n\nbsx.every(500, update_all)\nupdate_all()\nbsx.log(\"Performance HUD loaded (Safe tier, Ctrl+F9 toggle)\")\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Performance HUD\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7\n}\n","lang":"json","name":"script.json"},{"code":"[PerfHud]\nVisible=true\nCorner=TopRight\nShowRam=true\nShow1PctLow=true\nShowFrameTime=true\nOpacity=0.82\n","lang":"ini","name":"settings.ini"}],"id":"recipe_perf_hud","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/perf_hud","tier":"safe","title":"Recipe: Live FPS, 1% Low & RAM Performance Overlay","uses":["ui"]},{"category":"Cookbook Recipes","description":"Safe-tier Floating Combat Text (6 styles: 3D above enemy, Arc, Side Scroll, Radial Burst, Combo Stacker, HUD-only) and smooth 3D Enemy Nameplates using nearest-first 256-actor snapshots, aggro/lock-on polling, HP normalization, Live Preview, measure_text layout, double-ring outlines, customizable fonts/colors/debuffs, and live diagnostics.","featured":true,"files":[{"code":"-- Combat Meter, Floating Combat Text (FCT) & Custom 3D Enemy Nameplates (Safe tier, Lua API 7+)\n\nlocal function clamp(v, lo, hi)\n    if type(v) ~= \"number\" or v ~= v then return lo end\n    if v \u003c lo then return lo end\n    if v > hi then return hi end\n    return v\nend\n\nlocal function fmt_num(n)\n    local v = math.floor(math.abs(tonumber(n) or 0) + 0.5)\n    local s = tostring(v)\n    local out = s:reverse():gsub(\"(%d%d%d)\", \"%1,\"):reverse()\n    if out:sub(1, 1) == \",\" then out = out:sub(2) end\n    return (tonumber(n) or 0) \u003c 0 and (\"-\" .. out) or out\nend\n\nlocal function trim_text(s, max_len)\n    s = tostring(s or \"\"):gsub(\"[%z\\1-\\31]\", \" \")\n    if #s \u003c= max_len then return s end\n    return s:sub(1, math.max(1, max_len - 2)) .. \"..\"\nend\n\nlocal function tidy_name(s)\n    s = tostring(s or \"\"):gsub(\"^Buff_\", \"\"):gsub(\"^Debuff_\", \"\"):gsub(\"^Char_\", \"\"):gsub(\"_\", \" \"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    return s\nend\n\n-- Hex #RRGGBBAA \u003c-> float rgba helpers\nlocal function parse_hex(hex, fb)\n    local s = tostring(hex or fb or \"#FFFFFFFF\"):gsub(\"^#\", \"\")\n    if #s == 6 then s = s .. \"FF\" end\n    if #s ~= 8 then return 1, 1, 1, 1 end\n    local r = tonumber(s:sub(1, 2), 16) or 255\n    local g = tonumber(s:sub(3, 4), 16) or 255\n    local b = tonumber(s:sub(5, 6), 16) or 255\n    local a = tonumber(s:sub(7, 8), 16) or 255\n    return r / 255, g / 255, b / 255, a / 255\nend\n\nlocal function scale_alpha(hex, a_mul)\n    local r, g, b, a = parse_hex(hex, \"#FFFFFFFF\")\n    local na = math.max(0, math.min(255, math.floor(a * clamp(a_mul or 1.0, 0.0, 1.0) * 255 + 0.5)))\n    return string.format(\"#%02X%02X%02X%02X\",\n        math.floor(r * 255 + 0.5), math.floor(g * 255 + 0.5), math.floor(b * 255 + 0.5), na)\nend\n\nlocal function rgba_tbl(hex)\n    local r, g, b, a = parse_hex(hex, \"#FFFFFFFF\")\n    return { r = r, g = g, b = b, a = a }\nend\n\nlocal FCT_STYLES = { \"3D Above Enemy\", \"WoW Arc\", \"Side Scroll\", \"Radial Burst\", \"Combo Stacker\", \"HUD Only\" }\nlocal FONT_LABELS = { \"Impact / Bold\", \"Bold UI\", \"Classic Serif\", \"Clean Sans\", \"Monospace\" }\nlocal FONT_NAMES = { \"impact\", \"bold\", \"serif\", \"sans\", \"mono\" }\nlocal OUTLINE_LABELS = { \"Heavy Outline\", \"Bold Outline\", \"Drop Shadow\", \"Clean (None)\" }\nlocal OUTLINE_NAMES = { \"heavy\", \"outline\", \"shadow\", \"none\" }\nlocal FILTER_LABELS = { \"Nearby Non-Allied\", \"Hostile / Aggro / Target\", \"Combat / Aggro Only\", \"All Living (Debug)\" }\nlocal BAR_STYLE_LABELS = { \"Framed Gloss\", \"Segmented (25%)\", \"Clean Flat\" }\nlocal NAME_POS_LABELS = { \"Above Bar\", \"Below Bar\", \"Hidden\" }\nlocal HP_FMT_LABELS = { \"Current / Max\", \"Current (Pct%)\", \"Percent Only\", \"Current Only\", \"Hidden\" }\nlocal HP_POS_LABELS = { \"Inside Bar\", \"Right of Bar\", \"Above Right\", \"Below Bar\" }\nlocal DEBUFF_POS_LABELS = { \"Above Name\", \"Below Bar\", \"Left of Bar\", \"Right of Bar\" }\nlocal DEBUFF_STYLE_LABELS = { \"Vibrant Solid Pill\", \"Dark Glass + Accent\", \"Compact Tag\" }\nlocal PRESET_LABELS = { \"Crimson Default\", \"WoW Classic\", \"Neon Arcane\", \"Emerald\", \"High Contrast\" }\n\nlocal PRESETS = {\n    { out = \"#FFF5D6FF\", crit = \"#FFD100FF\", inc = \"#FF3B4EFF\", heal = \"#3BE87AFF\", hp = \"#D92B38FF\", ag = \"#FFB020FF\", name = \"#FFFFFFFF\", hptxt = \"#FFFFFFFF\", bg = \"#0C0E14D8\" },\n    { out = \"#FFE64DFF\", crit = \"#FF7F11FF\", inc = \"#FF2222FF\", heal = \"#2EFF66FF\", hp = \"#C82020FF\", ag = \"#FFCC00FF\", name = \"#FFF3D1FF\", hptxt = \"#FFFFFFFF\", bg = \"#090B10DC\" },\n    { out = \"#66E5FFFF\", crit = \"#FF4DFFFF\", inc = \"#FF3366FF\", heal = \"#4DFFB8FF\", hp = \"#E63975FF\", ag = \"#00F0FFFF\", name = \"#F2FCFFFF\", hptxt = \"#FFFFFFFF\", bg = \"#100C1EDB\" },\n    { out = \"#E8FFF0FF\", crit = \"#AAFF33FF\", inc = \"#FF5544FF\", heal = \"#33FFAAFF\", hp = \"#249E5BFF\", ag = \"#E6E633FF\", name = \"#F2FFF6FF\", hptxt = \"#FFFFFFFF\", bg = \"#0A140FD8\" },\n    { out = \"#FFFFFFFF\", crit = \"#FFFF00FF\", inc = \"#FF0033FF\", heal = \"#00FF66FF\", hp = \"#FF1E2DFF\", ag = \"#FFFF00FF\", name = \"#FFFFFFFF\", hptxt = \"#FFFFFFFF\", bg = \"#000000EB\" },\n}\n\nlocal cfg = {\n    -- FCT & HUD\n    fct_enabled = config.bool(\"FCT\", \"Enabled\", true),\n    hud_pinned = config.bool(\"HUD\", \"Pinned\", true),\n    fct_style = math.floor(clamp(config.int(\"FCT\", \"Style\", 2), 1, #FCT_STYLES)),\n    fct_font = math.floor(clamp(config.int(\"FCT\", \"Font\", 1), 1, #FONT_LABELS)),\n    fct_outline = math.floor(clamp(config.int(\"FCT\", \"OutlineStyle\", 1), 1, #OUTLINE_LABELS)),\n    fct_scale = clamp(config.float(\"FCT\", \"Scale\", 1.55), 0.7, 3.0),\n    fct_dur = clamp(config.float(\"FCT\", \"Duration\", 1.75), 0.5, 4.0),\n    crit_ratio = clamp(config.float(\"FCT\", \"CritRatio\", 3.0), 1.5, 8.0),\n    show_out = config.bool(\"FCT\", \"ShowOutgoing\", true),\n    show_in = config.bool(\"FCT\", \"ShowIncoming\", true),\n    show_heal = config.bool(\"FCT\", \"ShowHeal\", true),\n    include_nearby = config.bool(\"FCT\", \"IncludeNearby\", false),\n    merge_rapid = config.bool(\"FCT\", \"MergeRapid\", true),\n\n    -- Nameplates & Bars\n    np_enabled = config.bool(\"Nameplates\", \"Enabled\", true),\n    np_preview = config.bool(\"Nameplates\", \"LivePreview\", false),\n    np_filter = math.floor(clamp(config.int(\"Nameplates\", \"FilterMode\", 1), 1, #FILTER_LABELS)),\n    np_bar_style = math.floor(clamp(config.int(\"Nameplates\", \"BarStyle\", 1), 1, #BAR_STYLE_LABELS)),\n    np_width = clamp(config.float(\"Nameplates\", \"BarWidth\", 160), 70, 260),\n    np_height = clamp(config.float(\"Nameplates\", \"BarHeight\", 16), 6, 28),\n    np_opacity = clamp(config.float(\"Nameplates\", \"Opacity\", 0.94), 0.35, 1.0),\n    np_border = clamp(config.float(\"Nameplates\", \"BorderSize\", 2), 1, 4),\n    np_head_offset = clamp(config.float(\"Nameplates\", \"HeadOffset\", 2.15), 0.8, 3.8),\n    np_max_dist = clamp(config.float(\"Nameplates\", \"MaxDistance\", 45), 10, 90),\n    np_max_bars = math.floor(clamp(config.int(\"Nameplates\", \"MaxBars\", 10), 1, 20)),\n    np_dist_scale = config.bool(\"Nameplates\", \"DistanceScale\", true),\n    np_smooth = config.bool(\"Nameplates\", \"SmoothMotion\", true),\n    np_scale_hp = config.bool(\"Nameplates\", \"ScaleHP1000\", true),\n    np_prev_x = clamp(config.float(\"Nameplates\", \"PreviewX\", 50), 10, 90),\n    np_prev_y = clamp(config.float(\"Nameplates\", \"PreviewY\", 28), 10, 85),\n\n    -- Fonts, Text & Debuffs\n    np_outline = math.floor(clamp(config.int(\"Nameplates\", \"OutlineStyle\", 1), 1, #OUTLINE_LABELS)),\n    np_name_pos = math.floor(clamp(config.int(\"Nameplates\", \"NamePos\", 1), 1, #NAME_POS_LABELS)),\n    np_name_font = math.floor(clamp(config.int(\"Nameplates\", \"NameFont\", 2), 1, #FONT_LABELS)),\n    np_name_scale = clamp(config.float(\"Nameplates\", \"NameScale\", 1.15), 0.7, 2.5),\n    np_name_gap = clamp(config.float(\"Nameplates\", \"NameGap\", 6), 2, 24),\n    np_name_bg = config.bool(\"Nameplates\", \"NameBackdrop\", true),\n    np_hp_fmt = math.floor(clamp(config.int(\"Nameplates\", \"HPFormat\", 1), 1, #HP_FMT_LABELS)),\n    np_hp_pos = math.floor(clamp(config.int(\"Nameplates\", \"HPPos\", 1), 1, #HP_POS_LABELS)),\n    np_hp_font = math.floor(clamp(config.int(\"Nameplates\", \"HPFont\", 4), 1, #FONT_LABELS)),\n    np_hp_scale = clamp(config.float(\"Nameplates\", \"HPScale\", 0.95), 0.65, 2.2),\n    np_show_debuffs = config.bool(\"Nameplates\", \"ShowDebuffs\", true),\n    np_debuff_pos = math.floor(clamp(config.int(\"Debuffs\", \"Position\", 1), 1, #DEBUFF_POS_LABELS)),\n    np_debuff_style = math.floor(clamp(config.int(\"Debuffs\", \"Style\", 1), 1, #DEBUFF_STYLE_LABELS)),\n    np_debuff_font = math.floor(clamp(config.int(\"Debuffs\", \"Font\", 2), 1, #FONT_LABELS)),\n    np_debuff_scale = clamp(config.float(\"Debuffs\", \"Scale\", 0.92), 0.65, 1.8),\n    np_debuff_gap = clamp(config.float(\"Debuffs\", \"Gap\", 6), 2, 24),\n    np_debuff_max = math.floor(clamp(config.int(\"Debuffs\", \"MaxPills\", 4), 1, 6)),\n\n    -- Colors\n    preset = math.floor(clamp(config.int(\"Colors\", \"Preset\", 1), 1, #PRESET_LABELS)),\n    col_out = config.string(\"Colors\", \"Outgoing\", \"#FFF5D6FF\"),\n    col_crit = config.string(\"Colors\", \"Crit\", \"#FFD100FF\"),\n    col_in = config.string(\"Colors\", \"Incoming\", \"#FF3B4EFF\"),\n    col_heal = config.string(\"Colors\", \"Heal\", \"#3BE87AFF\"),\n    col_nphp = config.string(\"Colors\", \"NameplateHP\", \"#D92B38FF\"),\n    col_npag = config.string(\"Colors\", \"NameplateAggro\", \"#FFB020FF\"),\n    col_npname = config.string(\"Colors\", \"NameplateName\", \"#FFFFFFFF\"),\n    col_nptext = config.string(\"Colors\", \"NameplateText\", \"#FFFFFFFF\"),\n    col_npbg = config.string(\"Colors\", \"NameplateBG\", \"#0C0E14D8\"),\n}\n\nlocal function save_cfg()\n    config.set(\"FCT\", \"Enabled\", cfg.fct_enabled)\n    config.set(\"HUD\", \"Pinned\", cfg.hud_pinned)\n    config.set(\"FCT\", \"Style\", cfg.fct_style)\n    config.set(\"FCT\", \"Font\", cfg.fct_font)\n    config.set(\"FCT\", \"OutlineStyle\", cfg.fct_outline)\n    config.set(\"FCT\", \"Scale\", cfg.fct_scale)\n    config.set(\"FCT\", \"Duration\", cfg.fct_dur)\n    config.set(\"FCT\", \"CritRatio\", cfg.crit_ratio)\n    config.set(\"FCT\", \"ShowOutgoing\", cfg.show_out)\n    config.set(\"FCT\", \"ShowIncoming\", cfg.show_in)\n    config.set(\"FCT\", \"ShowHeal\", cfg.show_heal)\n    config.set(\"FCT\", \"IncludeNearby\", cfg.include_nearby)\n    config.set(\"FCT\", \"MergeRapid\", cfg.merge_rapid)\n\n    config.set(\"Nameplates\", \"Enabled\", cfg.np_enabled)\n    config.set(\"Nameplates\", \"LivePreview\", cfg.np_preview)\n    config.set(\"Nameplates\", \"FilterMode\", cfg.np_filter)\n    config.set(\"Nameplates\", \"BarStyle\", cfg.np_bar_style)\n    config.set(\"Nameplates\", \"BarWidth\", cfg.np_width)\n    config.set(\"Nameplates\", \"BarHeight\", cfg.np_height)\n    config.set(\"Nameplates\", \"Opacity\", cfg.np_opacity)\n    config.set(\"Nameplates\", \"BorderSize\", cfg.np_border)\n    config.set(\"Nameplates\", \"HeadOffset\", cfg.np_head_offset)\n    config.set(\"Nameplates\", \"MaxDistance\", cfg.np_max_dist)\n    config.set(\"Nameplates\", \"MaxBars\", cfg.np_max_bars)\n    config.set(\"Nameplates\", \"DistanceScale\", cfg.np_dist_scale)\n    config.set(\"Nameplates\", \"SmoothMotion\", cfg.np_smooth)\n    config.set(\"Nameplates\", \"ScaleHP1000\", cfg.np_scale_hp)\n    config.set(\"Nameplates\", \"PreviewX\", cfg.np_prev_x)\n    config.set(\"Nameplates\", \"PreviewY\", cfg.np_prev_y)\n\n    config.set(\"Nameplates\", \"OutlineStyle\", cfg.np_outline)\n    config.set(\"Nameplates\", \"NamePos\", cfg.np_name_pos)\n    config.set(\"Nameplates\", \"NameFont\", cfg.np_name_font)\n    config.set(\"Nameplates\", \"NameScale\", cfg.np_name_scale)\n    config.set(\"Nameplates\", \"NameGap\", cfg.np_name_gap)\n    config.set(\"Nameplates\", \"NameBackdrop\", cfg.np_name_bg)\n    config.set(\"Nameplates\", \"HPFormat\", cfg.np_hp_fmt)\n    config.set(\"Nameplates\", \"HPPos\", cfg.np_hp_pos)\n    config.set(\"Nameplates\", \"HPFont\", cfg.np_hp_font)\n    config.set(\"Nameplates\", \"HPScale\", cfg.np_hp_scale)\n    config.set(\"Nameplates\", \"ShowDebuffs\", cfg.np_show_debuffs)\n    config.set(\"Debuffs\", \"Position\", cfg.np_debuff_pos)\n    config.set(\"Debuffs\", \"Style\", cfg.np_debuff_style)\n    config.set(\"Debuffs\", \"Font\", cfg.np_debuff_font)\n    config.set(\"Debuffs\", \"Scale\", cfg.np_debuff_scale)\n    config.set(\"Debuffs\", \"Gap\", cfg.np_debuff_gap)\n    config.set(\"Debuffs\", \"MaxPills\", cfg.np_debuff_max)\n\n    config.set(\"Colors\", \"Preset\", cfg.preset)\n    config.set(\"Colors\", \"Outgoing\", cfg.col_out)\n    config.set(\"Colors\", \"Crit\", cfg.col_crit)\n    config.set(\"Colors\", \"Incoming\", cfg.col_in)\n    config.set(\"Colors\", \"Heal\", cfg.col_heal)\n    config.set(\"Colors\", \"NameplateHP\", cfg.col_nphp)\n    config.set(\"Colors\", \"NameplateAggro\", cfg.col_npag)\n    config.set(\"Colors\", \"NameplateName\", cfg.col_npname)\n    config.set(\"Colors\", \"NameplateText\", cfg.col_nptext)\n    config.set(\"Colors\", \"NameplateBG\", cfg.col_npbg)\n    config.save()\nend\n\n-- Runtime Combat & Nameplate State\nlocal dmg_out, dmg_in, hits_out, heavy_out, kills, peak_hit = 0, 0, 0, 0, 0, 0\nlocal in_fight, fight_start, last_activity = false, 0.0, 0.0\nlocal dps_ring = {}\nlocal floaters = {}\nlocal recent_hits = {}\nlocal char_name_cache, buff_name_cache = {}, {}\nlocal aggro_cache = {}\nlocal plate_state = {}\nlocal active_cands = {}\nlocal last_poll_t = -10.0\nlocal last_frame_t = os.clock()\nlocal combo_total, combo_ts = 0, 0.0\n\nlocal diag = {\n    world = false, total_actors = 0, near = 0, cands = 0, shown = 0,\n    stats_ok = 0, stats_fail = 0, last_err = \"none\", cam = \"--\", tgt_key = 0, pfac = -1\n}\n\n-- HUD & Settings Panels (total widgets on panel kept well below 128 cap)\nlocal hud = bsx.ui.panel(\"Combat Meter\", { hud = true, open = cfg.hud_pinned })\nhud:set_theme({ accent = \"#E03131\", header = \"#1C1E26\", child_bg = \"#0E1016CC\", border = \"#3A3E4C\" })\nlocal hud_l1 = hud:text(\"IDLE | DPS: 0 | 5s: 0 | 0.0s\")\nlocal hud_l2 = hud:text(\"Dmg: 0 | Peak: 0 | Hits: 0 | Kills: 0\")\n\nlocal panel = bsx.ui.panel(\"Combat Text & Nameplates\")\npanel:set_theme({ accent = \"#E03131\", header = \"#1C1E26\", child_bg = \"#12141B\", border = \"#323644\" })\nlocal panel_summary = panel:text(\"IDLE | DPS: 0 | Peak: 0 | Kills: 0\")\n\nlocal function rolling_5s_dps(now)\n    local cutoff = now - 5.0\n    local sum, keep = 0, {}\n    for i = 1, #dps_ring do\n        local e = dps_ring[i]\n        if e.t >= cutoff then\n            sum = sum + e.a\n            keep[#keep + 1] = e\n        end\n    end\n    dps_ring = keep\n    return sum / 5.0\nend\n\nlocal function reset_combat()\n    dmg_out, dmg_in, hits_out, heavy_out, kills, peak_hit = 0, 0, 0, 0, 0, 0\n    in_fight, fight_start, last_activity = false, 0.0, 0.0\n    dps_ring, floaters, combo_total, combo_ts = {}, {}, 0, 0.0\n    hud:set_text(hud_l1, \"IDLE | DPS: 0 | 5s: 0 | 0.0s\")\n    hud:set_text(hud_l2, \"Dmg: 0 | Peak: 0 | Hits: 0 | Kills: 0\")\n    panel:set_text(panel_summary, \"IDLE | DPS: 0 | Peak: 0 | Kills: 0\")\nend\n\nlocal function avg_out_hit()\n    if hits_out \u003c= 0 then return 100 end\n    return math.max(10, dmg_out / hits_out)\nend\n\nlocal function spawn_floater(kind, amt, is_crit, target_key, label_override)\n    if not cfg.fct_enabled or cfg.fct_style == 6 then return end\n    local now = os.clock()\n    if cfg.merge_rapid and not label_override then\n        for i = #floaters, math.max(1, #floaters - 8), -1 do\n            local f = floaters[i]\n            if f.kind == kind and f.target_key == target_key and (now - f.t0) \u003c= 0.18 then\n                f.amt = f.amt + amt\n                f.crit = f.crit or is_crit\n                f.text = (kind == \"heal\" and \"+\" or (kind == \"in\" and \"-\" or \"\")) .. fmt_num(f.amt) .. (f.crit and \"!\" or \"\")\n                f.t0 = now\n                return\n            end\n        end\n    end\n    local wx, wy, wz = nil, nil, nil\n    if target_key and target_key > 0 then\n        local st = plate_state[target_key]\n        if st and st.wx then wx, wy, wz = st.wx, st.wy + cfg.np_head_offset * 0.85, st.wz end\n    end\n    local idx = (#floaters % 7) - 3\n    floaters[#floaters + 1] = {\n        kind = kind, amt = amt, crit = is_crit, target_key = target_key or 0,\n        text = label_override or ((kind == \"heal\" and \"+\" or (kind == \"in\" and \"-\" or \"\")) .. fmt_num(amt) .. (is_crit and \"!\" or \"\")),\n        t0 = now, jx = idx * 14, ang = (idx * 0.48) - 1.57, wx = wx, wy = wy, wz = wz\n    }\n    if #floaters > 48 then table.remove(floaters, 1) end\nend\n\nlocal c_out, c_crit, c_in, c_heal, c_nphp, c_npag, c_npname, c_nptext, c_npbg\n\npanel:begin_tab_bar(\"dps_tabs\")\n\n-- Tab 1: Combat & FCT (23 widgets)\npanel:tab(\"Combat & FCT\")\npanel:checkbox(\"Floating Combat Text\", cfg.fct_enabled, function(v) cfg.fct_enabled = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"HUD Meter\", cfg.hud_pinned, function(v)\n    cfg.hud_pinned = (v == true)\n    if hud.set_open then hud:set_open(cfg.hud_pinned) end\n    save_cfg()\nend)\npanel:button(\"Test Hit\", function()\n    spawn_floater(\"out\", 1420, false, diag.tgt_key)\n    bsx.ui.toast(\"Spawned test hit floater\", { level = \"info\" })\nend)\npanel:same_line()\npanel:button(\"Test Crit\", function()\n    spawn_floater(\"out\", 6840, true, diag.tgt_key)\n    bsx.ui.toast(\"Spawned test crit floater\", { level = \"ok\" })\nend)\npanel:same_line()\npanel:button(\"Reset Stats\", reset_combat)\npanel:separator()\npanel:combo(\"FCT Style\", FCT_STYLES, cfg.fct_style, function(idx) cfg.fct_style = idx; save_cfg() end)\npanel:combo(\"FCT Font\", FONT_LABELS, cfg.fct_font, function(idx) cfg.fct_font = idx; save_cfg() end)\npanel:combo(\"FCT Outline\", OUTLINE_LABELS, cfg.fct_outline, function(idx) cfg.fct_outline = idx; save_cfg() end)\npanel:slider(\"FCT Scale\", 0.7, 3.0, cfg.fct_scale, function(v) cfg.fct_scale = v; save_cfg() end)\npanel:slider(\"FCT Duration (s)\", 0.5, 4.0, cfg.fct_dur, function(v) cfg.fct_dur = v; save_cfg() end)\npanel:slider(\"Crit Ratio\", 1.5, 8.0, cfg.crit_ratio, function(v) cfg.crit_ratio = v; save_cfg() end)\npanel:checkbox(\"Outgoing\", cfg.show_out, function(v) cfg.show_out = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Incoming\", cfg.show_in, function(v) cfg.show_in = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Heals\", cfg.show_heal, function(v) cfg.show_heal = (v == true); save_cfg() end)\npanel:checkbox(\"Include Nearby NPC Skirmishes\", cfg.include_nearby, function(v) cfg.include_nearby = (v == true); save_cfg() end)\npanel:checkbox(\"Merge Rapid Hits (0.18s)\", cfg.merge_rapid, function(v) cfg.merge_rapid = (v == true); save_cfg() end)\npanel:end_tab()\n\n-- Tab 2: Nameplates & Bars (23 widgets)\npanel:tab(\"Nameplates & Bars\")\npanel:checkbox(\"Enemy Nameplates\", cfg.np_enabled, function(v) cfg.np_enabled = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Live Preview Plate\", cfg.np_preview, function(v) cfg.np_preview = (v == true); save_cfg() end)\npanel:combo(\"Show Bars For\", FILTER_LABELS, cfg.np_filter, function(idx) cfg.np_filter = idx; last_poll_t = -10; save_cfg() end)\npanel:combo(\"Bar Style\", BAR_STYLE_LABELS, cfg.np_bar_style, function(idx) cfg.np_bar_style = idx; save_cfg() end)\npanel:slider(\"Width (px)\", 70, 260, cfg.np_width, function(v) cfg.np_width = v; save_cfg() end)\npanel:slider(\"Height (px)\", 6, 28, cfg.np_height, function(v) cfg.np_height = v; save_cfg() end)\npanel:slider(\"Bar Opacity\", 0.35, 1.0, cfg.np_opacity, function(v) cfg.np_opacity = v; save_cfg() end)\npanel:slider(\"Border Size\", 1, 4, cfg.np_border, function(v) cfg.np_border = v; save_cfg() end)\npanel:slider(\"Head Offset (m)\", 0.8, 3.8, cfg.np_head_offset, function(v) cfg.np_head_offset = v; save_cfg() end)\npanel:slider(\"Max Distance (m)\", 10, 90, cfg.np_max_dist, function(v) cfg.np_max_dist = v; save_cfg() end)\npanel:slider(\"Max Bars\", 1, 20, cfg.np_max_bars, function(v) cfg.np_max_bars = math.floor(v + 0.5); save_cfg() end)\npanel:checkbox(\"Distance Scale\", cfg.np_dist_scale, function(v) cfg.np_dist_scale = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Smoothing\", cfg.np_smooth, function(v) cfg.np_smooth = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Scale HP (/1000)\", cfg.np_scale_hp, function(v) cfg.np_scale_hp = (v == true); save_cfg() end)\npanel:slider(\"Preview X (%)\", 10, 90, cfg.np_prev_x, function(v) cfg.np_prev_x = v; save_cfg() end)\npanel:slider(\"Preview Y (%)\", 10, 85, cfg.np_prev_y, function(v) cfg.np_prev_y = v; save_cfg() end)\nlocal diag_l1 = panel:text(\"Diag: waiting for world...\")\nlocal diag_l2 = panel:text(\"Stats: ok=0 fail=0 | err=none\")\npanel:end_tab()\n\n-- Tab 3: Fonts, Text & Debuffs (21 widgets)\npanel:tab(\"Fonts & Debuffs\")\npanel:combo(\"Plate Outline\", OUTLINE_LABELS, cfg.np_outline, function(idx) cfg.np_outline = idx; save_cfg() end)\npanel:combo(\"Name Position\", NAME_POS_LABELS, cfg.np_name_pos, function(idx) cfg.np_name_pos = idx; save_cfg() end)\npanel:combo(\"Name Font\", FONT_LABELS, cfg.np_name_font, function(idx) cfg.np_name_font = idx; save_cfg() end)\npanel:slider(\"Name Size\", 0.7, 2.5, cfg.np_name_scale, function(v) cfg.np_name_scale = v; save_cfg() end)\npanel:slider(\"Name Gap (px)\", 2, 24, cfg.np_name_gap, function(v) cfg.np_name_gap = v; save_cfg() end)\npanel:checkbox(\"Dark Name Backdrop\", cfg.np_name_bg, function(v) cfg.np_name_bg = (v == true); save_cfg() end)\npanel:separator()\npanel:combo(\"HP Format\", HP_FMT_LABELS, cfg.np_hp_fmt, function(idx) cfg.np_hp_fmt = idx; save_cfg() end)\npanel:combo(\"HP Position\", HP_POS_LABELS, cfg.np_hp_pos, function(idx) cfg.np_hp_pos = idx; save_cfg() end)\npanel:combo(\"HP Font\", FONT_LABELS, cfg.np_hp_font, function(idx) cfg.np_hp_font = idx; save_cfg() end)\npanel:slider(\"HP Size\", 0.65, 2.2, cfg.np_hp_scale, function(v) cfg.np_hp_scale = v; save_cfg() end)\npanel:separator()\npanel:checkbox(\"Show Buffs / Debuffs\", cfg.np_show_debuffs, function(v) cfg.np_show_debuffs = (v == true); save_cfg() end)\npanel:combo(\"Debuff Pos\", DEBUFF_POS_LABELS, cfg.np_debuff_pos, function(idx) cfg.np_debuff_pos = idx; save_cfg() end)\npanel:combo(\"Debuff Style\", DEBUFF_STYLE_LABELS, cfg.np_debuff_style, function(idx) cfg.np_debuff_style = idx; save_cfg() end)\npanel:combo(\"Debuff Font\", FONT_LABELS, cfg.np_debuff_font, function(idx) cfg.np_debuff_font = idx; save_cfg() end)\npanel:slider(\"Debuff Size\", 0.65, 1.8, cfg.np_debuff_scale, function(v) cfg.np_debuff_scale = v; save_cfg() end)\npanel:slider(\"Debuff Gap (px)\", 2, 24, cfg.np_debuff_gap, function(v) cfg.np_debuff_gap = v; save_cfg() end)\npanel:slider(\"Max Debuffs\", 1, 6, cfg.np_debuff_max, function(v) cfg.np_debuff_max = math.floor(v + 0.5); save_cfg() end)\npanel:end_tab()\n\n-- Tab 4: Colors & Presets (14 widgets)\npanel:tab(\"Colors & Presets\")\npanel:combo(\"Theme Preset\", PRESET_LABELS, cfg.preset, function(idx)\n    cfg.preset = idx\n    local p = PRESETS[idx]\n    if p then\n        cfg.col_out, cfg.col_crit, cfg.col_in, cfg.col_heal = p.out, p.crit, p.inc, p.heal\n        cfg.col_nphp, cfg.col_npag, cfg.col_npname, cfg.col_nptext, cfg.col_npbg = p.hp, p.ag, p.name, p.hptxt, p.bg\n        panel:set_value(c_out, rgba_tbl(p.out)); panel:set_value(c_crit, rgba_tbl(p.crit))\n        panel:set_value(c_in, rgba_tbl(p.inc)); panel:set_value(c_heal, rgba_tbl(p.heal))\n        panel:set_value(c_nphp, rgba_tbl(p.hp)); panel:set_value(c_npag, rgba_tbl(p.ag))\n        panel:set_value(c_npname, rgba_tbl(p.name)); panel:set_value(c_nptext, rgba_tbl(p.hptxt))\n        panel:set_value(c_npbg, rgba_tbl(p.bg))\n    end\n    save_cfg()\nend)\nc_out = panel:color(\"Outgoing Hit\", rgba_tbl(cfg.col_out), function(_, h) cfg.col_out = h; save_cfg() end)\nc_crit = panel:color(\"Critical Hit\", rgba_tbl(cfg.col_crit), function(_, h) cfg.col_crit = h; save_cfg() end)\nc_in = panel:color(\"Incoming Hit\", rgba_tbl(cfg.col_in), function(_, h) cfg.col_in = h; save_cfg() end)\nc_heal = panel:color(\"Heal\", rgba_tbl(cfg.col_heal), function(_, h) cfg.col_heal = h; save_cfg() end)\nc_nphp = panel:color(\"Enemy HP Bar\", rgba_tbl(cfg.col_nphp), function(_, h) cfg.col_nphp = h; save_cfg() end)\nc_npag = panel:color(\"Aggro / Target Glow\", rgba_tbl(cfg.col_npag), function(_, h) cfg.col_npag = h; save_cfg() end)\nc_npname = panel:color(\"Nameplate Name\", rgba_tbl(cfg.col_npname), function(_, h) cfg.col_npname = h; save_cfg() end)\nc_nptext = panel:color(\"HP Text Color\", rgba_tbl(cfg.col_nptext), function(_, h) cfg.col_nptext = h; save_cfg() end)\nc_npbg = panel:color(\"Bar Background\", rgba_tbl(cfg.col_npbg), function(_, h) cfg.col_npbg = h; save_cfg() end)\npanel:separator()\npanel:button(\"Save Settings Now\", function() save_cfg(); bsx.ui.toast(\"Saved Combat Meter settings\", { level = \"ok\" }) end)\npanel:end_tab()\npanel:end_tab_bar()\n\n-- Event Listeners\nbsx.on(\"battle_state\", function(e)\n    local now = os.clock()\n    if e and e.in_battle then\n        if not in_fight then in_fight, fight_start = true, now end\n        last_activity = now\n    else\n        in_fight = false\n    end\nend)\n\nbsx.on(\"death\", function() kills = kills + 1 end)\n\nbsx.on(\"world_ready\", function()\n    plate_state, active_cands, recent_hits, aggro_cache, floaters = {}, {}, {}, {}, {}\n    last_poll_t = -10.0\nend)\n\nbsx.on(\"title_screen\", function()\n    plate_state, active_cands, recent_hits, aggro_cache, floaters = {}, {}, {}, {}, {}\nend)\n\nbsx.on(\"combat_damage\", function(e)\n    if not e or not e.amount or e.amount \u003c= 0 then return end\n    local now = os.clock()\n    if e.target_key and e.target_key > 0 then recent_hits[e.target_key] = now end\n    if e.is_heal then\n        if cfg.show_heal and (e.is_player_target or cfg.include_nearby) then\n            spawn_floater(\"heal\", e.amount, false, e.target_key)\n        end\n        return\n    end\n    if e.is_player_attacker then\n        if not in_fight then in_fight, fight_start = true, now end\n        last_activity = now\n        dmg_out = dmg_out + e.amount\n        hits_out = hits_out + 1\n        if e.amount > peak_hit then peak_hit = e.amount end\n        dps_ring[#dps_ring + 1] = { t = now, a = e.amount }\n        local is_crit = e.amount >= (avg_out_hit() * cfg.crit_ratio)\n        if is_crit then heavy_out = heavy_out + 1 end\n        combo_total = ((now - combo_ts) \u003c= 2.4) and (combo_total + e.amount) or e.amount\n        combo_ts = now\n        if cfg.show_out then spawn_floater(\"out\", e.amount, is_crit, e.target_key) end\n    elseif e.is_player_target then\n        if not in_fight then in_fight, fight_start = true, now end\n        last_activity = now\n        dmg_in = dmg_in + e.amount\n        if cfg.show_in then spawn_floater(\"in\", e.amount, false, e.target_key) end\n    elseif cfg.include_nearby and cfg.show_out then\n        spawn_floater(\"out\", e.amount, false, e.target_key)\n    end\nend)\n\n-- Name & Buff Helpers\nlocal function actor_display_name(a)\n    if a.display_name and #a.display_name > 0 then return a.display_name end\n    if a.character_row and game.characters and game.characters.info then\n        local c = char_name_cache[a.character_row]\n        if c == nil then\n            local ok, info = pcall(game.characters.info, a.character_row)\n            c = (ok and info and ((info.display_name and #info.display_name > 0 and info.display_name) or tidy_name(info.name))) or false\n            char_name_cache[a.character_row] = c\n        end\n        if type(c) == \"string\" and #c > 0 then return c end\n    end\n    if a.character_name and #a.character_name > 0 then\n        local t = tidy_name(a.character_name)\n        if #t > 0 then return t end\n    end\n    return \"Actor #\" .. tostring(a.key)\nend\n\nlocal function format_buff_tag(b)\n    local lbl = (b.name and #b.name > 0) and tidy_name(b.name) or nil\n    if not lbl then\n        if b.buff_row and game.buffs and game.buffs.info then\n            local c = buff_name_cache[\"b\" .. b.buff_row]\n            if c == nil then\n                local ok, info = pcall(game.buffs.info, b.buff_row)\n                c = (ok and info and tidy_name(info.name)) or false\n                buff_name_cache[\"b\" .. b.buff_row] = c\n            end\n            if type(c) == \"string\" and #c > 0 then lbl = c end\n        elseif b.skill_row and game.skills and game.skills.info then\n            local c = buff_name_cache[\"s\" .. b.skill_row]\n            if c == nil then\n                local ok, info = pcall(game.skills.info, b.skill_row)\n                c = (ok and info and tidy_name(info.name)) or false\n                buff_name_cache[\"s\" .. b.skill_row] = c\n            end\n            if type(c) == \"string\" and #c > 0 then lbl = c end\n        end\n    end\n    lbl = trim_text(lbl or (\"Fx#\" .. tostring(b.buff_row or b.skill_row or b.sub_index or 0)), 14)\n    if b.level and b.level > 1 then lbl = lbl .. \" \" .. tostring(b.level) end\n    local lo = lbl:lower()\n    local accent = \"#3898ECFF\"\n    if lo:find(\"burn\") or lo:find(\"fire\") or lo:find(\"flame\") or lo:find(\"ignite\") then accent = \"#E84A1EFF\"\n    elseif lo:find(\"frost\") or lo:find(\"ice\") or lo:find(\"chill\") or lo:find(\"freez\") then accent = \"#18B4E8FF\"\n    elseif lo:find(\"stun\") or lo:find(\"shock\") or lo:find(\"light\") or lo:find(\"thun\") then accent = \"#E8A618FF\"\n    elseif lo:find(\"bleed\") or lo:find(\"blood\") or lo:find(\"rupt\") then accent = \"#D9265AFF\"\n    elseif lo:find(\"poison\") or lo:find(\"venom\") or lo:find(\"acid\") then accent = \"#2EB85CFF\"\n    elseif lo:find(\"curse\") or lo:find(\"dark\") or lo:find(\"hex\") then accent = \"#A03CF0FF\" end\n    return lbl, accent\nend\n\nlocal function format_hp_text(hp_cur, hp_max, stat_ok)\n    if cfg.np_hp_fmt == 5 then return \"\" end\n    if not stat_ok or not hp_max or hp_max \u003c= 0 then return \"HP: --\" end\n    local cur_v = tonumber(hp_cur) or 0\n    local div = (cfg.np_scale_hp and hp_max >= 1000) and 1000 or 1\n    local d_cur = (cur_v > 0) and math.max(1, math.floor(cur_v / div + 0.5)) or 0\n    local d_max = math.max(1, math.floor(hp_max / div + 0.5))\n    local pct = math.floor(clamp(cur_v / hp_max, 0, 1) * 100 + 0.5)\n    if cfg.np_hp_fmt == 1 then return fmt_num(d_cur) .. \" / \" .. fmt_num(d_max)\n    elseif cfg.np_hp_fmt == 2 then return string.format(\"%s (%d%%)\", fmt_num(d_cur), pct)\n    elseif cfg.np_hp_fmt == 3 then return tostring(pct) .. \"%\"\n    else return fmt_num(d_cur) end\nend\n\nlocal function poll_candidates(now, actors, pk, pfac, px, py, pz, tgt_key)\n    diag.world = true\n    diag.total_actors = actors.total or #actors\n    diag.pfac = pfac or -1\n    diag.tgt_key = tgt_key\n\n    -- Collect living non-controlled actors with computed distance\n    local pool = {}\n    for i = 1, #actors do\n        local a = actors[i]\n        if a and not a.controlled and not a.dead and a.key and a.key ~= 0 then\n            local d = a.distance\n            if d == nil and px and a.x then\n                local dx, dy, dz = a.x - px, a.y - py, a.z - pz\n                d = math.sqrt(dx * dx + dy * dy + dz * dz)\n            end\n            d = d or 999\n            local max_allowed = (a.key == tgt_key) and (cfg.np_max_dist * 1.5) or cfg.np_max_dist\n            if d \u003c= max_allowed then\n                pool[#pool + 1] = { a = a, d = d }\n            end\n        end\n    end\n    diag.near = #pool\n    table.sort(pool, function(u, v) return u.d \u003c v.d end)\n\n    -- Pre-poll has_aggro up to nearest 32 actors before filtering so aggro enemies never miss\n    local aggro_budget = 0\n    if pk ~= 0 and game.actors and game.actors.has_aggro then\n        for i = 1, #pool do\n            local a = pool[i].a\n            if aggro_budget \u003c 32 then\n                local ok_ag, is_ag = pcall(game.actors.has_aggro, a.key, pk)\n                if ok_ag and is_ag ~= nil then aggro_cache[a.key] = (is_ag == true) end\n                aggro_budget = aggro_budget + 1\n            end\n        end\n    end\n\n    local next_cands = {}\n    local ok_cnt, fail_cnt = 0, 0\n    local err_sample = nil\n    for i = 1, #pool do\n        local a, d = pool[i].a, pool[i].d\n        local is_tgt = (a.key == tgt_key and tgt_key ~= 0)\n        local is_ag = aggro_cache[a.key] == true\n        local is_hit = (recent_hits[a.key] ~= nil) and ((now - recent_hits[a.key]) \u003c= 15.0)\n        local ag = nil\n        if pfac and a.faction and game.factions and game.factions.agreement then\n            local ok_f, res = pcall(game.factions.agreement, pfac, a.faction)\n            if ok_f then ag = res end\n        end\n        local same_fac = (pfac ~= nil and a.faction ~= nil and a.faction == pfac) or (ag == 3)\n\n        local pass = false\n        if cfg.np_filter == 1 then\n            pass = is_tgt or is_ag or is_hit or ((not same_fac) and (a.kind ~= \"child\"))\n        elseif cfg.np_filter == 2 then\n            pass = is_tgt or is_ag or is_hit or ((not same_fac) and (ag == nil or ag \u003c= 2) and (a.kind ~= \"child\"))\n        elseif cfg.np_filter == 3 then\n            pass = is_tgt or is_ag or is_hit\n        else\n            pass = true\n        end\n\n        if pass then\n            local st = plate_state[a.key] or {\n                key = a.key, trail_frac = 1.0, last_dmg_t = 0.0\n            }\n            st.actor = a.actor\n            st.dist = d\n            st.name = actor_display_name(a)\n            st.aggro = is_ag\n            st.targeted = is_tgt\n            st.hit = is_hit\n            st.kind = a.kind or \"?\"\n            st.fac = a.faction or -1\n            st.ag_code = ag or -1\n            if a.x then st.wx, st.wy, st.wz = a.x, a.y, a.z end\n\n            if game.stats and game.stats.read then\n                local sr, serr = game.stats.read(a.actor, 0)\n                if sr and sr.max and sr.max > 0 then\n                    local frac = clamp((sr.current or 0) / sr.max, 0.0, 1.0)\n                    if not st.hp_frac or frac > st.hp_frac then\n                        st.trail_frac = frac\n                    elseif frac \u003c st.hp_frac then\n                        st.last_dmg_t = now\n                    end\n                    st.hp_cur = sr.current or 0\n                    st.hp_max = sr.max\n                    st.hp_frac = frac\n                    st.stat_ok = true\n                    ok_cnt = ok_cnt + 1\n                else\n                    st.stat_ok = st.hp_max ~= nil and st.hp_max > 0\n                    fail_cnt = fail_cnt + 1\n                    err_sample = err_sample or tostring(serr or \"no max hp\")\n                end\n            end\n\n            if cfg.np_show_debuffs and game.buffs and game.buffs.active then\n                local ok_b, blist = pcall(game.buffs.active, a.key)\n                if ok_b and type(blist) == \"table\" then\n                    local tags = {}\n                    for bi = 1, math.min(#blist, cfg.np_debuff_max) do\n                        local ttxt, tcol = format_buff_tag(blist[bi])\n                        tags[#tags + 1] = { text = ttxt, col = tcol }\n                    end\n                    st.buffs = tags\n                end\n            else\n                st.buffs = nil\n            end\n\n            -- Show bar if stats valid, OR if locked/aggro/hit/debug mode\n            local show_fallback = is_tgt or is_ag or is_hit or (cfg.np_filter == 4)\n            if st.stat_ok or show_fallback then\n                plate_state[a.key] = st\n                next_cands[#next_cands + 1] = st\n            end\n        end\n    end\n\n    table.sort(next_cands, function(u, v)\n        if u.targeted ~= v.targeted then return u.targeted end\n        return (u.dist or 999) \u003c (v.dist or 999)\n    end)\n    while #next_cands > cfg.np_max_bars do table.remove(next_cands) end\n    active_cands = next_cands\n    diag.cands = #active_cands\n    diag.stats_ok = ok_cnt\n    diag.stats_fail = fail_cnt\n    if err_sample then diag.last_err = trim_text(err_sample, 28) elseif ok_cnt > 0 then diag.last_err = \"ok\" end\nend\n\nlocal function draw_debuff_strip(st_buffs, bw, bar_x, bar_y, bh, name_top_y, bot_bottom_y, outline, dfont, dscale, dgap, a_mul)\n    if not cfg.np_show_debuffs or not st_buffs or #st_buffs == 0 then return end\n    local count = math.min(#st_buffs, cfg.np_debuff_max)\n    local pills, total_w, max_h = {}, 0, 14\n    for i = 1, count do\n        local b = st_buffs[i]\n        local m = bsx.draw.measure_text(b.text, dscale, dfont)\n        local pw = math.floor(m.w + 12)\n        local ph = math.floor(math.max(15, m.h + 5))\n        if ph > max_h then max_h = ph end\n        pills[i] = { text = b.text, col = b.col, w = pw, h = ph, tw = m.w, th = m.h }\n        total_w = total_w + pw + (i > 1 and 4 or 0)\n    end\n\n    local pos = cfg.np_debuff_pos\n    if pos == 1 or pos == 2 then\n        local px = bar_x + (bw - total_w) * 0.5\n        local py = (pos == 1) and (name_top_y - dgap - max_h) or (bot_bottom_y + dgap)\n        for i = 1, count do\n            local p = pills[i]\n            local bg_col, brd_col, txt_col\n            if cfg.np_debuff_style == 1 then\n                bg_col = scale_alpha(p.col, a_mul * 0.90)\n                brd_col = scale_alpha(\"#FFFFFFE6\", a_mul)\n                txt_col = scale_alpha(\"#FFFFFFFF\", a_mul)\n            elseif cfg.np_debuff_style == 2 then\n                bg_col = scale_alpha(\"#0E1016EB\", a_mul)\n                brd_col = scale_alpha(p.col, a_mul)\n                txt_col = scale_alpha(\"#FFFFFFFF\", a_mul)\n            else\n                bg_col, brd_col, txt_col = nil, nil, scale_alpha(p.col, a_mul)\n            end\n            if bg_col then\n                bsx.draw.rect(px, py, p.w, p.h, bg_col, true)\n                bsx.draw.rect(px, py, p.w, p.h, brd_col, false, 1.5)\n            end\n            bsx.draw.text(px + (p.w - p.tw) * 0.5, py + (p.h - p.th) * 0.5, p.text, txt_col, dscale, dfont, outline)\n            px = px + p.w + 4\n        end\n    else\n        -- Left (3) or Right (4) stacked or inline beside bar\n        local cur_x = (pos == 3) and (bar_x - 6) or (bar_x + bw + 6)\n        local py = bar_y + (bh - max_h) * 0.5\n        for i = 1, count do\n            local p = pills[i]\n            local rx = (pos == 3) and (cur_x - p.w) or cur_x\n            if cfg.np_debuff_style ~= 3 then\n                local bg = (cfg.np_debuff_style == 1) and scale_alpha(p.col, a_mul * 0.90) or scale_alpha(\"#0E1016EB\", a_mul)\n                local brd = (cfg.np_debuff_style == 1) and scale_alpha(\"#FFFFFFE6\", a_mul) or scale_alpha(p.col, a_mul)\n                bsx.draw.rect(rx, py, p.w, p.h, bg, true)\n                bsx.draw.rect(rx, py, p.w, p.h, brd, false, 1.5)\n            end\n            local tc = (cfg.np_debuff_style == 3) and scale_alpha(p.col, a_mul) or scale_alpha(\"#FFFFFFFF\", a_mul)\n            bsx.draw.text(rx + (p.w - p.tw) * 0.5, py + (p.h - p.th) * 0.5, p.text, tc, dscale, dfont, outline)\n            cur_x = (pos == 3) and (rx - 4) or (rx + p.w + 4)\n        end\n    end\nend\n\nlocal function draw_nameplate(cx, bar_y, bw, bh, scale_mul, label, hp_cur, hp_max, hp_frac, trail_frac, stat_ok, is_ag, is_tgt, buffs)\n    local outline = OUTLINE_NAMES[cfg.np_outline] or \"heavy\"\n    local nfont = FONT_NAMES[cfg.np_name_font] or \"bold\"\n    local hfont = FONT_NAMES[cfg.np_hp_font] or \"sans\"\n    local dfont = FONT_NAMES[cfg.np_debuff_font] or \"bold\"\n    local nscale = clamp(cfg.np_name_scale * scale_mul, 0.55, 3.0)\n    local hscale = clamp(cfg.np_hp_scale * scale_mul, 0.55, 2.8)\n    local dscale = clamp(cfg.np_debuff_scale * scale_mul, 0.55, 2.4)\n    local brd = clamp(cfg.np_border * scale_mul, 1, 5)\n    local a_mul = cfg.np_opacity\n    local bx = cx - bw * 0.5\n\n    -- Bar Background & Drain Trail & Fill\n    bsx.draw.rect(bx, bar_y, bw, bh, scale_alpha(cfg.col_npbg, a_mul), true)\n    local frac = clamp(hp_frac or 1.0, 0.0, 1.0)\n    local tf = clamp(trail_frac or frac, frac, 1.0)\n    if tf > frac + 0.004 then\n        bsx.draw.rect(bx + 1, bar_y + 1, math.max(0, (bw - 2) * tf), math.max(1, bh - 2), scale_alpha(\"#FFF2C2CC\", a_mul), true)\n    end\n    local fill_col = stat_ok and cfg.col_nphp or \"#565E73FF\"\n    local fill_w = math.max(0, (bw - 2) * frac)\n    if fill_w >= 1 then\n        bsx.draw.rect(bx + 1, bar_y + 1, fill_w, math.max(1, bh - 2), scale_alpha(fill_col, a_mul), true)\n        if cfg.np_bar_style == 1 and bh >= 8 then\n            bsx.draw.rect(bx + 1, bar_y + 1, fill_w, math.max(1, math.floor((bh - 2) * 0.36)), scale_alpha(\"#FFFFFF2B\", a_mul), true)\n        end\n    end\n\n    -- Segmented 25% tick lines\n    if cfg.np_bar_style == 2 then\n        for q = 1, 3 do\n            local tx = bx + bw * (q * 0.25)\n            bsx.draw.line(tx, bar_y + 1, tx, bar_y + bh - 1, scale_alpha(\"#000000B0\", a_mul), 1.5)\n        end\n    end\n\n    -- Outer Frame Border (Aggro / Target highlight)\n    local frame_col = is_tgt and \"#FFFFFFFF\" or (is_ag and cfg.col_npag or \"#181B24F0\")\n    local thick = is_tgt and (brd + 1) or (is_ag and (brd + 0.5) or brd)\n    bsx.draw.rect(bx, bar_y, bw, bh, scale_alpha(frame_col, a_mul), false, thick)\n\n    -- Nameplate Title using exact measure_text clearance\n    local name_top_y = bar_y - brd\n    local bot_bottom_y = bar_y + bh + brd\n    if cfg.np_name_pos ~= 3 and label and #label > 0 then\n        local nm = bsx.draw.measure_text(label, nscale, nfont)\n        local nx = cx - nm.w * 0.5\n        local ny\n        if cfg.np_name_pos == 1 then\n            ny = bar_y - brd - cfg.np_name_gap - nm.h\n            name_top_y = ny - (cfg.np_name_bg and 2 or 0)\n        else\n            ny = bar_y + bh + brd + cfg.np_name_gap\n            bot_bottom_y = ny + nm.h + (cfg.np_name_bg and 2 or 0)\n        end\n        if cfg.np_name_bg then\n            bsx.draw.rect(nx - 6, ny - 2, nm.w + 12, nm.h + 4, scale_alpha(\"#090B11A8\", a_mul), true)\n        end\n        bsx.draw.text(nx, ny, label, scale_alpha(cfg.col_npname, a_mul), nscale, nfont, outline)\n    end\n\n    -- HP Text (4 placement options + 5 formats)\n    local hptxt = format_hp_text(hp_cur, hp_max, stat_ok)\n    if #hptxt > 0 then\n        local hm = bsx.draw.measure_text(hptxt, hscale, hfont)\n        local hx, hy\n        if cfg.np_hp_pos == 1 then\n            hx = cx - hm.w * 0.5\n            hy = bar_y + (bh - hm.h) * 0.5\n        elseif cfg.np_hp_pos == 2 then\n            hx = bx + bw + 8\n            hy = bar_y + (bh - hm.h) * 0.5\n        elseif cfg.np_hp_pos == 3 then\n            hx = bx + bw - hm.w\n            hy = bar_y - brd - hm.h - 2\n            name_top_y = math.min(name_top_y, hy)\n        else\n            hx = cx - hm.w * 0.5\n            hy = bot_bottom_y + 3\n            bot_bottom_y = hy + hm.h\n        end\n        bsx.draw.text(hx, hy, hptxt, scale_alpha(cfg.col_nptext, a_mul), hscale, hfont, outline)\n    end\n\n    draw_debuff_strip(buffs, bw, bx, bar_y, bh, name_top_y, bot_bottom_y, outline, dfont, dscale, cfg.np_debuff_gap, a_mul)\nend\n\n-- Per-Frame Draw Loop\nbsx.on(\"frame\", function()\n    local now = os.clock()\n    local dt = clamp(now - last_frame_t, 0.001, 0.1)\n    last_frame_t = now\n    bsx.draw.clear()\n\n    local sys = bsx.system and bsx.system.info and bsx.system.info() or nil\n    local vw = (sys and sys.viewport_w and sys.viewport_w > 0) and sys.viewport_w or 1920\n    local vh = (sys and sys.viewport_h and sys.viewport_h > 0) and sys.viewport_h or 1080\n    local cx, cy = vw * 0.5, vh * 0.5\n\n    -- 1) Live World Actors & Smooth Nameplates\n    local actors = game.actors and game.actors(256) or nil\n    local ps = game.player_state and game.player_state() or nil\n    if actors then\n        local ppos = game.player_position and game.player_position() or nil\n        local px = ppos and ppos.x or nil\n        local py = ppos and ppos.y or nil\n        local pz = ppos and ppos.z or nil\n        local pk = 0\n        local pfac = ps and ps.faction or nil\n        for i = 1, #actors do\n            if actors[i].controlled then\n                pk = actors[i].key or 0\n                pfac = pfac or actors[i].faction\n                if not px and actors[i].x then\n                    px, py, pz = actors[i].x, actors[i].y, actors[i].z\n                end\n                break\n            end\n        end\n        local tgt, tgt_err = game.world and game.world.target and game.world.target() or nil\n        local tgt_key = (tgt and tgt.actor_key) or 0\n\n        if (now - last_poll_t) >= 0.10 then\n            last_poll_t = now\n            poll_candidates(now, actors, pk, pfac, px, py, pz, tgt_key)\n        else\n            -- Refresh live XYZ at full framerate so moving targets glide cleanly\n            local by_key = {}\n            for i = 1, #actors do\n                local a = actors[i]\n                if a and a.key then by_key[a.key] = a end\n            end\n            for i = 1, #active_cands do\n                local st = active_cands[i]\n                local live = by_key[st.key]\n                if live and live.x then st.wx, st.wy, st.wz = live.x, live.y, live.z end\n                if live and live.distance then st.dist = live.distance end\n                st.targeted = (st.key == tgt_key and tgt_key ~= 0)\n            end\n        end\n\n        local shown_cnt, cam_status = 0, \"ok\"\n        if cfg.np_enabled and game.camera and game.camera.world_to_screen then\n            local smooth_k = 1.0 - math.exp(-24.0 * dt)\n            for i = 1, #active_cands do\n                local st = active_cands[i]\n                if st.wx then\n                    if not st.swx or not cfg.np_smooth then\n                        st.swx, st.swy, st.swz = st.wx, st.wy, st.wz\n                    else\n                        local jx, jy, jz = st.wx - st.swx, st.wy - st.swy, st.wz - st.swz\n                        if (jx * jx + jy * jy + jz * jz) > 6.25 then\n                            st.swx, st.swy, st.swz = st.wx, st.wy, st.wz\n                        else\n                            st.swx = st.swx + jx * smooth_k\n                            st.swy = st.swy + jy * smooth_k\n                            st.swz = st.swz + jz * smooth_k\n                        end\n                    end\n                    local head_y = st.swy + cfg.np_head_offset\n                    local scr, cam_err = game.camera.world_to_screen(st.swx, head_y, st.swz)\n                    if scr then\n                        if scr.on_screen then\n                            local sc = cfg.np_dist_scale and clamp(14.0 / math.max(8.0, st.dist or 14.0), 0.72, 1.25) or 1.0\n                            if st.trail_frac > (st.hp_frac or 1.0) and (now - st.last_dmg_t) > 0.35 then\n                                st.trail_frac = math.max(st.hp_frac or 1.0, st.trail_frac - dt * 0.45)\n                            end\n                            local lbl = (cfg.np_filter == 4)\n                                and string.format(\"%s [%s f=%s a=%s]\", st.name, st.kind, tostring(st.fac), tostring(st.ag_code))\n                                or st.name\n                            draw_nameplate(scr.x, scr.y, cfg.np_width * sc, cfg.np_height * sc, sc,\n                                lbl, st.hp_cur, st.hp_max, st.hp_frac, st.trail_frac, st.stat_ok, st.aggro, st.targeted, st.buffs)\n                            shown_cnt = shown_cnt + 1\n                        end\n                    elseif cam_err then\n                        cam_status = trim_text(cam_err, 22)\n                    end\n                end\n            end\n        elseif not (game.camera and game.camera.world_to_screen) then\n            cam_status = \"no camera api\"\n        end\n        diag.shown = shown_cnt\n        diag.cam = string.format(\"%s %dx%d\", cam_status, vw, vh)\n    else\n        diag.world = false\n        diag.cam = \"no actors\"\n    end\n\n    -- 2) Persistent Live Preview Nameplate (always visible while toggled ON)\n    if cfg.np_preview then\n        local px_s = vw * (cfg.np_prev_x / 100.0)\n        local py_s = vh * (cfg.np_prev_y / 100.0)\n        local wave = 0.48 + 0.14 * math.sin(now * 1.4)\n        local p_cur = math.floor(18500000 * wave)\n        local p_buffs = cfg.np_show_debuffs and {\n            { text = \"Burn 2\", col = \"#E84A1EFF\" },\n            { text = \"Stun\", col = \"#E8A618FF\" },\n            { text = \"Bleed 3\", col = \"#D9265AFF\" },\n        } or nil\n        draw_nameplate(px_s, py_s, cfg.np_width, cfg.np_height, 1.0,\n            \"Crimson Sentinel [Preview]\", p_cur, 18500000, wave, math.min(1.0, wave + 0.10), true, true, false, p_buffs)\n    end\n\n    -- 3) Floating Combat Text (5 visual styles; 6 = HUD only)\n    if cfg.fct_enabled and cfg.fct_style ~= 6 then\n        local font_name = FONT_NAMES[cfg.fct_font] or \"impact\"\n        local text_style = OUTLINE_NAMES[cfg.fct_outline] or \"heavy\"\n        local alive = {}\n        for i = 1, #floaters do\n            local f = floaters[i]\n            local age = now - f.t0\n            if age \u003c cfg.fct_dur then\n                alive[#alive + 1] = f\n                local p = clamp(age / cfg.fct_dur, 0.0, 1.0)\n                local alpha = (p > 0.68) and (1.0 - (p - 0.68) / 0.32) or 1.0\n                local base_col = (f.kind == \"heal\") and cfg.col_heal or ((f.kind == \"in\") and cfg.col_in or (f.crit and cfg.col_crit or cfg.col_out))\n                local pop = (f.crit and age \u003c 0.18) and (1.35 - age * 1.6) or 1.0\n                local fscale = clamp(cfg.fct_scale * (f.crit and 1.32 or 1.0) * pop, 0.65, 3.8)\n                local sx, sy = cx + f.jx, cy - p * 165\n\n                if cfg.fct_style == 1 and f.wx and game.camera and game.camera.world_to_screen then\n                    local scr = game.camera.world_to_screen(f.wx, f.wy + p * 1.4, f.wz)\n                    if scr and scr.on_screen then sx, sy = scr.x + f.jx * 0.6, scr.y end\n                elseif cfg.fct_style == 3 then\n                    sx = (f.kind == \"in\") and (cx - 210) or ((f.kind == \"heal\") and (cx - 110) or (cx + 185))\n                    sy = cy + 60 - p * 210\n                elseif cfg.fct_style == 4 then\n                    local rad = 40 + p * 170\n                    sx, sy = cx + math.cos(f.ang) * rad, cy + math.sin(f.ang) * rad\n                elseif cfg.fct_style == 5 then\n                    sx, sy = cx + f.jx * 0.7, cy - 35 - p * 155\n                else\n                    local arc = math.sin(p * math.pi)\n                    if f.kind == \"in\" then sx, sy = cx - 175 - arc * 58 + f.jx * 0.4, cy - 20 + p * 145\n                    elseif f.kind == \"heal\" then sx, sy = cx - 80 - f.jx * 0.4, cy + 35 - p * 140\n                    else sx, sy = cx + 150 + arc * 78 + f.jx * 0.5, cy + 45 - p * 195 end\n                end\n\n                local fm = bsx.draw.measure_text(f.text, fscale, font_name)\n                bsx.draw.text(sx - fm.w * 0.5, sy, f.text, scale_alpha(base_col, alpha), fscale, font_name, text_style)\n            end\n        end\n        floaters = alive\n\n        if cfg.fct_style == 5 and combo_total > 0 and (now - combo_ts) \u003c= 2.8 then\n            local c_age = now - combo_ts\n            local ca = (c_age > 2.0) and (1.0 - (c_age - 2.0) / 0.8) or 1.0\n            local cscale = clamp(cfg.fct_scale * (c_age \u003c 0.14 and 1.45 or 1.25), 0.8, 3.5)\n            bsx.draw.text(cx + 155, cy - 34, \"COMBO \" .. fmt_num(combo_total), scale_alpha(cfg.col_crit, ca), cscale, font_name, text_style)\n        end\n    end\nend)\n\nbsx.every(250, function()\n    local now = os.clock()\n    local end_t = in_fight and now or ((last_activity > fight_start) and last_activity or fight_start)\n    local elapsed = (fight_start > 0 and end_t > fight_start) and math.max(0.1, end_t - fight_start) or 0.0\n    local dps = elapsed > 0 and (dmg_out / elapsed) or 0.0\n    local dps5 = in_fight and rolling_5s_dps(now) or 0.0\n    local l1 = string.format(\"%s | DPS: %s | 5s: %s | %.1fs\",\n        in_fight and \"IN COMBAT\" or \"IDLE\", fmt_num(dps), fmt_num(dps5), elapsed)\n    local l2 = string.format(\"Dmg: %s | Peak: %s | Hits: %d | Kills: %d\",\n        fmt_num(dmg_out), fmt_num(peak_hit), hits_out, kills)\n    hud:set_text(hud_l1, trim_text(l1, 125))\n    hud:set_text(hud_l2, trim_text(l2, 125))\n    panel:set_text(panel_summary, trim_text(l1 .. \" | Heavy: \" .. tostring(heavy_out) .. \" | Taken: \" .. fmt_num(dmg_in), 125))\n\n    local dl1 = string.format(\"Diag: world=%s actors=%d near=%d cands=%d shown=%d filt=%d | %s\",\n        diag.world and \"Y\" or \"N\", diag.total_actors, diag.near, diag.cands, diag.shown, cfg.np_filter, diag.cam)\n    local dl2 = string.format(\"Stats: ok=%d fail=%d | pfac=%d tgt=%d | err=%s\",\n        diag.stats_ok, diag.stats_fail, diag.pfac, diag.tgt_key, diag.last_err)\n    panel:set_text(diag_l1, trim_text(dl1, 125))\n    panel:set_text(diag_l2, trim_text(dl2, 125))\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Combat Meter, Floating Text & Nameplates\",\n  \"version\": \"2.0.0\",\n  \"lua_api\": 7,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"inventory\", \"definitions\"]\n}\n","lang":"json","name":"script.json"},{"code":"[FCT]\nCritRatio=3\nDuration=1.85\nEnabled=1\nIncludeNearby=0\nScale=1.91\nShowHeal=0\nShowIncoming=0\nShowOutgoing=1\nStyle=1\n\nFont=1\nMergeRapid=1\nOutline=3\nOutlineStyle=1\n[HUD]\nPinned=1\n\n[Colors]\nCrit=#FFD100FF\nHeal=#3BE87AFF\nIncoming=#FF3B4EFF\nNameplateAggro=#FFB020FF\nNameplateHP=#D92B38FF\nOutgoing=#FFF5D6FF\nPreset=1\n\nNameplateBG=#0C0E14D8\nNameplateName=#FFFFFFFF\nNameplateText=#FFFFFFFF\n[Nameplates]\nBarHeight=22.95\nBarWidth=161.72\nDistanceScale=1\nEnabled=1\nFilter=2\nHeadOffset=2.38\nMaxDistance=55.47\nShowDebuffs=0\nShowHPText=1\n\nBarStyle=3\nBorderSize=4\nFilterMode=2\nHPFont=4\nHPFormat=1\nHPPos=1\nHPScale=0.95\nLivePreview=0\nMaxBars=12\nNameBackdrop=0\nNameFont=5\nNameGap=6\nNamePos=1\nNameScale=1.15\nOpacity=1\nOutlineStyle=1\nPreviewX=50.07\nPreviewY=32.08\nScaleHP1000=1\nSmoothMotion=1\n[Debuffs]\nFont=2\nGap=6\nMaxPills=4\nPosition=1\nScale=0.92\nStyle=1\n","lang":"ini","name":"settings.ini"}],"id":"recipe_dps_meter","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/dps_meter","tier":"safe","title":"Recipe: Floating Combat Text, Enemy Nameplates & DPS Meter","uses":["ui","player","snapshots","positions","inventory","definitions"]},{"category":"Cookbook Recipes","description":"FastLoad-inspired Safe-tier telemetry mod measuring startup, fast-travel, and save-reload durations (load_request -> world_ready), tracking working-set RAM MB, logging to data/load_history.csv, showing avg/best/worst stats in F10, and copying a benchmark summary.","featured":true,"files":[{"code":"-- FastLoad-Inspired Load-Time Profiler & History CSV Logger (Safe tier, Lua API 7+)\nlocal CSV_FILE = \"load_history.csv\"\nlocal startup_time = os.clock()\nlocal first_world_done = false\n\nlocal cfg = {\n    show_toast = config.bool(\"Profiler\", \"LoadToast\", true),\n    save_csv = config.bool(\"Profiler\", \"SaveCSV\", true)\n}\n\nlocal function save_cfg()\n    config.set(\"Profiler\", \"LoadToast\", cfg.show_toast)\n    config.set(\"Profiler\", \"SaveCSV\", cfg.save_csv)\n    config.save()\nend\n\nlocal pending = nil -- { kind, start_t, stage, prev_stage, save_key }\nlocal records = {}  -- { kind, sec, ram_mb, stage, follow_save }\n\nlocal function parse_csv_history()\n    if not (bsx.fs and bsx.fs.exists and bsx.fs.exists(CSV_FILE)) then return end\n    local ok, raw = pcall(bsx.fs.read, CSV_FILE)\n    if not ok or type(raw) ~= \"string\" then return end\n    for line in raw:gmatch(\"[^\\r\\n]+\") do\n        if not line:match(\"^kind,\") then\n            local k, sec_s, ram_s, stg_s, fs_s = line:match(\"^([^,]+),([^,]+),([^,]+),([^,]+),([^,]+)$\")\n            local sec = tonumber(sec_s)\n            if k and sec and sec > 0 then\n                records[#records + 1] = {\n                    kind = k,\n                    sec = sec,\n                    ram_mb = tonumber(ram_s) or 0,\n                    stage = tonumber(stg_s) or 0,\n                    follow_save = (fs_s == \"1\" or fs_s == \"true\")\n                }\n            end\n        end\n    end\n    while #records > 40 do table.remove(records, 1) end\nend\n\nlocal function write_csv_history()\n    if not cfg.save_csv or not (bsx.fs and bsx.fs.write) then return end\n    local lines = { \"kind,seconds,ram_mb,stage,follows_save\" }\n    for i = 1, #records do\n        local r = records[i]\n        lines[#lines + 1] = string.format(\"%s,%.2f,%.0f,%d,%s\",\n            r.kind, r.sec, r.ram_mb or 0, r.stage or 0, r.follow_save and \"1\" or \"0\")\n    end\n    pcall(bsx.fs.write, CSV_FILE, table.concat(lines, \"\\n\") .. \"\\n\")\nend\n\nparse_csv_history()\n\nlocal ok_p, panel = pcall(bsx.ui.panel, \"Load-Time Profiler\")\nif not ok_p then panel = nil end\nif panel and panel.set_theme then\n    pcall(panel.set_theme, panel, {\n        accent = \"#38BDF8\",\n        header = \"#0F1E2E\",\n        child_bg = \"#0E141B\",\n        border = \"#1E3A5F\"\n    })\nend\n\nlocal w_stats = panel and panel:text(\"No loads recorded yet.\") or nil\nlocal w_last = panel and panel:text(\"Last Load: --\") or nil\nlocal w_recent = {}\n\nlocal function compute_summary()\n    if #records == 0 then\n        return \"No loads recorded yet (waiting for startup or travel load).\"\n    end\n    local sum, best, worst = 0.0, 999999.0, 0.0\n    for i = 1, #records do\n        local s = records[i].sec\n        sum = sum + s\n        if s \u003c best then best = s end\n        if s > worst then worst = s end\n    end\n    return string.format(\"Loads: %d | Avg: %.2fs | Best: %.2fs | Worst: %.2fs\", #records, sum / #records, best, worst)\nend\n\nlocal function refresh_ui()\n    if not panel then return end\n    panel:set_text(w_stats, compute_summary())\n    local last = records[#records]\n    if last then\n        panel:set_text(w_last, string.format(\"Last: %s in %.2fs (RAM %.0f MB, stage %d)\",\n            last.kind, last.sec, last.ram_mb or 0, last.stage or 0))\n    else\n        panel:set_text(w_last, \"Last Load: --\")\n    end\n    for idx = 1, #w_recent do\n        local r = records[#records - idx + 1]\n        if r then\n            panel:set_text(w_recent[idx], string.format(\"#%d %-8s  %6.2fs  |  %.0f MB RAM\",\n                #records - idx + 1, r.kind, r.sec, r.ram_mb or 0))\n        else\n            panel:set_text(w_recent[idx], string.format(\"#%d --\", idx))\n        end\n    end\nend\n\nif panel then\n    panel:separator()\n    panel:checkbox(\"Show Load-Time Toast on World Ready\", cfg.show_toast, function(v) cfg.show_toast = v; save_cfg() end)\n    panel:same_line()\n    panel:checkbox(\"Save data/load_history.csv\", cfg.save_csv, function(v) cfg.save_csv = v; save_cfg() end)\n    panel:section(\"Recent Loads (Newest First)\", true)\n    for i = 1, 6 do\n        w_recent[i] = panel:text(string.format(\"#%d --\", i))\n    end\n    panel:end_section()\n    panel:button(\"Copy Benchmark Report\", function()\n        local out = { \"BSX Load-Time Profiler Report\", compute_summary(), \"\" }\n        for i = #records, math.max(1, #records - 14), -1 do\n            local r = records[i]\n            out[#out + 1] = string.format(\"- #%d [%s] %.2fs (RAM: %.0f MB, stage %d)\", i, r.kind, r.sec, r.ram_mb or 0, r.stage or 0)\n        end\n        local ok = bsx.system.copy_text(table.concat(out, \"\\n\"))\n        bsx.ui.toast(ok and \"Load benchmark copied!\" or \"Clipboard busy\", { level = ok and \"ok\" or \"warn\" })\n    end)\n    panel:same_line()\n    panel:button(\"Clear History\", function()\n        records = {}\n        write_csv_history()\n        refresh_ui()\n        bsx.ui.toast(\"Cleared load history\", { level = \"info\" })\n    end)\n    refresh_ui()\nend\n\nbsx.on(\"load_request\", function(e)\n    pending = {\n        kind = \"Travel\",\n        start_t = os.clock(),\n        stage = tonumber(e.requested_stage) or 0,\n        prev_stage = tonumber(e.previous_stage) or 0,\n        save_key = nil\n    }\nend)\n\nbsx.on(\"save_loaded\", function(e)\n    if not pending then\n        pending = {\n            kind = first_world_done and \"SaveLoad\" or \"Startup\",\n            start_t = first_world_done and os.clock() or startup_time,\n            stage = 0,\n            prev_stage = 0,\n            save_key = e.key\n        }\n    else\n        pending.kind = first_world_done and \"SaveLoad\" or \"Startup\"\n        pending.save_key = e.key\n    end\nend)\n\nbsx.on(\"world_ready\", function(e)\n    local now = os.clock()\n    local kind, elapsed\n    if pending then\n        kind = pending.kind\n        elapsed = math.max(0.05, now - pending.start_t)\n    elseif not first_world_done then\n        kind = \"Startup\"\n        elapsed = math.max(0.05, now - startup_time)\n    else\n        return\n    end\n    first_world_done = true\n    local mem = bsx.memory and bsx.memory.info and bsx.memory.info() or nil\n    local ram_mb = mem and mem.working_set_mb or 0\n    local entry = {\n        kind = kind,\n        sec = elapsed,\n        ram_mb = ram_mb,\n        stage = (pending and pending.stage and pending.stage > 0) and pending.stage or (tonumber(e.requested_stage) or 0),\n        follow_save = e.follows_save == true\n    }\n    pending = nil\n    records[#records + 1] = entry\n    while #records > 40 do table.remove(records, 1) end\n    write_csv_history()\n    refresh_ui()\n    if cfg.show_toast and bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(string.format(\"%s load finished in %.2fs (RAM %.0f MB)\", kind, elapsed, ram_mb), { level = \"ok\", duration_ms = 3200 })\n    end\nend)\n\nbsx.on(\"title_screen\", function()\n    pending = nil\n    startup_time = os.clock()\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Load-Time Profiler & History\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"uses\": [\"ui\"]\n}\n","lang":"json","name":"script.json"}],"id":"recipe_load_profiler","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/load_profiler","tier":"safe","title":"Recipe: FastLoad-Style Load-Time Profiler & History CSV","uses":["ui"]},{"category":"Cookbook Recipes","description":"FastLoad companion mod adding chunked procedural data/loading.wav loading-screen audio, configurable instant hold-to-interact & menu time scale, and a Ctrl+Shift+P Quick-Freeze (0.05x) + RAM Trim hotkey with an on-screen pause banner.","featured":true,"files":[{"code":"-- FastLoad Companion: Custom Loading Music, Instant Hold, Menu Slow-Mo & Quick-Freeze Trim (Changes tier, Lua API 7+)\nlocal AUDIO_FILE = \"loading.wav\"\n\nlocal cfg = {\n    fast_hold = config.bool(\"Companion\", \"FastHold\", true),\n    hold_sec = math.max(0.0, math.min(0.5, config.float(\"Companion\", \"HoldSeconds\", 0.05))),\n    menu_scale_on = config.bool(\"Companion\", \"CustomMenuScale\", false),\n    menu_scale = math.max(0.0, math.min(1.0, config.float(\"Companion\", \"MenuTimeScale\", 0.25))),\n    load_music = config.bool(\"Audio\", \"LoadingMusic\", false),\n    music_vol = math.max(0.0, math.min(1.0, config.float(\"Audio\", \"Volume\", 0.45))),\n    freeze_banner = config.bool(\"QuickFreeze\", \"ShowBanner\", true),\n    trim_on_freeze = config.bool(\"QuickFreeze\", \"AutoTrim\", true)\n}\n\nlocal function save_cfg()\n    config.set(\"Companion\", \"FastHold\", cfg.fast_hold)\n    config.set(\"Companion\", \"HoldSeconds\", cfg.hold_sec)\n    config.set(\"Companion\", \"CustomMenuScale\", cfg.menu_scale_on)\n    config.set(\"Companion\", \"MenuTimeScale\", cfg.menu_scale)\n    config.set(\"Audio\", \"LoadingMusic\", cfg.load_music)\n    config.set(\"Audio\", \"Volume\", cfg.music_vol)\n    config.set(\"QuickFreeze\", \"ShowBanner\", cfg.freeze_banner)\n    config.set(\"QuickFreeze\", \"AutoTrim\", cfg.trim_on_freeze)\n    config.save()\nend\n\nlocal frozen = false\nlocal had_banner = false\nlocal loading_voice = nil\n\n-- Generate a soft mono 16-bit PCM chord chime into data/loading.wav when requested\nlocal function write_sample_chime_wav()\n    if not (bsx.fs and bsx.fs.write) then return false, \"filesystem unavailable\" end\n    local sr = 22050\n    local secs = 1.35 -- keep total RIFF \u003c= 65536 bytes for sandbox table.concat limit\n    local n = math.floor(sr * secs)\n    local function u32(v)\n        return string.char(v % 256, math.floor(v / 256) % 256, math.floor(v / 65536) % 256, math.floor(v / 16777216) % 256)\n    end\n    local function u16(v)\n        return string.char(v % 256, math.floor(v / 256) % 256)\n    end\n    local data_sz = n * 2\n    local parts = {\n        \"RIFF\", u32(36 + data_sz), \"WAVE\",\n        \"fmt \", u32(16), u16(1), u16(1), u32(sr), u32(sr * 2), u16(2), u16(16),\n        \"data\", u32(data_sz)\n    }\n    local f1, f2, f3 = 261.63, 329.63, 392.00 -- C major soft pad\n    local pi2 = math.pi * 2.0\n    local unpack_fn = unpack or (table and table.unpack)\n    local chunk = {}\n    local c = 0\n    for i = 0, n - 1 do\n        local t = i / sr\n        local env = math.min(1.0, t / 0.12) * math.max(0.0, 1.0 - (t / secs))\n        local sig = (math.sin(pi2 * f1 * t) + 0.7 * math.sin(pi2 * f2 * t) + 0.5 * math.sin(pi2 * f3 * t)) / 2.2\n        local s = math.floor(math.max(-1.0, math.min(1.0, sig * env * 0.40)) * 32767)\n        if s \u003c 0 then s = s + 65536 end\n        chunk[c + 1] = s % 256\n        chunk[c + 2] = math.floor(s / 256) % 256\n        c = c + 2\n        if c >= 512 then\n            parts[#parts + 1] = string.char(unpack_fn(chunk, 1, c))\n            c = 0\n        end\n    end\n    if c > 0 then\n        parts[#parts + 1] = string.char(unpack_fn(chunk, 1, c))\n    end\n    return pcall(bsx.fs.write, AUDIO_FILE, table.concat(parts))\nend\n\nlocal function apply_gameplay_tweaks()\n    if game.gameplay and game.gameplay.set_interact_hold then\n        pcall(game.gameplay.set_interact_hold, cfg.fast_hold and cfg.hold_sec or nil)\n    end\n    if game.gameplay and game.gameplay.set_menu_time_scale then\n        pcall(game.gameplay.set_menu_time_scale, cfg.menu_scale_on and cfg.menu_scale or nil)\n    end\nend\n\nlocal function stop_music()\n    if loading_voice then\n        pcall(function() loading_voice:stop() end)\n        loading_voice = nil\n    end\n    if bsx.audio and bsx.audio.stop_all then\n        pcall(bsx.audio.stop_all)\n    end\nend\n\nlocal function toggle_quick_freeze(status_label, panel_ref)\n    if not (game.world and game.world.set_game_speed) then\n        bsx.ui.toast(\"Quick-Freeze requires ServerCommands=1 & Changes approval\", { level = \"warn\" })\n        return\n    end\n    frozen = not frozen\n    local ok, res, reason = pcall(game.world.set_game_speed, frozen and 0.05 or nil)\n    if not ok or res == nil then\n        frozen = false\n        bsx.ui.toast(\"Quick-Freeze blocked: \" .. tostring(reason or res), { level = \"warn\" })\n        return\n    end\n    if frozen and cfg.trim_on_freeze and bsx.memory and bsx.memory.trim then\n        local ok_t, tr = pcall(bsx.memory.trim)\n        if ok_t and tr then\n            bsx.ui.toast(string.format(\"Quick-Freeze ON (0.05x) + Trimming RAM (%.0f MB)\", tr.before_mb or 0), { level = \"ok\" })\n        else\n            bsx.ui.toast(\"Quick-Freeze ON (0.05x speed)\", { level = \"ok\" })\n        end\n    else\n        bsx.ui.toast(frozen and \"Quick-Freeze ON (0.05x speed)\" or \"Quick-Freeze OFF (1.0x native)\", { level = \"info\" })\n    end\n    if panel_ref and status_label then\n        panel_ref:set_text(status_label, frozen and \"State: FROZEN (0.05x speed) | Ctrl+Shift+P to resume\" or \"State: Normal Speed\")\n    end\nend\n\nlocal ok_p, panel = pcall(bsx.ui.panel, \"FastLoad Companion QoL\")\nif not ok_p then panel = nil end\nif panel and panel.set_theme then\n    pcall(panel.set_theme, panel, {\n        accent = \"#F59E0B\",\n        header = \"#291D0D\",\n        child_bg = \"#141210\",\n        border = \"#785312\"\n    })\nend\n\nlocal w_status = panel and panel:text(\"State: Normal Speed (Changes tier)\") or nil\nif panel then\n    panel:separator()\n    panel:section(\"Hold-to-Interact & Menu Speed\", true)\n    panel:checkbox(\"Instant / Fast Hold-to-Interact\", cfg.fast_hold, function(v)\n        cfg.fast_hold = v; save_cfg(); apply_gameplay_tweaks()\n    end)\n    panel:slider(\"Hold Duration (s)\", 0.0, 0.5, cfg.hold_sec, function(v)\n        cfg.hold_sec = v; save_cfg(); apply_gameplay_tweaks()\n    end)\n    panel:checkbox(\"Custom Menu Slow-Mo Scale\", cfg.menu_scale_on, function(v)\n        cfg.menu_scale_on = v; save_cfg(); apply_gameplay_tweaks()\n    end)\n    panel:slider(\"Menu Time Scale (0=Pause)\", 0.0, 1.0, cfg.menu_scale, function(v)\n        cfg.menu_scale = v; save_cfg(); apply_gameplay_tweaks()\n    end)\n    panel:end_section()\n\n    panel:section(\"Quick-Freeze & Loading Music\", true)\n    panel:checkbox(\"Show On-Screen Banner When Frozen\", cfg.freeze_banner, function(v) cfg.freeze_banner = v; save_cfg() end)\n    panel:same_line()\n    panel:checkbox(\"Auto-Trim RAM On Freeze\", cfg.trim_on_freeze, function(v) cfg.trim_on_freeze = v; save_cfg() end)\n    panel:button(\"Toggle Quick-Freeze + Trim (Ctrl+Shift+P)\", function() toggle_quick_freeze(w_status, panel) end)\n    panel:separator()\n    panel:checkbox(\"Play data/loading.wav While Loading\", cfg.load_music, function(v)\n        cfg.load_music = v; save_cfg()\n        if not v then stop_music() end\n    end)\n    panel:slider(\"Loading Music Volume\", 0.0, 1.0, cfg.music_vol, function(v) cfg.music_vol = v; save_cfg() end)\n    panel:button(\"Create Sample loading.wav\", function()\n        local ok, err = write_sample_chime_wav()\n        bsx.ui.toast(ok and \"Created data/loading.wav\" or (\"Failed: \" .. tostring(err)), { level = ok and \"ok\" or \"warn\" })\n    end)\n    panel:same_line()\n    panel:button(\"Test / Stop Audio\", function()\n        if loading_voice then\n            stop_music()\n        elseif bsx.fs and bsx.fs.exists(AUDIO_FILE) and bsx.audio and bsx.audio.play then\n            local v, err = bsx.audio.play(AUDIO_FILE, { volume = cfg.music_vol, loop = false })\n            loading_voice = v\n            if not v then bsx.ui.toast(\"Audio error: \" .. tostring(err), { level = \"warn\" }) end\n        else\n            bsx.ui.toast(\"Drop data/loading.wav or click Create Sample first\", { level = \"info\" })\n        end\n    end)\n    panel:end_section()\nend\n\nbsx.hotkey(\"ctrl+shift+p\", function()\n    toggle_quick_freeze(w_status, panel)\nend)\n\nbsx.on(\"world_ready\", function()\n    stop_music()\n    apply_gameplay_tweaks()\n    if frozen and game.world and game.world.set_game_speed then\n        frozen = false\n        pcall(game.world.set_game_speed, nil)\n    end\nend)\n\nbsx.on(\"load_request\", function()\n    if cfg.load_music and bsx.fs and bsx.fs.exists(AUDIO_FILE) and bsx.audio and bsx.audio.play then\n        stop_music()\n        local v = bsx.audio.play(AUDIO_FILE, { volume = cfg.music_vol, loop = true })\n        loading_voice = v\n    end\nend)\n\nbsx.on(\"title_screen\", function()\n    stop_music()\n    frozen = false\nend)\n\nbsx.on(\"frame\", function()\n    if not (bsx.draw and bsx.draw.clear) then return end\n    if frozen and cfg.freeze_banner then\n        bsx.draw.clear()\n        local si = bsx.system and bsx.system.info and bsx.system.info() or nil\n        local vw = (si and si.viewport_w and si.viewport_w > 0) and si.viewport_w or 1920\n        local mem = bsx.memory and bsx.memory.info and bsx.memory.info() or nil\n        local ram_str = mem and string.format(\" | RAM %.0f MB\", mem.working_set_mb or 0) or \"\"\n        local bx = math.floor(vw * 0.5 - 170)\n        bsx.draw.rect(bx, 18, 340, 32, \"#11131AE0\", true)\n        bsx.draw.rect(bx, 18, 340, 32, \"#F59E0BFF\", false, 1.5)\n        bsx.draw.text(bx + 14, 25, \"PAUSED (0.05x) - Ctrl+Shift+P\" .. ram_str, \"#FDE68AFF\", 1.0, \"bold\", \"shadow\")\n        had_banner = true\n    elseif had_banner then\n        bsx.draw.clear()\n        had_banner = false\n    end\nend)\n\nfunction on_unload()\n    stop_music()\n    if game.gameplay and game.gameplay.set_interact_hold then pcall(game.gameplay.set_interact_hold, nil) end\n    if game.gameplay and game.gameplay.set_menu_time_scale then pcall(game.gameplay.set_menu_time_scale, nil) end\n    if game.world and game.world.set_game_speed then pcall(game.world.set_game_speed, nil) end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"FastLoad Companion QoL\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"world\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"recipe_fastload_qol","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/fastload_qol","tier":"changes","title":"Recipe: FastLoad Companion QoL (Loading Music, Instant Hold & Quick-Freeze)","uses":["ui","world","positions"]},{"category":"Cookbook Recipes","description":"Cast aimed spells and toggle elemental weapon enchants using native Crimson Desert .effect assets via game.vfx (6 placement modes: Player Bone, Weapon Bone, Ground Ring, Orbit, Projectile, Target Enemy), live skeleton socket discovery (game.vfx.sockets), WAV SFX, and reentrancy-guarded game.stats.add_actor procs.","featured":true,"files":[{"code":"-- Spellcraft & Native VFX Studio (Changes tier, Lua API 7+)\n-- 100% real native Crimson Desert `.effect` visuals powered by `game.vfx`:\n-- Pick any `.effect`, choose Orbit/Rotate Around Me, Attach to Character Socket,\n-- Fireball/Projectile, Aim/Ground Spawn, Ring/Nova, or Follow Behind/Overhead,\n-- with full spatial/speed/scale/replay control and weaponless Wizard spells.\n\nlocal function clamp(v, lo, hi)\n    if type(v) ~= \"number\" or v ~= v then return lo end\n    if v \u003c lo then return lo end\n    if v > hi then return hi end\n    return v\nend\n\nlocal function trim_text(s, max_len)\n    s = tostring(s or \"\"):gsub(\"[%z\\1-\\31]\", \" \")\n    if #s \u003c= max_len then return s end\n    return s:sub(1, math.max(1, max_len - 2)) .. \"..\"\nend\n\nlocal STUDIO_MODES = {\n    \"Orbit / Rotate Around Me\",\n    \"Attach to Character Socket\",\n    \"Launch Fireball / Projectile\",\n    \"Spawn at Aim / Ground\",\n    \"Ring / Nova Around Me\",\n    \"Follow Behind / Overhead\",\n}\n\nlocal FILTER_CATEGORIES = {\n    \"All\",\n    \"Persistent (.level)\",\n    \"Combat (.action)\",\n    \"Fire\",\n    \"Frost\",\n    \"Storm\",\n    \"Shadow\",\n    \"Holy\",\n    \"Wind\",\n    \"Magic\",\n    \"Other\",\n}\n\nlocal SPELLS = {\n    { key = \"fireball\",  name = \"Fireball\",            def_hk = \"alt+1\", mp = 18, cd = 0.70 },\n    { key = \"lightning\", name = \"Chain Lightning\",     def_hk = \"alt+2\", mp = 24, cd = 0.90 },\n    { key = \"frost\",     name = \"Frost Nova\",          def_hk = \"alt+3\", mp = 20, cd = 1.00 },\n    { key = \"meteor\",    name = \"Meteor Strike\",       def_hk = \"alt+4\", mp = 40, cd = 1.80 },\n    { key = \"heal\",      name = \"Radiant Ward\",        def_hk = \"alt+5\", mp = 22, cd = 1.20 },\n    { key = \"custom\",    name = \"Trigger Studio Mode\", def_hk = \"alt+6\", mp = 0,  cd = 0.25 },\n}\n\nlocal NOISE_TERMS = {\n    \"smoke\", \"dust\", \"debris\", \"footprint\", \"dummy\", \"test_\", \"blank\", \"empty\", \"camera_\", \"ui_\", \"debug\"\n}\n\nlocal cfg = {\n    studio_mode = math.floor(clamp(config.int(\"Studio\", \"Mode\", 1), 1, #STUDIO_MODES)),\n    filter_cat = math.floor(clamp(config.int(\"Studio\", \"FilterCategory\", 1), 1, #FILTER_CATEGORIES)),\n    hide_noise = config.bool(\"Studio\", \"HideNoise\", true),\n    socket_name = config.string(\"Studio\", \"SocketName\", \"\"),\n    auto_replay = config.bool(\"Studio\", \"AutoReplay\", true),\n    replay_interval = clamp(config.float(\"Studio\", \"ReplayInterval\", 0.0), 0.0, 8.0),\n    vfx_scale = clamp(config.float(\"Studio\", \"Scale\", 1.0), 0.15, 5.0),\n    orbit_radius = clamp(config.float(\"Studio\", \"OrbitRadius\", 1.8), 0.0, 8.0),\n    orbit_speed = clamp(config.float(\"Studio\", \"OrbitSpeed\", 2.2), -8.0, 8.0),\n    count = math.floor(clamp(config.int(\"Studio\", \"Count\", 2), 1, 8)),\n    offset_y = clamp(config.float(\"Studio\", \"OffsetY\", 0.0), -2.0, 3.0),\n    offset_x = clamp(config.float(\"Studio\", \"OffsetX\", 0.0), -2.0, 2.0),\n    offset_z = clamp(config.float(\"Studio\", \"OffsetZ\", 0.0), -2.0, 2.0),\n    rot_y = clamp(config.float(\"Studio\", \"RotateY\", 0.0), -180.0, 180.0),\n    duration = clamp(config.float(\"Studio\", \"Duration\", 0.0), 0.0, 20.0),\n\n    deal_damage = config.bool(\"Spells\", \"DealDamage\", true),\n    auto_aim_target = config.bool(\"Spells\", \"AutoAimTarget\", true),\n    use_mp_cost = config.bool(\"Spells\", \"UseMPCost\", false),\n    spell_power = math.floor(clamp(config.int(\"Spells\", \"SpellPower\", 1400), 50, 80000)),\n    proj_speed = clamp(config.float(\"Spells\", \"ProjSpeed\", 26.0), 6.0, 60.0),\n    meteor_hitstop = clamp(config.float(\"Spells\", \"MeteorHitstop\", 0.08), 0.0, 0.35),\n    hotkeys = {},\n\n    slots = {\n        custom          = config.string(\"Slots\", \"CustomEffect\", \"\"),\n        fireball_proj   = config.string(\"Slots\", \"FireballProj\", \"\"),\n        fireball_impact = config.string(\"Slots\", \"FireballImpact\", \"\"),\n        lightning       = config.string(\"Slots\", \"Lightning\", \"\"),\n        frost           = config.string(\"Slots\", \"FrostNova\", \"\"),\n        meteor          = config.string(\"Slots\", \"Meteor\", \"\"),\n        ward            = config.string(\"Slots\", \"Ward\", \"\"),\n    },\n\n    sfx_enabled = config.bool(\"Audio\", \"SoundEnabled\", true),\n    sfx_vol = clamp(config.float(\"Audio\", \"SoundVolume\", 0.75), 0.05, 1.5),\n    cam_jolt = config.bool(\"Audio\", \"CameraJolt\", false),\n}\n\n-- Migrate away from the old v2 default smoke asset if present\nif cfg.slots.fireball_proj == \"fx_fire_common_smoke_a__black_1m.action.effect\" then\n    cfg.slots.fireball_proj = \"\"\nend\n\nfor i = 1, #SPELLS do\n    cfg.hotkeys[i] = config.string(\"Hotkeys\", \"Spell\" .. tostring(i), SPELLS[i].def_hk)\nend\n\nlocal function save_cfg()\n    config.set(\"Studio\", \"Mode\", cfg.studio_mode)\n    config.set(\"Studio\", \"FilterCategory\", cfg.filter_cat)\n    config.set(\"Studio\", \"HideNoise\", cfg.hide_noise)\n    config.set(\"Studio\", \"SocketName\", cfg.socket_name or \"\")\n    config.set(\"Studio\", \"AutoReplay\", cfg.auto_replay)\n    config.set(\"Studio\", \"ReplayInterval\", cfg.replay_interval)\n    config.set(\"Studio\", \"Scale\", cfg.vfx_scale)\n    config.set(\"Studio\", \"OrbitRadius\", cfg.orbit_radius)\n    config.set(\"Studio\", \"OrbitSpeed\", cfg.orbit_speed)\n    config.set(\"Studio\", \"Count\", cfg.count)\n    config.set(\"Studio\", \"OffsetY\", cfg.offset_y)\n    config.set(\"Studio\", \"OffsetX\", cfg.offset_x)\n    config.set(\"Studio\", \"OffsetZ\", cfg.offset_z)\n    config.set(\"Studio\", \"RotateY\", cfg.rot_y)\n    config.set(\"Studio\", \"Duration\", cfg.duration)\n\n    config.set(\"Spells\", \"DealDamage\", cfg.deal_damage)\n    config.set(\"Spells\", \"AutoAimTarget\", cfg.auto_aim_target)\n    config.set(\"Spells\", \"UseMPCost\", cfg.use_mp_cost)\n    config.set(\"Spells\", \"SpellPower\", cfg.spell_power)\n    config.set(\"Spells\", \"ProjSpeed\", cfg.proj_speed)\n    config.set(\"Spells\", \"MeteorHitstop\", cfg.meteor_hitstop)\n    for i = 1, #SPELLS do config.set(\"Hotkeys\", \"Spell\" .. tostring(i), cfg.hotkeys[i] or \"\") end\n\n    config.set(\"Slots\", \"CustomEffect\", cfg.slots.custom or \"\")\n    config.set(\"Slots\", \"FireballProj\", cfg.slots.fireball_proj or \"\")\n    config.set(\"Slots\", \"FireballImpact\", cfg.slots.fireball_impact or \"\")\n    config.set(\"Slots\", \"Lightning\", cfg.slots.lightning or \"\")\n    config.set(\"Slots\", \"FrostNova\", cfg.slots.frost or \"\")\n    config.set(\"Slots\", \"Meteor\", cfg.slots.meteor or \"\")\n    config.set(\"Slots\", \"Ward\", cfg.slots.ward or \"\")\n\n    config.set(\"Audio\", \"SoundEnabled\", cfg.sfx_enabled)\n    config.set(\"Audio\", \"SoundVolume\", cfg.sfx_vol)\n    config.set(\"Audio\", \"CameraJolt\", cfg.cam_jolt)\n    config.save()\nend\n\n-- Runtime state\nlocal projectiles, meteors = {}, {}\nlocal sfx_ready, hk_handles = {}, {}\nlocal last_cast_t = {}\nlocal cached_pk, cached_pfac, last_diag_str = 0, -1, \"Ready (100% Native .effect VFX)\"\nlocal last_frame_t = os.clock()\n\nlocal catalog_loaded = false\nlocal catalog_all = {}      -- array of { path, low, kind, element, is_noise }\nlocal catalog_by_path = {}\nlocal browser_items = {}\nlocal browser_query = \"\"\nlocal selected_path = cfg.slots.custom or \"\"\nlocal auto_fx = {}\n\nlocal live_sockets = {}\nlocal socket_idx = 1\n\nlocal studio_state = {\n    active = false,\n    mode = 1,\n    path = \"\",\n    bone = \"\",\n    actor = 0,\n    handles = {}, -- { h, spawned_t, ready_seen }\n    started_t = 0,\n}\n\nlocal function u32_le(v)\n    return string.char(v % 256, math.floor(v / 256) % 256, math.floor(v / 65536) % 256, math.floor(v / 16777216) % 256)\nend\nlocal function u16_le(v)\n    return string.char(v % 256, math.floor(v / 256) % 256)\nend\n\nlocal function ensure_sfx(kind)\n    local fname = kind .. \".wav\"\n    if sfx_ready[kind] then return fname end\n    if not (bsx.fs and bsx.fs.exists and bsx.fs.write) then return nil end\n    if bsx.fs.exists(fname) then sfx_ready[kind] = true; return fname end\n\n    local sr = 22050\n    local dur = (kind == \"proc\" and 0.22) or (kind == \"lightning\" and 0.36) or (kind == \"meteor\" and 0.65) or 0.48\n    local n = math.floor(sr * dur)\n    local data_sz = n * 2\n    local parts = {\n        \"RIFF\", u32_le(36 + data_sz), \"WAVE\",\n        \"fmt \", u32_le(16), u16_le(1), u16_le(1), u32_le(sr), u32_le(sr * 2), u16_le(2), u16_le(16),\n        \"data\", u32_le(data_sz)\n    }\n    local unpack_fn = unpack or (table and table.unpack)\n    local pi2 = math.pi * 2.0\n    local chunk, c, phase = {}, 0, 0.0\n    local seed = 1337\n    local function next_noise()\n        seed = (seed * 1103515245 + 12345) % 2147483648\n        return (seed / 1073741824.0) - 1.0\n    end\n    for i = 0, n - 1 do\n        local t = i / sr\n        local p = t / dur\n        local env = math.min(1.0, t / 0.015) * math.pow(math.max(0.0, 1.0 - p), 1.4)\n        local sig = 0.0\n        if kind == \"fireball\" then\n            local f = 240.0 - 155.0 * p\n            phase = phase + f / sr\n            sig = 0.55 * math.sin(pi2 * phase) + 0.45 * next_noise() * (1.0 - p * 0.5)\n        elseif kind == \"lightning\" then\n            local f = 1350.0 - 950.0 * p + 180.0 * math.sin(t * 90.0)\n            phase = phase + f / sr\n            local snap = (i % 7 \u003c 3) and 1.0 or -1.0\n            sig = 0.45 * snap * math.sin(pi2 * phase) + 0.55 * next_noise()\n        elseif kind == \"frost\" then\n            sig = (math.sin(pi2 * 880.0 * t) + 0.8 * math.sin(pi2 * 1318.5 * t) + 0.6 * math.sin(pi2 * 1760.0 * t)) / 2.4\n        elseif kind == \"meteor\" then\n            local f = 155.0 - 112.0 * p\n            phase = phase + f / sr\n            local impact = (p > 0.35 and p \u003c 0.72) and (next_noise() * 0.65) or 0.0\n            sig = 0.70 * math.sin(pi2 * phase) + 0.30 * math.sin(pi2 * phase * 0.5) + impact\n        elseif kind == \"heal\" then\n            local chord_f = (p \u003c 0.33 and 523.25) or (p \u003c 0.66 and 659.25) or 783.99\n            sig = 0.6 * math.sin(pi2 * chord_f * t) + 0.4 * math.sin(pi2 * 1046.5 * t)\n        else\n            local f = 640.0 + 380.0 * p\n            phase = phase + f / sr\n            sig = math.sin(pi2 * phase)\n        end\n        local s = math.floor(clamp(sig * env * 0.48, -1.0, 1.0) * 32767)\n        if s \u003c 0 then s = s + 65536 end\n        chunk[c + 1] = s % 256\n        chunk[c + 2] = math.floor(s / 256) % 256\n        c = c + 2\n        if c >= 512 then\n            parts[#parts + 1] = string.char(unpack_fn(chunk, 1, c))\n            c = 0\n        end\n    end\n    if c > 0 then parts[#parts + 1] = string.char(unpack_fn(chunk, 1, c)) end\n    local ok = pcall(bsx.fs.write, fname, table.concat(parts))\n    if ok then sfx_ready[kind] = true; return fname end\n    return nil\nend\n\nlocal function play_sfx(kind, pitch)\n    if not cfg.sfx_enabled or not (bsx.audio and bsx.audio.play) then return end\n    local f = ensure_sfx(kind)\n    if f then pcall(bsx.audio.play, f, { volume = cfg.sfx_vol, pitch = pitch or 1.0 }) end\nend\n\nlocal function trigger_jolt(deg)\n    if not cfg.cam_jolt or not (game.camera and game.camera.set_roll) then return end\n    pcall(game.camera.set_roll, deg)\n    bsx.after(45, function() pcall(game.camera.set_roll, -deg * 0.45) end)\n    bsx.after(95, function() pcall(game.camera.set_roll, 0.0) end)\nend\n\n-- Classification & Catalog\nlocal function infer_kind(path, api_kind)\n    if type(api_kind) == \"string\" and #api_kind > 0 then return api_kind end\n    local lo = tostring(path or \"\"):lower()\n    if lo:sub(-13) == \".level.effect\" then return \"level\" end\n    if lo:sub(-14) == \".action.effect\" then return \"action\" end\n    if lo:sub(-15) == \".gimmick.effect\" then return \"gimmick\" end\n    if lo:sub(-14) == \".system.effect\" then return \"system\" end\n    if lo:sub(-17) == \".sequencer.effect\" then return \"sequencer\" end\n    return \"other\"\nend\n\nlocal function categorize_element(path)\n    local lo = tostring(path or \"\"):lower()\n    if lo:find(\"fire\") or lo:find(\"flame\") or lo:find(\"burn\") or lo:find(\"lava\") or lo:find(\"explo\") or lo:find(\"blaze\") or lo:find(\"inferno\") then return \"Fire\" end\n    if lo:find(\"ice\") or lo:find(\"frost\") or lo:find(\"cold\") or lo:find(\"snow\") or lo:find(\"freez\") or lo:find(\"blizz\") then return \"Frost\" end\n    if lo:find(\"lightn\") or lo:find(\"thun\") or lo:find(\"shock\") or lo:find(\"elec\") or lo:find(\"spark\") or lo:find(\"storm\") then return \"Storm\" end\n    if lo:find(\"dark\") or lo:find(\"shadow\") or lo:find(\"void\") or lo:find(\"blood\") or lo:find(\"curse\") or lo:find(\"blacksp\") then return \"Shadow\" end\n    if lo:find(\"holy\") or lo:find(\"heal\") or lo:find(\"light_\") or lo:find(\"shield\") or lo:find(\"buff\") or lo:find(\"radiant\") then return \"Holy\" end\n    if lo:find(\"wind\") or lo:find(\"tornad\") or lo:find(\"air\") or lo:find(\"gust\") or lo:find(\"whirl\") then return \"Wind\" end\n    if lo:find(\"magic\") or lo:find(\"arcane\") or lo:find(\"spell\") or lo:find(\"aura\") or lo:find(\"mana\") then return \"Magic\" end\n    return \"Other\"\nend\n\nlocal function is_noise_path(lo)\n    for i = 1, #NOISE_TERMS do\n        if lo:find(NOISE_TERMS[i], 1, true) then return true end\n    end\n    return false\nend\n\nlocal function pick_best_effect(terms, prefer_level)\n    local best_score, best_path = -1000, nil\n    for i = 1, #catalog_all do\n        local e = catalog_all[i]\n        local lo = e.low\n        local score = 0\n        local term_hit = false\n        for ti, term in ipairs(terms) do\n            if lo:find(term, 1, true) then\n                term_hit = true\n                score = score + (#terms - ti + 1) * 20\n                break\n            end\n        end\n        if term_hit then\n            if e.is_noise then score = score - 200 end\n            if prefer_level then\n                if e.kind == \"level\" then score = score + 35 end\n                if lo:find(\"loop\", 1, true) or lo:find(\"aura\", 1, true) then score = score + 25 end\n                if lo:find(\"hit\", 1, true) or lo:find(\"end\", 1, true) then score = score - 25 end\n            else\n                if e.kind == \"action\" then score = score + 20 end\n                if lo:find(\"cast\", 1, true) or lo:find(\"shot\", 1, true) or lo:find(\"proj\", 1, true) then score = score + 15 end\n            end\n            if lo:find(\"common_smoke\", 1, true) then score = score - 300 end\n            if score > best_score then\n                best_score = score\n                best_path = e.path\n            end\n        end\n    end\n    return best_path or (catalog_all[1] and catalog_all[1].path) or \"\"\nend\n\nlocal function populate_auto_effects()\n    auto_fx.fireball_proj   = pick_best_effect({ \"fireball\", \"fire_ball\", \"flame\", \"fire_loop\", \"fire\", \"magic\" }, true)\n    auto_fx.fireball_impact = pick_best_effect({ \"fireball_hit\", \"explosion\", \"fire_boom\", \"fire_hit\", \"flame\", \"fire\" }, false)\n    auto_fx.lightning       = pick_best_effect({ \"lightning\", \"thunder\", \"shock\", \"spark\", \"storm\" }, false)\n    auto_fx.frost           = pick_best_effect({ \"frost_nova\", \"frost\", \"ice\", \"freeze\", \"cold\" }, false)\n    auto_fx.meteor          = pick_best_effect({ \"meteor\", \"inferno\", \"vortex\", \"fire_loop\", \"explosion\", \"fire\" }, true)\n    auto_fx.ward            = pick_best_effect({ \"holy_shield\", \"shield\", \"holy\", \"aura\", \"heal\", \"buff\" }, true)\n    auto_fx.custom          = pick_best_effect({ \"fire_blade\", \"fire_loop\", \"flame\", \"arcane\", \"magic\", \"aura\", \"fireball\" }, true)\n    if selected_path == \"\" or selected_path == \"fx_fire_common_smoke_a__black_1m.action.effect\" then\n        selected_path = auto_fx.custom\n    end\nend\n\nlocal function ensure_catalog(force)\n    if catalog_loaded and not force then return end\n    if not (game.vfx and game.vfx.catalog) then return end\n    local seen, list, by_p = {}, {}, {}\n    local function merge_query(q, lim)\n        local ok, res = pcall(game.vfx.catalog, q, lim)\n        if not ok or type(res) ~= \"table\" then return end\n        for i = 1, #res do\n            local row = res[i]\n            local p = row and row.path\n            if type(p) == \"string\" and #p > 0 then\n                local lo = p:lower()\n                if not seen[lo] then\n                    seen[lo] = true\n                    local item = {\n                        path = p,\n                        low = lo,\n                        kind = infer_kind(p, row.kind),\n                        element = categorize_element(p),\n                        is_noise = is_noise_path(lo),\n                    }\n                    list[#list + 1] = item\n                    by_p[lo] = item\n                end\n            end\n        end\n    end\n    merge_query(\"\", 2000)\n    local kw = { \"fire\", \"flame\", \"ice\", \"frost\", \"lightning\", \"thunder\", \"magic\", \"arcane\", \"holy\", \"heal\", \"shield\", \"shadow\", \"blood\", \"wind\", \"aura\", \"loop\", \"meteor\", \"nova\", \"explosion\" }\n    for i = 1, #kw do\n        merge_query(kw[i], 300)\n    end\n    if #list > 0 then\n        table.sort(list, function(a, b) return a.low \u003c b.low end)\n        catalog_all = list\n        catalog_by_path = by_p\n        catalog_loaded = true\n        populate_auto_effects()\n    end\nend\n\nlocal function slot_effect(slot_key)\n    local ov = cfg.slots[slot_key]\n    if type(ov) == \"string\" and #ov > 0 then return ov end\n    return auto_fx[slot_key] or \"\"\nend\n\nlocal function current_studio_path()\n    if type(selected_path) == \"string\" and #selected_path > 0 then return selected_path end\n    return slot_effect(\"custom\")\nend\n\n-- World / Actor / Sockets Helpers\nlocal function get_player_info()\n    local actors = game.actors and game.actors(256) or nil\n    local ppos = game.player_position and game.player_position() or nil\n    local ps = game.player_state and game.player_state() or nil\n    local px = ppos and ppos.x or nil\n    local py = ppos and ppos.y or nil\n    local pz = ppos and ppos.z or nil\n    local yaw = ppos and ppos.yaw_deg or nil\n    local pk, pfac, p_actor = cached_pk, (ps and ps.faction or cached_pfac), 0\n    if actors then\n        for i = 1, #actors do\n            if actors[i].controlled then\n                p_actor = actors[i].actor or 0\n                pk = actors[i].key or pk\n                pfac = pfac or actors[i].faction or -1\n                if not px and actors[i].x then px, py, pz = actors[i].x, actors[i].y, actors[i].z end\n                yaw = yaw or actors[i].yaw_deg\n                break\n            end\n        end\n    end\n    if p_actor == 0 and game.player then\n        local ok_p, pa = pcall(game.player)\n        if ok_p and type(pa) == \"number\" and pa > 0 then p_actor = pa end\n    end\n    cached_pk, cached_pfac = pk, pfac\n    return actors, ps, pk, pfac, px, py, pz, yaw, p_actor\nend\n\nlocal panel, socket_combo\n\nlocal function current_socket_name()\n    if #live_sockets > 0 then\n        return live_sockets[clamp(socket_idx, 1, #live_sockets)] or live_sockets[1]\n    end\n    return cfg.socket_name or \"\"\nend\n\nlocal function refresh_live_sockets(p_actor)\n    if not (game.vfx and game.vfx.sockets) then return end\n    local ok, list = pcall(game.vfx.sockets, (p_actor and p_actor > 0) and p_actor or nil)\n    if not ok or type(list) ~= \"table\" or #list == 0 then return end\n    live_sockets = list\n    local found_idx = 0\n    if type(cfg.socket_name) == \"string\" and #cfg.socket_name > 0 then\n        for i = 1, #live_sockets do\n            if live_sockets[i] == cfg.socket_name then found_idx = i; break end\n        end\n    end\n    if found_idx == 0 then\n        local pref = { \"hand_r\", \"r_hand\", \"weapon_r\", \"hand\", \"spine\", \"root\", \"head\" }\n        for _, p in ipairs(pref) do\n            for i = 1, #live_sockets do\n                if live_sockets[i]:lower():find(p, 1, true) then found_idx = i; break end\n            end\n            if found_idx > 0 then break end\n        end\n    end\n    if found_idx == 0 then found_idx = 1 end\n    socket_idx = found_idx\n    cfg.socket_name = live_sockets[socket_idx]\n    if socket_combo then\n        pcall(function() panel:set_items(socket_combo, live_sockets, socket_idx) end)\n    end\nend\n\nlocal function is_hostile(a, pfac, pk)\n    if not a or a.controlled or a.dead or not a.key or a.key == 0 or a.key == pk then return false end\n    if a.kind == \"child\" then\n        if pk ~= 0 and game.actors and game.actors.has_aggro then\n            local ok_ag, ag = pcall(game.actors.has_aggro, a.key, pk)\n            return ok_ag and ag == true\n        end\n        return false\n    end\n    if pfac and pfac >= 0 and a.faction and game.factions and game.factions.agreement then\n        local ok_f, res = pcall(game.factions.agreement, pfac, a.faction)\n        if ok_f and res ~= nil then return res \u003c= 2 end\n    end\n    if pfac and pfac >= 0 and a.faction == pfac then return false end\n    return true\nend\n\nlocal function deal_damage(target_key, disp_dmg)\n    if not cfg.deal_damage or not target_key or target_key \u003c= 0 then return false end\n    if not (game.stats and game.stats.add_actor) then return false end\n    local d = math.floor(clamp(disp_dmg, 1, 90000) * 1000)\n    local ok, why = game.stats.add_actor(target_key, 0, -d)\n    if not ok then last_diag_str = trim_text(\"add_actor: \" .. tostring(why), 95) end\n    return ok\nend\n\nlocal function heal_actor(actor_key, stat_id, disp_amt)\n    if not actor_key or actor_key \u003c= 0 or not (game.stats and game.stats.add_actor) then return false end\n    local d = math.floor(clamp(disp_amt, 1, 50000) * 1000)\n    local ok, why = game.stats.add_actor(actor_key, stat_id, d)\n    if not ok then last_diag_str = trim_text(\"heal add_actor: \" .. tostring(why), 95) end\n    return ok\nend\n\nlocal function try_consume_mp(pk, mp_cost)\n    if not cfg.use_mp_cost or mp_cost \u003c= 0 or pk == 0 then return true end\n    local p_ptr = game.player and game.player() or nil\n    if p_ptr and game.stats and game.stats.read then\n        local mp = game.stats.read(p_ptr, 26)\n        if mp and mp.current and mp.current \u003c (mp_cost * 1000) then\n            bsx.ui.toast(string.format(\"Not enough MP (need %d)\", mp_cost), { level = \"warn\" })\n            return false\n        end\n    end\n    if game.stats and game.stats.add_actor then\n        game.stats.add_actor(pk, 26, -math.floor(mp_cost * 1000))\n    end\n    return true\nend\n\nlocal function compute_aim_point(actors, px, py, pz, yaw, pk)\n    local cam = game.camera and game.camera.pose and game.camera.pose() or nil\n    if cfg.auto_aim_target and game.world and game.world.target and actors then\n        local tgt = game.world.target()\n        if tgt and tgt.actor_key and tgt.actor_key ~= 0 and tgt.actor_key ~= pk then\n            for i = 1, #actors do\n                local a = actors[i]\n                if a.key == tgt.actor_key and not a.dead and a.x then\n                    return a.x, a.y + 1.05, a.z, a\n                end\n            end\n        end\n    end\n    if game.world and game.world.raycast then\n        local hit = game.world.raycast(45.0)\n        if hit and hit.hit and hit.x then\n            return hit.x, hit.y, hit.z, nil\n        end\n    end\n    if cam and cam.valid then\n        return cam.x + cam.fwd_x * 22.0, cam.y + cam.fwd_y * 22.0, cam.z + cam.fwd_z * 22.0, nil\n    end\n    if px then\n        local rad = math.rad(yaw or 0)\n        return px + math.sin(rad) * 10.0, py + 1.0, pz + math.cos(rad) * 10.0, nil\n    end\n    return nil\nend\n\nlocal function aoe_damage(actors, pfac, pk, cx, cy, cz, radius, dmg)\n    if not cfg.deal_damage or not actors then return 0 end\n    local r2 = radius * radius\n    local hits = 0\n    for i = 1, #actors do\n        local a = actors[i]\n        if is_hostile(a, pfac, pk) and a.x then\n            local dx, dy, dz = a.x - cx, (a.y + 0.8) - cy, a.z - cz\n            if (dx * dx + dy * dy + dz * dz) \u003c= r2 then\n                if deal_damage(a.key, dmg) then hits = hits + 1 end\n            end\n        end\n    end\n    return hits\nend\n\n-- Native VFX Helpers\nlocal function spawn_native(path, opts)\n    if type(path) ~= \"string\" or #path == 0 or not (game.vfx and game.vfx.spawn) then\n        return nil\n    end\n    local params = {}\n    if opts then\n        for k, v in pairs(opts) do params[k] = v end\n    end\n    params.scale = clamp(params.scale or 1.0, 0.05, 15.0)\n    local ok, h, err = pcall(game.vfx.spawn, path, params)\n    if ok and h then return h end\n    if err then last_diag_str = trim_text(\"VFX error: \" .. tostring(err), 95) end\n    return nil\nend\n\nlocal function stop_handle_safe(h, fade)\n    if h then pcall(function() h:stop(fade or 0.0) end) end\nend\n\nlocal function stop_studio_handles()\n    for i = 1, #studio_state.handles do\n        stop_handle_safe(studio_state.handles[i].h, 0.12)\n    end\n    studio_state.handles = {}\n    studio_state.active = false\nend\n\nlocal function launch_projectile(proj_path, impact_path, scale, speed, dmg)\n    local actors, _, pk, pfac, px, py, pz, yaw = get_player_info()\n    if not px then\n        bsx.ui.toast(\"Enter the world first to launch \" .. tostring(proj_path), { level = \"warn\" })\n        return false\n    end\n    local ax, ay, az = compute_aim_point(actors, px, py, pz, yaw, pk)\n    if not ax then ax, ay, az = px, py + 1.0, pz + 14.0 end\n    local cam = game.camera and game.camera.pose and game.camera.pose() or nil\n    local fx, fz = 0.0, 1.0\n    if cam and cam.valid then\n        fx, fz = cam.fwd_x, cam.fwd_z\n    elseif yaw then\n        local r = math.rad(yaw)\n        fx, fz = math.sin(r), math.cos(r)\n    end\n    local flen = math.sqrt(fx * fx + fz * fz)\n    if flen > 0.001 then fx, fz = fx / flen, fz / flen else fx, fz = 0.0, 1.0 end\n    local ox = px + fx * 0.9 + cfg.offset_x\n    local oy = py + 1.25 + cfg.offset_y\n    local oz = pz + fz * 0.9 + cfg.offset_z\n    local dx, dy, dz = ax - ox, (ay + 0.4) - oy, az - oz\n    local yaw_dir = math.deg(math.atan2(dx, dz)) + cfg.rot_y\n    play_sfx(\"fireball\", 1.0)\n    local nh = spawn_native(proj_path, {\n        x = ox, y = oy, z = oz, ry = yaw_dir, scale = scale, duration = 3.2\n    })\n    projectiles[#projectiles + 1] = {\n        ox = ox, oy = oy, oz = oz, tx = ax, ty = ay + 0.4, tz = az,\n        x = ox, y = oy, z = oz, speed = speed, radius = 4.6,\n        dmg = dmg, t0 = os.clock(), handle = nh, impact = impact_path, scale = scale\n    }\n    last_diag_str = trim_text(\"Launched Projectile: \" .. proj_path, 95)\n    return true\nend\n\nlocal function compute_studio_slot_pose(mode, idx, total, now, px, py, pz, yaw)\n    if mode == 1 then\n        -- Orbit / Rotate Around Me\n        local ang = now * cfg.orbit_speed + ((idx - 1) * (math.pi * 2.0 / math.max(1, total)))\n        local rad = math.max(0.2, cfg.orbit_radius)\n        local x = px + cfg.offset_x + math.cos(ang) * rad\n        local z = pz + cfg.offset_z + math.sin(ang) * rad\n        local y = py + 1.25 + cfg.offset_y + math.sin(now * 2.5 + idx) * 0.14\n        local tangent_deg = math.deg(math.atan2(-math.sin(ang), math.cos(ang))) + cfg.rot_y\n        return x, y, z, tangent_deg\n    elseif mode == 5 then\n        -- Ring / Nova Around Me\n        local n = math.max(4, total)\n        local ang = now * cfg.orbit_speed + ((idx - 1) * (math.pi * 2.0 / n))\n        local rad = math.max(0.5, cfg.orbit_radius)\n        local x = px + cfg.offset_x + math.cos(ang) * rad\n        local z = pz + cfg.offset_z + math.sin(ang) * rad\n        local y = py + 0.20 + cfg.offset_y\n        local outward_deg = math.deg(math.atan2(math.cos(ang), math.sin(ang))) + cfg.rot_y\n        return x, y, z, outward_deg\n    elseif mode == 6 then\n        -- Follow Behind / Overhead\n        local r = math.rad(yaw or 0)\n        local fx, fz = math.sin(r), math.cos(r)\n        local cam = game.camera and game.camera.pose and game.camera.pose() or nil\n        if not yaw and cam and cam.valid then fx, fz = cam.fwd_x, cam.fwd_z end\n        local flen = math.sqrt(fx * fx + fz * fz)\n        if flen > 0.001 then fx, fz = fx / flen, fz / flen else fx, fz = 0.0, 1.0 end\n        local rx, rz = fz, -fx\n        local spread = (total > 1) and ((idx - (total + 1) * 0.5) * 0.65) or 0.0\n        local x = px - fx * cfg.orbit_radius + rx * (cfg.offset_x + spread)\n        local z = pz - fz * cfg.orbit_radius + rz * (cfg.offset_z + spread)\n        local y = py + 1.25 + cfg.offset_y\n        local dir_deg = math.deg(math.atan2(fx, fz)) + cfg.rot_y\n        return x, y, z, dir_deg\n    end\n    return px + cfg.offset_x, py + 1.25 + cfg.offset_y, pz + cfg.offset_z, cfg.rot_y\nend\n\nlocal function spawn_studio_slot(idx, total, mode, path, bone, p_actor, now, px, py, pz, yaw)\n    local dur = (cfg.duration > 0.05) and cfg.duration or 0.0\n    if mode == 2 then\n        -- Attach to real live Character Socket\n        if p_actor > 0 then\n            return spawn_native(path, {\n                attach_actor = p_actor,\n                bone = (#bone > 0) and bone or nil,\n                offset_x = cfg.offset_x,\n                offset_y = cfg.offset_y,\n                offset_z = cfg.offset_z,\n                ry = cfg.rot_y,\n                scale = cfg.vfx_scale,\n                duration = dur,\n            })\n        else\n            return spawn_native(path, {\n                x = px + cfg.offset_x, y = py + 1.25 + cfg.offset_y, z = pz + cfg.offset_z,\n                ry = cfg.rot_y, scale = cfg.vfx_scale, duration = dur,\n            })\n        end\n    else\n        local x, y, z, ry = compute_studio_slot_pose(mode, idx, total, now, px, py, pz, yaw)\n        return spawn_native(path, {\n            x = x, y = y, z = z, ry = ry, scale = cfg.vfx_scale, duration = dur,\n        })\n    end\nend\n\nlocal function start_or_trigger_studio(effect_path)\n    local path = (type(effect_path) == \"string\" and #effect_path > 0) and effect_path or current_studio_path()\n    if type(path) ~= \"string\" or #path == 0 then\n        bsx.ui.toast(\"Select a .effect from the Effect Studio list first\", { level = \"warn\" })\n        return\n    end\n    ensure_catalog(false)\n    local actors, _, pk, _, px, py, pz, yaw, p_actor = get_player_info()\n    if not px then\n        bsx.ui.toast(\"Enter the world first to place \" .. path, { level = \"warn\" })\n        return\n    end\n    refresh_live_sockets(p_actor)\n    local mode = cfg.studio_mode\n\n    if mode == 3 then\n        -- Launch Fireball / Projectile using selected effect\n        local imp = slot_effect(\"fireball_impact\")\n        if #imp == 0 then imp = path end\n        launch_projectile(path, imp, cfg.vfx_scale, cfg.proj_speed, cfg.spell_power)\n        return\n    elseif mode == 4 then\n        -- Spawn at Aim / Ground\n        local ax, ay, az = compute_aim_point(actors, px, py, pz, yaw, pk)\n        if not ax then ax, ay, az = px, py + 0.2, pz + 4.0 end\n        local dur = (cfg.duration > 0.05) and cfg.duration or 4.0\n        local nh = spawn_native(path, {\n            x = ax + cfg.offset_x,\n            y = ay + cfg.offset_y,\n            z = az + cfg.offset_z,\n            ry = cfg.rot_y,\n            scale = cfg.vfx_scale,\n            duration = dur,\n        })\n        play_sfx(\"proc\", 1.1)\n        last_diag_str = trim_text(nh and (\"Spawned at Aim: \" .. path) or last_diag_str, 95)\n        return\n    end\n\n    -- Managed continuous modes: 1=Orbit, 2=Attach Socket, 5=Ring/Nova, 6=Follow Behind/Overhead\n    stop_studio_handles()\n    local total = (mode == 2) and 1 or ((mode == 5) and math.max(4, cfg.count) or cfg.count)\n    local bone = current_socket_name()\n    local now = os.clock()\n    studio_state.active = true\n    studio_state.mode = mode\n    studio_state.path = path\n    studio_state.bone = bone\n    studio_state.actor = p_actor\n    studio_state.started_t = now\n    for i = 1, total do\n        local nh = spawn_studio_slot(i, total, mode, path, bone, p_actor, now, px, py, pz, yaw)\n        studio_state.handles[i] = { h = nh, spawned_t = now, ready_seen = false }\n    end\n    play_sfx(\"proc\", 1.05)\n    last_diag_str = trim_text(string.format(\"Active [%s]: %s\", STUDIO_MODES[mode], path), 95)\nend\n\nlocal function cast_spell(idx)\n    local sp = SPELLS[idx]\n    if not sp then return end\n    ensure_catalog(false)\n    if idx == 6 then\n        start_or_trigger_studio(current_studio_path())\n        return\n    end\n    local now = os.clock()\n    if last_cast_t[idx] and (now - last_cast_t[idx]) \u003c sp.cd then return end\n\n    local actors, _, pk, pfac, px, py, pz, yaw, p_actor = get_player_info()\n    if not px then\n        bsx.ui.toast(\"Enter the world first to cast \" .. sp.name, { level = \"warn\" })\n        return\n    end\n    if not try_consume_mp(pk, sp.mp) then return end\n    last_cast_t[idx] = now\n\n    local ax, ay, az = compute_aim_point(actors, px, py, pz, yaw, pk)\n    if not ax then ax, ay, az = px, py + 0.5, pz + 10.0 end\n\n    if idx == 1 then\n        launch_projectile(slot_effect(\"fireball_proj\"), slot_effect(\"fireball_impact\"), cfg.vfx_scale, cfg.proj_speed, cfg.spell_power)\n    elseif idx == 2 then\n        play_sfx(\"lightning\", 1.0)\n        trigger_jolt(1.6)\n        local lfx = slot_effect(\"lightning\")\n        spawn_native(lfx, { x = px, y = py + 1.2, z = pz, scale = cfg.vfx_scale, duration = 1.3 })\n        local hops = 0\n        if actors then\n            local cur_x, cur_y, cur_z = ax, ay, az\n            local used, cur_dmg = {}, cfg.spell_power * 1.15\n            for hop = 1, 4 do\n                local best, best_d = nil, (hop == 1 and 18.0 or 12.0)\n                for i = 1, #actors do\n                    local a = actors[i]\n                    if not used[a.key] and is_hostile(a, pfac, pk) and a.x then\n                        local d = math.sqrt((a.x - cur_x)^2 + (a.y + 1.0 - cur_y)^2 + (a.z - cur_z)^2)\n                        if d \u003c best_d then best_d = d; best = a end\n                    end\n                end\n                if not best then break end\n                used[best.key] = true\n                hops = hops + 1\n                spawn_native(lfx, { x = best.x, y = best.y + 1.0, z = best.z, scale = cfg.vfx_scale * 1.1, duration = 1.4 })\n                deal_damage(best.key, cur_dmg)\n                cur_x, cur_y, cur_z = best.x, best.y + 1.0, best.z\n                cur_dmg = cur_dmg * 0.78\n            end\n        end\n        if hops == 0 then\n            spawn_native(lfx, { x = ax, y = ay + 0.6, z = az, scale = cfg.vfx_scale * 1.1, duration = 1.4 })\n        end\n        last_diag_str = trim_text(\"Cast Chain Lightning: \" .. lfx, 95)\n    elseif idx == 3 then\n        play_sfx(\"frost\", 1.0)\n        local nfx = slot_effect(\"frost\")\n        spawn_native(nfx, { x = px, y = py + 0.25, z = pz, scale = cfg.vfx_scale * 1.35, duration = 2.0 })\n        for k = 1, 6 do\n            local ang = k * (math.pi / 3.0)\n            spawn_native(nfx, {\n                x = px + math.cos(ang) * 3.0, y = py + 0.2, z = pz + math.sin(ang) * 3.0,\n                ry = math.deg(ang), scale = cfg.vfx_scale * 0.9, duration = 1.8\n            })\n        end\n        aoe_damage(actors, pfac, pk, px, py + 0.8, pz, 8.0, cfg.spell_power * 0.85)\n        last_diag_str = trim_text(\"Cast Frost Nova: \" .. nfx, 95)\n    elseif idx == 4 then\n        play_sfx(\"fireball\", 0.72)\n        local mfx = slot_effect(\"meteor\")\n        local nh = spawn_native(mfx, { x = ax, y = ay + 15.0, z = az, scale = cfg.vfx_scale * 1.4, duration = 2.2 })\n        meteors[#meteors + 1] = {\n            x = ax, y = ay, z = az, t0 = now, impact_at = 0.52,\n            dmg = cfg.spell_power * 2.1, handle = nh, scale = cfg.vfx_scale * 1.8\n        }\n        last_diag_str = trim_text(\"Cast Meteor Strike: \" .. mfx, 95)\n    elseif idx == 5 then\n        play_sfx(\"heal\", 1.0)\n        local wfx = slot_effect(\"ward\")\n        refresh_live_sockets(p_actor)\n        local sock = current_socket_name()\n        if p_actor > 0 then\n            spawn_native(wfx, { attach_actor = p_actor, bone = (#sock > 0) and sock or nil, scale = cfg.vfx_scale * 1.15, duration = 4.0 })\n        else\n            spawn_native(wfx, { x = px, y = py + 0.3, z = pz, scale = cfg.vfx_scale * 1.15, duration = 4.0 })\n        end\n        if pk ~= 0 then\n            local h = math.floor(cfg.spell_power * 1.25)\n            heal_actor(pk, 0, h)\n            heal_actor(pk, 25, math.floor(h * 0.4))\n            heal_actor(pk, 26, math.floor(h * 0.4))\n        end\n        last_diag_str = trim_text(\"Cast Radiant Ward: \" .. wfx, 95)\n    end\nend\n\nlocal function bind_spell_hotkey(idx)\n    if hk_handles[idx] then pcall(function() hk_handles[idx]:off() end); hk_handles[idx] = nil end\n    local chord = cfg.hotkeys[idx]\n    if chord and #chord > 0 and bsx.hotkey then\n        local ok, h = pcall(bsx.hotkey, chord, function() cast_spell(idx) end)\n        if ok and h then hk_handles[idx] = h end\n    end\nend\n\nfor i = 1, #SPELLS do bind_spell_hotkey(i) end\n\n-- UI Panel (1 panel, 3 tabs, ~84 widgets - within 128-widget limit)\npanel = bsx.ui.panel(\"Spellcraft & Native VFX Studio\")\npanel:set_theme({ accent = \"#FF6B1A\", header = \"#1E1924\", child_bg = \"#131118\", border = \"#44374F\" })\nlocal selected_lbl = panel:text(\"Selected Effect: (loading catalog...)\")\nlocal status_lbl = panel:text(\"Studio: Pick an effect and mode below, then press Start / Trigger.\")\n\nlocal fx_listbox, slots_lbl, cap_lbl, socks_lbl, active_lbl, diag_lbl\n\nlocal function refresh_slots_label()\n    if not slots_lbl then return end\n    local short = function(p)\n        local b = tostring(p or \"\"):match(\"([^/\\\\]+)$\") or \"\"\n        return (b ~= \"\" and b or \"(auto)\"):sub(1, 22)\n    end\n    panel:set_text(slots_lbl, trim_text(string.format(\"FB=%s | Imp=%s | Lit=%s | Ice=%s\",\n        short(slot_effect(\"fireball_proj\")), short(slot_effect(\"fireball_impact\")),\n        short(slot_effect(\"lightning\")), short(slot_effect(\"frost\"))), 125))\nend\n\nlocal function refresh_selected_label()\n    if not selected_lbl then return end\n    local cur = current_studio_path()\n    local meta = cur ~= \"\" and catalog_by_path[cur:lower()] or nil\n    local tag = meta and (\"[\" .. meta.kind .. \" / \" .. meta.element .. \"] \") or \"\"\n    panel:set_text(selected_lbl, trim_text(string.format(\"Selected (%d): %s%s\",\n        #browser_items, tag, cur ~= \"\" and cur or \"(none)\"), 125))\nend\n\nlocal function refresh_browser(query)\n    browser_query = tostring(query or \"\")\n    ensure_catalog(false)\n    local qlo = browser_query:lower()\n    local fcat = cfg.filter_cat\n    local out = {}\n    for i = 1, #catalog_all do\n        local e = catalog_all[i]\n        local ok = true\n        if cfg.hide_noise and e.is_noise then ok = false end\n        if ok and #qlo > 0 and not e.low:find(qlo, 1, true) then ok = false end\n        if ok and fcat == 2 and e.kind ~= \"level\" then ok = false end\n        if ok and fcat == 3 and e.kind ~= \"action\" then ok = false end\n        if ok and fcat >= 4 then\n            local target_el = FILTER_CATEGORIES[fcat]\n            if e.element ~= target_el then ok = false end\n        end\n        if ok then\n            out[#out + 1] = {\n                label = trim_text(e.path, 120),\n                category = e.kind .. \" | \" .. e.element,\n            }\n            if #out >= 800 then break end\n        end\n    end\n    browser_items = out\n    local sel = 0\n    for i = 1, #browser_items do\n        if browser_items[i].label == selected_path then sel = i; break end\n    end\n    if sel == 0 and #browser_items > 0 then\n        sel = 1\n        selected_path = browser_items[1].label\n    end\n    if fx_listbox then panel:set_items(fx_listbox, browser_items, sel) end\n    refresh_selected_label()\n    refresh_slots_label()\nend\n\npanel:begin_tab_bar(\"sc_studio_tabs\")\n\npanel:tab(\"Effect Studio\")\npanel:input_text(\"Search .effect\", \"\", function(txt) refresh_browser(txt) end, { live = true })\npanel:combo(\"Category / Type\", FILTER_CATEGORIES, cfg.filter_cat, function(idx)\n    cfg.filter_cat = idx; save_cfg(); refresh_browser(browser_query)\nend)\npanel:same_line()\npanel:checkbox(\"Hide Smoke/Dust\", cfg.hide_noise, function(v)\n    cfg.hide_noise = (v == true); save_cfg(); refresh_browser(browser_query)\nend)\nfx_listbox = panel:listbox(\"Game .effect Assets\", {}, { height = 210, searchable = false }, function(_, label)\n    if type(label) == \"string\" and #label > 0 then\n        selected_path = label\n        cfg.slots.custom = label\n        save_cfg()\n        refresh_selected_label()\n        if studio_state.active and (cfg.studio_mode == 1 or cfg.studio_mode == 2 or cfg.studio_mode == 5 or cfg.studio_mode == 6) then\n            start_or_trigger_studio(label)\n        end\n    end\nend)\npanel:combo(\"Placement / Motion Mode\", STUDIO_MODES, cfg.studio_mode, function(idx)\n    cfg.studio_mode = idx\n    save_cfg()\n    if studio_state.active and (idx == 1 or idx == 2 or idx == 5 or idx == 6) then\n        start_or_trigger_studio(current_studio_path())\n    end\nend)\nsocket_combo = panel:combo(\"Character Socket (for Attach)\", { \"(enter world / Refresh Sockets)\" }, 1, function(idx, label)\n    socket_idx = idx\n    if #live_sockets > 0 and live_sockets[idx] then\n        cfg.socket_name = live_sockets[idx]\n    elseif type(label) == \"string\" and not label:find(\"(enter world\", 1, true) then\n        cfg.socket_name = label\n    end\n    save_cfg()\n    if studio_state.active and cfg.studio_mode == 2 then\n        start_or_trigger_studio(current_studio_path())\n    end\nend)\npanel:button(\"Start / Trigger Selected\", function() start_or_trigger_studio(current_studio_path()) end)\npanel:same_line()\npanel:button(\"Stop Studio Effect\", function() stop_studio_handles(); last_diag_str = \"Studio effect stopped\" end)\npanel:same_line()\npanel:button(\"Stop All Native VFX\", function()\n    stop_studio_handles(); projectiles = {}; meteors = {}\n    if game.vfx and game.vfx.stop_all then pcall(game.vfx.stop_all, 0.15) end\n    last_diag_str = \"Stopped all native VFX\"\nend)\npanel:checkbox(\"Auto-Replay One-Shots\", cfg.auto_replay, function(v) cfg.auto_replay = (v == true); save_cfg() end)\npanel:same_line()\npanel:slider(\"Replay Interval (s; 0=auto)\", 0.0, 8.0, cfg.replay_interval, function(v) cfg.replay_interval = v; save_cfg() end)\npanel:slider(\"Scale\", 0.15, 5.0, cfg.vfx_scale, function(v) cfg.vfx_scale = v; save_cfg() end)\npanel:slider(\"Orbit Radius / Follow Dist (m)\", 0.0, 8.0, cfg.orbit_radius, function(v) cfg.orbit_radius = v; save_cfg() end)\npanel:slider(\"Orbit Speed (rad/s)\", -8.0, 8.0, cfg.orbit_speed, function(v) cfg.orbit_speed = v; save_cfg() end)\npanel:slider(\"Effect Count (Orbit / Ring)\", 1, 8, cfg.count, function(v)\n    local nc = math.floor(v + 0.5)\n    if nc ~= cfg.count then\n        cfg.count = nc; save_cfg()\n        if studio_state.active and (cfg.studio_mode == 1 or cfg.studio_mode == 5 or cfg.studio_mode == 6) then\n            start_or_trigger_studio(studio_state.path)\n        end\n    end\nend)\npanel:slider(\"Height / Offset Y (m)\", -2.0, 3.0, cfg.offset_y, function(v) cfg.offset_y = v; save_cfg() end)\npanel:slider(\"Offset X (m)\", -2.0, 2.0, cfg.offset_x, function(v) cfg.offset_x = v; save_cfg() end)\npanel:slider(\"Offset Z (m)\", -2.0, 2.0, cfg.offset_z, function(v) cfg.offset_z = v; save_cfg() end)\npanel:slider(\"Rotate Y (deg)\", -180.0, 180.0, cfg.rot_y, function(v) cfg.rot_y = v; save_cfg() end)\npanel:slider(\"Duration (s; 0=continuous)\", 0.0, 20.0, cfg.duration, function(v) cfg.duration = v; save_cfg() end)\npanel:text(\"Assign Selected .effect to Wizard Spell Slot:\")\npanel:button(\"Set Fireball\", function() cfg.slots.fireball_proj = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:same_line()\npanel:button(\"Set Impact\", function() cfg.slots.fireball_impact = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:same_line()\npanel:button(\"Set Lightning\", function() cfg.slots.lightning = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:button(\"Set Frost Nova\", function() cfg.slots.frost = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:same_line()\npanel:button(\"Set Meteor\", function() cfg.slots.meteor = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:same_line()\npanel:button(\"Set Ward\", function() cfg.slots.ward = current_studio_path(); save_cfg(); refresh_slots_label() end)\npanel:end_tab()\n\npanel:tab(\"Spellbook (Alt+1..6)\")\nslots_lbl = panel:text(\"Slots: (auto)\")\npanel:checkbox(\"Deal Spell Damage\", cfg.deal_damage, function(v) cfg.deal_damage = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Auto-Aim Target\", cfg.auto_aim_target, function(v) cfg.auto_aim_target = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Consume MP (Stat 26)\", cfg.use_mp_cost, function(v) cfg.use_mp_cost = (v == true); save_cfg() end)\npanel:slider(\"Spell Power (HP)\", 50, 80000, cfg.spell_power, function(v) cfg.spell_power = math.floor(v + 0.5); save_cfg() end)\npanel:slider(\"Projectile Speed (m/s)\", 6.0, 60.0, cfg.proj_speed, function(v) cfg.proj_speed = v; save_cfg() end)\npanel:button(\"Reset Auto Effects\", function()\n    for k in pairs(cfg.slots) do cfg.slots[k] = \"\" end\n    populate_auto_effects(); save_cfg(); refresh_slots_label(); refresh_selected_label()\n    bsx.ui.toast(\"Reset spell .effect overrides to filtered auto picks\", { level = \"ok\" })\nend)\npanel:separator()\nfor i = 1, #SPELLS do\n    local sp = SPELLS[i]\n    panel:button(\"Cast \" .. sp.name, function() cast_spell(i) end)\n    panel:same_line()\n    panel:hotkey(sp.name .. \" Key\", cfg.hotkeys[i] or \"\", function(chord)\n        cfg.hotkeys[i] = chord or \"\"; bind_spell_hotkey(i); save_cfg()\n    end)\nend\npanel:end_tab()\n\npanel:tab(\"Active VFX & Diagnostics\")\ncap_lbl = panel:text(\"Engine: waiting...\")\nsocks_lbl = panel:text(\"Sockets: waiting for world_ready...\")\nactive_lbl = panel:text(\"Active Native VFX: none\")\ndiag_lbl = panel:text(\"Status: waiting...\")\npanel:button(\"Refresh Sockets\", function()\n    local _, _, _, _, _, _, _, _, pa = get_player_info()\n    refresh_live_sockets(pa)\nend)\npanel:same_line()\npanel:button(\"Refresh Catalog\", function() ensure_catalog(true); refresh_browser(browser_query) end)\npanel:same_line()\npanel:button(\"Stop All\", function()\n    stop_studio_handles(); projectiles = {}; meteors = {}\n    if game.vfx and game.vfx.stop_all then pcall(game.vfx.stop_all, 0.1) end\nend)\npanel:checkbox(\"Sound Effects (WAV)\", cfg.sfx_enabled, function(v) cfg.sfx_enabled = (v == true); save_cfg() end)\npanel:same_line()\npanel:checkbox(\"Camera Jolts\", cfg.cam_jolt, function(v) cfg.cam_jolt = (v == true); save_cfg() end)\npanel:slider(\"SFX Volume\", 0.05, 1.5, cfg.sfx_vol, function(v) cfg.sfx_vol = v; save_cfg() end)\npanel:button(\"Save Settings\", function() save_cfg(); bsx.ui.toast(\"Saved Spellcraft settings\", { level = \"ok\" }) end)\npanel:end_tab()\n\npanel:end_tab_bar()\n\nbsx.on(\"world_ready\", function()\n    studio_state = { active = false, mode = 1, path = \"\", bone = \"\", actor = 0, handles = {}, started_t = 0 }\n    projectiles = {}\n    meteors = {}\n    ensure_catalog(true)\n    refresh_browser(browser_query)\n    local _, _, _, _, _, _, _, _, pa = get_player_info()\n    refresh_live_sockets(pa)\nend)\n\nbsx.on(\"title_screen\", function()\n    studio_state = { active = false, mode = 1, path = \"\", bone = \"\", actor = 0, handles = {}, started_t = 0 }\n    projectiles = {}\n    meteors = {}\nend)\n\nbsx.on(\"frame\", function()\n    local now = os.clock()\n    local dt = clamp(now - last_frame_t, 0.001, 0.1)\n    last_frame_t = now\n\n    local actors, _, pk, pfac, px, py, pz, yaw, p_actor = get_player_info()\n    if not px then return end\n    ensure_catalog(false)\n    if #live_sockets == 0 and p_actor > 0 then refresh_live_sockets(p_actor) end\n\n    -- 1) Update Continuous Native VFX Studio Modes\n    if studio_state.active then\n        local mode = studio_state.mode\n        local path = studio_state.path\n        local bone = studio_state.bone\n        local total = #studio_state.handles\n        if mode == 2 and p_actor > 0 and studio_state.actor ~= p_actor then\n            studio_state.actor = p_actor\n            refresh_live_sockets(p_actor)\n            bone = current_socket_name()\n            studio_state.bone = bone\n        end\n        for i = 1, total do\n            local slot = studio_state.handles[i]\n            local h = slot and slot.h or nil\n            local info = h and h.info and h:info() or nil\n            local is_alive = (info ~= nil and info.alive) or (h and h.alive and h:alive()) or false\n            local should_replay = false\n            if cfg.auto_replay then\n                if not is_alive then\n                    should_replay = true\n                elseif info and not info.pending then\n                    if info.prepared then slot.ready_seen = true end\n                    if cfg.replay_interval > 0.05 then\n                        if (now - slot.spawned_t) >= cfg.replay_interval then should_replay = true end\n                    elseif slot.ready_seen and not info.cpu_active and not info.gpu_active and (now - slot.spawned_t) >= 0.15 then\n                        should_replay = true\n                    end\n                end\n            end\n\n            if should_replay then\n                if h then stop_handle_safe(h, 0.0) end\n                slot.h = spawn_studio_slot(i, total, mode, path, bone, p_actor, now, px, py, pz, yaw)\n                slot.spawned_t = now\n                slot.ready_seen = false\n            elseif is_alive and h then\n                if mode == 2 then\n                    pcall(function()\n                        h:set_transform({\n                            x = cfg.offset_x, y = cfg.offset_y, z = cfg.offset_z,\n                            ry = cfg.rot_y, scale = cfg.vfx_scale\n                        })\n                    end)\n                elseif mode == 1 or mode == 5 or mode == 6 then\n                    local tx, ty, tz, ry = compute_studio_slot_pose(mode, i, total, now, px, py, pz, yaw)\n                    pcall(function()\n                        h:set_transform({ x = tx, y = ty, z = tz, ry = ry, scale = cfg.vfx_scale })\n                    end)\n                end\n            end\n        end\n        if cfg.duration > 0.05 and (now - studio_state.started_t) >= cfg.duration then\n            studio_state.active = false\n        end\n    end\n\n    -- 2) Projectiles (Fireball / Custom Projectile native .effect + impact burst)\n    local keep_proj = {}\n    for i = 1, #projectiles do\n        local pr = projectiles[i]\n        local dx, dy, dz = pr.tx - pr.x, pr.ty - pr.y, pr.tz - pr.z\n        local dist = math.sqrt(dx * dx + dy * dy + dz * dz)\n        local step = pr.speed * dt\n        local hit = (dist \u003c= math.max(0.8, step)) or ((now - pr.t0) > 2.8)\n        if not hit and cfg.deal_damage and actors then\n            for ai = 1, #actors do\n                local a = actors[ai]\n                if is_hostile(a, pfac, pk) and a.x then\n                    local ad2 = (a.x - pr.x)^2 + (a.y + 1.0 - pr.y)^2 + (a.z - pr.z)^2\n                    if ad2 \u003c= 3.24 then hit = true; break end\n                end\n            end\n        end\n        if hit then\n            stop_handle_safe(pr.handle, 0.05)\n            spawn_native(pr.impact, { x = pr.x, y = pr.y, z = pr.z, scale = pr.scale * 1.25, duration = 2.0 })\n            play_sfx(\"meteor\", 1.3)\n            trigger_jolt(1.2)\n            aoe_damage(actors, pfac, pk, pr.x, pr.y, pr.z, pr.radius, pr.dmg)\n        else\n            local inv = 1.0 / math.max(0.001, dist)\n            pr.x, pr.y, pr.z = pr.x + dx * inv * step, pr.y + dy * inv * step, pr.z + dz * inv * step\n            local yaw_dir = math.deg(math.atan2(dx, dz)) + cfg.rot_y\n            if pr.handle then\n                pcall(function()\n                    pr.handle:set_transform({ x = pr.x, y = pr.y, z = pr.z, ry = yaw_dir, scale = pr.scale })\n                end)\n            end\n            keep_proj[#keep_proj + 1] = pr\n        end\n    end\n    projectiles = keep_proj\n\n    -- 3) Falling Meteors (native .effect descent -> impact burst)\n    local keep_met = {}\n    for i = 1, #meteors do\n        local m = meteors[i]\n        local age = now - m.t0\n        if age \u003c m.impact_at then\n            local tp = clamp(age / m.impact_at, 0.0, 1.0)\n            local my = m.y + 15.0 * (1.0 - tp)\n            if m.handle then pcall(function() m.handle:set_pos(m.x, my, m.z) end) end\n            keep_met[#keep_met + 1] = m\n        else\n            stop_handle_safe(m.handle, 0.05)\n            spawn_native(slot_effect(\"fireball_impact\"), { x = m.x, y = m.y + 0.3, z = m.z, scale = m.scale, duration = 2.4 })\n            play_sfx(\"meteor\", 0.9)\n            trigger_jolt(2.4)\n            if cfg.meteor_hitstop > 0.01 and game.world and game.world.set_game_speed then\n                pcall(game.world.set_game_speed, 0.16)\n                bsx.after(math.floor(cfg.meteor_hitstop * 1000), function()\n                    pcall(game.world.set_game_speed, 1.0)\n                end)\n            end\n            aoe_damage(actors, pfac, pk, m.x, m.y + 0.8, m.z, 5.6, m.dmg)\n        end\n    end\n    meteors = keep_met\nend)\n\nbsx.every(350, function()\n    local _, _, pk, pfac = get_player_info()\n    local av = (game.vfx and game.vfx.available) and game.vfx.available() or nil\n    local act = (game.vfx and game.vfx.active) and game.vfx.active() or {}\n\n    if status_lbl then\n        local mode_str = studio_state.active and (\"RUNNING \" .. STUDIO_MODES[studio_state.mode]) or (\"IDLE (\" .. STUDIO_MODES[cfg.studio_mode] .. \")\")\n        panel:set_text(status_lbl, trim_text(string.format(\"Studio: %s | Socket=%s | ActiveVFX=%d | %s\",\n            mode_str, current_socket_name() ~= \"\" and current_socket_name() or \"(none)\", #act, last_diag_str), 125))\n    end\n    if cap_lbl and av then\n        panel:set_text(cap_lbl, trim_text(string.format(\"VFX API: spawn=%s move=%s stop=%s socks=%s cat=%s | Catalog=%d | PK=%d Fac=%d\",\n            av.can_spawn and \"Y\" or \"N\", av.can_transform and \"Y\" or \"N\", av.can_stop and \"Y\" or \"N\",\n            av.can_sockets and \"Y\" or \"N\", av.can_catalog and \"Y\" or \"N\", #catalog_all, pk, pfac or -1), 125))\n    end\n    if socks_lbl then\n        local sample = {}\n        for i = 1, math.min(5, #live_sockets) do sample[i] = live_sockets[i] end\n        panel:set_text(socks_lbl, trim_text(string.format(\"Sockets (%d): %s\",\n            #live_sockets, #sample > 0 and table.concat(sample, \", \") or \"(enter world / Refresh)\"), 125))\n    end\n    if active_lbl then\n        if #act == 0 then\n            panel:set_text(active_lbl, \"Active Native VFX: none\")\n        else\n            local parts = {}\n            for i = 1, math.min(3, #act) do\n                local a = act[i]\n                local nm = tostring(a.path):match(\"([^/\\\\]+)$\") or a.path\n                parts[#parts + 1] = string.format(\"%s[p%s/a%s/c%s/g%s @(%.0f,%.0f,%.0f) x%.1f]\",\n                    nm:sub(1, 20), a.prepared and \"1\" or \"0\", a.attached and \"1\" or \"0\",\n                    a.cpu_active and \"1\" or \"0\", a.gpu_active and \"1\" or \"0\", a.x, a.y, a.z, a.scale)\n            end\n            panel:set_text(active_lbl, trim_text(\"Active (\" .. #act .. \"): \" .. table.concat(parts, \"; \"), 125))\n        end\n    end\n    if diag_lbl then\n        panel:set_text(diag_lbl, trim_text(\"Diag: \" .. last_diag_str, 125))\n    end\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Spellcraft & Native VFX Studio\",\n  \"version\": \"3.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"definitions\", \"world\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"},{"code":"[Enchants]\nActiveEnchant=4\nAuraEnabled=1\nAuraScale=1\nCombatProcs=0\nProcCooldown=0.75\nProcPower=420\n\nAttachBone=1\nAuraMode=2\nNativeVfx=1\n[Hotkeys]\nSpell1=e\nSpell2=alt+2\nSpell3=alt+3\nSpell4=alt+4\nSpell5=alt+5\n\nSpell6=alt+6\n[Spells]\nAutoAimTarget=1\nMeteorHitstop=0.09\nSpellPower=1400\nUseMPCost=0\n\nCustomDuration=3.5\nNativeScale=1\nDealDamage=1\nProjSpeed=26\n[Visuals]\nCameraJolt=1\nEnabled=1\nIntensity=1\nSoundEnabled=1\nSoundVolume=0.8\n\n[Slots]\nCustomEffect=fx_fire_cast_a__cast1.action.effect\nFireballImpact=fx_fire_torch_a__torch4.action.effect\nFireballProj=fx_decal_exp_a__fire1.action.effect\nFrostNova=\nHandAura=\nLightning=\nMeteor=\nWard=\n\n[Audio]\nCameraJolt=0\nSoundEnabled=1\nSoundVolume=0.75\n\n[Studio]\nAutoReplay=1\nCount=2\nDuration=0\nFilterCategory=1\nHideNoise=0\nMode=3\nOffsetX=0\nOffsetY=0\nOffsetZ=0\nOrbitRadius=1.8\nOrbitSpeed=2.2\nReplayInterval=0\nRotateY=0\nScale=1\nSocketName=Gimmick_Hand_R_00_Socket\n","lang":"ini","name":"settings.ini"}],"id":"recipe_spellcraft_enchants","kind":"lua","lua_api":7,"path":"bsx/lua/cookbook/spellcraft_enchants","tier":"changes","title":"Recipe: Spellcraft & Elemental Enchants (Native Engine .effect VFX)","uses":["ui","player","snapshots","positions","definitions","world","server_commands"]},{"category":"Cookbook Recipes","description":"Save named locations to sandboxed JSON, filter them in an ImGui listbox, warp cleanly with terrain snap, and share/copy bookmark JSON via clipboard.","featured":true,"files":[{"code":"-- Custom Teleport Bookmarks & Shareable Waypoints (Changes tier, Lua API 7+)\nlocal FILE = \"bookmarks.json\"\nlocal p = bsx.ui.panel(\"Waypoints & Bookmarks\")\np:set_theme({ accent = \"#D7263D\", child_bg = \"#141318\" })\n\nlocal bookmarks = {}\nif bsx.fs.exists(FILE) then\n    local ok, parsed = pcall(bsx.json.decode, bsx.fs.read(FILE))\n    if ok and type(parsed) == \"table\" then bookmarks = parsed end\nend\n\nlocal new_name, filter_q, sel = \"My Spot\", \"\", 1\nlocal shown_indices, list_id = {}, nil\n\nlocal function save_all() bsx.fs.write(FILE, bsx.json.encode(bookmarks)) end\n\nlocal function refresh_list()\n    local items, q = {}, filter_q:lower()\n    shown_indices = {}\n    for i, bm in ipairs(bookmarks) do\n        local lbl = string.format(\"%s (%.0f, %.0f, %.0f)\", bm.name, bm.x, bm.y, bm.z)\n        if q == \"\" or lbl:lower():find(q, 1, true) then\n            items[#items + 1] = lbl\n            shown_indices[#shown_indices + 1] = i\n        end\n    end\n    if #items == 0 then items[1] = \"(no matching bookmarks)\" end\n    if list_id then p:set_items(list_id, items, math.min(sel, #items)) end\nend\n\np:input_text(\"New Name\", new_name, function(v) new_name = (v ~= \"\" and v or \"Bookmark\") end)\np:same_line()\np:button(\"Save Here\", function()\n    local pos, err = game.player_position()\n    if not pos then bsx.ui.toast(tostring(err), { level = \"warn\" }); return end\n    bookmarks[#bookmarks + 1] = { name = new_name, x = pos.x, y = pos.y, z = pos.z, yaw = pos.yaw_deg or 0 }\n    save_all()\n    refresh_list()\n    bsx.ui.toast(\"Saved bookmark: \" .. new_name, { level = \"ok\" })\nend)\n\np:input_text(\"Search\", filter_q, function(v) filter_q = v or \"\"; refresh_list() end, { live = true })\nlist_id = p:listbox(\"Saved Spots\", { \"(no saved bookmarks)\" }, { height = 200 }, function(idx) sel = idx end)\n\np:button(\"Teleport Selected\", function()\n    local bm = bookmarks[shown_indices[sel] or 0]\n    if not bm then return end\n    local ok, err = game.world.teleport(bm.x, bm.y, bm.z, bm.yaw or 0, true)\n    bsx.ui.toast(ok and (\"Warped to \" .. bm.name) or tostring(err), { level = ok and \"ok\" or \"warn\" })\nend)\np:same_line()\np:button(\"Copy Share JSON\", function()\n    local bm = bookmarks[shown_indices[sel] or 0]\n    if bm and bsx.system.copy_text(bsx.json.encode(bm)) then\n        bsx.ui.toast(\"Copied waypoint JSON to clipboard!\", { level = \"ok\" })\n    end\nend)\np:same_line()\np:button(\"Delete\", function()\n    local real_idx = shown_indices[sel]\n    if not real_idx then return end\n    table.remove(bookmarks, real_idx)\n    save_all()\n    refresh_list()\nend)\nrefresh_list()","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Teleport Bookmarks\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_fast_travel_bookmarks","kind":"lua","lua_api":7,"path":"cookbook/fast_travel_bookmarks","tier":"changes","title":"Recipe: Custom Teleport Bookmarks & Shareable Waypoints","uses":["ui","player","snapshots","positions","server_commands"]},{"category":"Cookbook Recipes","description":"Resolution-aware 2.39:1 cinema letterbox bars + rule-of-thirds overlay using bsx.system.info(), plus eased A->B Free-Cam dolly tracks via bsx.tween.","featured":true,"files":[{"code":"-- Cinematic Letterbox & Smooth A->B Camera Dolly (Changes tier, Lua API 7+)\nlocal p = bsx.ui.panel(\"Cinema Rig\")\nlocal letterbox, thirds, duration = false, false, 4.0\nlocal key_a, key_b, dolly_handle = nil, nil, nil\n\nlocal function redraw_guides()\n    bsx.draw.clear()\n    if not letterbox and not thirds then return end\n    local sys = bsx.system.info()\n    local w, h = sys.viewport_w, sys.viewport_h\n    if letterbox then\n        local bar_h = math.max(0, math.floor((h - (w / 2.39)) * 0.5))\n        if bar_h > 0 then\n            bsx.draw.rect(0, 0, w, bar_h, \"#000000FF\", true)\n            bsx.draw.rect(0, h - bar_h, w, bar_h, \"#000000FF\", true)\n        end\n    end\n    if thirds then\n        for i = 1, 2 do\n            bsx.draw.line(w * i / 3, 0, w * i / 3, h, \"#FFFFFF55\", 1)\n            bsx.draw.line(0, h * i / 3, w, h * i / 3, \"#FFFFFF55\", 1)\n        end\n    end\nend\n\nlocal function capture_point(label)\n    if not game.camera.free_cam() then game.camera.set_free_cam(true) end\n    local pose = game.camera.pose()\n    if not pose or not pose.valid then return nil end\n    bsx.ui.toast(\"Captured keyframe \" .. label, { level = \"ok\" })\n    return { x = pose.x, y = pose.y, z = pose.z, fov = game.camera.fov() or 60 }\nend\n\np:checkbox(\"2.39:1 Cinema Letterbox\", letterbox, function(v) letterbox = v; redraw_guides() end)\np:checkbox(\"Rule of Thirds Grid\", thirds, function(v) thirds = v; redraw_guides() end)\np:slider(\"Dolly Duration (s)\", 1.0, 15.0, duration, function(v) duration = v end)\np:button(\"Set Start (A)\", function() key_a = capture_point(\"A\") end)\np:same_line()\np:button(\"Set End (B)\", function() key_b = capture_point(\"B\") end)\np:button(\"Play Smooth Dolly A -> B\", function()\n    if not (key_a and key_b) then bsx.ui.toast(\"Set both A and B keyframes first\", { level = \"warn\" }); return end\n    if dolly_handle then dolly_handle:off() end\n    game.camera.set_free_cam(true)\n    dolly_handle = bsx.tween.to(key_a, key_b, duration, {\n        ease = \"in_out_cubic\",\n        on_update = function(v)\n            game.camera.set_free_cam_pos(v.x, v.y, v.z)\n            game.camera.set_fov(v.fov)\n        end,\n        on_done = function() bsx.ui.toast(\"Dolly shot complete!\", { level = \"ok\" }) end,\n    })\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Cinematic Photo Rig\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_cinematic_photo_rig","kind":"lua","lua_api":7,"path":"cookbook/cinematic_photo_rig","tier":"changes","title":"Recipe: Cinematic Letterbox & A->B Camera Dolly","uses":["ui","server_commands"]},{"category":"Cookbook Recipes","description":"Widens FOV during combat, eases back during exploration, and removes sprint stamina cost inside safe zones and towns.","featured":true,"files":[{"code":"-- Contextual FOV + Town Comfort (Changes tier, Lua API 7+)\nlocal explore_fov, combat_fov = 68.0, 80.0\nlocal fov_tween, town_stam_hook = nil, nil\nlocal in_combat, in_town = false, false\n\nlocal function tween_fov(target)\n    if fov_tween then fov_tween:off(); fov_tween = nil end\n    local cur = game.camera.fov() or explore_fov\n    fov_tween = bsx.tween.to(cur, target, 0.55, {\n        ease = \"out_cubic\",\n        on_update = function(v) game.camera.set_fov(v) end,\n    })\nend\n\nlocal function update_town_stamina(town_flag)\n    in_town = town_flag == true\n    if town_stam_hook then town_stam_hook:enable(in_town) end\nend\n\nbsx.on(\"world_ready\", function()\n    if not town_stam_hook then\n        town_stam_hook = game.hooks.add(\"on_stamina_cost\", { mult = 0.0, add = 0.0, priority = 10, enabled = false })\n    end\n    local st = game.player_state()\n    if st then update_town_stamina(st.in_town or st.in_safe_zone) end\nend)\n\nbsx.on(\"zone_changed\", function(e)\n    update_town_stamina(e.in_town or e.in_safe_zone)\nend)\n\nbsx.on(\"battle_state\", function(e)\n    if e.in_battle ~= in_combat then\n        in_combat = e.in_battle == true\n        tween_fov(in_combat and combat_fov or explore_fov)\n    end\nend)\n\nlocal p = bsx.ui.panel(\"Dynamic Immersion\")\np:slider(\"Explore FOV\", 50, 100, explore_fov, function(v) explore_fov = v; if not in_combat then tween_fov(v) end end)\np:slider(\"Combat FOV\", 55, 115, combat_fov, function(v) combat_fov = v; if in_combat then tween_fov(v) end end)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Dynamic Immersion\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_dynamic_immersion_hud","kind":"lua","lua_api":7,"path":"cookbook/dynamic_immersion","tier":"changes","title":"Recipe: Contextual FOV & Town Immersion Comfort","uses":["ui","player","server_commands"]},{"category":"Cookbook Recipes","description":"Monitors HP cleanly on a 250 ms timer, draws a crimson border below threshold, and triggers game.request.use_item for your chosen potion row on cooldown.","featured":true,"files":[{"code":"-- Smart Auto-Potion & Low-HP Alert Frame (Changes tier, Lua API 7+)\nlocal POTION_ROW = config.int(\"AutoPotion\", \"ItemRow\", 1980)\nlocal HP_PCT_TRIGGER = config.int(\"AutoPotion\", \"TriggerPct\", 35)\nlocal COOLDOWN_SEC = config.int(\"AutoPotion\", \"CooldownSec\", 8)\n\nlocal enabled, last_use, world_up = true, -999.0, false\nlocal p = bsx.ui.panel(\"Auto-Potion Lifesaver\")\np:checkbox(\"Enable Auto-Potion\", enabled, function(v) enabled = v end)\np:slider(\"Trigger below HP %\", 10, 80, HP_PCT_TRIGGER, function(v) HP_PCT_TRIGGER = math.floor(v) end)\n\nlocal function find_potion_slot()\n    local bag = game.inventory.list(256)\n    if not bag then return nil end\n    for _, it in ipairs(bag) do\n        if it.row == POTION_ROW and tonumber(it.count) and tonumber(it.count) > 0 then\n            return it.bucket, it.index\n        end\n    end\n    return nil\nend\n\nlocal function draw_low_hp_border(on)\n    bsx.draw.clear()\n    if not on then return end\n    local sys = bsx.system.info()\n    bsx.draw.rect(2, 2, sys.viewport_w - 4, sys.viewport_h - 4, \"#D7263DAA\", false, 8)\nend\n\nbsx.on(\"world_ready\", function() world_up = true end)\nbsx.on(\"title_screen\", function() world_up = false; draw_low_hp_border(false) end)\n\nbsx.every(250, function()\n    if not world_up then return end\n    local actor = game.player()\n    if not actor then return end\n    local hp = game.stats.read(actor, 0) -- stat 0 = HP\n    if not hp or (hp.max or 0) \u003c= 0 then draw_low_hp_border(false); return end\n    local pct = (hp.current / hp.max) * 100.0\n    local low = pct > 0 and pct \u003c= HP_PCT_TRIGGER\n    draw_low_hp_border(low)\n    if enabled and low and (os.clock() - last_use) >= COOLDOWN_SEC then\n        local bucket, idx = find_potion_slot()\n        if bucket and idx and game.request.use_item(bucket, idx) then\n            last_use = os.clock()\n            bsx.ui.toast(string.format(\"Auto-used potion at %.0f%% HP\", pct), { level = \"warn\" })\n        end\n    end\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Auto-Potion Lifesaver\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"inventory\", \"snapshots\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_auto_potion_lifesaver","kind":"lua","lua_api":7,"path":"cookbook/auto_potion","tier":"changes","title":"Recipe: Smart Auto-Potion & Low-HP Vignette","uses":["ui","player","inventory","snapshots","server_commands"]},{"category":"Cookbook Recipes","description":"Detects newly gained bag items every 500 ms via game.inventory.list() snapshot diffs with localized item names (game.item_display_name), bottom-left fading on-screen loot ticker, drops/hour pace, and clipboard log copy.","featured":true,"files":[{"code":"-- Session Loot Tracker (Inventory-Diff + Localized Names + Screen Ticker, Safe tier, Lua API 7+)\nlocal p = bsx.ui.panel(\"Loot Tracker\")\nif p.set_theme then\n    pcall(p.set_theme, p, {\n        accent = \"#10B981\",\n        header = \"#142620\",\n        child_bg = \"#101615\",\n        border = \"#065F46\"\n    })\nend\n\nlocal show_ticker = config.bool(\"Loot\", \"ScreenTicker\", true)\nlocal toast_loot = config.bool(\"Loot\", \"ToastOnDrop\", false)\n\nlocal function save_cfg()\n    config.set(\"Loot\", \"ScreenTicker\", show_ticker)\n    config.set(\"Loot\", \"ToastOnDrop\", toast_loot)\n    config.save()\nend\n\nlocal started = os.clock()\nlocal session_items, session_events, unique_count = 0, 0, 0\nlocal baseline_ready, last_actor_key = false, nil\nlocal baseline = {}\nlocal per_item_totals = {}\nlocal name_cache = {}\nlocal feed = {}\nlocal ticker = {}\nlocal had_drawn = false\n\nlocal stat_lbl = p:text(\"Items: 0  |  Drops: 0  |  Rate: 0.0 / hr  |  Unique: 0\")\nlocal cb_ticker = p:checkbox(\"On-Screen Loot Ticker\", show_ticker, function(v)\n    show_ticker = v\n    if not v and had_drawn and bsx.draw and bsx.draw.clear then\n        pcall(bsx.draw.clear)\n        ticker = {}\n        had_drawn = false\n    end\n    save_cfg()\nend)\np:same_line()\nlocal cb_toast = p:checkbox(\"Corner Toast on Loot\", toast_loot, function(v)\n    toast_loot = v\n    save_cfg()\nend)\nlocal list_id = p:listbox(\"Recent Looted Items\", { \"(watching inventory changes)\" }, { height = 240 })\n\nlocal function item_label(row)\n    if name_cache[row] then return name_cache[row] end\n    local lbl\n    if game.item_display_name then\n        local ok, dn = pcall(game.item_display_name, row)\n        if ok and type(dn) == \"string\" and #dn > 0 then lbl = dn end\n    end\n    if not lbl and game.item_name then\n        local ok, nm = pcall(game.item_name, row)\n        if ok and type(nm) == \"string\" and #nm > 0 then lbl = nm end\n    end\n    if not lbl then lbl = \"Item #\" .. tostring(row) end\n    if #lbl > 48 then lbl = lbl:sub(1, 45) .. \"...\" end\n    name_cache[row] = lbl\n    return lbl\nend\n\nlocal function fmt_elapsed(sec)\n    local m = math.floor(sec / 60)\n    local s = math.floor(sec % 60)\n    return string.format(\"%02d:%02d\", m, s)\nend\n\nlocal function sync()\n    local hrs = math.max(1 / 3600, (os.clock() - started) / 3600.0)\n    local txt = string.format(\"Items: %d  |  Drops: %d  |  Rate: %.1f / hr  |  Unique: %d\",\n        session_items, session_events, session_items / hrs, unique_count)\n    p:set_text(stat_lbl, txt:sub(1, 125))\nend\n\nlocal function push_drop(row, delta, bag_total, label_override)\n    local lbl = label_override or item_label(row)\n    local now = os.clock()\n    if row and not per_item_totals[row] then unique_count = unique_count + 1 end\n    if row then per_item_totals[row] = (per_item_totals[row] or 0) + delta end\n    session_items = session_items + delta\n    session_events = session_events + 1\n\n    local line = bag_total\n        and string.format(\"[%s] +%d %s (Bag: %d)\", fmt_elapsed(now - started), delta, lbl, bag_total)\n        or string.format(\"[%s] +%d %s\", fmt_elapsed(now - started), delta, lbl)\n    table.insert(feed, 1, line)\n    if #feed > 80 then table.remove(feed) end\n    p:set_items(list_id, feed, 1)\n\n    if show_ticker then\n        table.insert(ticker, 1, { text = string.format(\"+%d %s\", delta, lbl), born = now, dur = 4.2 })\n        if #ticker > 6 then table.remove(ticker) end\n    end\n    if toast_loot then\n        bsx.ui.toast(string.format(\"Loot: +%d %s\", delta, lbl), { level = \"ok\", duration_ms = 2400 })\n    end\n    sync()\nend\n\nlocal function reset_baseline()\n    baseline_ready = false\n    baseline = {}\nend\n\nlocal function poll_inventory()\n    if not (game.inventory and game.inventory.list) then return end\n    local ok, inv = pcall(game.inventory.list, 2048)\n    if not ok or type(inv) ~= \"table\" then return end\n\n    local totals = {}\n    for i = 1, #inv do\n        local it = inv[i]\n        if it and it.row then\n            local cnt = tonumber(it.count) or 1\n            if cnt > 0 then\n                totals[it.row] = (totals[it.row] or 0) + cnt\n            end\n        end\n    end\n\n    if not baseline_ready or (inv.actor_key and last_actor_key and inv.actor_key ~= last_actor_key) then\n        baseline = totals\n        last_actor_key = inv.actor_key\n        baseline_ready = true\n        return\n    end\n    last_actor_key = inv.actor_key or last_actor_key\n\n    local gained = {}\n    for row, cnt in pairs(totals) do\n        local prev = baseline[row] or 0\n        if cnt > prev then\n            gained[#gained + 1] = { row = row, delta = cnt - prev, total = cnt }\n        end\n    end\n    table.sort(gained, function(a, b) return a.row \u003c b.row end)\n    for i = 1, #gained do\n        push_drop(gained[i].row, gained[i].delta, gained[i].total)\n    end\n    baseline = totals\nend\n\nbsx.every(500, function()\n    poll_inventory()\n    sync()\nend)\n\nbsx.on(\"loot_pickup\", function(e)\n    if e and e.target_key and e.target_key > 0 then\n        bsx.log(string.format(\"loot_pickup: kind=%s target=%d res=%d\",\n            tostring(e.kind), e.target_key or 0, e.result or 0))\n    end\nend)\n\nbsx.on(\"world_ready\", reset_baseline)\nbsx.on(\"save_loaded\", reset_baseline)\nbsx.on(\"load_request\", reset_baseline)\nbsx.on(\"title_screen\", reset_baseline)\n\nbsx.on(\"frame\", function()\n    if #ticker == 0 then\n        if had_drawn and bsx.draw and bsx.draw.clear then\n            bsx.draw.clear()\n            had_drawn = false\n        end\n        return\n    end\n    if not (show_ticker and bsx.draw and bsx.draw.clear) then return end\n    bsx.draw.clear()\n    local si = bsx.system and bsx.system.info and bsx.system.info() or nil\n    local vh = (si and si.viewport_h and si.viewport_h > 0) and si.viewport_h or 1080\n    local now = os.clock()\n    local alive = {}\n    local y = vh - 210\n    for i = 1, #ticker do\n        local tk = ticker[i]\n        local p01 = (now - tk.born) / tk.dur\n        if p01 \u003c 1.0 then\n            alive[#alive + 1] = tk\n            local a = (p01 \u003c 0.08) and (p01 / 0.08) or ((p01 > 0.72) and (1.0 - (p01 - 0.72) / 0.28) or 1.0)\n            local aa = math.max(0, math.min(255, math.floor(a * 255 + 0.5)))\n            bsx.draw.text(28, y + 1, tk.text, string.format(\"#000000%02X\", math.floor(aa * 0.85)), 1.05)\n            bsx.draw.text(27, y, tk.text, string.format(\"#34D399%02X\", aa), 1.05)\n            y = y - 24\n        end\n    end\n    ticker = alive\n    had_drawn = (#ticker > 0)\nend)\n\np:button(\"Test Ticker\", function()\n    push_drop(nil, 3, nil, \"Sample Crimson Ore\")\nend)\np:same_line()\np:button(\"Reset Session\", function()\n    started = os.clock()\n    session_items, session_events, unique_count = 0, 0, 0\n    per_item_totals = {}\n    feed = {}\n    ticker = {}\n    if had_drawn and bsx.draw and bsx.draw.clear then pcall(bsx.draw.clear); had_drawn = false end\n    reset_baseline()\n    p:set_items(list_id, { \"(session reset - watching inventory)\" }, 1)\n    sync()\nend)\np:same_line()\np:button(\"Copy Loot Log\", function()\n    local ok = bsx.system.copy_text(#feed > 0 and table.concat(feed, \"\\n\") or \"No loot recorded yet.\")\n    bsx.ui.toast(ok and \"Loot log copied!\" or \"Nothing to copy\", { level = ok and \"ok\" or \"warn\" })\nend)\n\nfunction on_unload()\n    if bsx.draw and bsx.draw.clear then pcall(bsx.draw.clear) end\nend","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Loot Tracker\",\n  \"version\": \"1.1.0\",\n  \"lua_api\": 7,\n  \"uses\": [\"ui\", \"player\", \"inventory\", \"definitions\"],\n  \"needs_ids\": [\n    \"ItemInfo::DisplayName\",\n    \"Localization::sTextPoolManager\"\n  ]\n}","lang":"json","name":"script.json"}],"id":"recipe_loot_value_tracker","kind":"lua","lua_api":7,"path":"cookbook/loot_tracker","tier":"safe","title":"Recipe: Inventory-Diff Loot Feed & Screen Ticker","uses":["ui","player","inventory","definitions"]},{"category":"Cookbook Recipes","description":"Tune parry window & parry range sliders live, toggle zero-damage sparring mode with an on_damage hook, bind a 0.5x slow-mo hotkey, and count Boss Rush phases.","featured":true,"files":[{"code":"-- Boss Rush & Parry Practice Trainer (Changes tier, Lua API 7+)\nlocal p = bsx.ui.panel(\"Parry & Boss Practice\")\nlocal god_hook = game.hooks.add(\"on_damage\", { target = \"taken\", mult = 0.0, add = 0.0, priority = 50, enabled = false })\nlocal slowmo = false\nlocal rush_lbl = p:text(\"Boss Rush: idle\")\n\np:checkbox(\"No Damage Taken (Sparring Mode)\", false, function(on)\n    if god_hook then god_hook:enable(on) end\nend)\np:slider(\"Parry Window Scale\", 0.5, 4.0, game.gameplay.parry_window_scale() or 1.0, function(v)\n    game.gameplay.set_parry_window_scale(v)\nend)\np:slider(\"Parry Range Scale\", 0.5, 3.0, game.gameplay.parry_range_scale() or 1.0, function(v)\n    game.gameplay.set_parry_range_scale(v)\nend)\n\nlocal function toggle_slowmo()\n    slowmo = not slowmo\n    game.world.set_game_speed(slowmo and 0.5 or 1.0)\n    bsx.ui.toast(slowmo and \"Practice Slow-Mo 0.5x\" or \"Normal Speed 1.0x\", { level = \"info\" })\nend\np:button(\"Toggle Slow-Mo (Ctrl+F11)\", toggle_slowmo)\npcall(bsx.hotkey, \"ctrl+f11\", toggle_slowmo)\n\nbsx.on(\"boss_rush_event\", function(e)\n    p:set_text(rush_lbl, string.format(\"Boss Rush: %s | %s (%d/%d)\", e.phase, e.event_name, e.round, e.round_limit))\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Parry & Boss Practice\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"world\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_boss_rush_practice","kind":"lua","lua_api":7,"path":"cookbook/boss_practice_trainer","tier":"changes","title":"Recipe: Boss Rush & Parry Practice Arena Trainer","uses":["ui","world","server_commands"]},{"category":"Cookbook Recipes","description":"All-in-one life-skill control panel: fish/bug catch multipliers, trap chance scale, instant interaction hold bypass, Dragon Anywhere summon, and mount stamina lock.","featured":true,"files":[{"code":"-- Cozy Fishing, Gathering & Dragon Mount QoL (Changes tier, Lua API 7+)\nlocal p = bsx.ui.panel(\"Life-Skill & Mount QoL\")\nlocal catches = 0\nlocal lbl = p:text(\"Session fishing catches: 0\")\n\np:slider(\"Fish Catch Multiplier\", 1, 20, game.fishing.catch_multiplier() or 1, function(v)\n    game.fishing.set_catch_multiplier(math.floor(v))\nend)\np:slider(\"Bug Catch Multiplier\", 1, 20, game.fishing.bug_catch_multiplier() or 1, function(v)\n    game.fishing.set_bug_catch_multiplier(math.floor(v))\nend)\np:slider(\"Fishing Trap Chance Scale\", 0.5, 5.0, game.fishing.trap_chance_scale() or 1.0, function(v)\n    game.fishing.set_trap_chance_scale(v)\nend)\np:slider(\"Gather Multiplier\", 1, 10, game.gameplay.gather_multiplier() or 1, function(v)\n    game.gameplay.set_gather_multiplier(math.floor(v))\nend)\np:checkbox(\"Instant Interact\", game.gameplay.interact_hold() or false, function(on)\n    game.gameplay.set_interact_hold(on)\nend)\np:checkbox(\"Summon Dragon Anywhere\", game.mounts.dragon_anywhere() or false, function(on)\n    game.mounts.set_dragon_anywhere(on)\nend)\np:checkbox(\"Lock Display Mount Stamina\", game.mounts.display_stamina_lock() or false, function(on)\n    game.mounts.set_display_stamina_lock(on)\nend)\n\nbsx.on(\"fishing_result\", function(e)\n    catches = catches + 1\n    p:set_text(lbl, string.format(\"Session catches: %d (matched=%s cat=%d)\", catches, tostring(e.matched), e.category_key or 0))\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Cozy Life-Skill QoL\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_fishing_gathering_qol","kind":"lua","lua_api":7,"path":"cookbook/cozy_lifeskill_qol","tier":"changes","title":"Recipe: Cozy Fishing, Gathering & Dragon Mount QoL","uses":["ui","server_commands"]},{"category":"Cookbook Recipes","description":"Export your character part visibility preset to JSON, copy it straight to Discord with bsx.system.copy_text, or paste & apply a friend's preset code live.","featured":true,"files":[{"code":"-- Shareable Outfit Studio (Changes tier, Lua API 7+)\nlocal p = bsx.ui.panel(\"Shareable Wardrobe\")\nlocal paste_buf = \"\"\nlocal box_id = nil\n\np:button(\"Export Current Look to Clipboard\", function()\n    local preset, err = game.appearance.export_preset()\n    if not preset then bsx.ui.toast(tostring(err), { level = \"warn\" }); return end\n    local encoded = bsx.json.encode(preset)\n    paste_buf = encoded\n    if box_id then p:set_value(box_id, encoded) end\n    bsx.system.copy_text(encoded)\n    bsx.ui.toast(\"Look preset copied to clipboard!\", { level = \"ok\" })\nend)\n\nbox_id = p:multiline(\"Paste Preset JSON\", paste_buf, 110, function(v) paste_buf = v or \"\" end)\n\np:button(\"Apply Pasted Look\", function()\n    local ok_j, preset = pcall(bsx.json.decode, paste_buf)\n    if not ok_j or type(preset) ~= \"table\" then\n        bsx.ui.toast(\"Invalid preset JSON\", { level = \"warn\" }); return\n    end\n    local ok, err = game.appearance.apply_preset(preset)\n    bsx.ui.toast(ok and \"Applied shared preset!\" or tostring(err), { level = ok and \"ok\" or \"warn\" })\nend)\np:same_line()\np:button(\"Reset Parts\", function()\n    game.appearance.clear_part_overrides()\n    bsx.ui.toast(\"Appearance part overrides cleared\", { level = \"info\" })\nend)","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Shareable Wardrobe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_shareable_wardrobe","kind":"lua","lua_api":7,"path":"cookbook/shareable_wardrobe","tier":"changes","title":"Recipe: Shareable Outfit Studio (Clipboard Export/Import)","uses":["ui","server_commands"]},{"category":"Cookbook Recipes","description":"Data-only Lua API 7 pack using tweaks.json schema_version 4 to enable Dragon Anywhere, lock mount stamina, boost fishing/gathering, widen parry range, and cut crafting materials in half.","featured":true,"files":[{"code":"{\n  \"schema_version\": 4,\n  \"description\": \"Cozy Explorer preset: mounts, fishing, forgiving parries & lighter crafting.\",\n  \"recipes\": {\n    \"1\": {\n      \"name\": \"Half-Cost Starter Craft\",\n      \"material_count_scale\": 0.5\n    }\n  },\n  \"gameplay\": {\n    \"dragon_anywhere\": true,\n    \"mount_display_stamina_lock\": true,\n    \"fish_catch_multiplier\": 3,\n    \"bug_catch_multiplier\": 3,\n    \"gather_multiplier\": 2,\n    \"parry_range_scale\": 1.35,\n    \"ignore_wanted_surcharge\": true,\n    \"stamina_cost_scale\": 0.7\n  },\n  \"hooks\": [\n    {\n      \"channel\": \"on_parry_window\",\n      \"mult\": 1.25,\n      \"add\": 0.0,\n      \"priority\": 0,\n      \"enabled\": true\n    }\n  ]\n}","lang":"json","name":"tweaks.json"},{"code":"{\n  \"name\": \"Cozy Explorer Pack\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 7,\n  \"data_only\": true,\n  \"changes\": true,\n  \"uses\": [\"server_commands\"]\n}","lang":"json","name":"script.json"}],"id":"recipe_cozy_explorer_pack","kind":"data_only","lua_api":7,"path":"cookbook/cozy_explorer_pack","tier":"data_only","title":"Recipe: Data-Only Cozy Explorer Pack (tweaks.json v4)","uses":["server_commands"]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Aerial Maneuver: the Improved Axiom mod's edit, which removes one call from the aerial update loop. Native tier: the player approves this folder like a DL","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Aerial Maneuver: the Improved Axiom mod's edit, which removes one call from\n-- the aerial update loop. Native tier: the player approves this folder like a\n-- DLL mod. Recipe and limits: bsx/lua/recipes/r5-flight.md. Not yet tested in\n-- game. Do not run the Improved Axiom ASI at the same time.\nlocal ffi = require(\"ffi\")\nlocal function log(message) bsx.log(\"aerial_maneuver: \" .. message) end\nlocal SITE = \"AerialManeuver::UpdateLoopCall\"\n\nif not config.bool(\"AerialManeuver\", \"Enabled\", true) then return log(\"off\") end\n\n-- The call is E8 xx xx xx xx. Its distance differs between builds, but on every\n-- checked build it is E8 ?? CF FF FF followed by the loop counter step.\nlocal CALL = {0xE8, nil, 0xCF, 0xFF, 0xFF, 0x48, 0x83, 0xEB, 0x01}\nlocal at = tonumber(ffi.cast(\"uintptr_t\", cdal.address(SITE)))\nfor i = 1, 9 do\n    if CALL[i] and mem.read_u8(at + i - 1) ~= CALL[i] then\n        return log(\"off: the game's bytes are not the checked call\")\n    end\nend\nlocal ok, why = cdal.patch(SITE, string.rep(\"\\x90\", 5))  -- five NOPs replace the call\nlog(ok and \"on\" or \"off: \" .. tostring(why))\n","lang":"lua","name":"main.lua"},{"code":"[AerialManeuver]\n; Improved Axiom aerial maneuvering. A byte patch: it stays until you set\n; Enabled=0 (the script then reloads and the game's bytes come back) or quit.\nEnabled=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Aerial Maneuver\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"AerialManeuver::UpdateLoopCall\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"aerial_maneuver","kind":"lua","lua_api":3,"path":"bsx/lua/examples/aerial_maneuver","tier":"safe","title":"Aerial Maneuver","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Ammo Saving: shooting does not use up arrows and other ammunition. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Ammo Saving: shooting does not use up arrows and other ammunition.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r4-stamina.md. Not yet tested in game.\n--\n-- When ammunition is used, one caller asks a lookup function for a chance\n-- value, with a selector in R8D. The ammunition-saving mod answers 1000000 for\n-- six selectors. Each rule here does the same: only for that one caller (the\n-- return address at [rsp] on entry) and one selector, the function returns\n-- 1000000 at once. Every other call runs normally.\nlocal function log(message) bsx.log(\"ammo_saving: \" .. message) end\nlocal SELECTORS = {1000000, 1000013, 1000014, 1000015, 1000017, 1000018}\n\nlocal caller = cdal.address(\"AmmoSave::ChanceLookupReturn\")\nlocal start = config.bool(\"Ammo\", \"Enabled\", true)\nlocal rules = {}\nfor _, selector in ipairs(SELECTORS) do\n    local rule, why = cdal.rule(\"AmmoSave::ChanceLookup\", {\n        expect = \"E9 ?? ?? ?? ??\",  -- the entry is a jump on every checked build\n        enabled = start,\n        when = { {\"[rsp+0x0].u64\", \"==\", caller}, {\"r8d\", \"==\", selector} },\n        ret = {\"eax\", 1000000},\n    })\n    if not rule then\n        for _, r in ipairs(rules) do r:remove() end  -- all six or none\n        return log(\"off: \" .. tostring(why))\n    end\n    rules[#rules + 1] = rule\nend\n\nlocal function hits()\n    local total = 0\n    for _, r in ipairs(rules) do total = total + r:hits() end\n    return total\nend\nlocal chord = config.string(\"Ammo\", \"Hotkey\", \"ctrl+numpad2\")\nlocal ok, why = pcall(bsx.hotkey, chord, function()\n    local on = not rules[1]:active()\n    for _, r in ipairs(rules) do r:enable(on) end\n    log((on and \"on\" or \"off\") .. \" (\" .. hits() .. \" matching uses so far)\")\nend)\nlog((start and \"on\" or \"off\") .. \"; \" .. (ok and chord .. \" toggles\" or \"no toggle key: \" .. tostring(why)))\n","lang":"lua","name":"main.lua"},{"code":"[Ammo]\n; 1 turns ammunition saving on when the game starts; the hotkey toggles it.\n; It does not change firearm reload animations.\nEnabled=1\nHotkey=ctrl+numpad2\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Ammo Saving\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"AmmoSave::ChanceLookup\",\n    \"AmmoSave::ChanceLookupReturn\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"ammo_saving","kind":"lua","lua_api":3,"path":"bsx/lua/examples/ammo_saving","tier":"safe","title":"Ammo Saving","uses":[]},{"category":"UI & Overlays","description":"Runnable BSX Lua example (api4_panel).","featured":false,"files":[{"code":"local panel = bsx.ui.panel(\"API 4 Live Panel\")\nlocal status_id = panel:text(\"Waiting for world...\")\npanel:separator()\n\nlocal auto_update = true\nlocal poll_seconds = 2.0\nlocal world_ready = false\nlocal logged_panel = false\n\nlocal function read_player_line()\n    local actors, why_a = game.actors(32)\n    if not actors then\n        return \"Snapshot unavailable: \" .. tostring(why_a)\n    end\n    for i = 1, #actors do\n        if actors[i].controlled then\n            local st, why_s = game.stats.read(actors[i].actor, 0)\n            if st then\n                return string.format(\"HP: %d / %d (actors=%d)\", st.current, st.max, actors.total or #actors)\n            end\n            return \"HP unavailable: \" .. tostring(why_s)\n        end\n    end\n    return \"No controlled actor in snapshot\"\nend\n\npanel:button(\"Refresh & Log\", function()\n    local line = read_player_line()\n    panel:set_text(status_id, line)\n    bsx.bus.emit(\"api4_panel.refreshed\", { text = line, dev = bsx.dev_mode })\n    bsx.log(\"api4_panel: \" .. line)\nend)\n\npanel:checkbox(\"Auto refresh\", auto_update, function(checked)\n    auto_update = checked\n    bsx.log(\"api4_panel: auto_update=\" .. tostring(checked))\nend)\n\npanel:slider(\"Poll seconds\", 1.0, 10.0, poll_seconds, function(value)\n    poll_seconds = value\nend)\n\nbsx.bus.provide(\"api4_panel.state\", function()\n    return { active = panel:active(), auto = auto_update, poll = poll_seconds, world_ready = world_ready }\nend)\n\nlocal function on_world_entered()\n    if world_ready then return end\n    world_ready = true\n    panel:set_text(status_id, \"World ready | \" .. read_player_line())\nend\n\nlocal function sync_world_ready()\n    if world_ready then return end\n    local st = game.player_state()\n    if (st and st.world_ready) or game.player_position() then\n        on_world_entered()\n    end\nend\n\nbsx.on(\"world_ready\", on_world_entered)\nbsx.on(\"save_load\", function() world_ready = false end)\npcall(bsx.on, \"title_screen\", function() world_ready = false end)\n\nlocal last_poll = 0\nbsx.on(\"frame\", function()\n    if not logged_panel then\n        logged_panel = true\n        bsx.log(\"api4_panel: panel ready dev=\" .. tostring(bsx.dev_mode))\n    end\n    sync_world_ready()\n    if not auto_update or not world_ready then return end\n    local now = os.clock()\n    if now - last_poll >= poll_seconds then\n        last_poll = now\n        panel:set_text(status_id, read_player_line())\n    end\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"API 4 Overlay Panel\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"uses\": [\"player\", \"snapshots\", \"bus\", \"ui\"]\n}\n","lang":"json","name":"script.json"}],"id":"api4_panel","kind":"lua","lua_api":4,"path":"bsx/lua/examples/api4_panel","tier":"safe","title":"API 4 Overlay Panel","uses":["player","snapshots","bus","ui"]},{"category":"World, Time & Exploration","description":"Demonstrates BSX Lua API 7 and Wave 19 Overlay features inside one structured `bsx.ui.panel` window alongside a `tweaks.json` v4 override file:","featured":false,"files":[{"code":"-- API 7 Showcase: UI/4 tabs & tables, bsx.tween & bsx.audio, recipes, API 7 domains/hooks, and passive events.\n\nlocal state = {\n  wind_mult = 1.0,\n  wind_hook_on = false,\n  counts = {\n    fishing_result = 0,\n    loot_pickup = 0,\n    pet_summoned = 0,\n    boss_rush_event = 0,\n  },\n}\n\nlocal wind_hook = nil\nlocal pulse_tween = nil\n\nlocal panel = bsx.ui.panel('API 7 Showcase')\nlocal status_lbl, recipe_lbl, dye_lbl, pets_lbl, events_lbl, pulse_lbl\n\nlocal function clamp_text(s, limit)\n  local txt = tostring(s or '')\n  if #txt \u003c= limit then return txt end\n  return string.sub(txt, 1, limit - 3) .. '...'\nend\n\nlocal function refresh_events_label()\n  if panel and events_lbl then\n    panel:set_text(events_lbl, string.format(\n      'Events: fish=%d loot=%d pet=%d boss=%d',\n      state.counts.fishing_result,\n      state.counts.loot_pickup,\n      state.counts.pet_summoned,\n      state.counts.boss_rush_event\n    ))\n  end\nend\n\nlocal function refresh_world_snapshot()\n  local ok_r, recipes, r_err = pcall(game.recipes.find, '', 3)\n  local ok_w, wind, w_err = pcall(game.world.wind_scale)\n  local ok_d, dyes, d_err = pcall(game.appearance.dye_palettes, 8)\n  local ok_b, ban_days = pcall(game.minigames.ban_duration_days)\n  local ok_p, pets, p_err = pcall(game.pets.observed)\n\n  if panel and status_lbl then\n    local wtxt = (ok_w and wind ~= nil) and string.format('wind=%.2fx', wind) or ('wind=' .. tostring(w_err))\n    local btxt = ok_b and ban_days ~= nil and ('ban_days=' .. tostring(ban_days)) or 'ban_days=?'\n    panel:set_text(status_lbl, clamp_text(wtxt .. ' | ' .. btxt, 118))\n  end\n  if panel and recipe_lbl then\n    if ok_r and type(recipes) == 'table' then\n      local first = recipes[1] and (tostring(recipes[1].row) .. ':' .. tostring(recipes[1].name or recipes[1].display_name or '-')) or 'none'\n      panel:set_text(recipe_lbl, clamp_text(string.format('Recipes sampled: %d (first=%s)', #recipes, first), 118))\n    else\n      panel:set_text(recipe_lbl, clamp_text('Recipes: ' .. tostring(r_err), 118))\n    end\n  end\n  if panel and dye_lbl then\n    if ok_d and type(dyes) == 'table' then\n      panel:set_text(dye_lbl, string.format('Dye palettes: groups=%d textures=%d', #(dyes.color_groups or {}), #(dyes.texture_palettes or {})))\n    else\n      panel:set_text(dye_lbl, clamp_text('Dye palettes: ' .. tostring(d_err), 118))\n    end\n  end\n  if panel and pets_lbl then\n    if ok_p and type(pets) == 'table' then\n      panel:set_text(pets_lbl, string.format('Observed pets: %d', #pets))\n    else\n      panel:set_text(pets_lbl, clamp_text('Observed pets: ' .. tostring(p_err), 118))\n    end\n  end\nend\n\nlocal function sync_wind_hook()\n  if wind_hook then\n    wind_hook:remove()\n    wind_hook = nil\n  end\n  if state.wind_hook_on then\n    wind_hook = game.hooks.add('on_wind', { mult = state.wind_mult, add = 0.0, priority = 0 })\n  end\nend\n\nif panel then\n  panel:colored_text('BSX Lua API 7 & UI/4 Showcase', { r = 0.45, g = 0.85, b = 1.0, a = 1.0 })\n  panel:tooltip('Exercises UI/4 tables & tabs, bsx.tween, bsx.audio, recipes, wind hooks, and Wave 21 events')\n\n  panel:begin_tab_bar('api7_showcase_tabs')\n\n  panel:tab('Overview')\n  status_lbl = panel:text('Waiting for world_ready...')\n  pulse_lbl = panel:text('Tween pulse: idle')\n  panel:button('Tween Pulse', function()\n    if pulse_tween and pulse_tween.cancel then pulse_tween:cancel() end\n    pulse_tween = bsx.tween.to(0.0, 1.0, 0.35, {\n      ease = 'out_quad',\n      on_update = function(v)\n        if panel and pulse_lbl then\n          panel:set_text(pulse_lbl, string.format('Tween pulse: %.2f', v))\n        end\n      end,\n      on_done = function()\n        if panel and pulse_lbl then\n          panel:set_text(pulse_lbl, 'Tween pulse: complete')\n        end\n      end,\n    })\n  end)\n  panel:same_line()\n  panel:button('Audio Vol Check', function()\n    local vol = bsx.audio.master_volume()\n    bsx.ui.toast(string.format('Audio master volume: %.2f', vol), { title = 'API 7 Showcase', level = 'info' })\n  end)\n  panel:end_tab()\n\n  panel:tab('Recipes & Wind')\n  recipe_lbl = panel:text('Recipes: waiting')\n  dye_lbl = panel:text('Dye palettes: waiting')\n  panel:drag_float('Wind Multiplier', state.wind_mult, 0.05, 0.0, 5.0, function(v)\n    state.wind_mult = v\n    if state.wind_hook_on then sync_wind_hook() end\n  end)\n  panel:checkbox('Enable on_wind Hook', state.wind_hook_on, function(v)\n    state.wind_hook_on = (v == true)\n    sync_wind_hook()\n  end)\n  local sample_ok, sample_rows = pcall(game.recipes.find, '', 3)\n  panel:begin_table('api7_sample_recipes', 3, { 'Row', 'Name', 'Scale' })\n  if sample_ok and type(sample_rows) == 'table' and #sample_rows > 0 then\n    for _, row in ipairs(sample_rows) do\n      panel:table_row()\n      panel:table_cell(tostring(row.row or '?'))\n      panel:table_cell(clamp_text(row.name or row.display_name or '-', 32))\n      panel:table_cell(tostring(row.fixed_material_count or '-'))\n    end\n  else\n    panel:table_row()\n    panel:table_cell('1')\n    panel:table_cell('Recipe sample (live when loaded)')\n    panel:table_cell('0.50x')\n  end\n  panel:end_table()\n  panel:end_tab()\n\n  panel:tab('Events & Pets')\n  pets_lbl = panel:text('Observed pets: waiting')\n  events_lbl = panel:text('Events: fish=0 loot=0 pet=0 boss=0')\n  panel:button('Refresh Snapshot', function()\n    refresh_world_snapshot()\n  end)\n  panel:end_tab()\n\n  panel:end_tab_bar()\nend\n\nfor name, _ in pairs(state.counts) do\n  bsx.on(name, function()\n    state.counts[name] = state.counts[name] + 1\n    refresh_events_label()\n  end)\nend\n\nbsx.on('world_ready', function()\n  refresh_world_snapshot()\n  refresh_events_label()\n  local vol = bsx.audio.master_volume()\n  local ok_w, wind = pcall(game.world.wind_scale)\n  local ok_r, recipes = pcall(game.recipes.find, '', 3)\n  bsx.log(string.format('API7_SHOWCASE_READY recipes=%s wind=%s audio_vol=%.2f',\n    (ok_r and type(recipes) == 'table') and tostring(#recipes) or 'nil',\n    ok_w and tostring(wind) or 'nil',\n    vol))\nend)\n\nfunction on_unload()\n  if wind_hook and wind_hook.remove then\n    wind_hook:remove()\n    wind_hook = nil\n  end\n  if pulse_tween and pulse_tween.cancel then\n    pulse_tween:cancel()\n    pulse_tween = nil\n  end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"schema_version\": 4,\n  \"description\": \"Showcase tweaks.json v4 pack overriding a recipe row and API 7 wind/fishing/parry scales safely.\",\n  \"recipes\": {\n    \"1\": {\n      \"name\": \"Sample Recipe Override\",\n      \"material_count_scale\": 0.5\n    }\n  },\n  \"gameplay\": {\n    \"wind_scale\": 1.0,\n    \"parry_range_scale\": 1.0,\n    \"fish_catch_multiplier\": 1\n  },\n  \"hooks\": [\n    {\n      \"channel\": \"on_wind\",\n      \"mult\": 1.0,\n      \"add\": 0.0,\n      \"priority\": 0,\n      \"enabled\": true\n    }\n  ]\n}\n","lang":"json","name":"tweaks.json"},{"code":"{\n  \"name\": \"API 7 Showcase\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"snapshots\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"api7_showcase","kind":"lua","lua_api":7,"path":"bsx/lua/examples/api7_showcase","tier":"changes","title":"API 7 Showcase","uses":["ui","snapshots","server_commands"]},{"category":"Appearance & Outfits","description":"Lua API 4 controlled-player part visibility studio, equipped visual gear inspector, and customization observer.","featured":false,"files":[{"code":"-- Appearance Studio: Lua API 4 player part-visibility studio, equipped gear inspector,\n-- JSON visibility presets, and Character Customization observer.\n\nlocal function clamp_text(text)\n    local s = tostring(text or \"\"):gsub(\"%z\", \" \")\n    if #s \u003c= 127 then return s end\n    return string.sub(s, 1, 124) .. \"...\"\nend\n\nlocal function toast_msg(msg, level)\n    if bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(clamp_text(msg), { level = level or \"info\", duration_ms = 2600 })\n    end\nend\n\nlocal function json_encode_flat(tbl)\n    local keys = {}\n    for k in pairs(tbl) do\n        if type(k) == \"string\" then keys[#keys + 1] = k end\n    end\n    table.sort(keys)\n    local lines = { \"{\" }\n    for i = 1, #keys do\n        local k = keys[i]\n        local v = tbl[k]\n        local vs = tostring(math.floor(tonumber(v) or -1))\n        local comma = (i \u003c #keys) and \",\" or \"\"\n        lines[#lines + 1] = '  \"' .. k .. '\": ' .. vs .. comma\n    end\n    lines[#lines + 1] = \"}\"\n    return table.concat(lines, \"\\n\") .. \"\\n\"\nend\n\nlocal function json_decode_flat(text)\n    if type(text) ~= \"string\" then return nil end\n    local out = {}\n    local pos = 1\n    local len = #text\n    while pos \u003c= len do\n        local nl = string.find(text, \"\\n\", pos, true)\n        local line = nl and string.sub(text, pos, nl - 1) or string.sub(text, pos)\n        pos = nl and (nl + 1) or (len + 1)\n        local q1 = string.find(line, '\"', 1, true)\n        if q1 then\n            local q2 = string.find(line, '\"', q1 + 1, true)\n            if q2 then\n                local col = string.find(line, \":\", q2 + 1, true)\n                if col then\n                    local key = string.sub(line, q1 + 1, q2 - 1)\n                    local val_str = string.sub(line, col + 1)\n                    while #val_str > 0 and (string.sub(val_str, 1, 1) == \" \" or string.sub(val_str, 1, 1) == \"\\t\") do\n                        val_str = string.sub(val_str, 2)\n                    end\n                    while #val_str > 0 do\n                        local last = string.sub(val_str, -1)\n                        if last == \" \" or last == \"\\t\" or last == \"\\r\" or last == \",\" then\n                            val_str = string.sub(val_str, 1, -2)\n                        else\n                            break\n                        end\n                    end\n                    local num = tonumber(val_str)\n                    if num ~= nil then out[key] = math.floor(num) end\n                end\n            end\n        end\n    end\n    return out\nend\n\nlocal auto_refresh = config.bool(\"AppearanceStudio\", \"AutoRefresh\", true)\nlocal world_ready = false\nlocal logged_ready = false\nlocal parts_list = {}\nlocal part_pages = { { labels = { \"(no parts observed yet)\" }, items = {} } }\nlocal part_page = 1\nlocal part_idx = 1\nlocal preset_labels = { \"Preset 1\", \"Preset 2\", \"Preset 3\" }\nlocal preset_idx = 1\n\nlocal panel = bsx.ui.panel(\"Appearance Studio\")\nlocal status_id = panel:text(\"Appearance Studio: waiting for world_ready...\")\nlocal gear_info_id, part_detail_id, part_combo_id, preset_combo_id, cust_info_id\n\nlocal function set_status(msg)\n    panel:set_text(status_id, clamp_text(msg))\nend\n\nlocal function mode_tag(mode)\n    if mode == 0 then return \"HIDE\" end\n    if mode == 1 then return \"SHOW\" end\n    return \"native\"\nend\n\nlocal function selected_part_entry()\n    local pg = part_pages[part_page]\n    return pg and pg.items[part_idx] or nil\nend\n\nlocal function update_selected_part_detail()\n    local e = selected_part_entry()\n    if not e then\n        panel:set_text(part_detail_id, string.format(\"Parts: %d observed\", #parts_list))\n        return\n    end\n    local nm = e.name or string.format(\"0x%X\", e.key or 0)\n    panel:set_text(part_detail_id, clamp_text(string.format(\n        \"p%d/%d (%d) %s [key=%d] ov=%s\",\n        part_page, #part_pages, #parts_list, nm, e.key or 0, mode_tag(e.override_mode))))\nend\n\nlocal function show_part_page(target_page, target_idx)\n    if #part_pages == 0 then\n        part_pages = { { labels = { \"(no parts observed yet)\" }, items = {} } }\n    end\n    part_page = math.max(1, math.min(#part_pages, target_page or 1))\n    local pg = part_pages[part_page]\n    part_idx = math.max(1, math.min(math.max(1, #pg.labels), target_idx or 1))\n    panel:set_items(part_combo_id, pg.labels, part_idx)\n    update_selected_part_detail()\nend\n\nlocal function refresh_parts(silent)\n    if not world_ready then\n        if not silent then set_status(\"Waiting for world_ready...\") end\n        return\n    end\n    local list, why = game.appearance.parts()\n    if not list then\n        if not silent then set_status(\"Parts unavailable: \" .. tostring(why)) end\n        return\n    end\n    local prev_e = selected_part_entry()\n    local prev_key = prev_e and prev_e.key or nil\n    parts_list = list\n    local pages = {}\n    local target_page, target_idx = 1, 1\n    if #list == 0 then\n        pages[1] = { labels = { \"(no parts observed yet)\" }, items = {} }\n    else\n        local cur_labels, cur_items, cur_bytes = {}, {}, 0\n        for i = 1, #list do\n            local e = list[i]\n            local nm = e.name or string.format(\"key_%d\", e.key or 0)\n            if #nm > 20 then nm = string.sub(nm, 1, 17) .. \"...\" end\n            local lbl = string.format(\"[%s] %s (%d)\", mode_tag(e.override_mode), nm, e.key or 0)\n            if #lbl > 36 then lbl = string.sub(lbl, 1, 36) end\n            local add_bytes = #lbl + 1\n            if #cur_labels >= 6 or (cur_bytes + add_bytes > 240 and #cur_labels > 0) then\n                pages[#pages + 1] = { labels = cur_labels, items = cur_items }\n                cur_labels, cur_items, cur_bytes = {}, {}, 0\n            end\n            cur_labels[#cur_labels + 1] = lbl\n            cur_items[#cur_items + 1] = e\n            cur_bytes = cur_bytes + add_bytes\n            if prev_key and e.key == prev_key then\n                target_page = #pages + 1\n                target_idx = #cur_labels\n            end\n        end\n        if #cur_labels > 0 then\n            pages[#pages + 1] = { labels = cur_labels, items = cur_items }\n        end\n    end\n    part_pages = pages\n    show_part_page(target_page, target_idx)\n    if not silent then\n        set_status(string.format(\"Refreshed %d observed player part(s)\", #list))\n    end\nend\n\nlocal function apply_selected_part(mode)\n    if not world_ready then return set_status(\"Waiting for world_ready...\") end\n    local e = selected_part_entry()\n    if not e or not e.key then\n        return set_status(\"Select an observed part first (press Refresh Parts)\")\n    end\n    local ok, why = game.appearance.set_part_visibility(e.key, mode)\n    if ok then\n        local nm = e.name or (\"key \" .. tostring(e.key))\n        local msg = string.format(\"%s -> %s\", nm, mode_tag(mode))\n        set_status(msg)\n        toast_msg(msg, \"info\")\n        refresh_parts(true)\n    else\n        set_status(\"Override blocked: \" .. tostring(why))\n        toast_msg(\"Override blocked: \" .. tostring(why), \"warn\")\n    end\nend\n\nlocal function refresh_gear()\n    if not world_ready then return set_status(\"Waiting for world_ready...\") end\n    local eq, why = game.equipment_snapshot()\n    if not eq then\n        panel:set_text(gear_info_id, clamp_text(\"Gear unavailable: \" .. tostring(why)))\n        return\n    end\n    local names = {}\n    for i = 1, math.min(4, #eq) do\n        local row = eq[i].row\n        local nm = row and (game.item_display_name(row) or game.item_name(row) or (\"row#\" .. tostring(row))) or \"?\"\n        if #nm > 18 then nm = string.sub(nm, 1, 15) .. \"...\" end\n        names[#names + 1] = nm\n    end\n    local extra = (#eq > 4) and (\" +\" .. tostring(#eq - 4)) or \"\"\n    panel:set_text(gear_info_id, clamp_text(string.format(\n        \"Equipped (%d): %s%s\", #eq, (#names > 0) and table.concat(names, \", \") or \"none\", extra)))\nend\n\nlocal function refresh_customization(silent)\n    if not world_ready then return end\n    local rec, why = game.appearance.customization()\n    if not rec then\n        if not silent then panel:set_text(cust_info_id, clamp_text(\"Customization: \" .. tostring(why))) end\n        return\n    end\n    if not rec.valid then\n        panel:set_text(cust_info_id, \"Customization: open Character Creator to observe edits\"\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[AppearanceStudio]\nAutoRefresh=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Appearance Studio\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"inventory\", \"definitions\", \"server_commands\"],\n  \"needs_ids\": [\n    \"CommonEquipSlotActorComponent::StorageOffset\",\n    \"EquipmentSlotRecord::Stride\",\n    \"EquipmentSlotRecord::SlotTag\",\n    \"ItemInfo::DisplayName\",\n    \"Localization::sTextPoolManager\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"appearance_studio","kind":"lua","lua_api":4,"path":"bsx/lua/examples/appearance_studio","tier":"changes","title":"Appearance Studio","uses":["ui","player","snapshots","inventory","definitions","server_commands"]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Flight Freedom's BlackstarStays action filter. Native approval gives this script full process trust. See bsx/lua/recipes/r5-flight.md. Untested in game. D","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Flight Freedom's BlackstarStays action filter. Native approval gives this\n-- script full process trust. See bsx/lua/recipes/r5-flight.md. Untested in game.\n-- Do not load Flight Freedom's ASI with this example: they edit the same entry.\nlocal function log(message) bsx.log(\"blackstar_stays: \" .. message) end\n\n-- At function entry R9 points to an action record. The ASI compares its first\n-- eight bytes with this action identifier and answers false on a match. It does\n-- not filter by actor, so this example also applies to any matching actor.\nlocal rule, why = cdal.rule(\"FlightFreedom::StartAiAction\", {\n    expect = \"48 89 5C 24 08 48 89 74 24 10 57 48 83 EC 50 49 8B ?? 08 49 8B D9 49 8B F0 48 8B F9\",\n    enabled = false,\n    when = {{\"[r9+0x0].u64\", \"==\", 0x513043A8}},\n    ret = {\"eax\", 0},\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal on = false\nlocal function switch(want)\n    local ok, reason = rule:enable(want)\n    if not ok then log(\"could not change state: \" .. tostring(reason)); return end\n    on = want\n    log(on and \"on\" or \"off\")\nend\n\nif config.bool(\"BlackstarStays\", \"Enabled\", false) then switch(true) end\nlocal chord = config.string(\"BlackstarStays\", \"Hotkey\", \"ctrl+shift+numpad1\")\nlocal ok, reason = pcall(bsx.hotkey, chord, function() switch(not on) end)\nif not ok then log(\"no toggle key: \" .. tostring(reason)) end\n\n-- At most one counter line per 30 seconds. A hit means the action matched,\n-- not that a particular mount was identified or that flight was tested.\nlocal function report()\n    local count, error = rule:hits()\n    if count == nil then return log(\"counter off: \" .. tostring(error)) end\n    log(\"matching actions refused: \" .. tostring(count))\n    local scheduled, schedule_error = pcall(bsx.after, 30000, report)\n    if not scheduled then log(\"counter off: \" .. tostring(schedule_error)) end\nend\nlocal scheduled, schedule_error = pcall(bsx.after, 30000, report)\nif not scheduled then log(\"counter off: \" .. tostring(schedule_error)) end\nlog(\"ready; \" .. (ok and chord .. \" toggles\" or \"toggle key unavailable\"))\n","lang":"lua","name":"main.lua"},{"code":"[BlackstarStays]\n; Flight Freedom's action filter applies to every actor using the same action.\n; Start disabled; press Ctrl+Shift+Numpad1 to turn it on or off.\nEnabled=0\nHotkey=ctrl+shift+numpad1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Blackstar Stays\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"FlightFreedom::StartAiAction\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"blackstar_stays","kind":"lua","lua_api":3,"path":"bsx/lua/examples/blackstar_stays","tier":"safe","title":"Blackstar Stays","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Bounty Carry: keep holding a captured bounty while you teleport. Native tier: the player approves this folder like a DLL mod. Recipe, risks and limits: bs","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Bounty Carry: keep holding a captured bounty while you teleport.\n-- Native tier: the player approves this folder like a DLL mod. Recipe, risks and\n-- limits: bsx/lua/recipes/r9-travel.md. Not yet tested in game.\n--\n-- The game decides to release a carry at four tests and asks one function\n-- whether the holder still carries. During the window, rules make the tests\n-- say \"keep\" (BL, or EDI and EBX, set to 0) and the function return 1.\nlocal function log(message) bsx.log(\"bounty_carry: \" .. message) end\n\nlocal seconds = config.float(\"BountyCarry\", \"WindowSeconds\", 8)\nif not (seconds >= 0.5 and seconds \u003c= 30) then return log(\"off: WindowSeconds must be 0.5 to 30\") end\nlocal SITES = {}\nif config.bool(\"BountyCarry\", \"KeepCatch\", true) then\n    SITES[#SITES + 1] = {\"CatchControl::ServerReleaseTest\", \"84 DB 74 22\", {set = {{\"bl\", \"set\", 0}}}}\n    SITES[#SITES + 1] = {\"CatchControl::ClientReleaseTest\", \"84 DB 74 22\", {set = {{\"bl\", \"set\", 0}}}}\n    SITES[#SITES + 1] = {\"CatchTransition::ReleaseTest\", \"84 DB 74 20\", {set = {{\"bl\", \"set\", 0}}}}\n    SITES[#SITES + 1] = {\"CatchActorComponent::ReleaseWatchdogTest\", \"85 FF 75 04 85 DB 74 3E\",\n                         {set = {{\"edi\", \"set\", 0}, {\"ebx\", \"set\", 0}}}}\nend\nif config.bool(\"BountyCarry\", \"KeepCarried\", true) then\n    SITES[#SITES + 1] = {\"ActorState::TestOtherEntriesOrFlag\", \"48 89 5C 24 08 44 8B 41 1C\", {ret = {\"eax\", 1}}}\nend\nif #SITES == 0 then return log(\"off: KeepCatch and KeepCarried are both 0\") end\n\n-- Installed paused: nothing changes until the hotkey opens the window.\nlocal rules = {}\nfor _, site in ipairs(SITES) do\n    local spec = site[3]\n    spec.expect, spec.enabled = site[2], false\n    local rule, why = cdal.rule(site[1], spec)\n    if not rule then\n        for _, r in ipairs(rules) do r:remove() end  -- all or none\n        return log(\"off: \" .. site[1] .. \": \" .. tostring(why))\n    end\n    rules[#rules + 1] = rule\nend\n\nlocal open, window = false, 0\nlocal function set_open(want, message)\n    for _, r in ipairs(rules) do r:enable(want) end\n    open = want\n    log(message)\nend\nlocal chord = config.string(\"BountyCarry\", \"Hotkey\", \"ctrl+numpad8\")\nlocal ok, why = pcall(bsx.hotkey, chord, function()\n    window = window + 1\n    if open then return set_open(false, \"window closed\") end\n    local mine = window\n    set_open(true, \"window open for \" .. seconds .. \" s: no carry in the game is released\")\n    bsx.after(math.floor(seconds * 1000), function()\n        if mine == window and open then set_open(false, \"window over\") end\n    end)\nend)\nif not ok then\n    for _, r in ipairs(rules) do r:remove() end\n    return log(\"off: no hotkey: \" .. tostring(why))\nend\nlog(\"ready: \" .. chord .. \" opens a \" .. seconds .. \" s carry window\")\n","lang":"lua","name":"main.lua"},{"code":"[BountyCarry]\n; Bounty Teleportation's carry hold, as a manual window: press the hotkey before\n; teleporting with a carried bounty, and for WindowSeconds the game does not make\n; anyone let go. It affects every carry in the game during the window, and does\n; not have the mod's own player/target filter or recovery.\nHotkey=ctrl+numpad8\nWindowSeconds=8\n; Keep the catch (the held target is not released).\nKeepCatch=1\n; Keep the carried state (the holder still counts as carrying).\nKeepCarried=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Bounty Carry\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"CatchControl::ServerReleaseTest\",\n    \"CatchControl::ClientReleaseTest\",\n    \"CatchTransition::ReleaseTest\",\n    \"CatchActorComponent::ReleaseWatchdogTest\",\n    \"ActorState::TestOtherEntriesOrFlag\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"bounty_carry","kind":"lua","lua_api":3,"path":"bsx/lua/examples/bounty_carry","tier":"safe","title":"Bounty Carry","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Catch type rates: Desert Tooling 0.10.0's bug/fish catch classifier. Requires Native approval. Not tested in game. See bsx/lua/recipes/r2-loot.md before u","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Catch type rates: Desert Tooling 0.10.0's bug/fish catch classifier.\n-- Requires Native approval. Not tested in game.\n-- See bsx/lua/recipes/r2-loot.md before using this script.\nlocal function log(message) bsx.log(\"catch types: \" .. message) end\nlocal SITE = \"LootCatch::QuantityReady\"\nlocal EXPECT = \"48 8D 95 D0 01 00 00 48 8D 8D B0 00 00 00\"\n\n-- Stored values exist only for checked builds, and `expect` below refuses\n-- changed instructions, so an unknown build or a scanned guess stays off.\nlocal status = cdal.status(SITE)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. SITE .. \": \" .. tostring(status))\nend\n\nlocal bugs = config.int(\"Catch\", \"Bugs\", 1)\nlocal fish = config.int(\"Catch\", \"Fish\", 1)\nlocal hotkey = config.string(\"Catch\", \"Hotkey\", \"ctrl+alt+f4\")\nif bugs \u003c 1 or bugs > 100 or fish \u003c 1 or fish > 100 then\n    return log(\"off: Bugs and Fish must be whole numbers from 1 to 100\")\nend\n\n-- At the site R15 is the actor and RAX is the actor's class object. Nested\n-- reads are guarded by the rule engine; a missing pointer makes a check false.\nlocal TYPE = \"[[r15+0x88]+0x1].u8\"\nlocal CLASS = \"[rax+0x5a].u8\"\nlocal choices = {\n    {3, 0x80, bugs}, {6, 0x80, bugs},\n    {6, 0x23, fish}, {6, 0x44, fish}, {6, 0x65, fish}, {6, 0x83, fish},\n}\nlocal rules = {}\nlocal live = true\nlocal function remove_all()\n    live = false\n    for _, rule in ipairs(rules) do\n        local removed, why = rule:remove()\n        if not removed then log(\"could not remove a rule: \" .. tostring(why)) end\n    end\n    rules = {}\nend\n\n-- Install all rules paused so a partial installation cannot change a catch.\nfor _, choice in ipairs(choices) do\n    local rule, why = cdal.rule(SITE, {\n        expect = EXPECT, enabled = false,\n        when = {{TYPE, \"==\", choice[1]}, {CLASS, \"==\", choice[2]}},\n        set = {{\"r8d\", \"set\", choice[3]}},\n    })\n    if not rule then\n        remove_all()\n        return log(\"off: \" .. SITE .. \": \" .. tostring(why))\n    end\n    rules[#rules + 1] = rule\nend\n\nlocal on = false\nlocal function set_enabled(want)\n    if not live then return false end\n    for _, rule in ipairs(rules) do\n        local changed, why = rule:enable(want)\n        if not changed then\n            remove_all()\n            on = false\n            log(\"off: cannot change a rule: \" .. tostring(why))\n            return false\n        end\n    end\n    on = want\n    log(on and \"on\" or \"off\")\n    return true\nend\n\nlocal bound, key_why = pcall(bsx.hotkey, hotkey, function() set_enabled(not on) end)\nif not bound then\n    remove_all()\n    return log(\"off: hotkey unavailable: \" .. tostring(key_why))\nend\nif config.bool(\"Catch\", \"Enabled\", false) then\n    if not set_enabled(true) then return end\nelse\n    log(\"off; \" .. hotkey .. \" toggles bug and fish rates\")\nend\n\n-- A hit means a rule ran, not that an item reached the bag. Log only changes.\nlocal last_total = 0\nlocal function report()\n    if not live then return end\n    local total = 0\n    for _, rule in ipairs(rules) do\n        local count, why = rule:hits()\n        if count == nil then log(\"hit counter unavailable: \" .. tostring(why)); return end\n        total = total + count\n    end\n    if #rules == 0 then return end\n    if total ~= last_total then log(\"rule hits: \" .. total); last_total = total end\n    local scheduled, why = pcall(bsx.after, 10000, report)\n    if not scheduled then log(\"hit reporting stopped: \" .. tostring(why)) end\nend\nlocal scheduled, schedule_why = pcall(bsx.after, 10000, report)\nif not scheduled then log(\"hit reporting unavailable: \" .. tostring(schedule_why)) end\n","lang":"lua","name":"main.lua"},{"code":"[Catch]\n; Set whole-number catch quantities from 1 to 100. The script starts paused.\nBugs=1\nFish=1\nEnabled=false\nHotkey=ctrl+alt+f4\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Catch type rates\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"LootCatch::QuantityReady\"]\n}\n","lang":"json","name":"script.json"}],"id":"catch_types","kind":"lua","lua_api":3,"path":"bsx/lua/examples/catch_types","tier":"safe","title":"Catch type rates","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A global clock preview, not a complete JustSkip or Timescale replacement. Native approval is required. No game or mod has been tested in game.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A global clock preview, not a complete JustSkip or Timescale replacement.\n-- Native approval is required. No game or mod has been tested in game.\nlocal speeds = {\n    config.float(\"ClockFastForward\", \"Speed1\", 1.2),\n    config.float(\"ClockFastForward\", \"Speed2\", 2.0),\n    config.float(\"ClockFastForward\", \"Speed3\", 4.0),\n}\nlocal hold = config.bool(\"ClockFastForward\", \"Hold\", false)\nlocal burst = config.float(\"ClockFastForward\", \"BurstSpeed\", 8.0)\nlocal hold_seconds = config.int(\"ClockFastForward\", \"MaxHoldSeconds\", 120)\nfor _, value in ipairs({speeds[1], speeds[2], speeds[3], burst}) do\n    if not (value > 1 and value \u003c= 10) then\n        error(\"clock_fast_forward: off: speeds must be greater than 1 and at most 10\", 0)\n    end\nend\nif hold_seconds \u003c 1 or hold_seconds > 120 then\n    error(\"clock_fast_forward: off: MaxHoldSeconds must be 1 to 120\", 0)\nend\n\nlocal owns, held, mode, generation = false, false, 0, 0\nlocal pending = \"ready: Ctrl+Alt+F1; clock rate starts at normal\"\n\n-- An uncaught error also asks the host to remove the hotkey and timers. If a\n-- reset fails, the host tries again when it closes this script's state.\nlocal function fail(reason)\n    if owns then\n        local ok, why = cdal.clock_rate(1)\n        if ok then owns = false else reason = reason .. \"; reset failed: \" .. tostring(why) end\n    end\n    error(\"clock_fast_forward: off: \" .. reason, 0)\nend\n\nlocal function apply(rate)\n    local ok, why = cdal.clock_rate(rate)\n    if not ok then return fail(\"clock rate: \" .. tostring(why)) end\n    owns = rate ~= 1\n    pending = rate == 1 and \"normal rate; clock ownership released\"\n        or (\"game-executable clock rate x\" .. tostring(rate))\nend\n\nlocal function end_hold()\n    if not held then return end\n    held = false\n    generation = generation + 1\n    apply(1)\nend\n\n-- The hotkey has one non-repeat down. In hold mode the copied key stream\n-- supplies its release and focus/overflow resets. Neither callback runs in a hook.\nif hold then\n    local ok, why = pcall(bsx.on, \"key\", function(event)\n        if held and (event.reset or event.virtual_key == 0 or\n            (event.virtual_key == 112 and not event.down) or event.modifiers ~= 3) then\n            end_hold()\n        end\n    end)\n    if not ok then fail(\"key observation unavailable: \" .. tostring(why)) end\nend\n\nlocal registered, why = pcall(bsx.hotkey, \"ctrl+alt+f1\", function()\n    if hold then\n        if held then return end\n        generation = generation + 1\n        local this_hold = generation\n        -- Schedule before changing the rate. A stale timer cannot end a newer hold.\n        local scheduled, timer_why = pcall(bsx.after, hold_seconds * 1000, function()\n            if held and generation == this_hold then end_hold() end\n        end)\n        if not scheduled then return fail(\"hold timer unavailable: \" .. tostring(timer_why)) end\n        apply(burst)\n        held = true\n    else\n        local next_mode = (mode + 1) % 4\n        apply(next_mode == 0 and 1 or speeds[next_mode])\n        mode = next_mode\n    end\nend)\nif not registered then fail(\"hotkey unavailable: \" .. tostring(why)) end\n\n-- Coalesce status changes. At most one script log is emitted every ten seconds.\nlocal function report()\n    local scheduled, timer_why = pcall(bsx.after, 10000, report)\n    if not scheduled then return fail(\"report timer unavailable: \" .. tostring(timer_why)) end\n    if pending then bsx.log(\"clock_fast_forward: \" .. pending); pending = nil end\nend\nlocal scheduled, timer_why = pcall(bsx.after, 10000, report)\nif not scheduled then fail(\"report timer unavailable: \" .. tostring(timer_why)) end\n","lang":"lua","name":"main.lua"},{"code":"[ClockFastForward]\n; Ctrl+Alt+F1 cycles off, 1.2x, 2x, 4x, off. All factors must be >1 and \u003c=10.\nSpeed1=1.2\nSpeed2=2.0\nSpeed3=4.0\n; Set Hold=1 for a single burst while the chord is held instead of cycling.\nHold=0\nBurstSpeed=8.0\n; The hold safety timer and release run on a later FRAME, not a clock hook.\nMaxHoldSeconds=120\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Clock Fast Forward\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": []\n}\n","lang":"json","name":"script.json"}],"id":"clock_fast_forward","kind":"lua","lua_api":3,"path":"bsx/lua/examples/clock_fast_forward","tier":"safe","title":"Clock Fast Forward","uses":[]},{"category":"Camera, Movement & Flight","description":"Copy this folder to BSX/scripts/clock_log. Press the key in settings.ini and read BSX/bsx.log. This reports the client clock and raw climate values, not a named weather or forecast.","featured":false,"files":[{"code":"-- Copy this folder to BSX/scripts/clock_log. Press the key in settings.ini and read BSX/bsx.log.\n-- This reports the client clock and raw climate values, not a named weather or forecast.\n\nlocal shortcut = config.string(\"ClockLog\", \"Hotkey\", \"ctrl+f7\")\nlocal minutes = config.int(\"ClockLog\", \"IntervalMinutes\", 5)\nif minutes \u003c 1 or minutes > 1440 then\n    bsx.log(\"clock log: IntervalMinutes must be 1..1440; using 5\")\n    minutes = 5\nend\n\nlocal function report()\n    local time, time_why = game.time()\n    if time == nil then\n        bsx.log(\"clock log: time unavailable (\" .. tostring(time_why) .. \")\")\n    else\n        bsx.log(string.format(\"clock log: day %d, time %02d:%02d:%02d.%03d\",\n            time.day, time.hour, time.minute, time.second, time.millisecond))\n    end\n\n    local weather, weather_why = game.weather()\n    if weather == nil then\n        bsx.log(\"clock log: weather unavailable (\" .. tostring(weather_why) .. \")\")\n    else\n        bsx.log(\"clock log: raw rain base \" .. tostring(weather.rain_base) ..\n            \", raw snow base \" .. tostring(weather.snow_base))\n    end\nend\n\n-- Hotkeys require BSX API 3 and the key service. pcall keeps the script on if unavailable.\nlocal ok, why = pcall(bsx.hotkey, shortcut, report)\nif not ok then\n    bsx.log(\"clock log: hotkey unavailable (\" .. tostring(why) .. \"); using timer\")\n    local function poll()\n        report()\n        bsx.after(minutes * 60000, poll)\n    end\n    bsx.after(minutes * 60000, poll)\nend\n","lang":"lua","name":"main.lua"},{"code":"[ClockLog]\n; Exact modifiers: ctrl+shift+f7 is different from ctrl+f7.\nHotkey=ctrl+f7\n; Used only when the hotkey cannot be registered. Real minutes, not game minutes.\nIntervalMinutes=5\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Clock Log\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"FieldTime::sClientTime\",\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::RenderManager\",\n    \"RenderManager::WeatherState\",\n    \"WeatherState::Resource\",\n    \"WeatherResource::Climate\",\n    \"Climate::RainBase\",\n    \"Climate::SnowBase\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"clock_log","kind":"lua","lua_api":3,"path":"bsx/lua/examples/clock_log","tier":"safe","title":"Clock Log","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Global clock slow-motion preview, not Bullet-time's native transition. Native approval is required. No game or mod has been tested in game.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Global clock slow-motion preview, not Bullet-time's native transition.\n-- Native approval is required. No game or mod has been tested in game.\nlocal speed = config.float(\"ClockSlowPreview\", \"Speed\", 0.3)\nif not (speed >= 0.1 and speed \u003c 1) then\n    error(\"clock_slow_preview: off: Speed must be at least 0.1 and less than 1\", 0)\nend\n\nlocal owns = false\nlocal pending = \"ready: Ctrl+Alt+F2; clock rate starts at normal\"\n\nlocal function fail(reason)\n    if owns then\n        local ok, why = cdal.clock_rate(1)\n        if ok then owns = false else reason = reason .. \"; reset failed: \" .. tostring(why) end\n    end\n    -- The host removes the hotkey and timers, and retries any owned reset.\n    error(\"clock_slow_preview: off: \" .. reason, 0)\nend\n\nlocal registered, why = pcall(bsx.hotkey, \"ctrl+alt+f2\", function()\n    local rate = owns and 1 or speed\n    local ok, clock_why = cdal.clock_rate(rate)\n    if not ok then return fail(\"clock rate: \" .. tostring(clock_why)) end\n    owns = rate ~= 1\n    pending = owns and (\"game-executable clock rate x\" .. tostring(rate))\n        or \"normal rate; clock ownership released\"\nend)\nif not registered then fail(\"hotkey unavailable: \" .. tostring(why)) end\n\n-- Keep only the most recent status; the clock hooks never call Lua or log.\nlocal function report()\n    local scheduled, timer_why = pcall(bsx.after, 10000, report)\n    if not scheduled then return fail(\"report timer unavailable: \" .. tostring(timer_why)) end\n    if pending then bsx.log(\"clock_slow_preview: \" .. pending); pending = nil end\nend\nlocal scheduled, timer_why = pcall(bsx.after, 10000, report)\nif not scheduled then fail(\"report timer unavailable: \" .. tostring(timer_why)) end\n","lang":"lua","name":"main.lua"},{"code":"[ClockSlowPreview]\n; Ctrl+Alt+F2 toggles the executable's clock reads. 0.3 is 30% speed.\n; This is global and does not preserve a separate normal-speed player.\nSpeed=0.3\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Clock Slow Preview\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": []\n}\n","lang":"json","name":"script.json"}],"id":"clock_slow_preview","kind":"lua","lua_api":3,"path":"bsx/lua/examples/clock_slow_preview","tier":"safe","title":"Clock Slow Preview","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Observation only: the key is not consumed and no game state is changed. This is not Combat Evolved or Guard Cancel: the original filters, input polling an","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Observation only: the key is not consumed and no game state is changed.\n-- This is not Combat Evolved or Guard Cancel: the original filters, input\n-- polling and controller behavior are not established for this probe.\nlocal function log(message) bsx.log(\"combat_hold_probe: \" .. message) end\nlocal key = config.int(\"CombatHoldProbe\", \"Key\", 32)\nlocal hold = config.int(\"CombatHoldProbe\", \"HoldMs\", 400)\nif key \u003c 1 or key > 255 then return log(\"off: Key must be 1 to 255\") end\nif hold \u003c 1 or hold > 10000 then return log(\"off: HoldMs must be 1 to 10000\") end\n\nlocal site = \"ClientCharacterControlActorComponent::CheckConditionExtend\"\nlocal status, why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(why or status))\nend\n\n-- $0 says a KEY down has reached Lua; $1 is its deadline in the rule's\n-- monotonic milliseconds. The rule sees no physical-input timestamp: KEY\n-- delivery is queued until FRAME. A hit only means this entry was reached\n-- after that deadline while the latest delivered key state was held.\nlocal rule, error_text = cdal.rule(site, {\n    expect = \"48 89 5C 24 10 48 89 6C 24 18\",\n    enabled = false,\n    stop_on_failure = true,\n    when = { {\"$0.u64\", \"==\", 1}, {\"tick\", \">=\", \"$1.u64\"} },\n    set = { {\"$2.u64\", \"set\", \"tick\"} },\n})\nif not rule then return log(\"off: \" .. tostring(error_text)) end\n\nlocal on, alive, changed, last_hits, failure = false, true, false, 0, nil\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, err = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(err) end\n    failure = \"off: \" .. reason\nend\nlocal function set_cell(index, value)\n    local ok, err = cdal.set_cell(index, value, \"u64\")\n    if not ok then stop(\"input state unavailable: \" .. tostring(err)); return false end\n    return true\nend\n\nlocal subscribed, subscribe_error = pcall(bsx.on, \"key\", function(e)\n    if not alive or not on then return end\n    if e.reset or (e.virtual_key == key and not e.down) then\n        set_cell(0, 0)  -- includes focus-loss and queue-overflow reset\n    elseif e.virtual_key == key and e.down and not e[\"repeat\"] then\n        local now, tick_error = cdal.tick()\n        if now == nil then return stop(\"clock unavailable: \" .. tostring(tick_error)) end\n        -- Publish the deadline first. A game thread must not see held=1 with\n        -- the previous deadline for this press.\n        if set_cell(0, 0) and set_cell(1, now + hold) then set_cell(0, 1) end\n    end\nend)\nif not subscribed then\n    stop(\"KEY unavailable: \" .. tostring(subscribe_error))\n    return log(failure)\nend\n\nlocal bound, key_error = pcall(bsx.hotkey, \"ctrl+alt+shift+numpad5\", function()\n    if not alive then return end\n    -- Never reuse a held observation after pausing or re-enabling the probe.\n    if not set_cell(0, 0) then return end\n    local ok, err = rule:enable(not on)\n    if not ok then return stop(\"toggle failed: \" .. tostring(err)) end\n    on, changed = not on, true\nend)\nif not bound then\n    stop(\"hotkey unavailable: \" .. tostring(key_error))\n    return log(failure)\nend\n\nlocal function report()\n    if failure then return log(failure) end\n    local hits, err = rule:hits()\n    if hits == nil then stop(\"hit count unavailable: \" .. tostring(err)); return log(failure) end\n    local scheduled, schedule_error = pcall(bsx.after, 10000, report)\n    if not scheduled then stop(\"timer unavailable: \" .. tostring(schedule_error)); return log(failure) end\n    if changed or hits ~= last_hits then\n        log((on and \"on\" or \"paused\") .. \"; held-key condition entries=\" .. tostring(hits))\n        last_hits, changed = hits, false\n    end\nend\nlocal scheduled, schedule_error = pcall(bsx.after, 10000, report)\nif not scheduled then stop(\"timer unavailable: \" .. tostring(schedule_error)); return log(failure) end\nlog(\"ready: paused; Ctrl+Alt+Shift+Numpad5 toggles observation\")\n","lang":"lua","name":"main.lua"},{"code":"[CombatHoldProbe]\n; Windows virtual-key code to observe: 32 is Space. It is not consumed.\nKey=32\n; How long the FRAME-delivered key-down must have been held.\nHoldMs=400\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Combat Hold Probe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"ClientCharacterControlActorComponent::CheckConditionExtend\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"combat_hold_probe","kind":"lua","lua_api":3,"path":"bsx/lua/examples/combat_hold_probe","tier":"safe","title":"Combat Hold Probe","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Durability Wear: weapons and armour lose less (or no) durability. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Durability Wear: weapons and armour lose less (or no) durability.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r4-stamina.md. Not yet tested in game.\n--\n-- The game applies every durability change through one function. At its first\n-- instruction DX is the signed change, so one rule scales the negative ones.\nlocal function log(message) bsx.log(\"durability_wear: \" .. message) end\n\nlocal factor = config.float(\"Durability\", \"WearFactor\", 0)\nif not (factor >= 0 and factor \u003c= 1) then return log(\"off: WearFactor must be 0 to 1\") end\n\nlocal rule, why = cdal.rule(\"ItemDurability::ApplyDelta\", {\n    expect = \"48 89 5C 24 08 48 89 6C 24 10\",  -- the function's first two instructions\n    enabled = config.bool(\"Durability\", \"Enabled\", true),\n    when = { {\"dx\", \"\u003c\", 0} },\n    set = { {\"dx\", \"mul\", factor} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal chord = config.string(\"Durability\", \"Hotkey\", \"ctrl+numpad1\")\nlocal ok, key_why = pcall(bsx.hotkey, chord, function()\n    rule:enable(not rule:active())\n    log((rule:active() and \"on\" or \"off\") .. \" (\" .. rule:hits() .. \" wear changes so far)\")\nend)\nlog((rule:active() and \"on\" or \"off\") .. \": wear x\" .. factor .. \"; \"\n    .. (ok and chord .. \" toggles\" or \"no toggle key: \" .. tostring(key_why)))\n","lang":"lua","name":"main.lua"},{"code":"[Durability]\n; 1 is normal wear, 0.5 is half, 0 is no wear. Repairs are not changed.\n; Every item that wears is affected, the player's and everyone else's.\nWearFactor=0\nEnabled=1\nHotkey=ctrl+numpad1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Durability Wear\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"ItemDurability::ApplyDelta\"]\n}\n","lang":"json","name":"script.json"}],"id":"durability_wear","kind":"lua","lua_api":3,"path":"bsx/lua/examples/durability_wear","tier":"safe","title":"Durability Wear","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Review SlotTag in settings.ini before approving the folder's new digest.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Review SlotTag in settings.ini before approving the folder's new digest.\nlocal tag = config.int(\"EquipToggle\", \"SlotTag\", -1)\n-- The loaded world can still be behind the game's \"hold to continue\" screen at SAVE_LOADED.\nlocal start_delay = math.max(0, config.int(\"EquipToggle\", \"StartDelayFrames\", 300))\nlocal retry_frames, max_tries = 120, 30\nlocal pending, armed, last_save, frame = nil, nil, nil, 0\nlocal function log(s) bsx.log(\"equip_toggle: \" .. s) end\nlocal function cancel(why)\n    if pending or armed then log(\"cancelled: \" .. why) end\n    pending, armed = nil, nil\nend\nlocal function ptr(at)\n    local p, why = mem.read_ptr(at)\n    assert(p and p ~= 0, why or \"null pointer\")\n    return p\nend\nlocal function u16(at) return assert(mem.read_u8(at)) + 256 * assert(mem.read_u8(at + 1)) end\nlocal function offset(name) return assert(cdal.value(name)) end\nlocal function word(at) return assert(mem.read_u64(at)) end\nlocal function positive(at)\n    local n = word(at)\n    -- read_u64 is unsigned; signed positive amounts fit below 2^63.\n    return n ~= \"0\" and (#n \u003c 19 or (#n == 19 and n \u003c \"9223372036854775808\"))\nend\nlocal function equipped(actor)\n    local component = assert(game.equipment(actor))\n    local storage = ptr(component + offset(\"CommonEquipSlotActorComponent::StorageOffset\"))\n    local count = assert(mem.read_u32(storage + 0x10))\n    assert(count \u003c= 256, \"equipment bound\")\n    local records = count > 0 and ptr(storage + 8) or 0\n    local result\n    for i = 0, count - 1 do\n        local p = records + i * offset(\"EquipmentSlotRecord::Stride\")\n        if u16(p + offset(\"EquipmentSlotRecord::SlotTag\")) == tag then\n            local row = u16(p + offset(\"InventoryItem::Row\"))\n            if row ~= 65535 and positive(p + offset(\"InventoryItem::Amount\")) then\n                assert(not result, \"duplicate equipped tag\")\n                result = {row = row, word = word(p)}\n            end\n        end\n    end\n    assert(mem.read_u32(storage + 0x10) == count, \"equipment changed\")\n    return result\nend\nlocal function locate(actor, wanted)\n    local components = ptr(actor + offset(\"Actor::Components\"))\n    local holder = ptr(components + offset(\"ActorComponents::Inventory\"))\n    assert(ptr(holder) == cdal.address(\"pa::ClientInventoryActorComponent::vftable\"), \"inventory type\")\n    local count = assert(mem.read_u32(holder + offset(\"InventoryHolder::BucketCount\")))\n    assert(count \u003c= 256, \"bucket bound\")\n    local buckets = count > 0 and ptr(holder + offset(\"InventoryHolder::Buckets\")) or 0\n    local found, visited = nil, 0\n    for b = 0, count - 1 do\n        local bucket = ptr(buckets + b * 8)\n        local slots_count = u16(bucket + offset(\"InventoryBucket::SlotCount\"))\n        visited = visited + slots_count\n        assert(slots_count \u003c 32768 and visited \u003c= 4096, \"inventory bound\")\n        local slots = slots_count > 0 and ptr(bucket) or 0\n        for i = 0, slots_count - 1 do\n            local p = slots + i * offset(\"InventoryItem::Stride\")\n            if u16(p + offset(\"InventoryItem::Row\")) == wanted.row and word(p) == wanted.word\n                and positive(p + offset(\"InventoryItem::Amount\")) then\n                assert(not found, \"ambiguous item identity\")\n                -- +0x10 is the external bucket tag, not the array ordinal.\n                found = {bucket = u16(bucket + 0x10), index = i}\n            end\n        end\n    end\n    return found\nend\nlocal function same_player()\n    local actor = assert(game.player())\n    assert(actor == pending.actor and mem.read_u32(actor + offset(\"Actor::Key\")) == pending.key, \"player changed\")\n    return actor\nend\nlocal function applied(e, phase)\n    if not pending or pending.phase ~= phase or e.controlled ~= true or e.generation ~= pending.generation\n        or e.tag ~= tag or e.row ~= pending.row or e.item_word0 ~= pending.word then return end\n    log((phase == \"remove\" and \"UNEQUIP_APPLIED\" or \"EQUIP_APPLIED\") .. \" tag=\" .. tag .. \" row=\" .. e.row)\n    if phase == \"remove\" then pending.phase = \"find\"\n    else pending.phase = \"confirm\" end\nend\nlocal events = pcall(function()\n    bsx.on(\"unequip_applied\", function(e) applied(e, \"remove\") end)\n    bsx.on(\"equip_applied\", function(e) applied(e, \"equip\") end)\n    bsx.on(\"save_load\", function() cancel(\"new save request\") end)\n    bsx.on(\"load_request\", function() cancel(\"new loading request\") end)\nend)\nif not events then log(\"required completion/load events unavailable\") end\nif not game.request then log(\"read-only; changes approval required\") end\nif tag \u003c 0 or tag > 32767 then log(\"choose SlotTag in settings.ini and approve its digest\") end\nlocal function request_unequip()\n    local generation = armed.generation\n    armed.tries = armed.tries + 1\n    local ok, why = pcall(function()\n        local actor = assert(game.player())\n        local item = assert(equipped(actor), \"chosen slot is empty\")\n        assert(item.word ~= \"0\" and item.word ~= \"18446744073709551615\", \"no usable item identity\")\n        log(\"request unequip tag=\" .. tag .. \" row=\" .. item.row .. \" try=\" .. armed.tries)\n        local queued, reason = game.request.unequip(tag)\n        if not queued then\n            -- Nothing was sent, so asking again later cannot double a request.\n            if reason == \"native builder did not send a packet\" and armed.tries \u003c max_tries then\n                log(\"unequip not sent yet; trying again in \" .. retry_frames .. \" frames\")\n                armed.due = frame + retry_frames\n                return\n            end\n            cancel(\"unequip refused: \" .. tostring(reason)); return\n        end\n        armed = nil\n        pending = {actor = actor, key = assert(mem.read_u32(actor + offset(\"Actor::Key\"))),\n            generation = generation, row = item.row, word = item.word, phase = \"remove\", deadline = frame + 600}\n        log(\"unequip queued; waiting for UNEQUIP_APPLIED\")\n    end)\n    if not ok then cancel(tostring(why)); log(\"stopped: \" .. tostring(why)) end\nend\nlocal loaded_ok = pcall(bsx.on, \"save_loaded\", function(e)\n    cancel(\"replacement SAVE_LOADED\")\n    if last_save == e.generation then return end\n    last_save = e.generation\n    if not events or not game.request or tag \u003c 0 or tag > 32767 then return end\n    armed = {generation = e.generation, due = frame + start_delay, tries = 0}\n    log(\"save loaded; unequip in \" .. start_delay .. \" frames\")\nend)\nif not loaded_ok then log(\"SAVE_LOADED unavailable\") end\nbsx.on(\"frame\", function(e)\n    frame = e.frame\n    if armed and frame >= armed.due then request_unequip() end\n    if not pending then return end\n    if frame > pending.deadline then cancel(\"timeout; inspect current equipment before retrying\"); return end\n    local ok, why = pcall(function()\n        local actor = same_player()\n        if pending.phase == \"find\" then\n            assert(not equipped(actor), \"slot was filled by another or fallback request\")\n            local item = locate(actor, pending)\n            if not item then return end -- replication can follow the removal observation\n            pending.phase = \"equip\"\n            log(\"request equip bucket=\" .. item.bucket .. \" index=\" .. item.index .. \" tag=\" .. tag)\n            local queued, reason = game.request.equip(item.bucket, item.index, tag)\n            if not queued then cancel(\"equip refused: \" .. tostring(reason)); return end\n            log(\"equip queued; waiting for EQUIP_APPLIED\")\n        elseif pending.phase == \"confirm\" then\n            local item = assert(equipped(actor), \"confirmed slot absent\")\n            assert(item.row == pending.row and item.word == pending.word, \"confirmed item differs\")\n            log(\"complete: original item observed in chosen slot\")\n            pending = nil\n        end\n    end)\n    if not ok then cancel(tostring(why)) end\nend)\n","lang":"lua","name":"main.lua"},{"code":"[EquipToggle]\n; Choose a numeric tag observed for this actor (for example from smoke).\n; -1 keeps the example idle. Review the selection before approving its digest.\nSlotTag=-1\n; Frames to wait after SAVE_LOADED before the first unequip request (300 is about\n; 5 s at 60 fps). An unequip the game did not send is tried again every 120 frames,\n; at most 30 times; a request that was sent is never repeated.\nStartDelayFrames=300\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Equip toggle\",\n  \"version\": \"1\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\", \"WorldSystem::ActorManager\", \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\", \"pa::ClientNormalInGameActor::vftable\", \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Key\", \"Actor::Components\", \"ActorComponents::Inventory\", \"ActorComponents::Equipment\",\n    \"pa::ClientInventoryActorComponent::vftable\", \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"InventoryHolder::Buckets\", \"InventoryHolder::BucketCount\", \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\", \"InventoryItem::Row\", \"InventoryItem::Amount\",\n    \"CommonEquipSlotActorComponent::StorageOffset\", \"EquipmentSlotRecord::Stride\", \"EquipmentSlotRecord::SlotTag\",\n    \"Inventory::GetHolder\", \"Inventory::GetItem\", \"Inventory::GetBucketForItemRow\",\n    \"UsableItem::Construct\", \"UsableItem::Copy\", \"UsableItem::Destroy\",\n    \"ActorEquipment::RequestEquipItem\", \"ClientRequest::EquipPacketKind\", \"ActorEquipment::RequestUnequipItem\", \"ClientRequest::UnequipPacketKind\", \"ClientRequest::SendPacket\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"equip_toggle","kind":"lua","lua_api":3,"path":"bsx/lua/examples/equip_toggle","tier":"changes","title":"Equip toggle","uses":[]},{"category":"BSX Core & Diagnostics","description":"The script built step by step in bsx/lua/FIRST_MOD.md. It only reads the game. Copy this folder to BSX/scripts/first_mod. Its lines go to BSX/bsx.log, prefixed [first_mod].","featured":false,"files":[{"code":"-- The script built step by step in bsx/lua/FIRST_MOD.md. It only reads the game.\n-- Copy this folder to BSX/scripts/first_mod. Its lines go to BSX/bsx.log, prefixed [first_mod].\n\n-- Settings come from settings.ini next to this file; the second value is the default.\nlocal chord = config.string(\"FirstMod\", \"Hotkey\", \"ctrl+f6\")\nlocal greet = config.bool(\"FirstMod\", \"Greet\", true)\n\n-- data/ is this script's own folder for files. Count how many saves it has seen, across restarts.\nlocal function load_count()\n    local ok, text = pcall(bsx.fs.read, \"loads.txt\")\n    return ok and tonumber(text) or 0\nend\nlocal loads = load_count()\n\n-- game.player() returns the controlled character's actor, or nil and a reason.\nlocal function describe_player()\n    local actor, why = game.player()\n    if not actor then return \"no player yet (\" .. why .. \")\" end\n    local stats = game.stats(actor)\n    return string.format(\"player actor 0x%X, stat container %s\", actor,\n        stats and string.format(\"0x%X\", stats) or \"not found\")\nend\n\nbsx.on(\"save_loaded\", function(e)\n    loads = loads + 1\n    bsx.fs.write(\"loads.txt\", tostring(loads))\n    if greet then bsx.log(\"save loaded (\" .. loads .. \" so far): \" .. describe_player()) end\nend)\n\n-- Keys need native BSX API 3 and [BSX] Keys=1 (the default). pcall keeps the script\n-- running without the hotkey if they are unavailable.\nlocal ok, why = pcall(bsx.hotkey, chord, function()\n    bsx.log(chord .. \" pressed: \" .. describe_player())\nend)\nif ok then\n    bsx.log(\"ready: press \" .. chord .. \" in game\")\nelse\n    bsx.log(\"ready without a hotkey: \" .. tostring(why))\nend\n","lang":"lua","name":"main.lua"},{"code":"[FirstMod]\n; Any chord bsx.hotkey accepts, such as ctrl+f6, alt+k or f7.\nHotkey=ctrl+f6\n; Log a line each time a save loads.\nGreet=true\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"First Mod\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": false,\n  \"needs_ids\": [\"WorldSystem::sInstance\", \"WorldSystem::ActorManager\", \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\", \"ActorComponents::Status\", \"CommonStatusActorComponent::StatContainer\"],\n  \"needs_plugins\": [],\n  \"packs\": []\n}\n","lang":"json","name":"script.json"}],"id":"first_mod","kind":"lua","lua_api":3,"path":"bsx/lua/examples/first_mod","tier":"safe","title":"First Mod","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A configurable global preview, not a Blackstar identity or a full port. The row is sampled during the original call, earlier than the ASI's lookup.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A configurable global preview, not a Blackstar identity or a full port.\n-- The row is sampled during the original call, earlier than the ASI's lookup.\nlocal function log(s) bsx.log(\"flight_cooldown_preview: \" .. s) end\nlocal entry = \"MercenaryClan::CheckMemberTimedStatus\"\nlocal load = \"MercenaryClan::TimedStatusRowMemberLoad\"\nlocal row = config.int(\"FlightCooldownPreview\", \"RowKey\", -1)\nlocal status = config.int(\"FlightCooldownPreview\", \"StatusCode\", -1)\nlocal seconds = config.int(\"FlightCooldownPreview\", \"ReportSeconds\", 10)\nif row \u003c -1 or row > 65535 or status \u003c -1 or status == 0 or seconds \u003c 10 or seconds > 120 then\n    return log(\"off: RowKey must be -1 or 0..65535, StatusCode -1 or positive, and ReportSeconds 10..120\")\nend\n-- An unset value leaves an impossible u16 match. The hooks still start paused.\nlocal configured = row >= 0 and status > 0\nlocal key_match = configured and row or 65536\nlocal status_match = configured and status or 1\n\n-- CDAL metadata calls do not call the game. A scan alone does not approve the layout.\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    for _, name in ipairs({entry, load}) do\n        local id = lib.cdal_id_by_name(name)\n        if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. name) end\n    end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\n\n-- Each invocation has its own zeroed sample and present flag. The CAS checks\n-- the returned status again at the actual write; no sample means no write.\nlocal outer, err = cdal.rule(entry, {\n    after = true, context = true, enabled = false, stop_on_failure = true,\n    expect = \"48 89 5C 24 08 48 89 6C 24 10 48 89 74 24 18 57\",\n    set = {\n        {\"%1.u64\", \"==\", 1}, {\"%0.u64\", \"==\", key_match},\n        {\"[rax].u32\", \"cas\", 0, status_match}, {\"$0.u64\", \"add\", 1},\n    },\n})\nif not outer then return log(\"off: wrapper: \" .. tostring(err)) end\n\n-- Both encodings are checked on real images. Try each with its own `expect`;\n-- the host compares original bytes, including when another hook is present.\nlocal function capture(offset, instruction)\n    return cdal.rule(load, {\n        enabled = false, stop_on_failure = true, expect = instruction,\n        when = {{\"depth\", \">\", 0}},\n        set = {\n            {\"%%0.u64\", \"set\", \"[rax+0x\" .. offset .. \"].u16\"},\n            {\"%%1.u64\", \"set\", 1},\n        },\n    })\nend\nlocal inner, first_why = capture(\"20\", \"0F B7 50 20 4D 8B C6\")\nlocal second_why\nif not inner then inner, second_why = capture(\"24\", \"0F B7 50 24 4D 8B C6\") end\nif not inner then\n    local removed, problem = outer:remove()\n    return log(\"off: row capture: \" .. tostring(first_why) .. \"; \" .. tostring(second_why)\n        .. (removed and \"\" or \"; removal failed: \" .. tostring(problem)))\nend\n\nlocal live, on, pending = true, false, nil\nlocal function stop(reason)\n    live, on = false, false\n    local a, a_why = inner:remove()\n    local b, b_why = outer:remove()\n    local message = \"flight_cooldown_preview: off: \" .. tostring(reason)\n    if not a then message = message .. \"; capture removal failed: \" .. tostring(a_why) end\n    if not b then message = message .. \"; wrapper removal failed: \" .. tostring(b_why) end\n    error(message, 0) -- the host also cancels the hotkey and queued timer\nend\nok, why = pcall(bsx.hotkey, \"ctrl+f5\", function()\n    if not live then return end\n    local next_on = not on\n    -- Capture without a marked wrapper cannot change anything. Enable it\n    -- first; on pause disable the wrapper first and then the capture.\n    local first, second = next_on and inner or outer, next_on and outer or inner\n    local changed, problem = first:enable(next_on)\n    if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    changed, problem = second:enable(next_on)\n    if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    on = next_on\n    pending = on and \"on\" or \"paused\"\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\n\nlocal function report()\n    if not live then return end\n    local count, problem = cdal.cell(0, \"u64\")\n    if count == nil then return stop(\"count: \" .. tostring(problem)) end\n    local hits, hit_problem = inner:hits()\n    if hits == nil then return stop(\"hit count: \" .. tostring(hit_problem)) end\n    local scheduled, timer_problem = pcall(bsx.after, seconds * 1000, report)\n    if not scheduled then return stop(\"timer: \" .. tostring(timer_problem)) end\n    log((pending or (on and \"on\" or \"paused\")) .. \"; row-load hits=\" .. tostring(hits)\n        .. \"; successful clears about \" .. tostring(count))\n    pending = nil\nend\nok, why = pcall(bsx.after, seconds * 1000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; Ctrl+F5 toggles global preview\" .. (configured and \"\" or \"; configure RowKey and StatusCode for changes\"))\n","lang":"lua","name":"main.lua"},{"code":"[FlightCooldownPreview]\n; These values are NOT identified by the example. Leave -1 to make the\n; filter inert; supply a verified u16 row key and nonzero status to try it.\nRowKey=-1\nStatusCode=-1\nReportSeconds=10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Flight Cooldown Preview\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"MercenaryClan::CheckMemberTimedStatus\",\n    \"MercenaryClan::TimedStatusRowMemberLoad\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"flight_cooldown_preview","kind":"lua","lua_api":3,"path":"bsx/lua/examples/flight_cooldown_preview","tier":"safe","title":"Flight Cooldown Preview","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Flight Freedom: fly over towns and into no-fly zones, summon flying mounts anywhere. Native tier: the player approves this folder like a DLL mod. Recipe a","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Flight Freedom: fly over towns and into no-fly zones, summon flying mounts anywhere.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r5-flight.md. Not yet tested in game. Do not run the\n-- Flight Freedom ASI at the same time.\nlocal ffi = require(\"ffi\")\nlocal function log(message) bsx.log(\"flight_freedom: \" .. message) end\nlocal function setting(key) return config.bool(\"FlightFreedom\", key, true) end\n\n-- Two checks are functions that answer yes or no; a rule makes them return\n-- 0 (no) at once: \"this region does not forbid the vehicle\", \"not above a road\".\nlocal CHECKS = {\n    {\"NoFlyZones\", \"VehicleRegion::ContainsRelatedKey\", \"48 89 5C 24 08 48 89 74 24 10\"},\n    {\"TownFlight\", \"ConditionData_IsAboveRoad::Evaluate\", \"48 83 EC 28 48 8B 82 28 08 00 00\"},\n}\n-- Two summon refusals are a JE (74 xx) that a JMP (EB xx) replaces. The jump\n-- distance xx differs on 2976, so it is checked against the known values.\nlocal BRANCHES = {\n    {\"AbyssSummon\", \"FlightFreedom::AbyssSummonBranch\", {[0x75] = true, [0x7D] = true}},\n    {\"BlockedSummon\", \"FlightFreedom::BlockedSummonBranch\", {[0x35] = true, [0x36] = true}},\n}\n\nlocal rules = {}\nfor _, c in ipairs(CHECKS) do\n    if setting(c[1]) then\n        local rule, why = cdal.rule(c[2], { expect = c[3], ret = {\"eax\", 0} })\n        if rule then rules[#rules + 1] = rule else log(c[1] .. \" off: \" .. tostring(why)) end\n    end\nend\n\nfor _, b in ipairs(BRANCHES) do\n    if setting(b[1]) then\n        local at = tonumber(ffi.cast(\"uintptr_t\", cdal.address(b[2])))\n        if mem.read_u8(at) ~= 0x74 or not b[3][mem.read_u8(at + 1)] then\n            log(b[1] .. \" off: the game's bytes are not the checked jump\")\n        else\n            local ok, why = cdal.patch(b[2], \"\\xEB\")\n            log(b[1] .. (ok and \" on\" or \" off: \" .. tostring(why)))\n        end\n    end\nend\n\nif #rules == 0 then return log(\"no flight rules on\") end\nlocal chord = config.string(\"FlightFreedom\", \"Hotkey\", \"ctrl+numpad3\")\nlocal ok, why = pcall(bsx.hotkey, chord, function()\n    local on = not rules[1]:active()\n    for _, r in ipairs(rules) do r:enable(on) end\n    log(\"flight rules \" .. (on and \"on\" or \"off\"))\nend)\nlog(#rules .. \" flight rules on; \" .. (ok and chord .. \" toggles them\" or \"no toggle key: \" .. tostring(why)))\n","lang":"lua","name":"main.lua"},{"code":"[FlightFreedom]\n; Fly where the game normally refuses. Each option is one of the Flight Freedom\n; mod's edits and applies everywhere, not only to the player.\nNoFlyZones=1\nTownFlight=1\n; Summoning a flying mount in the Abyss and near obstacles. These two are byte\n; patches: they stay until you set them to 0 (the script then reloads) or quit.\nAbyssSummon=1\nBlockedSummon=1\n; Toggles NoFlyZones and TownFlight.\nHotkey=ctrl+numpad3\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Flight Freedom\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"VehicleRegion::ContainsRelatedKey\",\n    \"ConditionData_IsAboveRoad::Evaluate\",\n    \"FlightFreedom::AbyssSummonBranch\",\n    \"FlightFreedom::BlockedSummonBranch\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"flight_freedom","kind":"lua","lua_api":3,"path":"bsx/lua/examples/flight_freedom","tier":"safe","title":"Flight Freedom","uses":[]},{"category":"BSX Core & Diagnostics","description":"Overlay control panel for safe host-owned gameplay modifiers and inventory slot management:","featured":false,"files":[{"code":"-- Gameplay Tweaks (Lua API 4):\n-- Safe host-owned gameplay modifiers (instant interact, unbreakable gear, gather\n-- multiplier, auto breath) and paginated Bag Manager / Diff snapshots.\n\nlocal panel = bsx.ui.panel(\"Gameplay Tweaks\")\nlocal panel2 = bsx.ui.panel(\"Combat & Exploration\")\nlocal panel3 = bsx.ui.panel(\"Movement & World\")\n\nlocal PAGE_SIZE = 8\nlocal SNAPSHOT_KEY = \"bag_snapshot\"\nlocal BREATH_KEYWORDS = { \"breath\", \"oxygen\", \"o2\", \"lung\" }\nlocal INF_ITEMS_LABELS = { \"Off\", \"Keep > 1\", \"Never Consume\" }\n\nlocal world_ready = false\nlocal logged_panel = false\nlocal logged_ready = false\nlocal initial_applied = false\n\nlocal instant_interact = config.bool(\"GameplayTweaks\", \"InstantInteract\", false)\nlocal unbreakable_gear = config.bool(\"GameplayTweaks\", \"UnbreakableGear\", false)\nlocal gather_mult = math.max(1, math.min(10, math.floor(config.int(\"GameplayTweaks\", \"GatherMultiplier\", 1))))\nlocal damage_dealt = math.max(0.1, math.min(20.0, config.float(\"GameplayTweaks\", \"DamageDealt\", 1.0)))\nlocal damage_taken = math.max(0.0, math.min(5.0, config.float(\"GameplayTweaks\", \"DamageTaken\", 1.0)))\nlocal god_mode = config.bool(\"GameplayTweaks\", \"GodMode\", false) or (damage_taken == 0.0)\nlocal keep_breath = config.bool(\"GameplayTweaks\", \"AutoBreath\", false)\nlocal mini_hud = config.bool(\"GameplayTweaks\", \"MiniHud\", false)\nlocal skill_xp_mult = math.max(0.0, math.min(100.0, config.float(\"GameplayTweaks\", \"SkillXpMultiplier\", 1.0)))\nlocal inf_stamina = config.bool(\"GameplayTweaks\", \"InfiniteStamina\", false)\nlocal inf_mp = config.bool(\"GameplayTweaks\", \"InfiniteMp\", false)\nlocal ammo_saving = config.bool(\"GameplayTweaks\", \"AmmoSaving\", false)\nlocal inf_items_mode = math.max(0, math.min(2, math.floor(config.int(\"GameplayTweaks\", \"InfiniteItemsMode\", 0))))\nlocal parry_scale = math.max(0.5, math.min(5.0, config.float(\"GameplayTweaks\", \"ParryWindowScale\", 1.0)))\nlocal flight_freedom = config.bool(\"GameplayTweaks\", \"FlightFreedom\", false)\nlocal no_timewrap_cd = config.bool(\"GameplayTweaks\", \"NoTimeWrapCooldown\", false)\nlocal menu_pause = config.bool(\"GameplayTweaks\", \"MenuPause\", false)\nlocal fov_override = config.bool(\"GameplayTweaks\", \"CameraFovOverride\", false)\nlocal fov_deg = math.max(30.0, math.min(140.0, config.float(\"GameplayTweaks\", \"CameraFovDeg\", 70.0)))\nlocal craft_cost_scale = math.max(0.0, math.min(1.0, config.float(\"GameplayTweaks\", \"CraftCostScale\", 1.0)))\nlocal map_zoom_scale = math.max(0.2, math.min(4.0, config.float(\"GameplayTweaks\", \"MapZoomScale\", 1.0)))\nlocal mw = {\n    free_fly = config.bool(\"GameplayTweaks\", \"FreeFly\", false),\n    free_fly_hotkey = config.string(\"GameplayTweaks\", \"FreeFlyHotkey\", \"f7\"),\n    free_fly_handle = nil,\n    fly_speed = math.max(5.0, math.min(200.0, config.float(\"GameplayTweaks\", \"FlySpeed\", 25.0))),\n    move_speed = math.max(0.1, math.min(10.0, config.float(\"GameplayTweaks\", \"MoveSpeed\", 1.0))),\n    jump_scale = math.max(0.1, math.min(5.0, config.float(\"GameplayTweaks\", \"JumpScale\", 1.0))),\n    game_speed_override = config.bool(\"GameplayTweaks\", \"GameSpeedOverride\", false),\n    game_speed_val = math.max(0.05, math.min(5.0, config.float(\"GameplayTweaks\", \"GameSpeed\", 1.0))),\n    stealth_mode = config.bool(\"GameplayTweaks\", \"Stealth\", false),\n    no_wanted_mode = config.bool(\"GameplayTweaks\", \"NoWanted\", false),\n    shop_price_mult = math.max(0.0, math.min(5.0, config.float(\"GameplayTweaks\", \"ShopPriceScale\", 1.0))),\n    profile_names = { \"Default\", \"Combat\", \"Exploration\", \"Custom 1\", \"Custom 2\" },\n    profile_slugs = { \"default\", \"combat\", \"exploration\", \"custom_1\", \"custom_2\" },\n    profile_idx = 1,\n}\n\nlocal hud_panel = nil\nlocal hud_line1_id = nil\nlocal hud_line2_id = nil\n\nlocal breath_scan_cursor = 0\nlocal breath_scan_done = false\nlocal breath_stat_id = nil\nlocal breath_stat_name = nil\nlocal breath_fallback_id = nil\nlocal breath_fallback_name = nil\nlocal breath_warned = false\n\nlocal bag_all = {}\nlocal bag_labels = { \"(press Load Bag)\" }\nlocal bag_page_items = {}\nlocal bag_page = 1\nlocal bag_idx = 1\n\nlocal status_id = panel:text(\"Waiting for world_ready...\")\nlocal readout_id = panel:text(\"Gameplay: hold=native | wear=100% | gather=1x\")\nlocal status2_id = panel2:text(\"Combat & Exploration: waiting for world_ready...\")\nmw.status_id = panel3:text(\"Movement & World: waiting for world_ready...\")\n\nlocal skill_xp_slider_id\nlocal inf_stam_cb_id\nlocal inf_mp_cb_id\nlocal ammo_cb_id\nlocal inf_items_combo_id\nlocal parry_slider_id\nlocal flight_cb_id\nlocal timewrap_cb_id\nlocal menu_pause_cb_id\nlocal fov_slider_id\nlocal craft_cost_slider_id\nlocal map_zoom_slider_id\n\nlocal function clamp(v, lo, hi)\n    if v \u003c lo then return lo end\n    if v > hi then return hi end\n    return v\nend\n\nlocal function clamp_text(text)\n    local s = tostring(text or \"\")\n    if #s > 127 then\n        return string.sub(s, 1, 124) .. \"...\"\n    end\n    return s\nend\n\nlocal function item_label(row)\n    local disp = game.item_display_name(row)\n    if disp and disp ~= \"\" then return disp end\n    return game.item_name(row) or (\"Row \" .. tostring(row))\nend\n\nlocal function update_readout()\n    local hold = game.gameplay and game.gameplay.interact_hold and game.gameplay.interact_hold() or nil\n    local wear = game.gameplay and game.gameplay.durability_wear and game.gameplay.durability_wear() or 1.0\n    local gather = game.gameplay and game.gameplay.gather_multiplier and game.gameplay.gather_multiplier() or 1\n    local dealt = game.gameplay and game.gameplay.damage_dealt and game.gameplay.damage_dealt() or 1.0\n    local taken = game.gameplay and game.gameplay.damage_taken and game.gameplay.damage_taken() or 1.0\n    local hold_str = hold ~= nil and string.format(\"%.2fs\", hold) or \"native\"\n    local wear_pct = math.floor(wear * 100 + 0.5)\n    local taken_str = taken == 0.0 and \"GOD\" or string.format(\"%.1fx\", taken)\n    local breath_str = \"\"\n    if breath_stat_id ~= nil then\n        local actor = world_ready and game.player() or nil\n        local st = actor and game.stats.read(actor, breath_stat_id) or nil\n        if st and st.current and st.max then\n            breath_str = string.format(\" | O2=%d/%d\", st.current, st.max)\n        else\n            breath_str = string.format(\" | O2=%s[%d]\", tostring(breath_stat_name or \"id\"), breath_stat_id)\n        end\n    end\n    local summary = clamp_text(string.format(\n        \"dmg=%.1fx/%s | gather=%dx | wear=%d%% | hold=%s%s\", dealt, taken_str, gather, wear_pct, hold_str, breath_str))\n    panel:set_text(readout_id, summary)\n    if hud_panel and hud_panel:active() then\n        local fov_val = game.camera and game.camera.fov and game.camera.fov() or nil\n        local fov_tag = fov_val and string.format(\"FOV %.0f\", fov_val) or \"FOV native\"\n        local combat_line = clamp_text(string.format(\n            \"Dmg %.1fx/%s | Parry %.1fx | %s\", dealt, god_mode and \"GOD\" or string.format(\"%.1fx\", taken), parry_scale, fov_tag))\n        local misc_line = clamp_text(string.format(\n            \"Gather %dx | Wear %d%%%s%s%s%s\",\n            gather, wear_pct,\n            mw.free_fly and \" | FreeFly\" or \"\",\n            mw.stealth_mode and \" | Stealth\" or \"\",\n            mw.no_wanted_mode and \" | NoCrime\" or \"\",\n            keep_breath and \" | O2 ON\" or \"\"))\n        hud_panel:set_text(hud_line1_id, combat_line)\n        hud_panel:set_text(hud_line2_id, misc_line)\n    end\nend\n\nlocal instant_cb_id\nlocal unbreakable_cb_id\nlocal breath_cb_id\nlocal hud_cb_id\nlocal god_cb_id\nlocal gather_slider_id\nlocal dealt_slider_id\nlocal taken_slider_id\n\nlocal function apply_mini_hud(enabled)\n    mini_hud = enabled == true\n    if mini_hud then\n        if (not hud_panel or not hud_panel:active()) and bsx.ui and bsx.ui.hud then\n            hud_panel = bsx.ui.hud(\"Gameplay HUD\", { alpha = 0.65, x = 24, y = 24 })\n            hud_line1_id = hud_panel:text(\"Combat: 1.0x / 1.0x\")\n            hud_line2_id = hud_panel:text(\"Gather 1x | Wear 100%\")\n        end\n        update_readout()\n        panel:set_text(status_id, \"Mini HUD: ON (always visible when overlay closed)\")\n    else\n        if hud_panel then\n            pcall(function() hud_panel:remove() end)\n            hud_panel = nil\n            hud_line1_id = nil\n            hud_line2_id = nil\n        end\n        panel:s\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[GameplayTweaks]\nInstantInteract=0\nUnbreakableGear=0\nGatherMultiplier=1\nDamageDealt=1.0\nDamageTaken=1.0\nGodMode=0\nAutoBreath=0\nMiniHud=0\nSkillXpMultiplier=1.0\nInfiniteStamina=0\nInfiniteMp=0\nAmmoSaving=0\nInfiniteItemsMode=0\nParryWindowScale=1.0\nFlightFreedom=0\nNoTimeWrapCooldown=0\nMenuPause=0\nCameraFovOverride=0\nCameraFovDeg=70.0\nFreeFly=0\nFreeFlyHotkey=f7\nFlySpeed=25.0\nMoveSpeed=1.0\nJumpScale=1.0\nGameSpeedOverride=0\nGameSpeed=1.0\nStealth=0\nNoWanted=0\nShopPriceScale=1.0\nCraftCostScale=1.0\nMapZoomScale=1.0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Gameplay Tweaks\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"inventory\", \"definitions\", \"server_commands\"],\n  \"needs_ids\": [\n    \"ItemInfo::DisplayName\",\n    \"Localization::sTextPoolManager\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"gameplay_tweaks","kind":"lua","lua_api":4,"path":"bsx/lua/examples/gameplay_tweaks","tier":"changes","title":"Gameplay Tweaks","uses":["ui","player","snapshots","inventory","definitions","server_commands"]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Gather catch rates: more bugs and fish per catch, like Desert Tooling's catch factors. Native tier: the player approves this folder like a DLL mod. Recipe","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Gather catch rates: more bugs and fish per catch, like Desert Tooling's catch factors.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits\n-- (including the type check this leaves out): bsx/lua/recipes/r2-loot.md.\n-- Not yet tested in game.\n--\n-- At this place the game has just put the catch quantity (1) in R8D, and RAX is\n-- the caught creature's class object. One rule per class multiplies R8D.\nlocal SITE = \"LootCatch::QuantityReady\"\n-- lea rdx,[rbp+0x1D0]; lea rcx,[rbp+0xB0]: the same on all seven checked builds.\nlocal EXPECT = \"48 8D 95 D0 01 00 00 48 8D 8D B0 00 00 00\"\nlocal CLASS = \"[rax+0x5a].u8\"  -- the class byte Desert Tooling reads\n\nlocal function log(message) bsx.log(\"gather rates: \" .. message) end\n\nlocal bugs = config.int(\"Catch\", \"Bugs\", 1)\nlocal fish = config.int(\"Catch\", \"Fish\", 1)\nlocal hotkey = config.string(\"Catch\", \"Hotkey\", \"ctrl+shift+f4\")\nif bugs \u003c 1 or bugs > 100 or fish \u003c 1 or fish > 100 then\n    return log(\"off: Bugs and Fish must be whole numbers from 1 to 100\")\nend\n\nlocal CLASSES = { {0x80, bugs}, {0x23, fish}, {0x83, fish} }  -- bug, fish, fish\nlocal rules = {}\n\nlocal function remove_all()\n    for _, rule in ipairs(rules) do rule:remove() end\n    rules = {}\nend\n\nlocal function install()\n    for _, entry in ipairs(CLASSES) do\n        local rule, why = cdal.rule(SITE, {\n            expect = EXPECT,\n            when = { {CLASS, \"==\", entry[1]} },\n            set  = { {\"r8d\", \"mul\", entry[2]} },\n        })\n        if not rule then\n            remove_all()  -- all three or none\n            log(\"off: \" .. tostring(why))\n            return false\n        end\n        rules[#rules + 1] = rule\n    end\n    log(\"on (bugs x\" .. bugs .. \", fish x\" .. fish .. \"); \" .. hotkey .. \" toggles\")\n    return true\nend\n\nlocal function toggle()\n    if #rules == 0 then return install() end\n    local on = not rules[1]:active()\n    for _, rule in ipairs(rules) do rule:enable(on) end\n    log(on and \"on\" or \"off\")\nend\n\nif config.bool(\"Catch\", \"Enabled\", true) then\n    if not install() then return end\nelse\n    log(\"off; \" .. hotkey .. \" turns it on\")\nend\nlocal ok, why = pcall(bsx.hotkey, hotkey, toggle)\nif not ok then log(\"no toggle key: \" .. tostring(why)) end\n\n-- hits() counts catches that matched a class: proof in game that the rule is reached.\nlocal function report()\n    local total = 0\n    for _, rule in ipairs(rules) do total = total + rule:hits() end\n    if #rules > 0 then log(\"catches changed so far: \" .. total) end\n    bsx.after(60000, report)\nend\nbsx.after(10000, report)\n","lang":"lua","name":"main.lua"},{"code":"[Catch]\n; The original mod defaults to one. Choose whole numbers from 1 to 100.\nBugs=1\nFish=1\nEnabled=true\nHotkey=ctrl+shift+f4\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Gather catch rates\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"LootCatch::QuantityReady\"]\n}\n","lang":"json","name":"script.json"}],"id":"gather_rates","kind":"lua","lua_api":3,"path":"bsx/lua/examples/gather_rates","tier":"safe","title":"Gather catch rates","uses":[]},{"category":"Items & Inventory","description":"Copy to BSX/scripts/gear_report and press Ctrl+Shift+F1 after loading a save. Snapshots are read-only copies. ItemNo is an exact string, not a Lua number.","featured":false,"files":[{"code":"-- Copy to BSX/scripts/gear_report and press Ctrl+Shift+F1 after loading a save.\n-- Snapshots are read-only copies. ItemNo is an exact string, not a Lua number.\nlocal busy = false\nlocal function report()\n    if busy then return end -- Do not interleave two reports.\n    local equipment, why = game.equipment_snapshot()\n    if not equipment then return bsx.log(\"gear report: equipment unavailable (\" .. tostring(why) .. \")\") end\n    busy = true\n    bsx.after(0, function()\n        -- Read on another frame so a large inventory does not share the first callback.\n        local inventory, inventory_why = game.inventory.list(4096)\n        local summary\n        if not inventory then\n            summary = \"gear report: inventory unavailable (\" .. tostring(inventory_why) .. \")\"\n        elseif inventory.actor_key ~= equipment.actor_key or inventory.generation ~= equipment.generation then\n            summary = \"gear report: inventory unavailable (player or save changed between snapshots)\"\n        else\n            local seen, distinct = {}, 0\n            for _, item in ipairs(inventory) do\n                if not seen[item.row] then seen[item.row], distinct = true, distinct + 1 end\n            end\n            summary = \"gear report: \" .. (inventory.truncated and \"at least \" or \"\") .. distinct ..\n                \" distinct inventory rows\" .. (inventory.truncated and \" (truncated)\" or \"\")\n        end\n\n        local count = math.min(#equipment, 18) -- 18 items + optional omission + summary = 20 lines.\n        local index = 1\n        local function emit()\n            if index \u003c= count then\n                local item = equipment[index]\n                local name, name_why = game.item_name(item.row)\n                if not name then name = \"row \" .. item.row .. \" (name unavailable: \" .. tostring(name_why) .. \")\" end\n                bsx.log(\"gear report: slot=\" .. item.slot_tag .. \" name=\" .. name ..\n                    \" ItemNo=\" .. (item.instance_id or \"unassigned\"))\n            elseif index == count + 1 and #equipment > count then\n                bsx.log(\"gear report: \" .. (#equipment - count) .. \" more equipped items omitted\")\n            else\n                if #equipment == 0 and index == 1 then\n                    bsx.log(\"gear report: no equipped items\")\n                    index = index + 1\n                    bsx.after(250, emit)\n                    return\n                end\n                bsx.log(summary)\n                busy = false\n                return\n            end\n            index = index + 1\n            bsx.after(250, emit) -- Stay below the host's ten-logs-per-second quota.\n        end\n        emit()\n    end)\nend\n\nlocal ok, why = pcall(bsx.hotkey, \"ctrl+shift+f1\", report)\nif not ok then bsx.log(\"gear report: hotkey unavailable (\" .. tostring(why) .. \")\") end\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Gear Report\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\",\n    \"pa::ClientNormalInGameActor::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Key\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"ActorComponents::Equipment\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"InventoryBucket::Tag\",\n    \"InventoryItem::ItemNo\",\n    \"CommonEquipSlotActorComponent::StorageOffset\",\n    \"EquipmentSlotRecord::Stride\",\n    \"EquipmentSlotRecord::SlotTag\",\n    \"ItemInfoManager::sInstance\",\n    \"pa::ItemInfoManager::vftable\",\n    \"ItemInfoManager::sEmptyRow\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::Key\",\n    \"DefinitionRow::InternalName\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"gear_report","kind":"lua","lua_api":3,"path":"bsx/lua/examples/gear_report","tier":"safe","title":"Gear Report","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 One Gear Hider transition write for one already-known numeric part key. Requires Native approval and rule version 2 memory writes. This affects all actors","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- One Gear Hider transition write for one already-known numeric part key.\n-- Requires Native approval and rule version 2 memory writes. This affects\n-- all actors with that key and does not refresh or restore cached parts.\n-- See recipes/r8-visual.md. Not tested in game.\nlocal function log(message) bsx.log(\"gear_transition: \" .. message) end\n\nlocal key = config.float(\"GearTransition\", \"PartKey\", -1)\nif not (key >= 0 and key \u003c= 4294967295 and math.floor(key) == key) then\n    return log(\"off: PartKey must be an already-known unsigned 32-bit part key\")\nend\n\nlocal site = \"PartInOutSocket::TransitionCheck\"\nlocal status, status_why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(status_why or status))\nend\nlocal offset, why = cdal.value(\"PartInOut::Visibility\")\nif offset == nil then return log(\"off: \" .. tostring(why)) end\nif offset ~= 0x20 then return log(\"off: visibility offset differs from the checked instruction\") end\n\nlocal rule, rule_why = cdal.rule(site, {\n    expect = \"45 0F B6 58 20\", enabled = false,\n    when = {{\"[rdx+0x0].u32\", \"==\", key}},\n    set = {{string.format(\"[r8+0x%X].u8\", offset), \"set\", 2}},\n})\nif not rule then return log(\"off: \" .. tostring(rule_why)) end\n\nlocal on, live = false, true\nlocal function set_enabled(want)\n    if not live then return false end\n    local ok, reason = rule:enable(want)\n    if not ok then\n        local removed, remove_why = rule:remove()\n        if not removed then log(\"remove failed: \" .. tostring(remove_why)) end\n        live = false\n        log(\"off: cannot change rule: \" .. tostring(reason))\n        return false\n    end\n    on = want\n    return true\nend\nlocal chord = config.string(\"GearTransition\", \"Hotkey\", \"ctrl+alt+numpad3\")\nlocal key_ok, key_why = pcall(bsx.hotkey, chord, function()\n    if set_enabled(not on) then\n        log(on and \"on; wait for a native part transition\" or \"off; cached parts may stay hidden\")\n    end\nend)\nif not key_ok then\n    local removed, remove_why = rule:remove()\n    if not removed then log(\"remove failed: \" .. tostring(remove_why)) end\n    return log(\"off: cannot register hotkey: \" .. tostring(key_why))\nend\nif not set_enabled(config.bool(\"GearTransition\", \"Enabled\", false)) then return end\nlog((on and \"on\" or \"off\") .. \": one key, all actors; \" .. chord .. \" toggles\")\n\nlocal function report()\n    if not live then return end\n    local hits, reason = rule:hits()\n    if hits == nil then return log(\"hit count unavailable: \" .. tostring(reason)) end\n    log(\"matching transitions=\" .. hits .. \"; a hit does not confirm a visible change\")\n    local ok, timer_why = pcall(bsx.after, 60000, report)\n    if not ok then log(\"hit timer unavailable: \" .. tostring(timer_why)) end\nend\nlocal timer_ok, timer_why = pcall(bsx.after, 60000, report)\nif not timer_ok then log(\"hit timer unavailable: \" .. tostring(timer_why)) end\n","lang":"lua","name":"main.lua"},{"code":"; Enter one already-known numeric IndexedStringA part key for this run.\n; -1 leaves the example off. Keys are not portable names or item row numbers.\n; The write affects this key for every actor. It cannot refresh or restore\n; already cached parts, select a character, or resolve part names.\n[GearTransition]\nPartKey=-1\nEnabled=0\nHotkey=ctrl+alt+numpad3\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Gear Transition\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"PartInOutSocket::TransitionCheck\",\n    \"PartInOut::Visibility\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"gear_transition","kind":"lua","lua_api":3,"path":"bsx/lua/examples/gear_transition","tier":"safe","title":"Gear Transition","uses":[]},{"category":"Combat & Stats","description":"Refusal probe only: no heal, native call, game read or completion claim. Stat 0 and 5000 are the retained helper's legacy inputs, not a key/scale proof.","featured":false,"files":[{"code":"-- Refusal probe only: no heal, native call, game read or completion claim.\n-- Stat 0 and 5000 are the retained helper's legacy inputs, not a key/scale proof.\nlocal function log(text) bsx.log(\"heal_hotkey: \" .. text) end\nlocal ok, why = pcall(bsx.on, \"key\", function(e)\n    -- KEY callbacks run from the Lua FRAME queue. Observe Ctrl+F8; do not consume it.\n    if e.reset or not e.down or e[\"repeat\"] or e.virtual_key ~= 0x77 or e.modifiers ~= 1 then return end\n    if not game.stats.add then\n        log(\"read-only; changes approval required\")\n        return\n    end\n    local queued, reason = game.stats.add(0, 5000)\n    if queued then\n        log(\"queued; application not confirmed\")\n    else\n        log(\"refused: \" .. tostring(reason))\n    end\nend)\nif not ok then log(\"KEY unavailable: \" .. tostring(why))\nelse log(\"Ctrl+F8 refusal probe ready; this example does not heal\") end\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Heal hotkey refusal probe\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": []\n}\n","lang":"json","name":"script.json"}],"id":"heal_hotkey","kind":"lua","lua_api":3,"path":"bsx/lua/examples/heal_hotkey","tier":"changes","title":"Heal hotkey refusal probe","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A five-HP request after each SAVE_LOADED, only with player approval.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A five-HP request after each SAVE_LOADED, only with player approval.\nlocal last_generation\nlocal function stored_hp()\n    local actor, why = game.player()\n    if not actor then return nil, why end\n    local stats\n    stats, why = game.stats(actor)\n    if not stats then return nil, why end\n    local entries_offset = cdal.value('StatusComponent::StatEntries')\n    local current_offset = cdal.value('StatEntry::Current')\n    if not entries_offset or not current_offset then return nil, 'HP offsets unavailable' end\n    local entries\n    entries, why = mem.read_ptr(stats + entries_offset)\n    if not entries or entries == 0 then return nil, why or 'no stat entries' end\n    local low, high = mem.read_u8(entries), mem.read_u8(entries + 1)\n    if low ~= 0 or high ~= 0 then return nil, 'first stat entry is not HP key 0' end\n    return mem.read_u64(entries + current_offset)\nend\nlocal ok, why = pcall(bsx.on, 'save_loaded', function(event)\n    if last_generation == event.generation then return end\n    last_generation = event.generation\n    local before, reason = stored_hp()\n    if not before then return bsx.log('heal_on_load: ' .. reason) end\n    if type(game.stats) ~= 'table' or not game.stats.add then\n        return bsx.log('heal_on_load: read-only; HP before=' .. before .. ' after=' .. before .. ' (x1000)')\n    end\n    local result\n    result, reason = game.stats.add(0, 5000)\n    if not result then return bsx.log('heal_on_load: refused: ' .. reason) end\n    local after\n    after, reason = stored_hp()\n    bsx.log('heal_on_load: HP before=' .. before .. ' after=' .. (after or reason) ..\n        ' native_result=' .. result .. ' (x1000); requested +5 HP')\nend)\nif not ok then bsx.log('heal_on_load: SAVE_LOADED unavailable: ' .. tostring(why)) end\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Heal on load\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\",\n    \"pa::ClientNormalInGameActor::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Components\",\n    \"ActorComponents::Status\",\n    \"pa::ClientStatusActorComponent::vftable\",\n    \"CommonStatusActorComponent::StatContainer\",\n    \"StatusComponent::StatEntries\",\n    \"StatEntry::Current\",\n    \"StatDefinitions::ClientRoot\",\n    \"StatDefinitions::ServerRoot\",\n    \"GameTime::Now\",\n    \"StatusComponent::ApplyStatDelta\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"heal_on_load","kind":"lua","lua_api":3,"path":"bsx/lua/examples/heal_on_load","tier":"changes","title":"Heal on load","uses":[]},{"category":"BSX Core & Diagnostics","description":"The smallest BSX Lua script: logs a frame now and then, every save load and a timer. Copy this folder to BSX/scripts/hello. Its log lines go to BSX/bsx.log, prefixed [hello].","featured":false,"files":[{"code":"-- The smallest BSX Lua script: logs a frame now and then, every save load and a timer.\n-- Copy this folder to BSX/scripts/hello. Its log lines go to BSX/bsx.log, prefixed [hello].\n\n-- settings.ini next to this file can change it: [Hello] FrameEvery=600\nlocal every = config.int(\"Hello\", \"FrameEvery\", 600)\n\nbsx.on(\"frame\", function(e)\n    if e.frame == 1 or e.frame % every == 0 then bsx.log(\"frame \" .. e.frame) end\nend)\n\n-- A save starts loading. A script that starts after the save already loaded (BSX Lua starts\n-- at the first frame, FastLoad can load earlier) still gets it once, with replayed = true.\nbsx.on(\"save_load\", function(e)\n    bsx.log(\"save load: key \" .. e.key .. \", argument \" .. e.argument .. (e.replayed and \" (replayed)\" or \"\"))\nend)\n\n-- An event BSX can't offer on this game build raises an error. pcall keeps the script running\n-- without it; without pcall the script would switch off with the reason in its status.\nlocal ok, why = pcall(bsx.on, \"save_loaded\", function(e)\n    bsx.log(\"save loaded: generation \" .. e.generation)\nend)\nif not ok then bsx.log(\"no save_loaded event on this build: \" .. tostring(why)) end\n\nbsx.after(5000, function() bsx.log(\"five seconds after the script started\") end)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Hello Lua\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 1,\n  \"native\": false,\n  \"needs_ids\": [\"Game::Update\"],\n  \"needs_plugins\": [],\n  \"packs\": []\n}\n","lang":"json","name":"script.json"}],"id":"hello","kind":"lua","lua_api":1,"path":"bsx/lua/examples/hello","tier":"safe","title":"Hello Lua","uses":[]},{"category":"Appearance & Outfits","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Reproduces an older mod's numeric DISPLAY-record fingerprint and edit. It applies to any matching record, not only a proven owned horse, and is not eviden","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Reproduces an older mod's numeric DISPLAY-record fingerprint and edit.\n-- It applies to any matching record, not only a proven owned horse, and is\n-- not evidence of infinite gameplay stamina. Native approval is full trust.\n-- See bsx/lua/recipes/r4-stamina.md before enabling it; not tested in game.\nlocal function log(message) bsx.log(\"horse_display_limit: \" .. message) end\nlocal speed_only = config.bool(\"HorseDisplayLimit\", \"SpeedOnly\", false)\nlocal site = \"MountDisplay::CurrentComparison\"\nlocal status, status_why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(status_why or status))\nend\n\n-- The old build keeps the embedded record in R12 and compares RDX; the six\n-- later builds use R15 and RCX; 1.0.0.3732 is back on R12 and RDX with the\n-- longer jumps (checked offline, 2026-11-20). Each form checks the following\n-- comparison as well as the load, and then checks the actual record/object\n-- relationship.\nlocal function install(record, compared, expected)\n    local at = \"[\" .. record .. \"+0x\"\n    local kind, typ = at .. \"25].u8\", at .. \"26].u8\"\n    local key, maximum = at .. \"28].u16\", at .. \"8].u64\"\n    local current, field10, field18 = at .. \"0].u64\", at .. \"10].u64\", at .. \"18].u64\"\n    return cdal.rule(site, {\n        expect = expected, enabled = false, stop_on_failure = true,\n        when = {\n            {record, \"==\", \"&[r14+0x230]\"},\n            {kind, \"==\", 3}, {typ, \">=\", 15}, {typ, \"\u003c=\", speed_only and 15 or 18},\n            {maximum, \"==\", 5000}, {field10, \"==\", 0}, {field18, \"==\", 1000},\n            {current, \"\u003c=\", maximum},\n        },\n        set = {\n            {\"%0.u64\", \"set\", typ}, {\"%0.u64\", \">=\", 15},\n            {\"%0.u64\", \"\u003c=\", speed_only and 15 or 18}, {\"%0.u64\", \"add\", 32},\n            {key, \"==\", \"%0.u64\"},              -- key must equal the copied type + 32\n            {\"%1.u64\", \"set\", maximum}, {\"%1.u64\", \"==\", 5000},\n            {\"%2.u64\", \"set\", current}, {\"%2.u64\", \"\u003c=\", \"%1.u64\"},\n            {current, \"set\", \"%1.u64\"},         -- a failed write stops here\n            {compared, \"set\", \"%1.u64\"},        -- only after that write succeeds\n        },\n    })\nend\nlocal forms = {\n    {\"r12\", \"rdx\", \"4D 8B 96 30 02 00 00 49 3B D2 75 09 49 3B 8E 38 02 00 00 74 7B\"},\n    {\"r15\", \"rcx\", \"4D 8B 96 30 02 00 00 49 3B CA 75 0D 4D 3B AE 38 02 00 00 0F 84 80 00 00 00\"},\n    {\"r12\", \"rdx\", \"4D 8B 96 30 02 00 00 49 3B D2 75 0D 49 3B 8E 38 02 00 00 0F 84 80 00 00 00\"},\n}\nlocal rule, why\nfor _, form in ipairs(forms) do\n    rule, why = install(form[1], form[2], form[3])\n    if rule or not string.find(tostring(why), \"differ from `expect`\", 1, true) then break end\nend\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal on, alive, changed, last_hits, failure = false, true, false, 0, nil\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, remove_why = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(remove_why) end\n    failure = \"off: \" .. reason\nend\nlocal bound, key_why = pcall(bsx.hotkey, \"ctrl+numpad9\", function()\n    if not alive then return end\n    local ok, enable_why = rule:enable(not on)\n    if not ok then return stop(\"toggle failed: \" .. tostring(enable_why)) end\n    on, changed = not on, true\nend)\nif not bound then\n    stop(\"hotkey unavailable: \" .. tostring(key_why))\n    return log(failure)\nend\n-- Entries count even if the computed key check or guarded write fails.\nlocal function report()\n    if failure then return log(failure) end\n    local hits, hits_why = rule:hits()\n    if hits == nil then\n        stop(\"hit count unavailable: \" .. tostring(hits_why))\n        return log(failure)\n    end\n    local queued, timer_why = pcall(bsx.after, 10000, report)\n    if not queued then\n        stop(\"timer unavailable: \" .. tostring(timer_why))\n        return log(failure)\n    end\n    if changed or hits ~= last_hits then\n        log((on and \"on\" or \"paused\") .. \"; matching display entries=\" .. tostring(hits))\n        last_hits, changed = hits, false\n    end\nend\nlocal queued, timer_why = pcall(bsx.after, 10000, report)\nif not queued then\n    stop(\"timer unavailable: \" .. tostring(timer_why))\n    return log(failure)\nend\nlog(\"ready: paused; Ctrl+Numpad9 toggles a display-only record edit\")\n","lang":"lua","name":"main.lua"},{"code":"[HorseDisplayLimit]\n; false: the older all-stats fingerprint; true: its speed-only fingerprint.\nSpeedOnly=false\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Horse Display Limit\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"MountDisplay::CurrentComparison\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"horse_display_limit","kind":"lua","lua_api":3,"path":"bsx/lua/examples/horse_display_limit","tier":"safe","title":"Horse Display Limit","uses":[]},{"category":"UI & Overlays","description":"Safe-tier Lua API 4 showcase demonstrating:","featured":false,"files":[{"code":"-- HUD Overlay: safe-tier Lua API 4 showcase for bsx.ui.mcm, game.camera.world_to_screen, and bsx.draw.*\n\nlocal mcm\nlocal world_ready = false\nlocal logged_ready = false\nlocal last_draw_ok = true\n\nlocal function build_menu()\n    mcm = bsx.ui.mcm({ title = \"HUD Overlay\", section = \"Overlay\" }, {\n        { type = \"section\", label = \"Master & Hotkey\", open = true },\n        { type = \"checkbox\", key = \"Enabled\", label = \"Enable 2D Canvas\", default = true },\n        { type = \"hotkey\", key = \"ToggleKey\", label = \"Toggle Overlay Key\", default = \"F9\", on_change = function() end },\n        { type = \"section\", label = \"Layers\", open = true },\n        { type = \"checkbox\", key = \"ShowReticle\", label = \"Center Reticle\", default = true },\n        { type = \"checkbox\", key = \"ShowMarkers\", label = \"3D Actor Labels\", default = true },\n        { type = \"checkbox\", key = \"ShowCompass\", label = \"Compass Banner\", default = true },\n        { type = \"slider\", key = \"ReticleRadius\", label = \"Reticle Radius (px)\", min = 4, max = 40, default = 10 },\n        { type = \"slider\", key = \"MaxActors\", label = \"Max 3D Markers\", min = 1, max = 24, default = 6 },\n        { type = \"input_text\", key = \"ColorHex\", label = \"Accent #RRGGBBAA\", default = \"#64E6FFB0\" },\n        { type = \"button\", label = \"Clear Canvas Now\", on_click = function()\n            bsx.draw.clear()\n        end },\n    })\nend\n\nlocal function sanitize_color(hex)\n    if type(hex) == \"string\" and (hex:match(\"^#%x%x%x%x%x%x$\") or hex:match(\"^#%x%x%x%x%x%x%x%x$\")) then\n        return hex\n    end\n    return \"#64E6FFD0\"\nend\n\nlocal function render_overlay()\n    bsx.draw.clear()\n    if not mcm or not mcm.get(\"Enabled\") then return end\n\n    local color = sanitize_color(mcm.get(\"ColorHex\"))\n    local ps = game.player_state()\n    local in_world = world_ready or (ps and ps.world_ready)\n\n    if mcm.get(\"ShowCompass\") then\n        local heading = \"Heading: --\"\n        local cam = game.camera.pose()\n        if cam and cam.valid then\n            local deg = (math.deg(math.atan2(cam.fwd_x, cam.fwd_z)) + 360) % 360\n            heading = string.format(\"Heading: %03d deg\", math.floor(deg + 0.5))\n        end\n        bsx.draw.rect(18, 18, 220, 44, \"#0F141ECC\", true)\n        bsx.draw.rect(18, 18, 220, 44, color, false, 1.5)\n        bsx.draw.text(28, 30, \"BSX HUD | \" .. heading, color)\n    end\n\n    if not in_world then return end\n\n    if mcm.get(\"ShowReticle\") then\n        local rad = math.max(4, math.min(40, math.floor(tonumber(mcm.get(\"ReticleRadius\")) or 10)))\n        local cx, cy = 960, 540\n        local cam = game.camera.pose()\n        local pos = game.position()\n        if cam and cam.valid then\n            local proj = game.camera.world_to_screen(\n                cam.x + cam.fwd_x * 20,\n                cam.y + cam.fwd_y * 20,\n                cam.z + cam.fwd_z * 20)\n            if proj and proj.visible then\n                cx, cy = proj.x, proj.y\n            end\n        elseif pos then\n            local proj = game.camera.world_to_screen(pos.x, pos.y + 1.5, pos.z)\n            if proj and proj.visible then\n                cx, cy = proj.x, proj.y\n            end\n        end\n        bsx.draw.circle(cx, cy, rad, color, false, 1.5)\n        bsx.draw.line(cx - rad - 4, cy, cx - 3, cy, color, 1.5)\n        bsx.draw.line(cx + 3, cy, cx + rad + 4, cy, color, 1.5)\n    end\n\n    if mcm.get(\"ShowMarkers\") then\n        local limit = math.max(1, math.min(24, math.floor(tonumber(mcm.get(\"MaxActors\")) or 6)))\n        local actors = game.actors()\n        local me = game.position()\n        if type(actors) == \"table\" then\n            local drawn = 0\n            for i = 1, #actors do\n                if drawn >= limit then break end\n                local a = actors[i]\n                if not a.controlled and not a.dead and a.x and a.y and a.z then\n                    local st = game.stats.read(a.actor, 0)\n                    local hp_str = (st and st.max and st.max > 0)\n                        and string.format(\" [%d/%d]\", math.floor(st.current or 0), math.floor(st.max))\n                        or \"\"\n                    local dist = \"\"\n                    if a.distance then\n                        dist = string.format(\" %.0fm\", a.distance)\n                    elseif me then\n                        local dx, dy, dz = a.x - me.x, a.y - me.y, a.z - me.z\n                        dist = string.format(\" %.0fm\", math.sqrt(dx * dx + dy * dy + dz * dz))\n                    end\n                    local label = string.format(\"%s%s%s\", a.character_name or tostring(a.key or \"Actor\"), hp_str, dist)\n                    local proj = game.camera.world_to_screen(a.x, a.y + 2.0, a.z)\n                    if proj and proj.on_screen then\n                        local box_w = math.min(220, math.max(80, #label * 7 + 12))\n                        bsx.draw.rect(proj.x - 4, proj.y - 3, box_w, 20, \"#10141DB8\", true)\n                        local ok = bsx.draw.world_label(a.x, a.y + 2.0, a.z, label, color)\n                        if ok then drawn = drawn + 1 end\n                    end\n                end\n            end\n        end\n    end\n\n    if not logged_ready then\n        logged_ready = true\n        last_draw_ok = true\n        bsx.log(\"HUD_OVERLAY_READY\")\n    end\nend\n\nbuild_menu()\n\nbsx.hotkey(mcm.get(\"ToggleKey\") or \"F9\", function()\n    local next_v = not mcm.get(\"Enabled\")\n    mcm.set(\"Enabled\", next_v)\n    bsx.ui.toast(\"HUD Overlay \" .. (next_v and \"enabled\" or \"disabled\"), { level = next_v and \"ok\" or \"info\" })\nend)\n\nbsx.on(\"world_ready\", function()\n    world_ready = true\nend)\n\nbsx.on(\"title_screen\", function()\n    world_ready = false\n    bsx.draw.clear()\nend)\n\nbsx.on(\"frame\", function()\n    local ok, err = pcall(render_overlay)\n    if not ok and last_draw_ok then\n        last_draw_ok = false\n        bsx.log(\"hud_overlay draw note: \" .. tostring(err))\n    end\nend)\n","lang":"lua","name":"main.lua"},{"code":"[Overlay]\nEnabled=true\nShowReticle=true\nShowMarkers=true\nShowCompass=true\nMaxActors=6\nReticleRadius=10\nColorHex=#64E6FFB0\nToggleKey=F9\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"HUD Overlay\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": false,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"hud_overlay","kind":"lua","lua_api":4,"path":"bsx/lua/examples/hud_overlay","tier":"safe","title":"HUD Overlay","uses":["ui","player","snapshots","positions"]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Infinite items: using, selling or dropping an item does not lower its amount, like Infinite Items' modes. Native tier: the player approves this folder lik","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Infinite items: using, selling or dropping an item does not lower its amount,\n-- like Infinite Items' modes. Native tier: the player approves this folder like\n-- a DLL mod. Recipe and the differences from the mod: bsx/lua/recipes/r3-stacks.md.\n-- Not yet tested in game.\n--\n-- At this place the game subtracts R9 (how many to remove) from RDX (the old\n-- amount). Setting R9 to 0 keeps the old amount. It applies to every item\n-- decrease the game makes this way, for every character and container.\nlocal SITE = \"ItemValue::SubtractAmountChecked\"\nlocal EXPECT = \"4C 29 CA EB\"  -- sub rdx,r9; jmp\n\nlocal function log(message) bsx.log(\"infinite_items: \" .. message) end\n\nlocal mode = config.int(\"InfiniteItems\", \"Mode\", 1)\nlocal hotkey = config.string(\"InfiniteItems\", \"Hotkey\", \"ctrl+f2\")\nif mode \u003c 0 or mode > 2 then return log(\"off: Mode must be 0, 1 or 2\") end\nlocal NAMES = { [0] = \"off\", \"keep amounts above one\", \"never lose any\" }\n\n-- Mode 1 changes only amounts above one; mode 2 every amount of at least one.\nlocal function threshold(m) return m == 1 and 1 or 0 end\n\nlocal rule, why = cdal.rule(SITE, {\n    expect = EXPECT,\n    when = { {\"rdx\", \">\", threshold(mode)} },\n    set  = { {\"r9\", \"set\", 0} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\nrule:enable(mode ~= 0)\nlog(\"mode \" .. mode .. \" (\" .. NAMES[mode] .. \"); \" .. hotkey .. \" cycles modes\")\n\nlocal ok, err = pcall(bsx.hotkey, hotkey, function()\n    mode = (mode + 1) % 3\n    if mode ~= 0 then rule:when(1, threshold(mode)) end\n    rule:enable(mode ~= 0)\n    log(\"mode \" .. mode .. \" (\" .. NAMES[mode] .. \")\")\nend)\nif not ok then log(\"no mode key: \" .. tostring(err)) end\n\n-- hits() counts item decreases the rule kept: proof in game that it is reached.\nlocal function report()\n    log(\"decreases kept so far: \" .. rule:hits())\n    bsx.after(60000, report)\nend\nbsx.after(10000, report)\n","lang":"lua","name":"main.lua"},{"code":"[InfiniteItems]\n; 0 = off, 1 = keep amounts above one (the last one can still be used), 2 = never lose any.\nMode=1\nHotkey=ctrl+f2\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Infinite items\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"ItemValue::SubtractAmountChecked\"]\n}\n","lang":"json","name":"script.json"}],"id":"infinite_items","kind":"lua","lua_api":3,"path":"bsx/lua/examples/infinite_items","tier":"safe","title":"Infinite items","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Native-tier preview (needs Native approval); not tested in game. See r3-stacks.md. It affects every caller of the shared site.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Native-tier preview (needs Native approval); not tested in game. See r3-stacks.md.\n-- It affects every caller of the shared site.\n\nlocal function log(text) bsx.log(\"infinite_items_exact: \" .. text) end\nlocal mode = config.int(\"InfiniteItemsExact\", \"Mode\", 0)\nif mode \u003c 0 or mode > 2 then return log(\"off: Mode must be 0, 1 or 2\") end\n\n-- A mode-1 old quantity must be >= 2. Mode 2 also accepts INT64_MIN; using\n-- a decimal string keeps the full signed 64-bit value exact in Lua.\nlocal function threshold(value)\n    if value == 2 then return \"-9223372036854775808\" end\n    return 2\nend\nlocal names = { [0] = \"off\", [1] = \"above one\", [2] = \"all\" }\n\n-- The rule runs BEFORE the store. CDAL's mid hook displaces both the store\n-- and the following three-byte mov. When the unsigned decrease and the\n-- mode's old-value test hold, reproduce that mov and resume after it.\n-- Jumping only four bytes would land inside the hook's patched bytes.\nlocal rule, why = cdal.rule(\"ItemValue::AdjustAmountStore\", {\n    expect = \"48 89 53 10 4C 89 D8 41 C7 03 00 00 00 00\",\n    enabled = false,\n    when = {\n        { \"rdx:u\", \"\u003c\", \"[rbx+0x10].u64\" },\n        { \"[rbx+0x10].i64\", \">=\", threshold(mode) },\n    },\n    set = { { \"rax\", \"set\", \"r11\" } },\n    jump = 7,\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal failed, changed, last_hits = false, false, 0\nlocal function fail(reason)\n    failed = true\n    local removed, remove_reason = rule:remove()\n    if not removed then log(\"removal failed: \" .. tostring(remove_reason)) end\n    log(\"off: \" .. tostring(reason))\nend\n\nlocal function use_mode(next_mode)\n    if failed then return end\n    -- Pause first so a mode change cannot briefly use the old threshold.\n    local ok, reason = rule:enable(false)\n    if not ok then return fail(reason) end\n    if next_mode ~= 0 then\n        ok, reason = rule:when(2, threshold(next_mode))\n        if not ok then return fail(reason) end\n        ok, reason = rule:enable(true)\n        if not ok then return fail(reason) end\n    end\n    mode = next_mode\n    changed = true\nend\n\nlocal ok, key_error = pcall(bsx.hotkey, \"ctrl+alt+f6\", function()\n    use_mode((mode + 1) % 3)\nend)\nif not ok then return fail(\"hotkey: \" .. tostring(key_error)) end\nuse_mode(mode)\nif failed then return end\nlog(\"ready: mode \" .. mode .. \" (\" .. names[mode] .. \"); Ctrl+Alt+F6 cycles modes\")\nchanged = false\n\nlocal function report()\n    if failed then return end\n    local hits, reason = rule:hits()\n    if hits == nil then return fail(reason) end\n    if changed or hits ~= last_hits then\n        log(\"mode \" .. mode .. \" (\" .. names[mode] .. \"); skipped stores so far: \" .. tostring(hits))\n        changed, last_hits = false, hits\n    end\n    local scheduled, err = pcall(bsx.after, 10000, report)\n    if not scheduled then return fail(\"hit report stopped: \" .. tostring(err)) end\nend\nlocal scheduled, err = pcall(bsx.after, 10000, report)\nif not scheduled then return fail(\"hit report unavailable: \" .. tostring(err)) end\n","lang":"lua","name":"main.lua"},{"code":"[InfiniteItemsExact]\n; 0 = off, 1 = keep quantities above one, 2 = keep every unsigned decrease.\n; Ctrl+Alt+F6 cycles these modes.\nMode=0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Infinite items exact\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"ItemValue::AdjustAmountStore\"]\n}\n","lang":"json","name":"script.json"}],"id":"infinite_items_exact","kind":"lua","lua_api":3,"path":"bsx/lua/examples/infinite_items_exact","tier":"safe","title":"Infinite items exact","uses":[]},{"category":"World, Time & Exploration","description":"Instant Interact: hold-to-interact prompts finish at once (or after a fixed time). Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/recipes/r1-interact.md. Not yet tested in game.  ","featured":false,"files":[{"code":"-- Instant Interact: hold-to-interact prompts finish at once (or after a fixed time).\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r1-interact.md. Not yet tested in game.\n--\n-- The game picks a hold time and stores it into the prompt button at two places.\n-- Just before each store, the time is the low float of XMM0, so one rule per\n-- place replaces it. Every button that reaches these two places is affected.\nlocal SITES = {\n    \"KeyGuideButton::InteractionHoldStore\",  -- when a prompt is set up\n    \"InteractionUi::RefreshHoldStore\",       -- when the prompt list refreshes\n}\n-- vmovss [rbx+disp32],xmm0; the button offset is 0x1D8 on 2976 and 0x1C8 later.\nlocal STORE = \"C5 FA 11 83 ?? 01 00 00\"\n\nlocal function log(message) bsx.log(\"instant_interact: \" .. message) end\n\nlocal seconds = config.float(\"InstantInteract\", \"Duration\", 0.0)\nif not (seconds >= 0 and seconds \u003c= 3.4e38) then\n    return log(\"off: Duration must be 0 or more\")\nend\n\nlocal rules = {}\nlocal function remove_all()\n    for _, rule in ipairs(rules) do rule:remove() end\n    rules = {}\nend\n\nlocal function install()\n    for _, site in ipairs(SITES) do\n        local rule, why = cdal.rule(site, {\n            expect = STORE,\n            set = { {\"xmm0.f32\", \"set\", seconds} },\n        })\n        if not rule then\n            remove_all()  -- both places or neither\n            log(\"off: \" .. site .. \": \" .. tostring(why))\n            return false\n        end\n        rules[#rules + 1] = rule\n    end\n    log(\"on: hold time \" .. seconds .. \" s; Ctrl+Shift+F3 toggles\")\n    return true\nend\n\nlocal function set_enabled(on)\n    for _, rule in ipairs(rules) do rule:enable(on) end\n    log(on and \"on\" or \"off (prompts already shown keep their time until refreshed)\")\nend\n\nif config.bool(\"InstantInteract\", \"Enabled\", true) then\n    if not install() then return end\nelse\n    log(\"off; Ctrl+Shift+F3 turns it on\")\nend\n\n-- pcall: without the hotkey service the rules still work, just without a toggle.\nlocal ok, why = pcall(bsx.hotkey, \"ctrl+shift+f3\", function()\n    if #rules == 0 then install()\n    else set_enabled(not rules[1]:active()) end\nend)\nif not ok then log(\"no toggle key: \" .. tostring(why)) end\n\n-- hits() counts how often the game ran each rule: proof in game that it is reached.\nlocal function report()\n    if #rules == 2 then\n        log(\"hits: setup=\" .. rules[1]:hits() .. \", refresh=\" .. rules[2]:hits())\n    end\n    bsx.after(60000, report)\nend\nbsx.after(10000, report)\n","lang":"lua","name":"main.lua"},{"code":"[InstantInteract]\n; 0 is instant. A positive value replaces the duration; it is not a multiplier.\nDuration=0.0\nEnabled=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Instant Interact\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"KeyGuideButton::InteractionHoldStore\",\n    \"InteractionUi::RefreshHoldStore\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"instant_interact","kind":"lua","lua_api":3,"path":"bsx/lua/examples/instant_interact","tier":"safe","title":"Instant Interact","uses":[]},{"category":"BSX Core & Diagnostics","description":"No changes permission. The queue contains copied text, never game pointers.","featured":false,"files":[{"code":"-- No changes permission. The queue contains copied text, never game pointers.\nlocal lines, next_line\nlocal function flush()\n    if not lines then return end\n    bsx.log(lines[next_line])\n    next_line = next_line + 1\n    if next_line > #lines then lines = nil else bsx.after(250, flush) end\nend\nbsx.hotkey(\"ctrl+shift+f9\", function()\n    if lines then return end\n    local items, why = game.inventory.list(50)\n    if not items then bsx.log(\"inventory_dump: \" .. tostring(why)); return end\n    lines, next_line = {}, 1\n    for i, item in ipairs(items) do\n        lines[i] = \"inventory_dump: bucket=\" .. item.bucket .. \" index=\" .. item.index\n            .. \" row=\" .. item.row .. \" count=\" .. item.count\n            .. \" instance=\" .. (item.instance_id or \"unassigned\")\n            .. ((i == #items and items.truncated) and \" (truncated at 50)\" or \"\")\n    end\n    if #lines == 0 then lines[1] = \"inventory_dump: empty\" end\n    flush()\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Inventory dump\",\n  \"version\": \"1\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\",\n    \"pa::ClientNormalInGameActor::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Key\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"ActorComponents::Equipment\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"InventoryBucket::Tag\",\n    \"InventoryItem::ItemNo\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"inventory_dump","kind":"lua","lua_api":3,"path":"bsx/lua/examples/inventory_dump","tier":"safe","title":"Inventory dump","uses":[]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Scale positive ItemValue adjustments. Its relationship to Player Status Modifier's item-gain hook is unconfirmed; no in-game test was run. Native approval","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Scale positive ItemValue adjustments. Its relationship to Player Status\n-- Modifier's item-gain hook is unconfirmed; no in-game test was run.\n-- Native approval is required.\n-- This is GLOBAL and includes transfers. It does not cover empty-slot copies.\nlocal function log(message) bsx.log(\"item_gain_factor: \" .. message) end\nlocal SITE = \"ItemValue::AdjustAmount\"\nlocal EXPECT = \"40 53 48 83 EC 50 48 B8 00 00 00 00 00 00 00 80\"\n\nlocal status = cdal.status(SITE)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. SITE .. \": \" .. tostring(status))\nend\nlocal factor = config.float(\"ItemGainFactor\", \"Factor\", 2)\nif not (factor >= 0 and factor \u003c= 100) then\n    return log(\"off: Factor must be between 0 and 100\")\nend\n\n-- R8 is the signed change. Ignore negative and zero changes and amounts\n-- above one billion. The original native range checks run after this rule.\nlocal rule, why = cdal.rule(SITE, {\n    expect = EXPECT, enabled = false,\n    when = {{\"r8\", \">\", 0}, {\"r8\", \"\u003c=\", 1000000000}},\n    set = {{\"r8\", \"mul\", factor}},\n})\nif not rule then return log(\"off: \" .. SITE .. \": \" .. tostring(why)) end\n\nlocal live, on = true, false\nlocal function remove_rule()\n    live = false\n    local removed, reason = rule:remove()\n    if not removed then log(\"could not remove rule: \" .. tostring(reason)) end\nend\nlocal function toggle()\n    if not live then return end\n    local changed, reason = rule:enable(not on)\n    if not changed then\n        remove_rule()\n        on = false\n        return log(\"off: cannot change rule: \" .. tostring(reason))\n    end\n    on = not on\n    log(on and \"on: positive adjustments change globally, including transfers\" or \"off\")\nend\n\nlocal chord = config.string(\"ItemGainFactor\", \"Hotkey\", \"ctrl+alt+f11\")\nlocal ok\nok, why = pcall(bsx.hotkey, chord, toggle)\nif not ok then\n    remove_rule()\n    return log(\"off: hotkey unavailable: \" .. tostring(why))\nend\nlog(\"off; \" .. chord .. \" toggles positive item adjustments\")\n\n-- A hit is a matching adjustment, not proof of a completed inventory change.\nlocal last = 0\nlocal function report()\n    if not live then return end\n    local count, reason = rule:hits()\n    if count == nil then\n        remove_rule()\n        return log(\"off: hit counter unavailable: \" .. tostring(reason))\n    end\n    if count ~= last then log(\"rule hits: \" .. count); last = count end\n    local scheduled, failure = pcall(bsx.after, 10000, report)\n    if not scheduled then\n        remove_rule()\n        log(\"off: hit reporting unavailable: \" .. tostring(failure))\n    end\nend\nok, why = pcall(bsx.after, 10000, report)\nif not ok then\n    remove_rule()\n    return log(\"off: hit reporting unavailable: \" .. tostring(why))\nend\n","lang":"lua","name":"main.lua"},{"code":"; Affects positive adjustments for every actor and container, including transfers.\n; See bsx/lua/recipes/r4-stamina.md before using this untested preview.\n[ItemGainFactor]\nFactor=2\nHotkey=ctrl+alt+f11\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Item Gain Factor\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"ItemValue::AdjustAmount\"]\n}\n","lang":"json","name":"script.json"}],"id":"item_gain_factor","kind":"lua","lua_api":3,"path":"bsx/lua/examples/item_gain_factor","tier":"safe","title":"Item Gain Factor","uses":[]},{"category":"Items & Inventory","description":"Copy this folder to BSX/scripts/item_tracker and choose an exact row in settings.ini. Lines go to BSX/bsx.log. These helpers read the controlled character's own inventory.","featured":false,"files":[{"code":"-- Copy this folder to BSX/scripts/item_tracker and choose an exact row in settings.ini.\n-- Lines go to BSX/bsx.log. These helpers read the controlled character's own inventory.\n\nlocal row = config.int(\"ItemTracker\", \"ItemRow\", -1)\nlocal interval = config.int(\"ItemTracker\", \"IntervalMs\", 5000)\nlocal last_count, last_error = nil, nil\n\nif interval \u003c 1000 or interval > 86400000 then\n    bsx.log(\"item tracker: IntervalMs must be 1000..86400000; using 5000\")\n    interval = 5000\nend\n\nlocal function check_count()\n    -- Counts are decimal strings, so even very large counts stay exact.\n    local count, why = game.inventory.count(row)\n    if count == nil then\n        local message = tostring(why)\n        if message ~= last_error and bsx.log(\"item tracker: count unavailable (\" .. message .. \")\") then\n            last_error = message\n        end\n        return\n    end\n    last_error = nil\n    if count == last_count then return end\n\n    -- A cached name may be unavailable even when the count was read successfully.\n    local name, name_why = game.item_name(row)\n    if name == nil then name = \"name unavailable: \" .. tostring(name_why) end\n    if bsx.log(\"item tracker: row \" .. row .. \" (\" .. name .. \") count \" .. count) then\n        last_count = count\n    end\nend\n\nlocal function poll()\n    check_count()\n    bsx.after(interval, poll)\nend\n\nif row \u003c 0 or row > 65534 then\n    bsx.log(\"item tracker: set ItemRow in settings.ini to an exact item row from 0 to 65534\")\nelse\n    -- Completion events can be unavailable on a build. Keep the timer and other events working.\n    for _, event in ipairs({\"save_loaded\", \"equip_applied\", \"unequip_applied\"}) do\n        local ok, why = pcall(bsx.on, event, check_count)\n        if not ok then bsx.log(\"item tracker: \" .. event .. \" unavailable (\" .. tostring(why) .. \")\") end\n    end\n    -- Polling also finds changes unrelated to equipment and handles a save loaded before startup.\n    bsx.after(interval, poll)\nend\n","lang":"lua","name":"main.lua"},{"code":"[ItemTracker]\n; The exact item row to track, 0..65534. -1 (the default) tracks nothing.\n; game.item_info and the smoke example's name search help find a row.\nItemRow=-1\n; Also check periodically, including when a save was loaded before this script started.\nIntervalMs=5000\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Item Tracker\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"ItemInfoManager::sInstance\",\n    \"pa::ItemInfoManager::vftable\",\n    \"ItemInfoManager::sEmptyRow\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::Key\",\n    \"DefinitionRow::InternalName\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"item_tracker","kind":"lua","lua_api":3,"path":"bsx/lua/examples/item_tracker","tier":"safe","title":"Item Tracker","uses":[]},{"category":"UI & Overlays","description":"Copy this folder to BSX/scripts/key_echo to find Windows virtual key codes in BSX/bsx.log. The modifier mask is Ctrl=1, Alt=2, Shift=4, Win=8. It is not text input. With [BSX] Gamepad=1 controller buttons are logged too,","featured":false,"files":[{"code":"-- Copy this folder to BSX/scripts/key_echo to find Windows virtual key codes in BSX/bsx.log.\n-- The modifier mask is Ctrl=1, Alt=2, Shift=4, Win=8. It is not text input. With [BSX] Gamepad=1\n-- controller buttons are logged too, with their controller number.\n\nlocal listening = true\nlocal function on_key(e)\n    if not listening then return end\n    if e.virtual_key == 0 then\n        -- This marker means focus or queue state was reset, not a key press.\n        bsx.log(\"key echo: reset marker\")\n    elseif e.down and not e[\"repeat\"] and not e.reset then\n        if e.gamepad then\n            bsx.log(\"key echo: controller \" .. e.scan_code .. \" button, virtual key \" .. e.virtual_key)\n        else\n            bsx.log(\"key echo: virtual key \" .. e.virtual_key .. \", modifiers \" .. e.modifiers)\n        end\n    end\nend\n\n-- Return nil and the reason when key events are unavailable, rather than switching off.\nlocal function listen()\n    local ok, why = pcall(bsx.on, \"key\", on_key)\n    if not ok then return nil, why end\n    return true\nend\n\nlocal started, why = listen()\nif not started then\n    bsx.log(\"key echo: key events unavailable (\" .. tostring(why) .. \")\")\nelse\n    bsx.log(\"key echo: listening for 30 seconds\")\n    bsx.after(30000, function()\n        -- Lua has no per-callback unsubscribe; ignore further keys until stop or reload.\n        listening = false\n        bsx.log(\"key echo: finished\")\n    end)\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Key Echo\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": []\n}\n","lang":"json","name":"script.json"}],"id":"key_echo","kind":"lua","lua_api":3,"path":"bsx/lua/examples/key_echo","tier":"safe","title":"Key Echo","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Preview of Sandevistan's older, non-smooth horizontal compensation mode. Native approval gives this script full process trust. It affects EVERY body reach","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Preview of Sandevistan's older, non-smooth horizontal compensation mode.\n-- Native approval gives this script full process trust. It affects EVERY body\n-- reaching this instruction, including NPCs; it does not identify the player.\n-- It does not slow time. Read bsx/lua/recipes/r6-combat.md before enabling it.\nlocal function log(message) bsx.log(\"legacy_motion_compensation: \" .. message) end\n\nlocal scale = config.float(\"LegacyMotionCompensation\", \"TimeScale\", 0.4)\nlocal strength = config.float(\"LegacyMotionCompensation\", \"Strength\", 1.0)\nlocal maximum = config.float(\"LegacyMotionCompensation\", \"MaxFactor\", 8.0)\nif not (scale >= 0.05 and scale \u003c= 1) then return log(\"off: TimeScale must be 0.05 to 1\") end\nif not (strength >= 0 and strength \u003c= 2) then return log(\"off: Strength must be 0 to 2\") end\nif not (maximum >= 1 and maximum \u003c= 20) then return log(\"off: MaxFactor must be 1 to 20\") end\n\n-- In the old mode, factor = min(maximum, max(1, 1 + (1 / scale - 1) * strength)).\n-- This is fixed at startup: choose the actual steady scale, not an easing target.\nlocal factor = math.min(maximum, math.max(1, 1 + (1 / scale - 1) * strength))\nlocal rule, why = cdal.rule(\"PhysicsBody::IntegratePosition_Delta\", {\n    expect = \"41 0F 58 45 00 41 0F 11 45 00\", -- add the delta; store the position\n    enabled = false,\n    set = {\n        {\"xmm0.f32[0]\", \"mul\", factor}, -- X; lane 1 (vertical) is unchanged\n        {\"xmm0.f32[2]\", \"mul\", factor}, -- Z; lane 3 is unchanged\n    },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal on, alive, changed, last_hits = false, true, false, 0\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, error_text = rule:remove()\n    if not removed then log(\"removal failed: \" .. tostring(error_text)) end\n    log(\"off: \" .. reason)\nend\n\nlocal bound, key_error = pcall(bsx.hotkey, \"ctrl+shift+numpad6\", function()\n    if not alive then return end\n    local ok, reason = rule:enable(not on)\n    if not ok then return stop(\"toggle failed: \" .. tostring(reason)) end\n    on, changed = not on, true\nend)\nif not bound then return stop(\"hotkey unavailable: \" .. tostring(key_error)) end\n\n-- Report state and executions at most once per ten seconds, never on a hook.\n-- A hit is an execution, not proof of safe physics or player identification.\nlocal function report()\n    if not alive then return end\n    local hits, reason = rule:hits()\n    if hits == nil then return stop(\"hit count unavailable: \" .. tostring(reason)) end\n    if changed or hits ~= last_hits then\n        log((on and \"on\" or \"paused\") .. \"; all bodies; executions=\" .. tostring(hits))\n        last_hits, changed = hits, false\n    end\n    local scheduled, schedule_error = pcall(bsx.after, 10000, report)\n    if not scheduled then stop(\"timer unavailable: \" .. tostring(schedule_error)) end\nend\nlocal scheduled, schedule_error = pcall(bsx.after, 10000, report)\nif not scheduled then return stop(\"timer unavailable: \" .. tostring(schedule_error)) end\nlog(string.format(\"ready: paused; Ctrl+Shift+Numpad6 toggles x%.3f for all bodies\", factor))\n","lang":"lua","name":"main.lua"},{"code":"[LegacyMotionCompensation]\n; Set this to the steady world scale used by your separate slow-motion script.\n; This example does not slow the world or follow a changing scale automatically.\nTimeScale=0.4\n; Strength is 0 to 2; MaxFactor is 1 to 20. See the combat recipe for scope.\nStrength=1.0\nMaxFactor=8.0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Legacy Motion Compensation\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"PhysicsBody::IntegratePosition_Delta\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"legacy_motion_compensation","kind":"lua","lua_api":3,"path":"bsx/lua/examples/legacy_motion_compensation","tier":"safe","title":"Legacy Motion Compensation","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Partial Map Marker Teleport protection edit. It does not teleport. Native approval is required. This global edit is not tested in game.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Partial Map Marker Teleport protection edit. It does not teleport.\n-- Native approval is required. This global edit is not tested in game.\nlocal function log(message) bsx.log(\"marker_guard_window: \" .. message) end\nlocal seconds = config.float(\"MarkerGuardWindow\", \"WindowSeconds\", 10)\nlocal report_seconds = config.int(\"MarkerGuardWindow\", \"ReportSeconds\", 10)\nif not (seconds >= 0.5 and seconds \u003c= 30) then return log(\"off: WindowSeconds must be 0.5 to 30\") end\nif report_seconds \u003c 10 or report_seconds > 600 then return log(\"off: ReportSeconds must be 10 to 600\") end\n\n-- The rule's tick operand uses the Windows uptime clock. Read the same clock\n-- only on FRAME, so the rule expires on time even if FRAME pauses during load.\n-- This calls Windows, not a game function; it does not check code bytes with FFI.\nlocal loaded, clock = pcall(function()\n    ffi.cdef[[unsigned long long GetTickCount64(void);]]\n    return ffi.load(\"kernel32.dll\")\nend)\nif not loaded then return log(\"off: Windows clock unavailable: \" .. tostring(clock)) end\n\nlocal rule, why = cdal.rule(\"StatEntry::ApplyDelta_PostWrite\", {\n    expect = \"48 8B 46 08\",\n    enabled = false,\n    when = { {\"[rsi+0x0].u8\", \"==\", 0}, {\"tick\", \"\u003c\", \"$0.u64\"} },\n    set = { {\"[rsi+0x8].u64\", \"set\", \"[rsi+0x18].u64\"} },\n})\nif not rule then return log(\"off: stat-entry rule: \" .. tostring(why)) end\n\nlocal alive, open, generation = true, false, 0\nlocal pending, last_hits = nil, 0\nlocal function stop(reason)\n    if not alive then return end\n    alive, open = false, false\n    generation = generation + 1\n    local removed, remove_error = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(remove_error) end\n    pending = \"off: \" .. reason\nend\n\n-- All status and hit messages after startup are combined into one report,\n-- at most once per ReportSeconds. A failure still removes the rule immediately.\nlocal function report()\n    if alive then\n        local hits, hit_error = rule:hits()\n        if hits == nil then stop(\"hit count unavailable: \" .. tostring(hit_error)) end\n        if alive then\n            local scheduled, timer_error = pcall(bsx.after, report_seconds * 1000, report)\n            if not scheduled then stop(\"report timer unavailable: \" .. tostring(timer_error)) end\n        end\n        if alive and (open or hits > last_hits) then\n            pending = (pending and (pending .. \"; \") or \"\") .. \"hits=\" .. tostring(hits)\n        end\n        if alive then last_hits = hits end\n    end\n    if pending then log(pending); pending = nil end\nend\n\nlocal registered, hotkey_error = pcall(bsx.hotkey, \"ctrl+alt+numpad9\", function()\n    if not alive then return end\n    generation = generation + 1\n    if open then\n        local changed, error_text = rule:enable(false)\n        if not changed then return stop(\"pause failed: \" .. tostring(error_text)) end\n        open = false\n        pending = \"window closed\"\n        return\n    end\n    local clock_ok, now = pcall(function() return tonumber(clock.GetTickCount64()) end)\n    if not clock_ok or type(now) ~= \"number\" then return stop(\"Windows clock failed: \" .. tostring(now)) end\n    local duration = math.floor(seconds * 1000)\n    local stored, cell_error = cdal.set_cell(0, now + duration, \"u64\")\n    if not stored then return stop(\"deadline unavailable: \" .. tostring(cell_error)) end\n    local mine = generation\n    local scheduled, timer_error = pcall(bsx.after, duration, function()\n        if not alive or mine ~= generation or not open then return end\n        local changed, error_text = rule:enable(false)\n        if not changed then return stop(\"expiry cleanup failed: \" .. tostring(error_text)) end\n        open = false\n        pending = \"window expired\"\n    end)\n    if not scheduled then return stop(\"window timer unavailable: \" .. tostring(timer_error)) end\n    local changed, enable_error = rule:enable(true)\n    if not changed then return stop(\"enable failed: \" .. tostring(enable_error)) end\n    open = true\n    pending = \"window open; all matching actors may be affected\"\nend)\nif not registered then\n    stop(\"hotkey unavailable: \" .. tostring(hotkey_error))\n    log(pending)\n    return\nend\nlocal scheduled, timer_error = pcall(bsx.after, report_seconds * 1000, report)\nif not scheduled then\n    stop(\"report timer unavailable: \" .. tostring(timer_error))\n    log(pending)\n    return\nend\nlog(\"ready: ctrl+alt+numpad9 opens a manual global window; no teleport\")\n","lang":"lua","name":"main.lua"},{"code":"[MarkerGuardWindow]\n; This is a manual, global stat-entry edit, not a teleport or a promise of\n; invulnerability. It affects every matching actor and may alter other stats.\n; Press Ctrl+Alt+Numpad9 to open or close the window.\nWindowSeconds=10\nReportSeconds=10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Marker Guard Window\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"StatEntry::ApplyDelta_PostWrite\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"marker_guard_window","kind":"lua","lua_api":3,"path":"bsx/lua/examples/marker_guard_window","tier":"safe","title":"Marker Guard Window","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Observes changed map markers. It does not teleport or write game memory. Requires Native approval; not tested in game. Samples are informational.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Observes changed map markers. It does not teleport or write game memory.\n-- Requires Native approval; not tested in game. Samples are informational.\nlocal function log(message) bsx.log(\"marker_observer: \" .. message) end\n\nlocal interval = config.int(\"MarkerObserver\", \"ReportSeconds\", 10)\nif interval \u003c 10 or interval > 600 then return log(\"off: ReportSeconds must be 10 to 600\") end\n\n-- At this ID, RDX points to three float32 marker coordinates. The game's\n-- own instruction and the following copy are unchanged. Every source read\n-- is guarded by the rule engine. Self-comparisons also reject NaNs.\n-- $3 counts started copies and $4 finished ones: a sample read while the\n-- two differ is half-written, so the reader below skips it. This holds while\n-- one game thread changes markers at a time. Read all three into call-local\n-- scratch first: a failed later read must not publish a partial sample.\nlocal rule, why = cdal.rule(\"Map::SetDestinationMarker_Changed\", {\n    expect = \"48 83 79 28 00 C5 FB 10 02\",\n    enabled = false,\n    stop_on_failure = true,\n    when = {\n        {\"[rdx+0x0].f32\", \"==\", \"[rdx+0x0].f32\"},\n        {\"[rdx+0x4].f32\", \"==\", \"[rdx+0x4].f32\"},\n        {\"[rdx+0x8].f32\", \"==\", \"[rdx+0x8].f32\"},\n    },\n    set = {\n        {\"%0.f32\", \"set\", \"[rdx+0x0].f32\"},\n        {\"%1.f32\", \"set\", \"[rdx+0x4].f32\"},\n        {\"%2.f32\", \"set\", \"[rdx+0x8].f32\"},\n        {\"$3.u64\", \"add\", 1},\n        {\"$0.f32\", \"set\", \"%0.f32\"},\n        {\"$1.f32\", \"set\", \"%1.f32\"},\n        {\"$2.f32\", \"set\", \"%2.f32\"},\n        {\"$4.u64\", \"set\", \"$3.u64\"},\n    },\n})\nif not rule then return log(\"off: marker rule: \" .. tostring(why)) end\n\nlocal on, alive, last_hits, last_sample = false, true, 0, 0\nlocal function stop_rule(reason)\n    if not alive then return end\n    alive = false\n    local removed, error_text = rule:remove()\n    if not removed then log(\"remove failed: \" .. tostring(error_text)) end\n    log(\"off: \" .. reason)\nend\n\nlocal chord = config.string(\"MarkerObserver\", \"Hotkey\", \"ctrl+alt+numpad7\")\nlocal registered, error_text = pcall(bsx.hotkey, chord, function()\n    if not alive then return end\n    local changed, reason = rule:enable(not on)\n    if not changed then return stop_rule(\"toggle failed: \" .. tostring(reason)) end\n    on = not on\n    log(on and \"sampling changed markers\" or \"paused\")\nend)\nif not registered then return stop_rule(\"hotkey unavailable: \" .. tostring(error_text)) end\n\nlocal function finite(value)\n    return type(value) == \"number\" and value == value and math.abs(value) \u003c math.huge\nend\n-- One consistent X, Y, Z: read \"finished\", the three values, then \"started\".\n-- Equal counts mean no copy ran in between. Returns nil after three tries,\n-- or false and a reason when a cell cannot be read.\nlocal function sample()\n    for _ = 1, 3 do\n        local done, why = cdal.cell(4, \"u64\")\n        if done == nil then return false, why end\n        local x = cdal.cell(0, \"f32\")\n        local y = cdal.cell(1, \"f32\")\n        local z = cdal.cell(2, \"f32\")\n        local started = cdal.cell(3, \"u64\")\n        if x == nil or y == nil or z == nil or started == nil then return false, \"read failed\" end\n        if started == done then return x, y, z, done end\n    end\n    return nil\nend\nlocal function report()\n    if not alive then return end\n    local hits, reason = rule:hits()\n    if hits == nil then return stop_rule(\"hit count unavailable: \" .. tostring(reason)) end\n    if on and hits > last_hits then\n        local x, y, z, generation = sample()\n        if x == false then return stop_rule(\"cell unavailable: \" .. tostring(y)) end\n        if x == nil then\n            log(\"sample skipped: the marker was changing; hits=\" .. tostring(hits))\n        elseif generation == 0 or generation == last_sample then\n            log(\"sample skipped: no new complete copy; hits=\" .. tostring(hits))\n        elseif finite(x) and finite(y) and finite(z) then\n            log(string.format(\"sample XYZ=(%.3f, %.3f, %.3f); hits=%d\", x, y, z, hits))\n            last_sample = generation\n        else\n            log(\"sample ignored: a coordinate is not finite; hits=\" .. tostring(hits))\n        end\n    end\n    last_hits = hits\n    local scheduled, schedule_error = pcall(bsx.after, interval * 1000, report)\n    if not scheduled then stop_rule(\"timer unavailable: \" .. tostring(schedule_error)) end\nend\n\nlocal scheduled, schedule_error = pcall(bsx.after, interval * 1000, report)\nif not scheduled then return stop_rule(\"timer unavailable: \" .. tostring(schedule_error)) end\nlog(\"ready: \" .. chord .. \" starts sampling; no character will move\")\n","lang":"lua","name":"main.lua"},{"code":"[MarkerObserver]\n; Observation only: this does not move a character or start travel.\n; Press to start or pause sampling changed map-marker positions.\nHotkey=ctrl+alt+numpad7\n; Log the most recent sample and hit count no more than once per 10 seconds.\nReportSeconds=10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Marker Observer\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"Map::SetDestinationMarker_Changed\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"marker_observer","kind":"lua","lua_api":3,"path":"bsx/lua/examples/marker_observer","tier":"safe","title":"Marker Observer","uses":[]},{"category":"UI & Overlays","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 First eligible, non-neutral descriptor after the game's getter returns. Native approval is required; see r6-combat.md. No in-game test has run.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- First eligible, non-neutral descriptor after the game's getter returns.\n-- Native approval is required; see r6-combat.md. No in-game test has run.\nlocal function log(s) bsx.log(\"menu_first_descriptor: \" .. s) end\nlocal site = \"UiControlManager::GetMenuTimeScale\"\nlocal phase = \"UIGamePlayControl::Phase\"\nlocal speed_field = \"UiControlDescriptor::RequestedTimeScale\"\nlocal link_field = \"UiControl::DescriptorLink\"\nlocal required = {site, phase, speed_field, link_field}\nlocal target = config.float(\"MenuFirstDescriptor\", \"Speed\", 0.3)\nif not (target > 0.001 and target \u003c 0.99) then\n    return log(\"off: Speed must be between 0.001 and 0.99\")\nend\n\n-- These are CDAL metadata calls, not calls into the game. In particular, a\n-- scan result is not enough to approve this layout on an unknown build.\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    for _, name in ipairs(required) do\n        local id = lib.cdal_id_by_name(name)\n        if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. name) end\n    end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\nlocal state, state_why = cdal.value(\"UIGamePlayControl::Phase\")\nif state == nil then return log(\"off: \" .. phase .. \": \" .. tostring(state_why)) end\nlocal speed, speed_why = cdal.value(\"UiControlDescriptor::RequestedTimeScale\")\nif speed == nil then return log(\"off: \" .. speed_field .. \": \" .. tostring(speed_why)) end\nlocal link, link_why = cdal.value(\"UiControl::DescriptorLink\")\nif link == nil then return log(\"off: \" .. link_field .. \": \" .. tostring(link_why)) end\n-- The site and both complete layouts have been checked on all seven images.\nif not ((state == 0x26F and speed == 0x23C and link == 0x10) or\n        (state == 0x281 and speed == 0x24C and link == 0x28)) then\n    return log(\"off: unrecognized control layout\")\nend\n\nlocal entry = \"48 89 5C 24 08 48 89 6C 24 10 48 89 74 24 18 48 89 7C 24 20\"\nlocal pointer = string.format(\"[[[@]+0xA0]+0x%X].u64\", link)\nlocal state_value = string.format(\"[rax+0x%X].u8\", state)\nlocal speed_value = string.format(\"[rax+0x%X].f32\", speed)\n\n-- The first installed function rule is the outer wrapper in CDAL's\n-- equal-priority chain. It saves this thread's previous value per invocation,\n-- initializes it, then checks the value supplied by the inner rule after the\n-- native getter returns. Restore the previous value before any check step.\nlocal outer, err = cdal.rule(site, {\n    after = true, enabled = false, expect = entry, stop_on_failure = true,\n    before = {{\"%0.f32\", \"set\", \"^1.f32\"}, {\"^1.f32\", \"set\", 1}},\n    set = {\n        {\"%1.f32\", \"set\", \"^1.f32\"}, {\"^1.f32\", \"set\", \"%0.f32\"},\n        {\"xmm0.f32\", \">\", 0}, {\"xmm0.f32\", \"\u003c\", 0.999},\n        {\"%1.f32\", \"sub\", \"xmm0.f32\"}, {\"%1.f32\", \"mul\", \"%1.f32\"},\n        {\"%1.f32\", \"\u003c\", 0.00000001},\n        {\"%2.f32\", \"set\", target}, {\"%2.f32\", \"sub\", \"xmm0.f32\"},\n        {\"%2.f32\", \"mul\", \"%2.f32\"}, {\"%2.f32\", \"\u003c\", 0.00000001},\n        {\"xmm0.f32\", \"set\", 0},\n    },\n})\nif not outer then return log(\"off: wrapper: \" .. tostring(err)) end\n\n-- The list is an array of pointers, not an array of descriptors. The rule\n-- saves and restores RAX around the deeper guarded pointer walk. Failed reads\n-- leave the sentinel state/speed values, so that element is skipped. Keeping\n-- stop_on_failure off here is essential: RAX must always be restored.\nlocal inner\ninner, err = cdal.rule(site, {\n    after = true, enabled = false, expect = entry,\n    each = {list = \"[[rcx+0x38]+0].u64\", count = \"[[rcx+0x38]+8].u32\",\n        stride = 8, max = 1024,\n        set = {\n            {\"^1.f32\", \"==\", 1},\n            {pointer, \"~=\", 0},\n            {\"%7.u64\", \"set\", \"rax:u\"}, {\"rax:u\", \"set\", 0},\n            {\"rax:u\", \"set\", pointer},\n            {\"%6.u8\", \"set\", 255}, {\"%6.u8\", \"set\", state_value},\n            {\"%2.f32\", \"set\", 1}, {\"%2.f32\", \"set\", speed_value},\n            {\"rax:u\", \"set\", \"%7.u64\"},\n            {\"%6.u8\", \"\u003c=\", 1},\n            {\"%3.f32\", \"set\", \"%2.f32\"}, {\"%3.f32\", \"sub\", 1},\n            {\"%3.f32\", \"mul\", \"%3.f32\"}, {\"%3.f32\", \">\", 0.000000000001},\n            {\"^1.f32\", \"set\", \"%2.f32\"},\n        }},\n})\nif not inner then\n    local removed, problem = outer:remove()\n    return log(\"off: list rule: \" .. tostring(err) .. (removed and \"\" or \"; removal failed: \" .. tostring(problem)))\nend\n\nlocal live, on, pending = true, false, nil\nlocal function stop(reason)\n    live, on = false, false\n    local a, a_why = outer:remove()\n    local b, b_why = inner:remove()\n    local problem = \"menu_first_descriptor: off: \" .. tostring(reason)\n    if not a then problem = problem .. \"; wrapper removal failed: \" .. tostring(a_why) end\n    if not b then problem = problem .. \"; list removal failed: \" .. tostring(b_why) end\n    -- Lua cannot unregister one hotkey; an error stops the script so the host\n    -- removes its hotkey token and any remaining hooks before closing it.\n    error(problem, 0)\nend\nok, why = pcall(bsx.hotkey, \"ctrl+alt+shift+numpad1\", function()\n    if not live then return end\n    local next_on = not on\n    -- An enabled outer rule without a scan only sees the neutral sentinel;\n    -- an enabled inner rule alone never changes the function result.\n    local changed, problem = inner:enable(next_on)\n    if not changed then return stop(\"list toggle: \" .. tostring(problem)) end\n    changed, problem = outer:enable(next_on)\n    if not changed then return stop(\"wrapper toggle: \" .. tostring(problem)) end\n    on = next_on\n    pending = on and \"on\" or \"paused\"\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\n\nlocal function report()\n    if not live then return end\n    local hits, problem = inner:hits()\n    if hits == nil then stop(\"hit count: \" .. tostring(problem)) end\n    local scheduled, timer_error = pcall(bsx.after, 10000, report)\n    if not scheduled then stop(\"timer: \" .. tostring(timer_error)) end\n    log((pending or (on and \"on\" or \"paused\")) .. \"; getter calls=\" .. tostring(hits))\n    pending = nil\nend\nok, why = pcall(bsx.after, 10000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; Ctrl+Alt+Shift+Numpad1 toggles the global filter\")\n","lang":"lua","name":"main.lua"},{"code":"[MenuFirstDescriptor]\n; Only this one configured slowed speed is converted to a full pause.\nSpeed=0.3\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Menu First Descriptor\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"UiControlManager::GetMenuTimeScale\",\n    \"UIGamePlayControl::Phase\",\n    \"UiControlDescriptor::RequestedTimeScale\",\n    \"UiControl::DescriptorLink\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"menu_first_descriptor","kind":"lua","lua_api":3,"path":"bsx/lua/examples/menu_first_descriptor","tier":"safe","title":"Menu First Descriptor","uses":[]},{"category":"UI & Overlays","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Copy the game's second menu-speed sample to its smoothing field. This native-tier preview needs version 2 of cdal.rule's memory writes; see bsx/lua/recipe","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Copy the game's second menu-speed sample to its smoothing field.\n-- This native-tier preview needs version 2 of cdal.rule's memory writes;\n-- see bsx/lua/recipes/r6-combat.md for the differences and in-game checks.\nlocal function log(message) bsx.log(\"menu_instant_smoothing: \" .. message) end\n\n-- The field moves between builds. Read its offset from CDAL, not a fixed number.\nlocal offset, why = cdal.value(\"UiControlManager::SmoothedMenuTimeScale\")\nif offset == nil then return log(\"off: \" .. tostring(why)) end\nlocal field = string.format(\"[rbx+0x%X].f32\", offset)\n\n-- The rule starts off, so it cannot run between installation and our toggle.\n-- It runs before the checked vmovaps; XMM0 is the just-returned speed and\n-- RBX is the current UI owner. The host checks the destination before writing.\nlocal rule\nrule, why = cdal.rule(\"FrameTimer::MenuTimeScaleSample\", {\n    expect = \"C5 78 28 C0 C5 FA 10 B3 ?? ?? 03 00 C5 F8 2E C6\",\n    enabled = false,\n    set = { {field, \"set\", \"xmm0.f32\"} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal on = false\nlocal function set_enabled(next_value)\n    local ok, reason = rule:enable(next_value)\n    if not ok then log(\"toggle failed: \" .. tostring(reason)); return false end\n    on = next_value\n    log(on and \"on\" or \"off\")\n    return true\nend\n\nlocal ok, key_why = pcall(bsx.hotkey, \"ctrl+shift+numpad4\", function()\n    set_enabled(not on)\nend)\nif not ok then return log(\"off: hotkey unavailable: \" .. tostring(key_why)) end\nif config.bool(\"MenuInstantSmoothing\", \"Enabled\", false) then\n    if not set_enabled(true) then return end\nelse\n    log(\"off: Ctrl+Shift+Numpad4 toggles\")\nend\n\n-- A hit means the rule ran, not that a guarded memory write succeeded.\nlocal last_hits = 0\nlocal function report_hits()\n    local hits, reason = rule:hits()\n    if hits == nil then return log(\"hit count unavailable: \" .. tostring(reason)) end\n    if hits ~= last_hits then\n        log(\"rule executions: \" .. hits)\n        last_hits = hits\n    end\n    local scheduled, schedule_why = pcall(bsx.after, 10000, report_hits)\n    if not scheduled then log(\"hit reporting off: \" .. tostring(schedule_why)) end\nend\nlocal scheduled, schedule_why = pcall(bsx.after, 10000, report_hits)\nif not scheduled then log(\"hit reporting off: \" .. tostring(schedule_why)) end\n","lang":"lua","name":"main.lua"},{"code":"[MenuInstantSmoothing]\n; 1 starts with the smoothing edit on. Ctrl+Shift+Numpad4 toggles it.\nEnabled=0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Menu Instant Smoothing\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"FrameTimer::MenuTimeScaleSample\",\n    \"UiControlManager::SmoothedMenuTimeScale\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"menu_instant_smoothing","kind":"lua","lua_api":3,"path":"bsx/lua/examples/menu_instant_smoothing","tier":"safe","title":"Menu Instant Smoothing","uses":[]},{"category":"UI & Overlays","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Menu Pause: menus that only slow the game down pause it instead. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/r","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Menu Pause: menus that only slow the game down pause it instead.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r6-combat.md. Not yet tested in game.\n--\n-- The game asks the open menus for a time scale. Where it returns the answer,\n-- XMM0 holds the scale and RBP the menu's descriptor. When both say Speed,\n-- the rule returns 0 instead. Other speeds, and no menu at all, stay as they are.\nlocal function log(message) bsx.log(\"menu_pause: \" .. message) end\n\nlocal speed = config.float(\"MenuPause\", \"Speed\", 0.3)\nif not (speed > 0.001 and speed \u003c 0.99) then return log(\"off: Speed must be between 0.001 and 0.99\") end\nlocal near = 0.00005  -- float rounding\nlocal offset, offset_why = cdal.value(\"UiControlDescriptor::RequestedTimeScale\")  -- 0x23C on 2976, 0x24C later\nif not offset then return log(\"off: \" .. tostring(offset_why)) end\nlocal descriptor = string.format(\"[rbp+0x%X].f32\", offset)\n\nlocal rule, why = cdal.rule(\"UiControlManager::MenuTimeScaleResult\", {\n    expect = \"48 8B 5C 24 40 48 8B 6C 24 48\",  -- mov rbx,[rsp+40]; mov rbp,[rsp+48]\n    enabled = config.bool(\"MenuPause\", \"Enabled\", true),\n    when = { {\"xmm0.f32\", \">=\", speed - near}, {\"xmm0.f32\", \"\u003c=\", speed + near},\n             {descriptor, \">=\", speed - near}, {descriptor, \"\u003c=\", speed + near} },\n    set = { {\"xmm0.f32\", \"set\", 0} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal chord = config.string(\"MenuPause\", \"Hotkey\", \"ctrl+numpad5\")\nlocal ok, key_why = pcall(bsx.hotkey, chord, function()\n    rule:enable(not rule:active())\n    log((rule:active() and \"on\" or \"off\") .. \" (\" .. rule:hits() .. \" menu speeds changed so far)\")\nend)\nlog((rule:active() and \"on\" or \"off\") .. \": menus at speed \" .. speed .. \" pause the game; \"\n    .. (ok and chord .. \" toggles\" or \"no toggle key: \" .. tostring(key_why)))\n","lang":"lua","name":"main.lua"},{"code":"[MenuPause]\n; Menus that slow the game to this speed pause it fully instead. 0.3 is the\n; speed the game's slow-motion menus ask for (the Instant Menu Pause default).\nSpeed=0.3\nEnabled=1\nHotkey=ctrl+numpad5\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Menu Pause\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"UiControlManager::MenuTimeScaleResult\", \"UiControlDescriptor::RequestedTimeScale\"]\n}\n","lang":"json","name":"script.json"}],"id":"menu_pause","kind":"lua","lua_api":3,"path":"bsx/lua/examples/menu_pause","tier":"safe","title":"Menu Pause","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A global horizontal-multiplier preview with Mobility's direction guard. This affects NPCs and objects too; it does not read sprint/dodge input or implemen","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A global horizontal-multiplier preview with Mobility's direction guard.\n-- This affects NPCs and objects too; it does not read sprint/dodge input or\n-- implement jumps or landings. See r5-flight.md before enabling it.\nlocal function log(s) bsx.log(\"mobility_jitter_guard: \" .. s) end\nlocal factor = config.float(\"MobilityJitterGuard\", \"Factor\", 1.5)\nif not (factor >= 1 and factor \u003c= 10) then return log(\"off: Factor must be 1 to 10\") end\nlocal site = \"PhysicsBody::IntegratePosition_Write\"\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    local id = lib.cdal_id_by_name(site)\n    if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. site) end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\n\n-- The original direction cache has 16 records. Configure the table before\n-- installing any rules, and leave the feature off if the host refuses it.\nlocal called, configured, problem = pcall(cdal.table_rows, 0, 16)\nif not called then return log(\"off: table setup: \" .. tostring(configured)) end\nif not configured then return log(\"off: table setup: \" .. tostring(problem)) end\n\n-- XMM0 contains the proposed position; R13 points at the old position.\n-- Prepare both new lanes before changing the keyed record or either lane.\nlocal function actions(recent)\n    local a = {\n        {\"%0.f32\", \"set\", \"xmm0.f32[0]\"}, {\"%0.f32\", \"sub\", \"[r13].f32\"},\n        {\"%1.f32\", \"set\", \"xmm0.f32[2]\"}, {\"%1.f32\", \"sub\", \"[r13+8].f32\"},\n        {\"%2.f32\", \"set\", \"%0.f32\"}, {\"%2.f32\", \"mul\", \"%0.f32\"},\n        {\"%3.f32\", \"set\", \"%1.f32\"}, {\"%3.f32\", \"mul\", \"%1.f32\"},\n        {\"%2.f32\", \"add\", \"%3.f32\"}, {\"%2.f32\", \">\", 0.000025},\n    }\n    if recent then\n        a[#a+1] = {\"%2.f32\", \"set\", \"#0[r13].0.f32\"}\n        a[#a+1] = {\"%2.f32\", \"mul\", \"%0.f32\"}\n        a[#a+1] = {\"%3.f32\", \"set\", \"#0[r13].1.f32\"}\n        a[#a+1] = {\"%3.f32\", \"mul\", \"%1.f32\"}\n        a[#a+1] = {\"%2.f32\", \"add\", \"%3.f32\"} -- negative means a reversal\n    end\n    a[#a+1] = {\"%4.f32\", \"set\", \"%0.f32\"}\n    a[#a+1] = {\"%4.f32\", \"mul\", factor}\n    a[#a+1] = {\"%4.f32\", \"add\", \"[r13].f32\"}\n    a[#a+1] = {\"%5.f32\", \"set\", \"%1.f32\"}\n    a[#a+1] = {\"%5.f32\", \"mul\", factor}\n    a[#a+1] = {\"%5.f32\", \"add\", \"[r13+8].f32\"}\n    a[#a+1] = {\"#0[r13].0.f32\", \"set\", \"%0.f32\"}\n    a[#a+1] = {\"#0[r13].1.f32\", \"set\", \"%1.f32\"}\n    a[#a+1] = {\"#0[r13].2.u64\", \"set\", \"tick\"}\n    a[#a+1] = {\"#0[r13].2.u64\", \"add\", 250}\n    if recent then a[#a+1] = {\"%2.f32\", \">=\", 0} end\n    a[#a+1] = {\"xmm0.f32[0]\", \"set\", \"%4.f32\"}\n    a[#a+1] = {\"xmm0.f32[2]\", \"set\", \"%5.f32\"}\n    return a\nend\n\n-- Order matters: an existing recent row is handled first; its new deadline\n-- makes the expired rule skip. A new row is made only by the final rule.\n-- Each rule holds the same table's nonblocking lock through its whole action.\nlocal rules = {}\nlocal function install(conditions, recent)\n    local r, err = cdal.rule(site, {expect = \"41 0F 11 45 00\", enabled = false,\n        stop_on_failure = true, when = conditions, set = actions(recent)})\n    if r then rules[#rules+1] = r end\n    return r, err\nend\nlocal nonnull = {\"r13:u\", \">=\", 65536}\nlocal first, err = install({nonnull, {\"#0[r13].0\", \"present\"},\n    {\"tick\", \"\u003c\", \"#0[r13].2.u64\"}}, true)\nif first then first, err = install({nonnull, {\"#0[r13].0\", \"present\"},\n    {\"tick\", \">=\", \"#0[r13].2.u64\"}}, false) end\nif first then first, err = install({nonnull, {\"#0[r13].0\", \"absent\"}}, false) end\nif not first then\n    local message = \"off: \" .. tostring(err)\n    for _, r in ipairs(rules) do\n        local removed, problem = r:remove()\n        if not removed then error(\"mobility_jitter_guard: \" .. message .. \"; removal failed: \" .. tostring(problem), 0) end\n    end\n    return log(message)\nend\n\nlocal alive, on = true, false\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    for _, r in ipairs(rules) do\n        local removed, problem = r:remove()\n        if not removed then reason = reason .. \"; removal failed: \" .. tostring(problem) end\n    end\n    error(\"mobility_jitter_guard: off: \" .. reason, 0)\nend\nok, why = pcall(bsx.hotkey, \"ctrl+alt+shift+numpad6\", function()\n    if not alive then return end\n    local next_on = not on\n    for _, r in ipairs(rules) do\n        local changed, problem = r:enable(next_on)\n        if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    end\n    on = next_on\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\nlocal function report()\n    if not alive then return end\n    local total = 0\n    for _, r in ipairs(rules) do\n        local hits, problem = r:hits()\n        if hits == nil then stop(\"hit count: \" .. tostring(problem)) end\n        total = total + hits\n    end\n    local queued, failure = pcall(bsx.after, 10000, report)\n    if not queued then stop(\"timer: \" .. tostring(failure)) end\n    log((on and \"on\" or \"paused\") .. \"; all bodies; rule entries=\" .. tostring(total))\nend\nok, why = pcall(bsx.after, 10000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; Ctrl+Alt+Shift+Numpad6 toggles the global preview\")\n","lang":"lua","name":"main.lua"},{"code":"[MobilityJitterGuard]\n; Horizontal multiplier for every matching body. The script starts paused.\nFactor=1.5\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Mobility Jitter Guard\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"PhysicsBody::IntegratePosition_Write\"]\n}\n","lang":"json","name":"script.json"}],"id":"mobility_jitter_guard","kind":"lua","lua_api":3,"path":"bsx/lua/examples/mobility_jitter_guard","tier":"safe","title":"Mobility Jitter Guard","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A stateless direction experiment, inspired by Sandevistan's smooth mode. It affects EVERY matching physics body, including NPCs and objects. It does not i","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A stateless direction experiment, inspired by Sandevistan's smooth mode.\n-- It affects EVERY matching physics body, including NPCs and objects. It does\n-- not identify the player, smooth direction, check input, or slow the world.\n-- Read bsx/lua/recipes/r6-combat.md before enabling this full-trust script.\nlocal function log(message) bsx.log(\"motion_direction_step: \" .. message) end\n\nlocal step = config.float(\"MotionDirectionStep\", \"Step\", 0.07)\nlocal minimum = config.float(\"MotionDirectionStep\", \"MinDelta\", 0.0001)\nif not (step > 0 and step \u003c= 1) then return log(\"off: Step must be greater than 0 and at most 1\") end\nif not (minimum >= 0.000001 and minimum \u003c= 1) then return log(\"off: MinDelta must be 0.000001 to 1\") end\nlocal site = \"PhysicsBody::IntegratePosition_Delta\"\nlocal status, status_why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(status_why or status))\nend\n\n-- Length = sqrt(X*X + Z*Z). Only after the length check and all arithmetic\n-- succeeds do we replace the two horizontal lanes. Scratch values belong to\n-- this call, so different physics calls do not share a direction or length.\nlocal rule, why = cdal.rule(site, {\n    expect = \"41 0F 58 45 00 41 0F 11 45 00\",\n    enabled = false,\n    stop_on_failure = true,\n    set = {\n        {\"%0.f64\", \"set\", \"xmm0.f32[0]\"},\n        {\"%1.f64\", \"set\", \"xmm0.f32[2]\"},\n        {\"%2.f64\", \"set\", \"%0.f64\"},\n        {\"%2.f64\", \"mul\", \"%0.f64\"},\n        {\"%3.f64\", \"set\", \"%1.f64\"},\n        {\"%3.f64\", \"mul\", \"%1.f64\"},\n        {\"%2.f64\", \"add\", \"%3.f64\"},\n        {\"%2.f64\", \"sqrt\", \"%2.f64\"},\n        {\"%2.f64\", \">\", minimum},\n        {\"%0.f64\", \"div\", \"%2.f64\"},\n        {\"%1.f64\", \"div\", \"%2.f64\"},\n        {\"%0.f64\", \"mul\", step},\n        {\"%1.f64\", \"mul\", step},\n        {\"xmm0.f32[0]\", \"set\", \"%0.f64\"},\n        {\"xmm0.f32[2]\", \"set\", \"%1.f64\"},\n    },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal on, alive, changed, last_hits, failure = false, true, false, 0, nil\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, error_text = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(error_text) end\n    failure = \"off: \" .. reason\nend\n\nlocal bound, key_error = pcall(bsx.hotkey, \"ctrl+alt+numpad8\", function()\n    if not alive then return end\n    local ok, reason = rule:enable(not on)\n    if not ok then return stop(\"toggle failed: \" .. tostring(reason)) end\n    on, changed = not on, true\nend)\nif not bound then\n    stop(\"hotkey unavailable: \" .. tostring(key_error))\n    return log(failure)\nend\n\n-- The count includes calls stopped by the length or arithmetic checks.\nlocal function report()\n    if failure then return log(failure) end\n    local hits, reason = rule:hits()\n    if hits == nil then\n        stop(\"hit count unavailable: \" .. tostring(reason))\n        return log(failure)\n    end\n    local scheduled, schedule_error = pcall(bsx.after, 10000, report)\n    if not scheduled then\n        stop(\"timer unavailable: \" .. tostring(schedule_error))\n        return log(failure)\n    end\n    if changed or hits ~= last_hits then\n        log((on and \"on\" or \"paused\") .. \"; all bodies; rule entries=\" .. tostring(hits))\n        last_hits, changed = hits, false\n    end\nend\nlocal scheduled, schedule_error = pcall(bsx.after, 10000, report)\nif not scheduled then\n    stop(\"timer unavailable: \" .. tostring(schedule_error))\n    return log(failure)\nend\nlog(\"ready: paused; Ctrl+Alt+Numpad8 toggles a stateless step for all bodies\")\n","lang":"lua","name":"main.lua"},{"code":"[MotionDirectionStep]\n; Horizontal distance per matching physics call, not per second.\nStep=0.07\n; Leave tiny movement alone instead of amplifying noise.\nMinDelta=0.0001\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Motion Direction Step\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"PhysicsBody::IntegratePosition_Delta\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"motion_direction_step","kind":"lua","lua_api":3,"path":"bsx/lua/examples/motion_direction_step","tier":"safe","title":"Motion Direction Step","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A global, per-position direction-history preview. It does not identify the player, read analog input, suppress locked movement or slow the world. Read r6-","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A global, per-position direction-history preview. It does not identify the\n-- player, read analog input, suppress locked movement or slow the world.\n-- Read r6-combat.md before enabling this full-trust script.\nlocal function log(s) bsx.log(\"motion_smooth_history: \" .. s) end\nlocal step = config.float(\"MotionSmoothHistory\", \"Step\", 0.07)\nlocal weight = config.float(\"MotionSmoothHistory\", \"DirectionWeight\", 0.30)\nif not (step > 0 and step \u003c= 1) then return log(\"off: Step must be greater than 0 and at most 1\") end\nif not (weight >= 0 and weight \u003c= 1) then return log(\"off: DirectionWeight must be 0 to 1\") end\nlocal site = \"PhysicsBody::IntegratePosition_Delta\"\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    local id = lib.cdal_id_by_name(site)\n    if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. site) end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\n\nlocal function actions(recent)\n    -- Normalize the current X/Z step. Division by zero, an unreadable value\n    -- or nonfinite arithmetic stops before changing the row or a game lane.\n    local a = {\n        {\"%0.f32\", \"set\", \"xmm0.f32[0]\"}, {\"%1.f32\", \"set\", \"xmm0.f32[2]\"},\n        {\"%2.f32\", \"set\", \"%0.f32\"}, {\"%2.f32\", \"mul\", \"%0.f32\"},\n        {\"%3.f32\", \"set\", \"%1.f32\"}, {\"%3.f32\", \"mul\", \"%1.f32\"},\n        {\"%2.f32\", \"add\", \"%3.f32\"}, {\"%2.f32\", \"sqrt\", \"%2.f32\"},\n        {\"%0.f32\", \"div\", \"%2.f32\"}, {\"%1.f32\", \"div\", \"%2.f32\"},\n    }\n    if recent then\n        -- Blend with this body's last unit direction, then normalize again.\n        a[#a+1] = {\"%0.f32\", \"mul\", weight}\n        a[#a+1] = {\"%1.f32\", \"mul\", weight}\n        a[#a+1] = {\"%2.f32\", \"set\", \"#0[r13].0.f32\"}\n        a[#a+1] = {\"%2.f32\", \"mul\", 1 - weight}\n        a[#a+1] = {\"%0.f32\", \"add\", \"%2.f32\"}\n        a[#a+1] = {\"%2.f32\", \"set\", \"#0[r13].1.f32\"}\n        a[#a+1] = {\"%2.f32\", \"mul\", 1 - weight}\n        a[#a+1] = {\"%1.f32\", \"add\", \"%2.f32\"}\n        a[#a+1] = {\"%2.f32\", \"set\", \"%0.f32\"}\n        a[#a+1] = {\"%2.f32\", \"mul\", \"%0.f32\"}\n        a[#a+1] = {\"%3.f32\", \"set\", \"%1.f32\"}\n        a[#a+1] = {\"%3.f32\", \"mul\", \"%1.f32\"}\n        a[#a+1] = {\"%2.f32\", \"add\", \"%3.f32\"}\n        a[#a+1] = {\"%2.f32\", \"sqrt\", \"%2.f32\"}\n        a[#a+1] = {\"%0.f32\", \"div\", \"%2.f32\"}\n        a[#a+1] = {\"%1.f32\", \"div\", \"%2.f32\"}\n    end\n    a[#a+1] = {\"#0[r13].0.f32\", \"set\", \"%0.f32\"}\n    a[#a+1] = {\"#0[r13].1.f32\", \"set\", \"%1.f32\"}\n    a[#a+1] = {\"xmm0.f32[0]\", \"set\", \"%0.f32\"}\n    a[#a+1] = {\"xmm0.f32[0]\", \"mul\", step}\n    a[#a+1] = {\"xmm0.f32[2]\", \"set\", \"%1.f32\"}\n    a[#a+1] = {\"xmm0.f32[2]\", \"mul\", step}\n    return a\nend\n\n-- An existing row is checked first. An absent row is initialized by the\n-- second rule. Within each rule the row's check, read and writes share one\n-- nonblocking table lock; a busy table leaves the game step unchanged.\nlocal rules = {}\nlocal function install(presence, recent)\n    local r, err = cdal.rule(site, {expect = \"41 0F 58 45 00 41 0F 11 45 00\",\n        enabled = false, stop_on_failure = true,\n        when = {{\"r13:u\", \">=\", 65536}, {\"#0[r13].0\", presence}}, set = actions(recent)})\n    if r then rules[#rules+1] = r end\n    return r, err\nend\nlocal first, err = install(\"present\", true)\nif first then first, err = install(\"absent\", false) end\nif not first then\n    local message = \"off: \" .. tostring(err)\n    for _, r in ipairs(rules) do\n        local removed, problem = r:remove()\n        if not removed then error(\"motion_smooth_history: \" .. message .. \"; removal failed: \" .. tostring(problem), 0) end\n    end\n    return log(message)\nend\nlocal alive, on = true, false\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    for _, r in ipairs(rules) do\n        local removed, problem = r:remove()\n        if not removed then reason = reason .. \"; removal failed: \" .. tostring(problem) end\n    end\n    error(\"motion_smooth_history: off: \" .. reason, 0)\nend\nok, why = pcall(bsx.hotkey, \"ctrl+alt+shift+numpad8\", function()\n    if not alive then return end\n    local next_on = not on\n    for _, r in ipairs(rules) do\n        local changed, problem = r:enable(next_on)\n        if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    end\n    on = next_on\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\nlocal function report()\n    if not alive then return end\n    local total = 0\n    for _, r in ipairs(rules) do\n        local hits, problem = r:hits()\n        if hits == nil then stop(\"hit count: \" .. tostring(problem)) end\n        total = total + hits\n    end\n    local queued, failure = pcall(bsx.after, 10000, report)\n    if not queued then stop(\"timer: \" .. tostring(failure)) end\n    log((on and \"on\" or \"paused\") .. \"; all bodies; rule entries=\" .. tostring(total))\nend\nok, why = pcall(bsx.after, 10000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; Ctrl+Alt+Shift+Numpad8 toggles the global preview\")\n","lang":"lua","name":"main.lua"},{"code":"[MotionSmoothHistory]\n; Distance per matching call, not per second. Applies to all bodies.\nStep=0.07\n; 1 follows the latest direction; smaller values retain more history.\nDirectionWeight=0.30\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Motion Smooth History\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"PhysicsBody::IntegratePosition_Delta\"]\n}\n","lang":"json","name":"script.json"}],"id":"motion_smooth_history","kind":"lua","lua_api":3,"path":"bsx/lua/examples/motion_smooth_history","tier":"safe","title":"Motion Smooth History","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 A dispatch-table-filtered preview of the examined No Reload wrapper. It can also see direct calls on the same object type; see r4-stamina.md. Native appro","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- A dispatch-table-filtered preview of the examined No Reload wrapper.\n-- It can also see direct calls on the same object type; see r4-stamina.md.\n-- Native approval gives this script full process trust. No in-game test yet.\nlocal function log(s) bsx.log(\"mounted_reload_predicate: \" .. s) end\nlocal report_seconds = config.int(\"MountedReloadPredicate\", \"ReportSeconds\", 10)\nlocal hotkey = config.string(\"MountedReloadPredicate\", \"Hotkey\", \"ctrl+alt+shift+numpad2\")\nif not (report_seconds >= 10 and report_seconds \u003c= 600) then\n    return log(\"off: ReportSeconds must be 10 to 600\")\nend\nlocal site = \"FirearmAnimation::Update\"\nlocal table_name = \"FirearmAnimation::UpdateDispatchVtable\"\nlocal names = {site, \"FirearmAnimation::UpdateUpperFloat\",\n    \"FirearmAnimation::UpdatePositionFloat\", \"FirearmAnimation::UpdateScaleFloat\",\n    \"FirearmAnimation::UpdateStateLink\", table_name}\n\n-- Scan-only addresses cannot approve a layout. These are CDAL metadata calls,\n-- not calls into the game.\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    for _, name in ipairs(names) do\n        local id = lib.cdal_id_by_name(name)\n        if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. name) end\n    end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\nlocal upper, upper_why = cdal.value(\"FirearmAnimation::UpdateUpperFloat\")\nlocal position, position_why = cdal.value(\"FirearmAnimation::UpdatePositionFloat\")\nlocal scale, scale_why = cdal.value(\"FirearmAnimation::UpdateScaleFloat\")\nlocal state_link, state_link_why = cdal.value(\"FirearmAnimation::UpdateStateLink\")\nif upper == nil or position == nil or scale == nil or state_link == nil then\n    return log(\"off: offset unavailable: \" .. tostring(upper_why or position_why or scale_why or state_link_why))\nend\nlocal old = upper == 0xF0 and position == 0x100 and scale == 0x108 and state_link == 0x118\nlocal later = upper == 0xF8 and position == 0x108 and scale == 0x110 and state_link == 0x120\nif not (old or later) then return log(\"off: unrecognized animation layout\") end\n\nlocal table_address, table_why = cdal.address(table_name)\nlocal function_address, function_why = cdal.address(site)\nif table_address == nil or function_address == nil then\n    return log(\"off: dispatch address unavailable: \" .. tostring(table_why or function_why))\nend\nlocal table_number = tonumber(ffi.cast(\"uintptr_t\", table_address))\nlocal function_number = tonumber(ffi.cast(\"uintptr_t\", function_address))\nif not table_number or not function_number or table_number > 9007199254740991\n    or function_number > 9007199254740991 then return log(\"off: dispatch address is not exact\") end\nlocal function slot_current()\n    local actual, problem = mem.read_ptr(table_number + (old and 0xA0 or 0xB8))\n    if actual == nil then return false, \"dispatch slot unreadable: \" .. tostring(problem) end\n    if actual ~= function_number then return false, \"dispatch slot changed\" end\n    return true\nend\nlocal current, slot_why = slot_current()\nif not current then return log(\"off: \" .. slot_why) end\n\nlocal function field(offset, kind) return string.format(\"[rcx+0x%X].%s\", offset, kind) end\n-- The callee reads this pointer on the checked path. Its complete gameplay\n-- meaning and the name object's identity still need a live trace.\nlocal linked = field(state_link, \"u64\")\nlocal p1 = \"[rcx+0x68].u64\"\nlocal p2 = \"[[rcx+0x68]+0x18].u64\"\nlocal name_pointer = \"[[[rcx+0x68]+0x18]+0].u64\"\nlocal low, high = 65536, 140737488355328\nlocal rule, err = cdal.rule(site, {\n    expect = \"48 89 5C 24 10 56 48 83 EC 40\",\n    enabled = false, stop_on_failure = true,\n    when = {\n        {\"r9b:u\", \"~=\", 0}, {\"rcx:u\", \">=\", low}, {\"rcx:u\", \"\u003c\", high},\n        {\"[rcx].u64\", \"==\", table_address},\n        {\"[rcx+0x50].u8\", \"==\", 0}, {\"[rcx+0x91].u8\", \"==\", 0},\n        {\"[rcx+0x94].u8\", \"==\", 0}, {linked, \"==\", 0},\n        {p1, \">=\", low}, {p1, \"\u003c\", high}, {p2, \">=\", low}, {p2, \"\u003c\", high},\n        {name_pointer, \">=\", low}, {name_pointer, \"\u003c\", high},\n    },\n    -- The string is a third pointer read, one deeper than a text operand can\n    -- express directly. Walk exactly one element at that pointer: @ is the\n    -- text address, without borrowing or modifying a game register. r9b is\n    -- nonzero above and max=1 limits even a flag greater than one to one walk.\n    each = {list = name_pointer, count = \"r9b:u\", stride = 1, max = 1, set = {\n        {\"[@].str192\", \"contains\", \"/1_pc/\"},\n        {\"[@].str192\", \"contains\", \"_reload_\"},\n        {\"%0.u32\", \"set\", 1},\n    }},\n    set = {\n        {\"%0.u32\", \"==\", 1},\n        {\"%1.f32\", \"set\", field(upper, \"f32\")},\n        {\"%2.f32\", \"set\", field(position, \"f32\")},\n        {\"%3.f32\", \"set\", field(scale, \"f32\")},\n        {\"%4.f32\", \"set\", \"xmm1.f32\"},\n        {\"%1.f32\", \">=\", 0.1}, {\"%1.f32\", \"\u003c=\", 15},\n        {\"%2.f32\", \">=\", 0}, {\"%3.f32\", \">=\", 0.1},\n        {\"%3.f32\", \"\u003c=\", 32}, {\"%4.f32\", \">\", 0},\n        {\"%4.f32\", \"\u003c=\", 0.25}, {\"%2.f32\", \"\u003c\", \"%1.f32\"},\n        {\"%1.f32\", \"sub\", \"%2.f32\"}, {\"%1.f32\", \"add\", 0.0001},\n        {\"%1.f32\", \"div\", \"%3.f32\"}, {\"xmm1.f32\", \"max\", \"%1.f32\"},\n    },\n})\nif not rule then return log(\"off: \" .. tostring(err)) end\n\nlocal alive, on = true, false\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, problem = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(problem) end\n    error(\"mounted_reload_predicate: off: \" .. reason, 0)\nend\nok, why = pcall(bsx.hotkey, hotkey, function()\n    if not alive then return end\n    if not on then\n        local valid, problem = slot_current()\n        if not valid then return stop(problem) end\n    end\n    local changed, problem = rule:enable(not on)\n    if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    on = not on\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\nlocal function report()\n    if not alive then return end\n    local valid, problem = slot_current()\n    if not valid then return stop(problem) end\n    local hits, problem = rule:hits()\n    if hits == nil then stop(\"hit count: \" .. tostring(problem)) end\n    local queued, failure = pcall(bsx.after, report_seconds * 1000, report)\n    if not queued then stop(\"timer: \" .. tostring(failure)) end\n    log((on and \"on\" or \"paused\") .. \"; eligible call entries=\" .. tostring(hits))\nend\nok, why = pcall(bsx.after, report_seconds * 1000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; \" .. hotkey .. \" toggles the dispatch-table preview\")\n","lang":"lua","name":"main.lua"},{"code":"[MountedReloadPredicate]\n; This full-trust example starts paused. Ctrl+Alt+Shift+Numpad2 toggles it.\n; Status is logged no more often than every 10 seconds.\nHotkey=ctrl+alt+shift+numpad2\nReportSeconds=10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Mounted Reload Predicate\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"FirearmAnimation::Update\",\n    \"FirearmAnimation::UpdateUpperFloat\",\n    \"FirearmAnimation::UpdatePositionFloat\",\n    \"FirearmAnimation::UpdateScaleFloat\",\n    \"FirearmAnimation::UpdateStateLink\",\n    \"FirearmAnimation::UpdateDispatchVtable\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"mounted_reload_predicate","kind":"lua","lua_api":3,"path":"bsx/lua/examples/mounted_reload_predicate","tier":"safe","title":"Mounted Reload Predicate","uses":[]},{"category":"UI & Overlays","description":"Demonstrates modular BSX Lua 4 scripting:","featured":false,"files":[{"code":"-- Multi-File Kit: demonstrates require(), bsx.json, sandboxed bsx.fs, bsx.ui v3 tabs/color, and bsx.draw v2 font_scale.\n\nlocal fmt = require('helpers.format')\n\nlocal THEME_DIR = 'presets'\nlocal THEME_FILE = 'presets/theme.json'\n\nlocal state = {\n  title = 'BSX Multi-File Kit',\n  accent = '#64E6FFFF',\n  scale = 1.35,\n  show_banner = false,\n  status = 'Ready',\n  files_summary = '(none)',\n}\n\nlocal function refresh_files()\n  local ok, list = pcall(bsx.fs.list, THEME_DIR)\n  state.files_summary = ok and fmt.summarize_files(list) or '(unavailable)'\nend\n\nlocal function load_theme()\n  if not bsx.fs.exists(THEME_FILE) then\n    refresh_files()\n    return false, 'no saved theme yet'\n  end\n  local ok_read, raw = pcall(bsx.fs.read, THEME_FILE)\n  if not ok_read or type(raw) ~= 'string' then\n    refresh_files()\n    return false, tostring(raw)\n  end\n  local decoded, err = bsx.json.decode(raw)\n  if type(decoded) ~= 'table' then\n    refresh_files()\n    return false, tostring(err)\n  end\n  if type(decoded.title) == 'string' and decoded.title ~= '' then\n    state.title = decoded.title\n  end\n  state.accent = fmt.sanitize_hex(decoded.accent, state.accent)\n  if type(decoded.scale) == 'number' then\n    state.scale = math.max(0.5, math.min(4.0, decoded.scale))\n  end\n  refresh_files()\n  return true, 'loaded presets/theme.json'\nend\n\nlocal function save_theme()\n  if not bsx.fs.exists(THEME_DIR) then\n    pcall(bsx.fs.mkdir, THEME_DIR)\n  end\n  local encoded, err = bsx.json.encode({\n    title = state.title,\n    accent = state.accent,\n    scale = state.scale,\n  }, { pretty = true })\n  if not encoded then\n    return false, tostring(err)\n  end\n  local ok_write, werr = pcall(bsx.fs.write, THEME_FILE, encoded)\n  refresh_files()\n  if not ok_write then\n    return false, tostring(werr)\n  end\n  return true, 'saved presets/theme.json'\nend\n\nload_theme()\nif not bsx.fs.exists(THEME_FILE) then\n  save_theme()\nend\n\nlocal panel = bsx.ui.panel('Multi-File Kit')\nlocal status_lbl\nlocal files_lbl\n\nlocal function update_labels(msg)\n  state.status = msg or state.status\n  if panel and status_lbl then\n    panel:set_text(status_lbl, 'Status: ' .. state.status)\n  end\n  if panel and files_lbl then\n    panel:set_text(files_lbl, 'data/' .. THEME_DIR .. ': ' .. state.files_summary)\n  end\nend\n\nif panel then\n  panel:begin_tab_bar('kit_tabs')\n\n  panel:tab('Theme & Draw')\n  panel:input_text('Banner Title', state.title, function(text)\n    if text ~= '' then\n      state.title = text\n    end\n  end)\n  panel:color('Accent RGBA', state.accent, function(_, hex)\n    state.accent = fmt.sanitize_hex(hex, state.accent)\n  end)\n  panel:slider('Draw Font Scale', 0.5, 3.0, state.scale, function(v)\n    state.scale = math.max(0.5, math.min(4.0, tonumber(v) or 1.0))\n  end)\n  panel:checkbox('Show Foreground Scaled Banner', state.show_banner, function(v)\n    state.show_banner = (v == true)\n    if not state.show_banner then\n      pcall(bsx.draw.clear)\n    end\n  end)\n  panel:end_tab()\n\n  panel:tab('Files (bsx.fs + JSON)')\n  files_lbl = panel:text('data/' .. THEME_DIR .. ': ' .. state.files_summary)\n  status_lbl = panel:text('Status: ' .. state.status)\n  panel:button('Save Theme JSON', function()\n    local ok, msg = save_theme()\n    update_labels(ok and msg or ('Save failed: ' .. msg))\n  end)\n  panel:same_line()\n  panel:button('Reload Theme JSON', function()\n    local ok, msg = load_theme()\n    update_labels(ok and msg or ('Load failed: ' .. msg))\n  end)\n  panel:end_tab()\n\n  panel:end_tab_bar()\nend\n\nbsx.on('frame', function()\n  if state.show_banner then\n    pcall(bsx.draw.clear)\n    pcall(bsx.draw.text, 28, 86, fmt.format_banner(state), state.accent, state.scale)\n  end\nend)\n\nbsx.log('MULTI_FILE_KIT_READY files=' .. state.files_summary .. ' scale=' .. string.format('%.2f', state.scale))\nbsx.on('world_ready', function()\n  bsx.log('MULTI_FILE_KIT_WORLD_READY files=' .. state.files_summary)\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Multi-File Kit\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 4,\n  \"uses\": [\"ui\"]\n}\n","lang":"json","name":"script.json"},{"code":"-- Helper module loaded via require('helpers.format').\n\nlocal M = {}\n\nfunction M.sanitize_hex(hex, fallback)\n  if type(hex) == 'string' and (hex:match('^#%x%x%x%x%x%x$') or hex:match('^#%x%x%x%x%x%x%x%x$')) then\n    return string.upper(hex)\n  end\n  return fallback or '#64E6FFFF'\nend\n\nfunction M.summarize_files(files)\n  if type(files) ~= 'table' or #files == 0 then\n    return '(none)'\n  end\n  local names = {}\n  for i = 1, math.min(#files, 6) do\n    names[#names + 1] = tostring(files[i])\n  end\n  if #files > 6 then\n    names[#names + 1] = string.format('(+%d more)', #files - 6)\n  end\n  return table.concat(names, ', ')\nend\n\nfunction M.format_banner(cfg)\n  local title = (type(cfg) == 'table' and type(cfg.title) == 'string' and cfg.title ~= '') and cfg.title or 'Multi-File Kit'\n  local scale = (type(cfg) == 'table' and tonumber(cfg.scale)) or 1.0\n  return string.format('%s (scale %.2fx)', title, scale)\nend\n\nreturn M\n","lang":"lua","name":"helpers/format.lua"}],"id":"multi_file_kit","kind":"lua","lua_api":4,"path":"bsx/lua/examples/multi_file_kit","tier":"safe","title":"Multi-File Kit","uses":["ui"]},{"category":"BSX Core & Diagnostics","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Requires separate Native approval of this folder's logged SHA-256. Reads the declared pointer slot with FFI. No game writes, patches or native calls.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Requires separate Native approval of this folder's logged SHA-256.\n-- Reads the declared pointer slot with FFI. No game writes, patches or native calls.\nlocal ffi = require(\"ffi\")\nlocal slot, why = cdal.address(\"WorldSystem::sInstance\")\nif not slot then return bsx.log(why) end\n-- A guarded read first reports an unavailable page without an FFI dereference.\nlocal value, reason = mem.read_ptr(slot)\nif value == nil then return bsx.log(reason) end\nbsx.log(\"native_hello: pointer slot = \" .. tostring(ffi.cast(\"const uintptr_t*\", slot)[0]))\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Native Hello\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"WorldSystem::sInstance\"]\n}\n","lang":"json","name":"script.json"}],"id":"native_hello","kind":"lua","lua_api":3,"path":"bsx/lua/examples/native_hello","tier":"safe","title":"Native Hello","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 The on-foot filter and formula from the examined No Reload wrapper. Name/object identity remains inferred; see r4-stamina.md. Native approval gives this s","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- The on-foot filter and formula from the examined No Reload wrapper.\n-- Name/object identity remains inferred; see r4-stamina.md.\n-- Native approval gives this script full process trust. No in-game test yet.\nlocal function log(s) bsx.log(\"onfoot_reload_predicate: \" .. s) end\nlocal report_seconds = config.int(\"OnfootReloadPredicate\", \"ReportSeconds\", 10)\nif not (report_seconds >= 10 and report_seconds \u003c= 600) then\n    return log(\"off: ReportSeconds must be 10 to 600\")\nend\nlocal site = \"FirearmAnimation::UpdateCall\"\nlocal names = {site, \"FirearmAnimation::UpdateUpperFloat\",\n    \"FirearmAnimation::UpdatePositionFloat\", \"FirearmAnimation::UpdateScaleFloat\",\n    \"FirearmAnimation::UpdateStateLink\"}\n\n-- Scan-only addresses cannot approve a layout. These are CDAL metadata calls,\n-- not calls into the game.\nlocal ffi = require(\"ffi\")\nlocal ok, why = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    for _, name in ipairs(names) do\n        local id = lib.cdal_id_by_name(name)\n        if id == 0 or lib.cdal_build_supports(id, 0) == 0 then error(\"no stored value for \" .. name) end\n    end\nend)\nif not ok then return log(\"off: CDAL build requirements: \" .. tostring(why)) end\nlocal upper, upper_why = cdal.value(\"FirearmAnimation::UpdateUpperFloat\")\nlocal position, position_why = cdal.value(\"FirearmAnimation::UpdatePositionFloat\")\nlocal scale, scale_why = cdal.value(\"FirearmAnimation::UpdateScaleFloat\")\nlocal state_link, state_link_why = cdal.value(\"FirearmAnimation::UpdateStateLink\")\nif upper == nil or position == nil or scale == nil or state_link == nil then\n    return log(\"off: offset unavailable: \" .. tostring(upper_why or position_why or scale_why or state_link_why))\nend\nlocal old = upper == 0xF0 and position == 0x100 and scale == 0x108 and state_link == 0x118\nlocal later = upper == 0xF8 and position == 0x108 and scale == 0x110 and state_link == 0x120\nif not (old or later) then return log(\"off: unrecognized animation layout\") end\n\nlocal function field(offset, kind) return string.format(\"[rcx+0x%X].%s\", offset, kind) end\n-- The callee reads this pointer on the checked path. Its complete gameplay\n-- meaning and the name object's identity still need a live trace.\nlocal linked = field(state_link, \"u64\")\nlocal p1 = \"[rcx+0x68].u64\"\nlocal p2 = \"[[rcx+0x68]+0x18].u64\"\nlocal name_pointer = \"[[[rcx+0x68]+0x18]+0].u64\"\nlocal low, high = 65536, 140737488355328\nlocal rule, err = cdal.rule(site, {\n    expect = old and \"E8 A8 DF FF FF\" or \"E8 88 DF FF FF\",\n    enabled = false, stop_on_failure = true,\n    when = {\n        {\"r9b:u\", \"~=\", 0}, {\"rcx:u\", \">=\", low}, {\"rcx:u\", \"\u003c\", high},\n        {\"[rcx+0x50].u8\", \"==\", 0}, {\"[rcx+0x91].u8\", \"==\", 0},\n        {\"[rcx+0x94].u8\", \"==\", 0}, {linked, \"==\", 0},\n        {p1, \">=\", low}, {p1, \"\u003c\", high}, {p2, \">=\", low}, {p2, \"\u003c\", high},\n        {name_pointer, \">=\", low}, {name_pointer, \"\u003c\", high},\n    },\n    -- The string is a third pointer read, one deeper than a text operand can\n    -- express directly. Walk exactly one element at that pointer: @ is the\n    -- text address, without borrowing or modifying a game register. r9b is\n    -- nonzero above and max=1 limits even a flag greater than one to one walk.\n    each = {list = name_pointer, count = \"r9b:u\", stride = 1, max = 1, set = {\n        {\"[@].str192\", \"contains\", \"/1_pc/\"},\n        {\"[@].str192\", \"contains\", \"_reload_\"},\n        {\"%0.u32\", \"set\", 1},\n    }},\n    set = {\n        {\"%0.u32\", \"==\", 1},\n        {\"%1.f32\", \"set\", field(upper, \"f32\")},\n        {\"%2.f32\", \"set\", field(position, \"f32\")},\n        {\"%3.f32\", \"set\", field(scale, \"f32\")},\n        {\"%4.f32\", \"set\", \"xmm1.f32\"},\n        {\"%1.f32\", \">=\", 0.1}, {\"%1.f32\", \"\u003c=\", 15},\n        {\"%2.f32\", \">=\", 0}, {\"%3.f32\", \">=\", 0.1},\n        {\"%3.f32\", \"\u003c=\", 32}, {\"%4.f32\", \">\", 0},\n        {\"%4.f32\", \"\u003c=\", 0.25}, {\"%2.f32\", \"\u003c\", \"%1.f32\"},\n        {\"%1.f32\", \"sub\", \"%2.f32\"}, {\"%1.f32\", \"add\", 0.0001},\n        {\"%1.f32\", \"div\", \"%3.f32\"}, {\"xmm1.f32\", \"max\", \"%1.f32\"},\n    },\n})\nif not rule then return log(\"off: \" .. tostring(err)) end\n\nlocal alive, on = true, false\nlocal function stop(reason)\n    if not alive then return end\n    alive = false\n    local removed, problem = rule:remove()\n    if not removed then reason = reason .. \"; removal failed: \" .. tostring(problem) end\n    error(\"onfoot_reload_predicate: off: \" .. reason, 0)\nend\nok, why = pcall(bsx.hotkey, \"ctrl+alt+shift+numpad7\", function()\n    if not alive then return end\n    local changed, problem = rule:enable(not on)\n    if not changed then return stop(\"toggle: \" .. tostring(problem)) end\n    on = not on\nend)\nif not ok then stop(\"hotkey: \" .. tostring(why)) end\nlocal function report()\n    if not alive then return end\n    local hits, problem = rule:hits()\n    if hits == nil then stop(\"hit count: \" .. tostring(problem)) end\n    local queued, failure = pcall(bsx.after, report_seconds * 1000, report)\n    if not queued then stop(\"timer: \" .. tostring(failure)) end\n    log((on and \"on\" or \"paused\") .. \"; eligible call entries=\" .. tostring(hits))\nend\nok, why = pcall(bsx.after, report_seconds * 1000, report)\nif not ok then stop(\"timer: \" .. tostring(why)) end\nlog(\"ready: paused; Ctrl+Alt+Shift+Numpad7 toggles the on-foot filter\")\n","lang":"lua","name":"main.lua"},{"code":"[OnfootReloadPredicate]\n; This full-trust example starts paused. Ctrl+Alt+Shift+Numpad7 toggles it.\n; Status is logged no more often than every 10 seconds.\nReportSeconds=10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"On-foot Reload Predicate\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"FirearmAnimation::UpdateCall\",\n    \"FirearmAnimation::UpdateUpperFloat\",\n    \"FirearmAnimation::UpdatePositionFloat\",\n    \"FirearmAnimation::UpdateScaleFloat\",\n    \"FirearmAnimation::UpdateStateLink\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"onfoot_reload_predicate","kind":"lua","lua_api":3,"path":"bsx/lua/examples/onfoot_reload_predicate","tier":"safe","title":"On-foot Reload Predicate","uses":[]},{"category":"Appearance & Outfits","description":"Session-only, inventory-only example. Requests still need live acceptance.","featured":false,"files":[{"code":"-- Session-only, inventory-only example. Requests still need live acceptance.\nlocal saved, pending, save_generation, frame = nil, nil, nil, 0\nlocal function log(s) bsx.log(\"outfits: \" .. s) end\nlocal function cancel(why)\n    if pending or saved then log(\"cancelled: \" .. why .. \"; save the current set again\") end\n    pending, saved = nil, nil\nend\nlocal function same(a, b)\n    return a and b and a.row == b.row and a.count == b.count and a.instance_id == b.instance_id\nend\nlocal function usable(item)\n    assert(item.instance_id and item.instance_id ~= \"0\", \"item has no usable ItemNo\")\n    assert(item.slot_tag == nil or item.slot_tag \u003c= 32767, \"unsupported request slot tag\")\nend\nlocal function snapshots()\n    local eq, why = game.equipment_snapshot()\n    assert(eq, why)\n    local inv, reason = game.inventory.list(4096)\n    assert(inv, reason)\n    assert(not inv.truncated and not eq.truncated, \"snapshot truncated\")\n    assert(eq.generation == inv.generation and eq.actor_key == inv.actor_key, \"snapshot generation changed\")\n    local tags = {}\n    for _, item in ipairs(eq) do\n        assert(not tags[item.slot_tag], \"duplicate equipment tag\")\n        tags[item.slot_tag] = item\n    end\n    return eq, inv, tags\nend\nlocal function guarded(fn)\n    local ok, why = pcall(fn)\n    if not ok then cancel(tostring(why)); log(\"stopped: \" .. tostring(why)) end\nend\nlocal function current(eq)\n    assert(saved and eq.generation == saved.generation and eq.actor_key == saved.actor_key\n        and save_generation == saved.save_generation, \"player or save generation changed\")\nend\nlocal function locate(inv, wanted)\n    local found\n    for _, item in ipairs(inv) do\n        if item.instance_id == wanted.instance_id then\n            assert(same(item, wanted) and not found, \"changed or ambiguous inventory instance\")\n            found = item\n        end\n    end\n    return found\nend\nlocal function validate_wanted(inv, tags, locations)\n    for tag, wanted in pairs(saved.tags) do\n        local equipped\n        for other_tag, item in pairs(tags) do\n            if item.instance_id == wanted.instance_id then\n                assert(other_tag == tag and same(item, wanted) and not equipped, \"saved instance changed slot or contents\")\n                equipped = item\n            end\n        end\n        local item = locate(inv, wanted)\n        assert(not (equipped and item), \"instance exists in both snapshots\")\n        assert(equipped or item, \"saved instance is missing from owned inventory\")\n        if item then\n            local old = locations[wanted.instance_id]\n            assert(not old or (old.bucket == item.bucket and old.index == item.index), \"inventory location changed\")\n            locations[wanted.instance_id] = {bucket = item.bucket, index = item.index}\n        end\n    end\nend\nlocal function equipment_matches(tags, expected)\n    for tag, item in pairs(tags) do if not same(item, expected[tag]) then return false end end\n    for tag, item in pairs(expected) do if not same(item, tags[tag]) then return false end end\n    return true\nend\nlocal function copy_tags(tags)\n    local result = {}\n    for tag, item in pairs(tags) do result[tag] = item end\n    return result\nend\nlocal function applied(e, kind)\n    local op = pending and pending.op\n    if not op or op.kind ~= kind or e.controlled ~= true or e.generation ~= saved.save_generation\n        or e.tag ~= op.tag or e.row ~= op.item.row or e.item_word0 ~= op.item.instance_id\n        or e.count ~= op.item.count then return end\n    op.applied = true\nend\nlocal events = pcall(function()\n    bsx.on(\"equip_applied\", function(e) applied(e, \"equip\") end)\n    bsx.on(\"unequip_applied\", function(e) applied(e, \"unequip\") end)\n    bsx.on(\"save_load\", function() cancel(\"save request\"); save_generation = nil end)\n    bsx.on(\"load_request\", function() cancel(\"loading request\"); save_generation = nil end)\n    bsx.on(\"title_screen\", function() cancel(\"title screen\"); save_generation = nil end)\n    bsx.on(\"save_loaded\", function(e) cancel(\"save replaced\"); save_generation = e.generation end)\nend)\nif not events then log(\"required lifecycle/APPLIED events unavailable\") end\nif not game.request then log(\"read-only; Changes approval is required to restore\") end\n\nbsx.hotkey(\"ctrl+shift+f7\", function()\n    if pending then return end\n    guarded(function()\n        assert(events and save_generation, \"wait for SAVE_LOADED before saving an outfit\")\n        local eq, inv, tags = snapshots()\n        local identities = {}\n        for _, item in ipairs(eq) do\n            usable(item)\n            assert(not identities[item.instance_id], \"ambiguous equipped instance\")\n            identities[item.instance_id] = true\n        end\n        saved = {tags = tags, generation = eq.generation, actor_key = eq.actor_key,\n            save_generation = save_generation, size = #eq}\n        validate_wanted(inv, tags, {})\n        log(\"saved \" .. #eq .. \" equipped items for this session\")\n    end)\nend)\nbsx.hotkey(\"ctrl+shift+f8\", function()\n    if pending then return end -- no second send while an outcome is uncertain\n    if not game.request then log(\"restore requires Changes approval\"); return end\n    guarded(function()\n        assert(saved, \"save an outfit with Ctrl+Shift+F7 first\")\n        local eq, inv, tags = snapshots()\n        current(eq)\n        local locations = {}\n        validate_wanted(inv, tags, locations)\n        pending = {expected = tags, locations = locations}\n        log(\"restore started; each request waits for APPLIED and matching state\")\n    end)\nend)\nbsx.on(\"frame\", function(e)\n    frame = e.frame\n    if not pending then return end\n    guarded(function()\n        local eq, inv, tags = snapshots()\n        current(eq)\n        if pending.op then\n            local op = pending.op\n            assert(frame \u003c= op.deadline, \"APPLIED/state timeout; uncertain request will not be retried\")\n            local after = copy_tags(pending.expected)\n            after[op.tag] = op.kind == \"equip\" and op.item or nil\n            assert(equipment_matches(tags, pending.expected) or equipment_matches(tags, after), \"unexpected equipment change\")\n            if not op.applied or not equipment_matches(tags, after) then return end\n            pending.expected, pending.op = after, nil\n            -- Reacquire on a later FRAME before making another request.\n            return\n        end\n        assert(equipment_matches(tags, pending.expected), \"equipment changed before request\")\n        validate_wanted(inv, tags, pending.locations)\n        local op\n        -- Remove extra or replaced pieces before putting saved pieces back.\n        for _, item in ipairs(eq) do\n            if not same(item, saved.tags[item.slot_tag]) then\n                usable(item); op = {kind = \"unequip\", item = item, tag = item.slot_tag}; break\n            end\n        end\n        if not op then\n            local order = {}\n            for tag in pairs(saved.tags) do order[#order + 1] = tag end\n            table.sort(order)\n            for _, tag in ipairs(order) do\n                if not tags[tag] then\n                    local item = assert(locate(inv, saved.tags[tag]), \"saved instance missing before equip\")\n                    op = {kind = \"equip\", item = saved.tags[tag], tag = tag, bucket = item.bucket, index = item.index}\n                    break\n                end\n            end\n        end\n        if not op then log(\"restored \" .. saved.size .. \" equipped items\"); pending = nil; return end\n        op.deadline = frame + 600\n        pending.op = op -- arm before the request; a sender result is never APPLIED\n        local queued, why\n        if op.kind == \"equip\" then queued, why = game.request.equip(op.bucket, op.index, op.tag)\n        else queued, why = game.request.unequip(op.tag) end\n        if not queued then cancel(op.kind .. \" refused or uncertain: \" .. tostring(why)); return end\n        log(op.kind .. \" queued for tag \" .. op.tag .. \"; waiting for APPLIED\")\n    end)\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Outfits\",\n  \"version\": \"1\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\",\n    \"pa::ClientNormalInGameActor::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Key\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"ActorComponents::Equipment\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"CommonEquipSlotActorComponent::StorageOffset\",\n    \"EquipmentSlotRecord::Stride\",\n    \"EquipmentSlotRecord::SlotTag\",\n    \"Inventory::GetHolder\",\n    \"Inventory::GetItem\",\n    \"Inventory::GetBucketForItemRow\",\n    \"UsableItem::Construct\",\n    \"UsableItem::Copy\",\n    \"UsableItem::Destroy\",\n    \"ActorEquipment::RequestEquipItem\", \"ClientRequest::EquipPacketKind\",\n    \"ActorEquipment::RequestUnequipItem\", \"ClientRequest::UnequipPacketKind\",\n    \"ClientRequest::SendPacket\",\n    \"InventoryBucket::Tag\",\n    \"InventoryItem::ItemNo\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"outfits","kind":"lua","lua_api":3,"path":"bsx/lua/examples/outfits","tier":"changes","title":"Outfits","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Enhanced Force Palm's timed vertical-step operation, with a BSX hotkey. Native approval is full trust. It affects all matching physics bodies. See r5-flig","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Enhanced Force Palm's timed vertical-step operation, with a BSX hotkey.\n-- Native approval is full trust. It affects all matching physics bodies.\n-- See r5-flight.md; no in-game test has been done.\nlocal ffi = require(\"ffi\")\nffi.cdef[[unsigned long long __stdcall GetTickCount64(void);]]\nlocal kernel = ffi.load(\"kernel32\")\nlocal function log(message) bsx.log(\"palm_boost: \" .. message) end\nlocal boost = config.float(\"PalmBoost\", \"BoostValue\", 35)\nlocal window = config.int(\"PalmBoost\", \"WindowMs\", 180)\nlocal cooldown = config.int(\"PalmBoost\", \"TriggerCooldownMs\", 400)\nif not (boost >= -1000 and boost \u003c= 1000 and window >= 1 and window \u003c= 5000\n        and cooldown >= 0 and cooldown \u003c= 60000) then\n    return log(\"off: boost must be -1000..1000, window 1..5000 ms and cooldown 0..60000 ms\")\nend\nlocal site = \"PhysicsBody::IntegratePosition_Delta\"\nlocal status, status_why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(status_why or status))\nend\n\n-- $0 is the last hook timestamp in microseconds; $1 is the active deadline\n-- in milliseconds; $2 is the last timestamp plus 10 microseconds. The mod's\n-- callback first measures elapsed time, then replaces the vertical lane with\n-- clamp(BoostValue * min(elapsed_seconds, 0.05), -50, 50), if elapsed >= 10 us.\n-- The two rules are installed in this order: calculate, then update the clock.\nlocal change, why = cdal.rule(site, {\n    expect = \"41 0F 58 45 00 41 0F 11 45 00\", enabled = false,\n    when = {\n        {\"r13:u\", \">=\", 0x100000}, {\"tick\", \"\u003c\", \"$1.u64\"},\n        {\"$0.u64\", \">\", 0}, {\"tick_us\", \">=\", \"$2.u64\"},\n    },\n    set = {\n        {\"%0.u64\", \"set\", \"tick_us\"}, {\"%0.u64\", \"sub\", \"$0.u64\"},\n        {\"%0.u64\", \"min\", 50000}, {\"%1.f64\", \"set\", \"%0.u64\"},\n        {\"%1.f64\", \"div\", 1000000}, {\"%1.f64\", \"mul\", boost},\n        {\"%1.f64\", \"max\", -50}, {\"%1.f64\", \"min\", 50},\n        {\"xmm0.f32[1]\", \"set\", \"%1.f64\"},\n    },\n})\nif not change then return log(\"off: boost rule: \" .. tostring(why)) end\nlocal clock, clock_why = cdal.rule(site, {\n    expect = \"41 0F 58 45 00 41 0F 11 45 00\", enabled = false,\n    when = {{\"r13:u\", \">=\", 0x100000}, {\"tick\", \"\u003c\", \"$1.u64\"}},\n    set = {\n        {\"$0.u64\", \"set\", \"tick_us\"}, {\"$2.u64\", \"set\", \"$0.u64\"},\n        {\"$2.u64\", \"add\", 10},\n    },\n})\nif not clock then\n    local removed, remove_why = change:remove()\n    if not removed then log(\"remove failed: \" .. tostring(remove_why)) end\n    return log(\"off: clock rule: \" .. tostring(clock_why))\nend\n\nlocal live, armed, serial, last_press = true, false, 0, nil\nlocal function fail(reason)\n    if not live then return end\n    live = false\n    for _, rule in ipairs({change, clock}) do\n        local removed, remove_why = rule:remove()\n        if not removed then log(\"remove failed: \" .. tostring(remove_why)) end\n    end\n    log(\"off: \" .. tostring(reason))\nend\nlocal function pause()\n    local cleared, clear_why = cdal.set_cell(1, 0, \"u64\")\n    if not cleared then return fail(\"cannot clear deadline: \" .. tostring(clear_why)) end\n    for _, rule in ipairs({change, clock}) do\n        local stopped, stop_why = rule:enable(false)\n        if not stopped then return fail(\"cannot pause: \" .. tostring(stop_why)) end\n    end\n    armed = false\nend\nlocal ok, key_why = pcall(bsx.hotkey, \"ctrl+shift+numpad3\", function()\n    if not live then return end\n    local read_ok, now = pcall(function() return tonumber(kernel.GetTickCount64()) end)\n    if not read_ok or not now or now \u003c= 0 then return fail(\"Windows clock unavailable: \" .. tostring(now)) end\n    if last_press and now - last_press \u003c cooldown then return end\n    last_press = now\n    serial = serial + 1\n    local ticket = serial\n    local scheduled, timer_why = pcall(bsx.after, window, function()\n        if live and ticket == serial then pause() end\n    end)\n    if not scheduled then return fail(\"window timer unavailable: \" .. tostring(timer_why)) end\n    if not armed then\n        -- Keep the deadline at zero until both rules have been enabled.\n        for _, rule in ipairs({change, clock}) do\n            local enabled, enable_why = rule:enable(true)\n            if not enabled then return fail(\"cannot arm: \" .. tostring(enable_why)) end\n        end\n        armed = true\n    end\n    local published, publish_why = cdal.set_cell(1, now + window, \"u64\")\n    if not published then return fail(\"cannot publish deadline: \" .. tostring(publish_why)) end\n    log(\"boost window started; all matching bodies\")\nend)\nif not ok then return fail(\"hotkey unavailable: \" .. tostring(key_why)) end\n\nlocal last_hits = 0\nlocal function report()\n    if not live then return end\n    local hits, reason = change:hits()\n    if hits == nil then return fail(\"counter unavailable: \" .. tostring(reason)) end\n    if hits ~= last_hits then log(\"boosted steps: \" .. tostring(hits)); last_hits = hits end\n    local scheduled, timer_why = pcall(bsx.after, 30000, report)\n    if not scheduled then return fail(\"counter timer unavailable: \" .. tostring(timer_why)) end\nend\nlocal scheduled, timer_why = pcall(bsx.after, 30000, report)\nif not scheduled then return fail(\"counter timer unavailable: \" .. tostring(timer_why)) end\nlog(\"paused; ctrl+shift+numpad3 starts a boost window\")\n","lang":"lua","name":"main.lua"},{"code":"[PalmBoost]\n; Ctrl+Shift+Numpad3 starts a short boost; every matching physics body is affected.\nBoostValue=35\nWindowMs=180\nTriggerCooldownMs=400\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Palm Boost\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"PhysicsBody::IntegratePosition_Delta\"]\n}\n","lang":"json","name":"script.json"}],"id":"palm_boost","kind":"lua","lua_api":3,"path":"bsx/lua/examples/palm_boost","tier":"safe","title":"Palm Boost","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Master Looter's stop-body-looting switch. Native approval is required. It affects every caller of the matching condition, not just one pet. It only search","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Master Looter's stop-body-looting switch. Native approval is required.\n-- It affects every caller of the matching condition, not just one pet.\n-- It only searches already-cached rows and has not been tested in game.\n-- Read bsx/lua/recipes/r2-loot.md before using it.\n-- Coalesce messages while the ten-second log window is closed. A terminal\n-- error remains queued until the FRAME callback can report it.\nlocal next_message, pending_message = 0, nil\nlocal function log(message)\n    local now = os.time()\n    if now \u003c next_message then pending_message = message; return end\n    pending_message = nil\n    bsx.log(\"pet body loot: \" .. message)\n    next_message = now + 11 -- os.time has one-second resolution\nend\nlocal function flush_log(now)\n    if pending_message and now >= next_message then log(pending_message) end\nend\nlocal SITE = \"ConditionData_HasInteraction::Evaluate\"\nlocal ROOT = \"InteractionInfoManager::sInstance\"\nlocal TYPE = \"pa::InteractionInfoManager::vftable\"\nlocal CAPACITY = \"DefinitionTable::Capacity\"\nlocal CACHE = \"DefinitionTable::CachedRows\"\nlocal NAME = \"DefinitionRow::InternalName\"\nlocal ffi = require(\"ffi\")\n-- cdal.value does not expose an offset's resolution status. Ask CDAL's own\n-- build API to reject unmatched builds and scanned-only values, including 0.\nlocal supported, problem = pcall(function()\n    ffi.cdef[[\n        int cdal_build_matched(void);\n        unsigned int cdal_id_by_name(const char *name);\n        int cdal_build_supports(unsigned int id, int require_checked);\n    ]]\n    local lib = ffi.load(\"cdal.dll\")\n    if lib.cdal_build_matched() == 0 then error(\"no exact game build match\") end\n    for _, name in ipairs({SITE, ROOT, TYPE, CAPACITY, CACHE, NAME}) do\n        local id = lib.cdal_id_by_name(name)\n        if id == 0 or lib.cdal_build_supports(id, 0) == 0 then\n            error(\"no stored build value for \" .. name)\n        end\n    end\nend)\nif not supported then return log(\"off: CDAL build requirements: \" .. tostring(problem)) end\nlocal function checked(id, status, why)\n    if status ~= \"resolved\" and status ~= \"verified\" then\n        log(\"off: \" .. id .. \": \" .. tostring(why or status))\n        return false\n    end\n    return true\nend\nlocal status, status_why = cdal.status(SITE)\nif not checked(SITE, status, status_why) then return end\nstatus, status_why = cdal.status(ROOT)\nif not checked(ROOT, status, status_why) then return end\nstatus, status_why = cdal.status(TYPE)\nif not checked(TYPE, status, status_why) then return end\nlocal capacity_offset, why = cdal.value(CAPACITY)\nif capacity_offset == nil then return log(\"off: \" .. CAPACITY .. \": \" .. tostring(why)) end\nlocal cache_offset\ncache_offset, why = cdal.value(CACHE)\nif cache_offset == nil then return log(\"off: \" .. CACHE .. \": \" .. tostring(why)) end\nlocal name_offset\nname_offset, why = cdal.value(NAME)\nif name_offset == nil then return log(\"off: \" .. NAME .. \": \" .. tostring(why)) end\nif capacity_offset ~= 8 or cache_offset ~= 0x58 or (name_offset ~= 0 and name_offset ~= 8) then\n    return log(\"off: interaction table layout differs from the checked layout\")\nend\nlocal expect = name_offset == 8 and\n    \"48 89 5C 24 08 48 89 74 24 18 57 48 81 EC D0 05 00 00\" or\n    \"48 89 5C 24 08 57 48 81 EC C0 06 00 00 48 8B F9\"\nlocal slot\nslot, why = cdal.address(ROOT)\nif not slot then return log(\"off: \" .. ROOT .. \": \" .. tostring(why)) end\nlocal type_address\ntype_address, why = cdal.address(TYPE)\nif not type_address then return log(\"off: \" .. TYPE .. \": \" .. tostring(why)) end\nlocal type_number = tonumber(ffi.cast(\"uintptr_t\", type_address))\nif not type_number or type_number \u003c 1 or type_number > 9007199254740991 then\n    return log(\"off: manager vtable address is not an exact number\")\nend\nlocal chunk = config.int(\"PetBodyLoot\", \"RowsPerFrame\", 16)\nlocal chord = config.string(\"PetBodyLoot\", \"Hotkey\", \"ctrl+alt+f8\")\nif chunk \u003c 1 or chunk > 64 then return log(\"off: RowsPerFrame must be 1 to 64\") end\n\n-- A condition receiver contains a u16 interaction ordinal at +0x18.\n-- 0xFFFF is not a row ordinal; the paused rule cannot match it accidentally.\nlocal rule\nrule, why = cdal.rule(SITE, {\n    expect = expect, enabled = false,\n    when = {{\"[rcx+0x18].u16\", \"==\", 0xffff}},\n    ret = {\"eax\", 1},\n})\nif not rule then return log(\"off: \" .. SITE .. \": \" .. tostring(why)) end\nlocal live, requested, active = true, false, false\nlocal cursor, snapshot, selected = 0, nil, nil\nlocal function fail(reason)\n    if not live then return end\n    live, requested, active = false, false, false\n    local removed, problem = rule:remove()\n    local message = \"off: \" .. tostring(reason)\n    if not removed then message = message .. \"; could not remove the rule: \" .. tostring(problem) end\n    log(message)\nend\nlocal function pause()\n    if not active then return true end\n    local ok, problem = rule:enable(false)\n    if not ok then fail(\"cannot pause the rule: \" .. tostring(problem)); return false end\n    active = false\n    return true\nend\n\n-- No game function is called: read only the manager and cached rows. Nil is\n-- a read error; zero means the game has not supplied that pointer yet.\nlocal function table_state()\n    local manager, err = mem.read_ptr(slot)\n    if manager == nil then return nil, \"manager pointer: \" .. tostring(err) end\n    if manager == 0 then return false end\n    local vt\n    vt, err = mem.read_ptr(manager)\n    if vt == nil then return nil, \"manager vtable: \" .. tostring(err) end\n    if vt ~= type_number then return false end\n    local count\n    count, err = mem.read_u32(manager + capacity_offset)\n    if count == nil then return nil, \"manager capacity: \" .. tostring(err) end\n    if count > 65535 then return nil, \"manager capacity exceeds 65535\" end\n    local rows\n    rows, err = mem.read_ptr(manager + cache_offset)\n    if rows == nil then return nil, \"row cache: \" .. tostring(err) end\n    if rows == 0 or count == 0 then return false end\n    return {manager = manager, count = count, rows = rows}\nend\nlocal function same_table(a, b)\n    return a and b and a.manager == b.manager and a.count == b.count and a.rows == b.rows\nend\nlocal target = \"Dead_Loot_Pet\"\nlocal function row_name_is_target(rows, ordinal)\n    local row, err = mem.read_ptr(rows + ordinal * 8)\n    if row == nil then return nil, \"row pointer: \" .. tostring(err) end\n    if row == 0 then return false end -- an unloaded cache entry is not a row\n    local holder\n    holder, err = mem.read_ptr(row + name_offset)\n    if holder == nil then return nil, \"row name holder: \" .. tostring(err) end\n    if holder == 0 then return false end\n    local text\n    text, err = mem.read_ptr(holder)\n    if text == nil then return nil, \"row name: \" .. tostring(err) end\n    if text == 0 then return false end\n    -- Compare the complete name, including its terminating NUL, not a prefix.\n    for i = 1, #target + 1 do\n        local byte\n        byte, err = mem.read_u8(text + i - 1)\n        if byte == nil then return nil, \"row name byte: \" .. tostring(err) end\n        if byte ~= (i \u003c= #target and string.byte(target, i) or 0) then return false end\n    end\n    return row\nend\nlocal function toggle()\n    if not live then return end\n    requested = not requested\n    if not requested then\n        if not pause() then return end\n        cursor, snapshot, selected = 0, nil, nil\n        return log(\"off\")\n    end\n    log(\"waiting for the cached Dead_Loot_Pet row\")\nend\nlocal ok\nok, why = pcall(bsx.hotkey, chord, toggle)\nif not ok then fail(\"hotkey unavailable: \" .. tostring(why)); return end\nlocal next_log = os.time() + 10\nok, why = pcall(bsx.on, \"frame\", function()\n    local now = os.time()\n    flush_log(now)\n    if not live then return end\n    if now >= next_log then\n        next_log = now + 10\n        local hits, err = rule:hits()\n        if hits == nil then return fail(\"hit count unavailable: \" .. tostring(err)) end\n        if active then log(\"rule hits: \" .. hits) end\n    end\n    if not requested then return end\n    local state, err = table_state()\n    if state == nil then return fail(err) end\n    if not state then\n        if active then\n            if not pause() then return end\n            l\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[PetBodyLoot]\nHotkey=ctrl+alt+f8\n; Limit how much of the already-loaded interaction table is checked per frame.\nRowsPerFrame=16\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Pet body loot toggle\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"ConditionData_HasInteraction::Evaluate\",\n    \"InteractionInfoManager::sInstance\",\n    \"pa::InteractionInfoManager::vftable\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::InternalName\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"pet_body_toggle","kind":"lua","lua_api":3,"path":"bsx/lua/examples/pet_body_toggle","tier":"safe","title":"Pet body loot toggle","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Pet loose loot toggle: the loose-item switch from Master Looter 1.6.53. Requires Native approval. This has not been tested in game. See bsx/lua/recipes/r2","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Pet loose loot toggle: the loose-item switch from Master Looter 1.6.53.\n-- Requires Native approval. This has not been tested in game.\n-- See bsx/lua/recipes/r2-loot.md for its global effect and limitations.\nlocal function log(message) bsx.log(\"pet loose loot: \" .. message) end\nlocal SITE = \"ConditionData_IsPetLooting::Evaluate\"\nlocal EXPECT = \"48 89 5C 24 08 48 89 74 24 18 48 89 7C 24 20\"\n\n-- Stored values exist only for checked builds, and `expect` below refuses\n-- changed instructions, so an unknown build or a scanned guess stays off.\nlocal status = cdal.status(SITE)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. SITE .. \": \" .. tostring(status))\nend\n\n-- This is a three-valued condition, not a boolean. The ASI returns code 1\n-- for its \"stop loose items\" switch. Other kinds of pet work are separate.\nlocal rule, why = cdal.rule(SITE, {\n    expect = EXPECT,\n    enabled = false,\n    ret = {\"eax\", 1},\n})\nif not rule then return log(\"off: \" .. SITE .. \": \" .. tostring(why)) end\nlocal live = true\nlocal function remove_rule()\n    live = false\n    local removed, reason = rule:remove()\n    if not removed then log(\"could not remove the rule: \" .. tostring(reason)) end\nend\nlocal on = false\nlocal function set_enabled(want)\n    if not live then return false end\n    local changed, reason = rule:enable(want)\n    if not changed then\n        remove_rule()\n        on = false\n        log(\"off: cannot change the rule: \" .. tostring(reason))\n        return false\n    end\n    on = want\n    log(on and \"on: the loose-item condition returns 1 globally\" or \"off\")\n    return true\nend\n\nlocal chord = config.string(\"PetLooseLoot\", \"Hotkey\", \"ctrl+alt+f5\")\nlocal ok\nok, why = pcall(bsx.hotkey, chord, function() set_enabled(not on) end)\nif not ok then remove_rule(); return log(\"off: hotkey unavailable: \" .. tostring(why)) end\nif config.bool(\"PetLooseLoot\", \"Enabled\", false) then\n    if not set_enabled(true) then return end\nelse\n    log(\"off; \" .. chord .. \" toggles the loose-item condition\")\nend\n\nlocal last_count = 0\nlocal function report()\n    if not live then return end\n    local count, reason = rule:hits()\n    if count == nil then log(\"hit counter unavailable: \" .. tostring(reason)); return end\n    if count ~= last_count then log(\"rule hits: \" .. count); last_count = count end\n    local scheduled, failure = pcall(bsx.after, 10000, report)\n    if not scheduled then log(\"hit reporting stopped: \" .. tostring(failure)) end\nend\nok, why = pcall(bsx.after, 10000, report)\nif not ok then log(\"hit reporting unavailable: \" .. tostring(why)) end\n","lang":"lua","name":"main.lua"},{"code":"[PetLooseLoot]\n; Starts paused. Turning it on stops the checked loose-item condition globally.\nEnabled=false\nHotkey=ctrl+alt+f5\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Pet loose loot toggle\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"ConditionData_IsPetLooting::Evaluate\"]\n}\n","lang":"json","name":"script.json"}],"id":"pet_loose_toggle","kind":"lua","lua_api":3,"path":"bsx/lua/examples/pet_loose_toggle","tier":"safe","title":"Pet loose loot toggle","uses":[]},{"category":"Camera, Movement & Flight","description":"Lua API 4 screenshot and framing studio powered by verified BSX camera, DOF, raycast, and time/weather helpers.","featured":false,"files":[{"code":"-- Photo Studio: Lua API 4 screenshot studio with Free Cam, roll tilt, DOF override,\n-- raycast/camera teleports, time/weather presets, and persistent camera bookmarks.\n\nlocal function clamp(v, lo, hi)\n    if type(v) ~= \"number\" or v ~= v then return lo end\n    if v \u003c lo then return lo end\n    if v > hi then return hi end\n    return v\nend\n\nlocal function clamp_text(text)\n    local s = tostring(text or \"\"):gsub(\"%z\", \" \")\n    if #s \u003c= 127 then return s end\n    return string.sub(s, 1, 124) .. \"...\"\nend\n\nlocal function toast_msg(msg, level)\n    if bsx.ui and bsx.ui.toast then\n        bsx.ui.toast(clamp_text(msg), { level = level or \"info\", duration_ms = 2600 })\n    end\nend\n\nlocal function json_encode_flat(tbl)\n    local keys = {}\n    for k in pairs(tbl) do\n        if type(k) == \"string\" then keys[#keys + 1] = k end\n    end\n    table.sort(keys)\n    local lines = { \"{\" }\n    for i = 1, #keys do\n        local k = keys[i]\n        local v = tbl[k]\n        local vs\n        if type(v) == \"boolean\" then\n            vs = v and \"true\" or \"false\"\n        elseif type(v) == \"number\" then\n            vs = string.format(\"%.6f\", v)\n        else\n            vs = '\"' .. tostring(v or \"\"):gsub('\\\\', '\\\\\\\\'):gsub('\"', '\\\\\"') .. '\"'\n        end\n        local comma = (i \u003c #keys) and \",\" or \"\"\n        lines[#lines + 1] = '  \"' .. k .. '\": ' .. vs .. comma\n    end\n    lines[#lines + 1] = \"}\"\n    return table.concat(lines, \"\\n\") .. \"\\n\"\nend\n\nlocal function json_decode_flat(text)\n    if type(text) ~= \"string\" then return nil end\n    local out = {}\n    local pos = 1\n    local len = #text\n    while pos \u003c= len do\n        local nl = string.find(text, \"\\n\", pos, true)\n        local line = nl and string.sub(text, pos, nl - 1) or string.sub(text, pos)\n        pos = nl and (nl + 1) or (len + 1)\n        local q1 = string.find(line, '\"', 1, true)\n        if q1 then\n            local q2 = string.find(line, '\"', q1 + 1, true)\n            if q2 then\n                local col = string.find(line, \":\", q2 + 1, true)\n                if col then\n                    local key = string.sub(line, q1 + 1, q2 - 1)\n                    local val_str = string.sub(line, col + 1)\n                    -- trim whitespace and trailing comma with zero-quantifier plain finds\n                    while #val_str > 0 and (string.sub(val_str, 1, 1) == \" \" or string.sub(val_str, 1, 1) == \"\\t\") do\n                        val_str = string.sub(val_str, 2)\n                    end\n                    while #val_str > 0 do\n                        local last = string.sub(val_str, -1)\n                        if last == \" \" or last == \"\\t\" or last == \"\\r\" or last == \",\" then\n                            val_str = string.sub(val_str, 1, -2)\n                        else\n                            break\n                        end\n                    end\n                    if val_str == \"true\" then\n                        out[key] = true\n                    elseif val_str == \"false\" then\n                        out[key] = false\n                    elseif string.sub(val_str, 1, 1) == '\"' and string.sub(val_str, -1) == '\"' and #val_str >= 2 then\n                        out[key] = string.sub(val_str, 2, -2)\n                    else\n                        local num = tonumber(val_str)\n                        if num ~= nil then out[key] = num end\n                    end\n                end\n            end\n        end\n    end\n    return out\nend\n\nlocal freecam_hotkey = config.string(\"PhotoStudio\", \"FreeCamHotkey\", \"f8\")\nlocal freecam_speed = clamp(config.float(\"PhotoStudio\", \"FreeCamSpeed\", 20.0), 1.0, 200.0)\nlocal fov_deg = clamp(config.float(\"PhotoStudio\", \"FovDeg\", 65.0), 30.0, 140.0)\nlocal roll_deg = clamp(config.float(\"PhotoStudio\", \"RollDeg\", 0.0), -180.0, 180.0)\nlocal slowmo_speed = clamp(config.float(\"PhotoStudio\", \"SlowMoSpeed\", 0.05), 0.05, 1.0)\nlocal dof_override = false\nlocal dof_enabled = config.bool(\"PhotoStudio\", \"DofEnabled\", false)\nlocal dof_focus = clamp(config.float(\"PhotoStudio\", \"DofFocus\", 5.0), 0.5, 250.0)\nlocal dof_focal = clamp(config.float(\"PhotoStudio\", \"DofFocal\", 35.0), 10.0, 200.0)\nlocal dof_aperture = clamp(config.float(\"PhotoStudio\", \"DofAperture\", 2.8), 1.0, 22.0)\nlocal dof_bokeh = clamp(config.float(\"PhotoStudio\", \"DofBokeh\", 4.0), 0.0, 16.0)\n\nlocal freecam_active = false\nlocal fov_active = false\nlocal world_ready = false\nlocal logged_ready = false\n\nlocal TIME_LABELS = { \"Dawn (06:00)\", \"Noon (12:00)\", \"Golden Hour (17:30)\", \"Dusk (19:30)\", \"Midnight (00:00)\" }\nlocal TIME_HM = { { 6, 0 }, { 12, 0 }, { 17, 30 }, { 19, 30 }, { 0, 0 } }\nlocal WEATHER_LABELS = { \"Clear\", \"Overcast\", \"Light Rain\", \"Storm\", \"Snow\" }\nlocal WEATHER_PRESETS = {\n    { rain = 0.0, snow = 0.0, precipitation = 0.0, humidity = 0.2, cloudiness = 0.1, wind_direction = 90, wind_speed = 2 },\n    { rain = 0.0, snow = 0.0, precipitation = 0.1, humidity = 0.6, cloudiness = 0.85, wind_direction = 120, wind_speed = 6 },\n    { rain = 0.45, snow = 0.0, precipitation = 0.45, humidity = 0.78, cloudiness = 0.7, wind_direction = 150, wind_speed = 10 },\n    { rain = 1.0, snow = 0.0, precipitation = 1.0, humidity = 0.96, cloudiness = 1.0, wind_direction = 225, wind_speed = 24 },\n    { rain = 0.0, snow = 0.9, precipitation = 0.9, humidity = 0.82, cloudiness = 0.88, wind_direction = 0, wind_speed = 9 },\n}\nlocal BM_LABELS = { \"Slot 1\", \"Slot 2\", \"Slot 3\" }\n\nlocal time_idx = 2\nlocal weather_idx = 1\nlocal bm_idx = 1\nlocal bookmarks = { {}, {}, {} }\n\nlocal panel = bsx.ui.panel(\"Photo Studio\")\nlocal dof_panel = bsx.ui.panel(\"Photo Studio: DOF & Lighting\")\n\nlocal status_id = panel:text(\"Photo Studio: waiting for world_ready...\")\nlocal pose_id = panel:text(\"Cam: -- | Player: --\")\nlocal dof_status_id = dof_panel:text(\"DOF: native (waiting for world_ready...)\")\n\nlocal freecam_cb_id, freecam_hk_id, speed_slider_id, fov_slider_id, roll_slider_id\nlocal bm_info_id, bm_combo_id\nlocal dof_ov_cb_id, dof_en_cb_id, dof_focus_id, dof_focal_id, dof_aperture_id, dof_bokeh_id\nlocal freecam_hotkey_handle = nil\n\nlocal function set_status(msg)\n    panel:set_text(status_id, clamp_text(msg))\nend\n\nlocal function update_bookmark_info()\n    local b = bookmarks[bm_idx]\n    if b and b.set then\n        panel:set_text(bm_info_id, clamp_text(string.format(\n            \"Slot %d: (%.1f, %.1f, %.1f) fov=%.0f roll=%.0f\",\n            bm_idx, b.x or 0, b.y or 0, b.z or 0, b.fov or 65, b.roll or 0)))\n    else\n        panel:set_text(bm_info_id, \"Slot \" .. tostring(bm_idx) .. \": empty\")\n    end\nend\n\nlocal function load_bookmarks_disk()\n    if not (bsx.fs and bsx.fs.read) then return update_bookmark_info() end\n    local rok, raw = pcall(bsx.fs.read, \"bookmarks.json\")\n    local flat = (rok and type(raw) == \"string\") and json_decode_flat(raw) or nil\n    if not flat then return update_bookmark_info() end\n    for i = 1, 3 do\n        local pfx = \"b\" .. tostring(i) .. \"_\"\n        if flat[pfx .. \"set\"] == true then\n            bookmarks[i] = {\n                set = true,\n                x = tonumber(flat[pfx .. \"x\"]) or 0,\n                y = tonumber(flat[pfx .. \"y\"]) or 0,\n                z = tonumber(flat[pfx .. \"z\"]) or 0,\n                fov = tonumber(flat[pfx .. \"fov\"]) or 65,\n                roll = tonumber(flat[pfx .. \"roll\"]) or 0,\n                dof_ov = flat[pfx .. \"dof_ov\"] == true,\n                dof_en = flat[pfx .. \"dof_en\"] == true,\n                dof_focus = tonumber(flat[pfx .. \"dof_focus\"]) or 5.0,\n                dof_focal = tonumber(flat[pfx .. \"dof_focal\"]) or 35.0,\n                dof_aperture = tonumber(flat[pfx .. \"dof_aperture\"]) or 2.8,\n                dof_bokeh = tonumber(flat[pfx .. \"dof_bokeh\"]) or 4.0,\n            }\n        end\n    end\n    update_bookmark_info()\nend\n\nlocal function save_bookmarks_disk()\n    if not (bsx.fs and bsx.fs.write) then return false, \"bsx.fs.write unavailable\" end\n    local flat = {}\n    for i = 1, 3 do\n        local b = bookmarks[i]\n        local pfx = \"b\" .. tostring(i) .. \"_\"\n        flat[pfx .. \"set\"] = b.set == true\n        if b.set then\n            flat[pfx .. \"x\"] = b.x or 0\n            flat[pfx .. \"y\"] = b.y or 0\n            flat[pfx .. \"z\"] = b.z or 0\n            flat[pfx .. \"fov\"] = b.fov or 65\n            flat[pfx ..\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[PhotoStudio]\nFreeCamHotkey=f8\nFreeCamSpeed=20.0\nFovDeg=65.0\nRollDeg=0.0\nDofEnabled=0\nDofFocus=5.0\nDofFocal=35.0\nDofAperture=2.8\nDofBokeh=4.0\nSlowMoSpeed=0.05\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Photo Studio\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"snapshots\", \"positions\", \"world\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"photo_studio","kind":"lua","lua_api":4,"path":"bsx/lua/examples/photo_studio","tier":"changes","title":"Photo Studio","uses":["ui","snapshots","positions","world","server_commands"]},{"category":"BSX Core & Diagnostics","description":"Lua API 2 example: finds the controlled character and its components once a save has loaded. Copy this folder to BSX/scripts/player_status. Everything here only reads; nothing changes the game. Every ID the game helpers ","featured":false,"files":[{"code":"-- Lua API 2 example: finds the controlled character and its components once a save has loaded.\n-- Copy this folder to BSX/scripts/player_status. Everything here only reads; nothing changes the game.\n-- Every ID the game helpers walk is listed in script.json, so a game build that lacks one shows\n-- \"off: needs X\" in the status list instead of failing later.\n\nlocal function report(when)\n    local actor, why = game.player()\n    if not actor then return bsx.log(when .. \": no player (\" .. why .. \")\") end\n    local equipment, why_equipment = game.equipment(actor)\n    local stats, why_stats = game.stats(actor)\n    bsx.log(string.format(\"%s: player 0x%X, equipment %s, stats %s\", when, actor,\n        equipment and string.format(\"0x%X\", equipment) or why_equipment,\n        stats and string.format(\"0x%X\", stats) or why_stats))\nend\n\nreport(\"at start\")\n\n-- save_loaded is a completion event: it fires once the world is ready after a save load.\nlocal ok, why = pcall(bsx.on, \"save_loaded\", function() report(\"after the save loaded\") end)\nif not ok then\n    -- Without it, look once a second until a player exists.\n    bsx.log(\"no save_loaded event on this build (\" .. tostring(why) .. \"), checking every second\")\n    local function poll()\n        if game.player() then report(\"player found\") else bsx.after(1000, poll) end\n    end\n    bsx.after(1000, poll)\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Player Status\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 2,\n  \"native\": false,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\",\n    \"ActorComponents::Equipment\",\n    \"ActorComponents::Status\",\n    \"CommonStatusActorComponent::StatContainer\",\n    \"pa::ClientEquipSlotActorComponent::vftable\"\n  ],\n  \"needs_plugins\": [],\n  \"packs\": []\n}\n","lang":"json","name":"script.json"}],"id":"player_status","kind":"lua","lua_api":2,"path":"bsx/lua/examples/player_status","tier":"safe","title":"Player Status","uses":[]},{"category":"UI & Overlays","description":"Overlay control panel for live player stats (HP, Stamina, MP, 12 Hz **Keep HP**/**Stam**/**MP**), Money (`2075`, `100 copper = 1 silver` display + `+100 Silver (10k)` / `+10k Silver (1M)`), cooperative **Search Item**, *","featured":false,"files":[{"code":"-- Player Toolkit: Lua API 4 overlay panel using BSX.Lua.UI/5 theming, tabs,\n-- searchable categorized item catalog, stats/keep-full, currency, and gear loadouts.\n\nlocal function clamp(value, low, high)\n    if type(value) ~= \"number\" or value ~= value then return low end\n    if value \u003c low then return low end\n    if value > high then return high end\n    return value\nend\n\nlocal function trim_utf8(text, max_bytes, ellipsis)\n    local s = tostring(text or \"\"):gsub(\"[%z\\1-\\31]\", \" \")\n    if #s \u003c= max_bytes then return s end\n    local suf = ellipsis or \"...\"\n    local cap = math.max(1, max_bytes - #suf)\n    while cap > 1 do\n        local b = string.byte(s, cap + 1)\n        if not b or b \u003c 0x80 or b >= 0xC0 then break end\n        cap = cap - 1\n    end\n    return string.sub(s, 1, cap) .. suf\nend\n\nlocal function clamp_text(text)\n    return trim_utf8(text, 127, \"...\")\nend\n\nlocal function pack_combo_items(list, fallback)\n    local out = {}\n    local bytes = 0\n    for i = 1, #list do\n        local s = trim_utf8(list[i], 28, \"...\")\n        if #s > 0 and (bytes + #s + 1) \u003c= 250 then\n            out[#out + 1] = s\n            bytes = bytes + #s + 1\n        end\n        if #out >= 8 then break end\n    end\n    if #out == 0 then\n        out[1] = fallback or \"(empty)\"\n    end\n    return out\nend\n\nlocal MAX_LISTBOX_ITEMS = 1500\nlocal MAX_LISTBOX_BYTES = 115000\n\nlocal function listbox_entry_bytes(entry)\n    local lbl = tostring(entry.label or \"\")\n    local cat = tostring(entry.category or \"\")\n    if #cat > 0 then\n        return #cat + 1 + #lbl + 1\n    end\n    return #lbl + 1\nend\n\nlocal refresh_seconds = clamp(config.float(\"PlayerToolkit\", \"RefreshSeconds\", 0.5), 0.25, 10.0)\nlocal item_row = math.floor(clamp(config.int(\"PlayerToolkit\", \"DefaultItemRow\", 2075), 0, 65534))\nlocal item_qty = math.floor(clamp(config.int(\"PlayerToolkit\", \"DefaultQty\", 1), 1, 100))\n\nlocal STAT_IDS = { 0, 25, 26 }\nlocal STAT_DEFAULTS = { \"HP\", \"Stamina\", \"MP\" }\nlocal STAT_LABELS = { \"HP [id:0]\", \"Stamina [id:25]\", \"MP [id:26]\" }\nlocal COPPER_ROW = 2075\n\nlocal stat_idx = 1\nlocal world_ready = false\nlocal logged_panel = false\nlocal logged_ready = false\nlocal stat_names_loaded = false\n\nlocal keep_hp = false\nlocal keep_stam = false\nlocal keep_mp = false\nlocal last_keep_poll = 0\n\nlocal cat_name_cache = {}\nlocal item_meta_cache = {}\nlocal view_mode = \"catalog\"\n\nlocal catalog_started = false\nlocal catalog_indexing = false\nlocal catalog_use_fast_search = true\nlocal catalog_cursor = 0\nlocal catalog_entries = {\n    { row = COPPER_ROW, label = \"2075: Money_Copper\", category = \"Currency\" },\n}\nlocal catalog_bytes = 0\nlocal catalog_last_push_count = 0\n\nlocal search_query = \"\"\nlocal search_cursor = nil\nlocal search_active = false\nlocal search_use_fast = true\nlocal search_hits = {}\nlocal search_bytes = 0\n\nlocal picker_entries = {\n    { row = COPPER_ROW, label = \"2075: Money_Copper\", category = \"Currency\" },\n}\nlocal selected_bag_row = nil\nlocal selected_bag_bucket = nil\nlocal selected_bag_index = nil\n\nlocal equipped_slots = {}\nlocal equipped_labels = { \"(press Refresh Gear)\" }\nlocal selected_slot_idx = 1\nlocal LOADOUT_LABELS = { \"Slot 1\", \"Slot 2\", \"Slot 3\" }\nlocal loadout_idx = 1\n\nlocal last_summary = {\n    world_ready = false,\n    stat_id = STAT_IDS[stat_idx],\n    item_row = item_row,\n    item_qty = item_qty,\n    copper = nil,\n}\n\nlocal TOOLKIT_THEME = {\n    accent = \"#C84B52\",\n    header = \"#3E1B20\",\n    child_bg = \"#141318\",\n    frame_bg = \"#201E27\",\n    border = \"#5A333D\",\n    text = \"#F2EFF6\",\n}\n\nlocal panel = bsx.ui.panel(\"Player Toolkit\")\nlocal gear_panel = bsx.ui.panel(\"Equipment & Loadouts\")\npanel:set_theme(TOOLKIT_THEME)\ngear_panel:set_theme(TOOLKIT_THEME)\n\nlocal status_id\nlocal stats_readout_id\nlocal hp_bar_id\nlocal stat_combo_id\nlocal copper_id\nlocal catalog_listbox_id\nlocal search_input_id\nlocal row_input_id\nlocal item_info_id\nlocal qty_slider_id\nlocal equip_info_id\nlocal slot_combo_id\nlocal loadout_combo_id\n\nlocal function format_stat(st)\n    if not st then return \"--/--\" end\n    return string.format(\"%d/%d\", st.current or 0, st.max or 0)\nend\n\nlocal function format_currency(copper_str)\n    local n = tonumber(copper_str)\n    if not n then return tostring(copper_str or \"--\") end\n    local whole = math.floor(n)\n    local silver = math.floor(whole / 100)\n    local copper = whole % 100\n    return string.format(\"%ds %02dc (%d copper)\", silver, copper, whole)\nend\n\nlocal function resolve_stat_labels()\n    if stat_names_loaded then return end\n    local updated = false\n    for i = 1, #STAT_IDS do\n        local name = game.stat_name(STAT_IDS[i])\n        if name and #name > 0 then\n            STAT_LABELS[i] = string.format(\"%s [id:%d]\", name, STAT_IDS[i])\n            updated = true\n        else\n            STAT_LABELS[i] = string.format(\"%s [id:%d]\", STAT_DEFAULTS[i], STAT_IDS[i])\n        end\n    end\n    if updated then\n        stat_names_loaded = true\n        panel:set_items(stat_combo_id, pack_combo_items(STAT_LABELS, \"HP [id:0]\"), stat_idx)\n    end\nend\n\nlocal function tidy_category_name(raw)\n    local s = tostring(raw or \"\"):gsub(\"[%z\\1-\\31]\", \" \")\n    s = s:gsub(\"^[Cc]ategory_\", \"\"):gsub(\"_\", \" \"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    if s == \"\" then return nil end\n    return trim_utf8(s, 28, \"..\")\nend\n\nlocal function resolve_category_label(cat_row, item_name, item_type)\n    if cat_row ~= nil then\n        local cached = cat_name_cache[cat_row]\n        if cached ~= nil then return cached end\n        local resolved = nil\n        if game.categories and game.categories.info then\n            local info = game.categories.info(cat_row)\n            if info then\n                resolved = tidy_category_name(info.display_name) or tidy_category_name(info.name)\n            end\n        end\n        resolved = resolved or (\"Cat \" .. tostring(cat_row))\n        cat_name_cache[cat_row] = resolved\n        return resolved\n    end\n    if type(item_name) == \"string\" and item_name:sub(1, 6) == \"Money_\" then\n        return \"Currency\"\n    end\n    if item_type ~= nil then\n        return \"Type \" .. tostring(item_type)\n    end\n    return \"Items\"\nend\n\nlocal function ensure_item_meta(row)\n    local meta = item_meta_cache[row]\n    if meta then return meta end\n    if game.items and game.items.search then\n        local hits = game.items.search(tostring(row), 4, row)\n        if hits then\n            for i = 1, #hits do\n                local h = hits[i]\n                item_meta_cache[h.row] = h\n                if h.row == row then return h end\n            end\n        end\n    end\n    return nil\nend\n\nlocal function update_item_info()\n    local meta = item_meta_cache[item_row]\n    local info, why = game.item_info(item_row)\n    local disp = (info and info.display_name) or (meta and meta.display_name) or game.item_display_name(item_row)\n    local name = (info and info.name) or (meta and meta.name) or game.item_name(item_row) or (info and tostring(info.key or \"?\"))\n    if disp or name then\n        local title = (disp and disp ~= \"\" and name and disp ~= name)\n            and string.format(\"%s (%s)\", tostring(disp), tostring(name))\n            or tostring(disp or name or \"?\")\n        local cat_txt = meta and resolve_category_label(meta.category_row, meta.name, meta.item_type) or nil\n        local stack_val = (info and info.max_stack) or (meta and meta.max_stack)\n        local dur_val = (meta and meta.max_durability ~= nil and meta.max_durability ~= 65535) and meta.max_durability or nil\n        local parts = { string.format(\"Row %d: %s\", item_row, title) }\n        if cat_txt then parts[#parts + 1] = \"Cat: \" .. cat_txt end\n        if stack_val ~= nil then parts[#parts + 1] = \"Stack: \" .. tostring(stack_val) end\n        if dur_val ~= nil then parts[#parts + 1] = \"Dur: \" .. tostring(dur_val) end\n        panel:set_text(item_info_id, clamp_text(table.concat(parts, \" | \")))\n    else\n        panel:set_text(item_info_id, clamp_text(string.format(\"Row %d: %s\", item_row, tostring(why or \"unavailable\"))))\n    end\nend\n\nlocal function format_listbox_entry(entry, extra_suffix)\n    local r = entry.row\n    local disp = entry.display_name\n    local name = entry.name\n    local base\n    if disp and disp ~= \"\" and name and disp ~= name then\n        base = s\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[PlayerToolkit]\nRefreshSeconds=1.0\nDefaultItemRow=2075\nDefaultQty=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Player Toolkit\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"inventory\", \"definitions\", \"server_commands\", \"bus\"],\n  \"needs_ids\": [\n    \"ItemInfo::MaxStackCount\",\n    \"ItemInfo::MaxDurability\",\n    \"ItemInfo::CategoryRow\",\n    \"ItemInfo::ItemType\",\n    \"ItemInfo::DisplayName\",\n    \"Localization::sTextPoolManager\",\n    \"CommonEquipSlotActorComponent::StorageOffset\",\n    \"EquipmentSlotRecord::Stride\",\n    \"EquipmentSlotRecord::SlotTag\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"player_toolkit","kind":"lua","lua_api":4,"path":"bsx/lua/examples/player_toolkit","tier":"changes","title":"Player Toolkit","uses":["ui","player","snapshots","inventory","definitions","server_commands","bus"]},{"category":"Combat & Stats","description":"Ctrl+Shift+F6 requests one default use of the first matching inventory item.","featured":false,"files":[{"code":"-- Ctrl+Shift+F6 requests one default use of the first matching inventory item.\nlocal row = config.int(\"QuickPotion\", \"ItemRow\", -1)\nlocal pending, loaded, frame = nil, false, 0\nlocal function log(s) bsx.log(\"quick_potion: \" .. s) end\nlocal function cancel(why)\n    if pending then log(\"cancelled: \" .. why) end\n    pending = nil\nend\nlocal function offset(name) return assert(cdal.value(name)) end\nlocal function ptr(at)\n    local p, why = mem.read_ptr(at)\n    assert(p and p ~= 0, why or \"null pointer\")\n    return p\nend\nlocal function u16(at) return assert(mem.read_u8(at)) + 256 * assert(mem.read_u8(at + 1)) end\nlocal function player()\n    local actor = assert(game.player())\n    return actor, assert(mem.read_u32(actor + offset(\"Actor::Key\")))\nend\nlocal function count()\n    local n = tonumber(assert(game.inventory.count(row)))\n    assert(n and n >= 0 and n \u003c= 9007199254740991, \"count exceeds exact Lua range\")\n    return n\nend\nlocal function first_item(actor)\n    local holder = ptr(ptr(actor + offset(\"Actor::Components\")) + offset(\"ActorComponents::Inventory\"))\n    assert(ptr(holder) == cdal.address(\"pa::ClientInventoryActorComponent::vftable\"), \"inventory type\")\n    local n = assert(mem.read_u32(holder + offset(\"InventoryHolder::BucketCount\")))\n    assert(n \u003c= 256, \"bucket bound\")\n    local buckets = n > 0 and ptr(holder + offset(\"InventoryHolder::Buckets\")) or 0\n    local visited = 0\n    for b = 0, n - 1 do\n        local bucket = ptr(buckets + b * 8)\n        local capacity = u16(bucket + offset(\"InventoryBucket::SlotCount\"))\n        visited = visited + capacity\n        assert(capacity \u003c= 4096 and visited \u003c= 4096, \"inventory bound\")\n        local slots = capacity > 0 and ptr(bucket) or 0\n        for i = 0, capacity - 1 do\n            local item = slots + i * offset(\"InventoryItem::Stride\")\n            local amount = assert(mem.read_u64(item + offset(\"InventoryItem::Amount\")))\n            if u16(item + offset(\"InventoryItem::Row\")) == row and amount ~= \"0\"\n                and (#amount \u003c 19 or (#amount == 19 and amount \u003c \"9223372036854775808\")) then\n                return u16(bucket + 0x10), i -- external bucket tag, not ordinal\n            end\n        end\n    end\n    error(\"configured item is absent\")\nend\nlocal events, event_error = pcall(function()\n    bsx.on(\"quick_slot_use_after\", function(e)\n        if not pending or e.storage ~= pending.bucket or e.index ~= pending.index\n            or e.amount ~= \"1\" or e.use_parameter ~= 65535 then return end\n        log(\"QUICK_SLOT_USE_AFTER (22) result=\" .. e.result .. \"; return observation only\")\n        pending.returned = true\n    end)\n    bsx.on(\"save_loaded\", function() cancel(\"replacement save\"); loaded = true end)\n    bsx.on(\"save_load\", function() cancel(\"save request\"); loaded = false end)\n    bsx.on(\"load_request\", function() cancel(\"loading request\"); loaded = false end)\n    bsx.on(\"title_screen\", function() cancel(\"title screen\"); loaded = false end)\nend)\nif not events then log(\"required events unavailable: \" .. tostring(event_error)) end\nif not game.request then log(\"read-only; changes approval required\") end\nif row \u003c 0 or row > 65534 then log(\"choose ItemRow in settings.ini and approve its digest\") end\nbsx.on(\"key\", function(e)\n    if e.virtual_key ~= 117 or e.modifiers ~= 5 or not e.down or e['repeat'] or e.reset then return end\n    if not events or not game.request or row \u003c 0 or row > 65534 then return end\n    if not loaded then log(\"wait for a loaded save and normal player control\"); return end\n    if pending then log(\"already waiting; no additional request\"); return end\n    local ok, why = pcall(function()\n        local actor, key = player()\n        local bucket, index = first_item(actor)\n        pending = {actor = actor, key = key, bucket = bucket, index = index,\n            before = count(), deadline = frame + 600, returned = false}\n        local queued, reason = game.request.use_item(bucket, index)\n        if not queued then cancel(\"request refused or uncertain: \" .. tostring(reason)); return end\n        log(\"queued row=\" .. row .. \" bucket=\" .. bucket .. \" index=\" .. index)\n    end)\n    if not ok then cancel(tostring(why)); log(\"request stopped: \" .. tostring(why)) end\nend)\nbsx.on(\"frame\", function(e)\n    frame = e.frame\n    if not pending then return end\n    local ok, why = pcall(function()\n        local actor, key = player()\n        assert(actor == pending.actor and key == pending.key, \"player changed\")\n        local now = count()\n        if pending.returned and now == pending.before - 1 then\n            log(\"inventory row decreased by one; verify the potion effect in game\")\n            pending = nil\n        elseif now ~= pending.before and now ~= pending.before - 1 then\n            cancel(\"inventory changed unexpectedly\")\n        elseif frame >= pending.deadline then cancel(\"timeout; no automatic retry\") end\n    end)\n    if not ok then cancel(tostring(why)) end\nend)\n","lang":"lua","name":"main.lua"},{"code":"[QuickPotion]\n; ItemInfo row ordinal for a reviewed consumable, not its external key.\n; -1 keeps the example idle. Edit before approving the folder digest.\nItemRow=-1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Quick potion\",\n  \"version\": \"1\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\", \"WorldSystem::ActorManager\", \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\", \"pa::ClientNormalInGameActor::vftable\", \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Key\", \"Actor::Components\", \"ActorComponents::Inventory\", \"ActorComponents::Equipment\",\n    \"pa::ClientInventoryActorComponent::vftable\", \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"InventoryHolder::Buckets\", \"InventoryHolder::BucketCount\", \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\", \"InventoryItem::Row\", \"InventoryItem::Amount\",\n    \"Inventory::GetHolder\", \"Inventory::GetItem\", \"Inventory::GetBucketForItemRow\",\n    \"UsableItem::Use\", \"ClientRequest::UseItemPacketKind\", \"ClientRequest::SendPacket\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"quick_potion","kind":"lua","lua_api":3,"path":"bsx/lua/examples/quick_potion","tier":"changes","title":"Quick potion","uses":[]},{"category":"BSX Core & Diagnostics","description":"Raycast Projectiles Cookbook (Lua API 7+, Changes tier) Demonstrates R2 3D Havok raycast (`game.world.raycast_segment` + `game.world.raycast_dir`) driving native `.effect` projectiles: 1. Gravity arc -> terrain hit -> do","featured":false,"files":[{"code":"-- Raycast Projectiles Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates R2 3D Havok raycast (`game.world.raycast_segment` + `game.world.raycast_dir`)\n-- driving native `.effect` projectiles:\n--   1. Gravity arc -> terrain hit -> downward raycast_dir surface-clamped ground hazard\n--   2. Surface-normal bounce reflection `v' = v - 2(v·n)n` off wall (`z = -4356, nz = -1`)\n--   3. Homing + piercing (`layer = 0x01` bypass after hitting actor sphere `Npc_Guard` key 1002)\n--   4. Helical spiral trajectory stepped with `raycast_segment`\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal state = {\n    world_ready = false,\n    started = false,\n    done = false,\n    step = 0,\n    projs = {},\n    handles = {},\n    metrics = { arc_hits = 0, bounces = 0, pierces = 0, zones = 0, spiral_steps = 0 },\n    status = \"Waiting for world_ready...\",\n}\n\nlocal panel, status_lbl\n\nlocal function pick_fx(query, fallback)\n    if game.vfx and game.vfx.catalog then\n        local ok, res = pcall(game.vfx.catalog, query, 20)\n        if ok and type(res) == \"table\" then\n            for i = 1, #res do\n                local p = res[i].path\n                if type(p) == \"string\" and not p:lower():find(\"pure_gpu\", 1, true) then\n                    return p\n                end\n            end\n        end\n    end\n    return fallback\nend\n\nlocal function spawn_fx(path, x, y, z, scale, dur)\n    local h = game.vfx.spawn({ path = path, pos = { x, y, z }, scale = scale or 1.0, duration = dur or 2.5 })\n    if h then state.handles[#state.handles + 1] = h end\n    return h\nend\n\nlocal function clamp_ground_zone(fx_path, hx, hy, hz)\n    local hit = assert(game.world.raycast_dir(hx, hy + 1.5, hz, 0.0, -1.0, 0.0, 12.0, 0x01))\n    local gx, gy, gz = hx, hy, hz\n    if hit.hit then\n        gx, gy, gz = hit.x, hit.y + 0.05, hit.z\n        state.metrics.zones = state.metrics.zones + 1\n    end\n    spawn_fx(fx_path, gx, gy, gz, 1.25, 3.0)\nend\n\nlocal function launch_demos()\n    state.started = true\n    local fire_fx = pick_fx(\"fireball_loop\", \"effect/magic/fireball_loop.level.effect\")\n    local hit_fx  = pick_fx(\"fireball_hit\", \"effect/magic/fireball_hit.action.effect\")\n    local ice_fx  = pick_fx(\"frost_nova\", \"effect/magic/ice_frost_nova.action.effect\")\n    local shad_fx = pick_fx(\"shadow_vortex\", \"effect/magic/shadow_vortex.level.effect\")\n\n    -- 1) Gravity Arc -> hits terrain y=612 -> surface-clamped ground zone\n    state.projs[1] = {\n        kind = \"arc\",\n        x = -10500.0, y = 613.5, z = -4375.0,\n        vx = 0.0, vy = 2.0, vz = 18.0,\n        gravity = 14.0,\n        fx = fire_fx, impact = hit_fx,\n        h = spawn_fx(fire_fx, -10500.0, 613.5, -4375.0, 1.1, 3.0),\n        alive = true,\n    }\n\n    -- 2) Surface-Normal Bounce toward MockWorld player wall (z = -4356, nz = -1)\n    state.projs[2] = {\n        kind = \"bounce\",\n        x = -10500.0, y = 613.5, z = -4360.0,\n        vx = 0.0, vy = 0.0, vz = 24.0,\n        bounces = 0, max_bounces = 2,\n        fx = ice_fx, impact = ice_fx,\n        h = spawn_fx(ice_fx, -10500.0, 613.5, -4360.0, 1.0, 3.0),\n        alive = true,\n    }\n\n    -- 3) Homing + Piercing toward Npc_Guard (-10490, 613, -4370) key=1002\n    state.projs[3] = {\n        kind = \"pierce\",\n        x = -10500.0, y = 613.0, z = -4375.0,\n        vx = 20.0, vy = 0.0, vz = 10.0,\n        tx = -10490.0, ty = 613.0, tz = -4370.0,\n        pierced = {},\n        fx = shad_fx, impact = hit_fx,\n        h = spawn_fx(shad_fx, -10500.0, 613.0, -4375.0, 1.0, 3.0),\n        alive = true,\n    }\n\n    -- 4) Spiral projectile along +Z\n    state.projs[4] = {\n        kind = \"spiral\",\n        x = -10502.0, y = 613.2, z = -4375.0,\n        vx = 0.0, vy = 0.0, vz = 18.0,\n        vis_x = -10502.0, vis_y = 613.2, vis_z = -4375.0,\n        age = 0.0,\n        fx = fire_fx, impact = hit_fx,\n        h = spawn_fx(fire_fx, -10502.0, 613.2, -4375.0, 0.85, 3.0),\n        alive = true,\n    }\n\n    state.status = \"Launched 4 raycast projectile demos\"\n    if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\nend\n\nlocal function step_projectiles(dt)\n    for i = 1, #state.projs do\n        local p = state.projs[i]\n        if p.alive then\n            p.age = (p.age or 0.0) + dt\n            if p.kind == \"arc\" then\n                p.vy = p.vy - p.gravity * dt\n            elseif p.kind == \"pierce\" then\n                local dx, dy, dz = p.tx - p.x, p.ty - p.y, p.tz - p.z\n                local len = math.sqrt(dx * dx + dy * dy + dz * dz)\n                if len > 0.5 then\n                    local spd = math.sqrt(p.vx * p.vx + p.vy * p.vy + p.vz * p.vz)\n                    p.vx, p.vy, p.vz = (dx / len) * spd, (dy / len) * spd, (dz / len) * spd\n                end\n            end\n\n            local nx, ny, nz = p.x + p.vx * dt, p.y + p.vy * dt, p.z + p.vz * dt\n            local sx1, sy1, sz1 = p.vis_x or p.x, p.vis_y or p.y, p.vis_z or p.z\n            local sx2, sy2, sz2 = nx, ny, nz\n\n            if p.kind == \"spiral\" then\n                local th = p.age * 12.0\n                sx2 = nx + math.cos(th) * 0.45\n                sy2 = ny + math.sin(th) * 0.45\n                state.metrics.spiral_steps = state.metrics.spiral_steps + 1\n            end\n\n            local hit = game.world.raycast_segment(sx1, sy1, sz1, sx2, sy2, sz2, 0x55)\n            if hit and hit.hit and hit.actor_key ~= 0 and p.pierced and p.pierced[hit.actor_key] then\n                hit = game.world.raycast_segment(sx1, sy1, sz1, sx2, sy2, sz2, 0x01)\n            end\n\n            if hit and hit.hit then\n                if p.kind == \"bounce\" and p.bounces \u003c p.max_bounces then\n                    local dot = p.vx * hit.nx + p.vy * hit.ny + p.vz * hit.nz\n                    p.vx = p.vx - 2.0 * dot * hit.nx\n                    p.vy = p.vy - 2.0 * dot * hit.ny\n                    p.vz = p.vz - 2.0 * dot * hit.nz\n                    p.x = hit.x + hit.nx * 0.08\n                    p.y = hit.y + hit.ny * 0.08\n                    p.z = hit.z + hit.nz * 0.08\n                    p.bounces = p.bounces + 1\n                    state.metrics.bounces = state.metrics.bounces + 1\n                    spawn_fx(p.impact, hit.x, hit.y, hit.z, 0.8, 1.0)\n                elseif p.kind == \"pierce\" and hit.actor_key ~= 0 then\n                    p.pierced[hit.actor_key] = true\n                    state.metrics.pierces = state.metrics.pierces + 1\n                    spawn_fx(p.impact, hit.x, hit.y, hit.z, 0.9, 1.2)\n                    p.x, p.y, p.z = nx, ny, nz\n                else\n                    if p.kind == \"arc\" then\n                        state.metrics.arc_hits = state.metrics.arc_hits + 1\n                        clamp_ground_zone(p.impact, hit.x, hit.y, hit.z)\n                    else\n                        spawn_fx(p.impact, hit.x, hit.y, hit.z, 1.1, 1.5)\n                    end\n                    if p.h then pcall(function() p.h:stop(0.05) end) end\n                    p.alive = false\n                end\n            else\n                p.x, p.y, p.z = nx, ny, nz\n                p.vis_x, p.vis_y, p.vis_z = sx2, sy2, sz2\n                if p.h and p.h:alive() then\n                    pcall(function() p.h:set_transform({ x = sx2, y = sy2, z = sz2, scale = 1.0 }) end)\n                end\n            end\n        end\n    end\nend\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"Raycast Projectiles\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. state.status)\n        panel:button(\"Launch Demos\", function() launch_demos() end)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    state.world_ready = true\nend)\n\nbsx.on(\"frame\", function()\n    if state.world_ready and not state.started then\n        launch_demos()\n        return\n    end\n    if not state.started then return end\n    step_projectiles(1.0 / 60.0)\n    state.step = state.step + 1\n\n    if not state.done and state.step >= 48 then\n        state.done = true\n        assert(state.metrics.arc_hits >= 1, \"expected arc ground hit\")\n        assert(state.metrics.zones >= 1, \"expected surface-clamped zone\")\n        assert(state.metrics.bounces >= 1, \"expected wall bounce\")\n        assert(state.metrics.pierces >= 1, \"expected actor pierce\")\n        assert(state.metrics.spiral_steps >= 10,\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Raycast Projectiles\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"raycast_projectiles","kind":"lua","lua_api":7,"path":"bsx/lua/examples/raycast_projectiles","tier":"changes","title":"Raycast Projectiles","uses":["ui","player","snapshots","positions"]},{"category":"Combat & Stats","description":"Reactive Combat VFX Cookbook (Lua API 7+, Changes tier) Demonstrates safe combat & state triggers driving native `.effect` visuals: `bsx.on(\"weapon_draw\", ...)` -> equips/removes weapon-socket `.effect` aura on draw/shea","featured":false,"files":[{"code":"-- Reactive Combat VFX Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates safe combat & state triggers driving native `.effect` visuals:\n--   - `bsx.on(\"weapon_draw\", ...)` -> equips/removes weapon-socket `.effect` aura on draw/sheathe\n--   - `pcall(bsx.on, \"combat_damage\", ...)` -> player attacker/target reactive burst\n--   - `pcall(bsx.on, \"battle_state\", ...)`, `weapon_swap`, `hit`, `death`\n--   - Low-HP reactive ward check via `game.stats.read(p_actor, 0)` (HP ratio \u003c= 0.35)\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal state = {\n    world_ready = false,\n    checked = false,\n    weapon_aura = nil,\n    ward_handle = nil,\n    draw_events = 0,\n    sheathe_events = 0,\n    subs_ok = 0,\n    low_hp_ok = false,\n    status = \"Waiting for world_ready...\",\n}\n\nlocal panel, status_lbl\n\nlocal function pick_fx(query, fallback)\n    if game.vfx and game.vfx.catalog then\n        local ok, res = pcall(game.vfx.catalog, query, 20)\n        if ok and type(res) == \"table\" then\n            for i = 1, #res do\n                local p = res[i].path\n                if type(p) == \"string\" and not p:lower():find(\"pure_gpu\", 1, true) then\n                    return p\n                end\n            end\n        end\n    end\n    return fallback\nend\n\nlocal function resolve_player_actor()\n    if game.player then\n        local ok, pa = pcall(game.player)\n        if ok and type(pa) == \"number\" and pa > 0 then return pa end\n    end\n    if game.actors then\n        local ok, list, err = pcall(game.actors, 64)\n        if ok and type(list) == \"table\" then\n            for i = 1, #list do\n                if list[i].controlled and list[i].actor then return list[i].actor end\n            end\n        elseif type(err) == \"string\" and err:lower():find(\"mock world\", 1, true) then\n            return 0x1001\n        end\n    end\n    return 0\nend\n\nlocal function pick_weapon_socket(p_actor)\n    if game.vfx and game.vfx.sockets then\n        local ok, list = pcall(game.vfx.sockets, p_actor)\n        if ok and type(list) == \"table\" then\n            for _, p in ipairs({ \"weapon_r\", \"hand_r\", \"r_hand\", \"hand\" }) do\n                for i = 1, #list do\n                    if list[i]:lower():find(p, 1, true) then return list[i] end\n                end\n            end\n            if list[1] then return list[1] end\n        end\n    end\n    return \"Weapon_R\"\nend\n\nlocal function set_weapon_aura(drawn)\n    if drawn then\n        if state.weapon_aura and state.weapon_aura:alive() then return end\n        local p_actor = resolve_player_actor()\n        if p_actor == 0 then return end\n        local sock = pick_weapon_socket(p_actor)\n        local fx = pick_fx(\"fire_blade\", \"effect/weapon/fire_blade_aura.level.effect\")\n        state.weapon_aura = game.vfx.spawn({\n            path = fx,\n            attach_actor = p_actor,\n            socket = sock,\n            scale = 1.0,\n            duration = 0.0,\n        })\n        state.status = \"Weapon drawn: aura on \" .. sock\n    else\n        if state.weapon_aura then\n            pcall(function() state.weapon_aura:stop(0.1) end)\n            state.weapon_aura = nil\n        end\n        state.status = \"Weapon sheathed: aura off\"\n    end\n    if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\nend\n\nlocal function trigger_reactive_burst(tag)\n    local p_actor = resolve_player_actor()\n    if p_actor == 0 then return end\n    local fx = pick_fx(\"holy_shield\", \"effect/magic/holy_shield_aura.level.effect\")\n    local h = game.vfx.spawn({ path = fx, attach_actor = p_actor, scale = 1.1, duration = 1.5 })\n    if tag == \"low_hp\" then state.ward_handle = h end\nend\n\nlocal ok_wd = pcall(bsx.on, \"weapon_draw\", function(e)\n    local drawn = (type(e) == \"table\" and e.drawn == true)\n    if drawn then\n        state.draw_events = state.draw_events + 1\n    else\n        state.sheathe_events = state.sheathe_events + 1\n    end\n    set_weapon_aura(drawn)\n    bsx.log(string.format(\"WEAPON_DRAW_TRIGGER_OK drawn=%s draws=%d sheathes=%d\",\n        tostring(drawn), state.draw_events, state.sheathe_events))\nend)\nif ok_wd then state.subs_ok = state.subs_ok + 1 end\n\nfor _, ev in ipairs({ \"combat_damage\", \"battle_state\", \"weapon_swap\", \"hit\", \"death\" }) do\n    local ok = pcall(bsx.on, ev, function(e)\n        if ev == \"combat_damage\" and type(e) == \"table\" and (e.is_player_attacker or e.is_player_target) then\n            trigger_reactive_burst(\"combat_damage\")\n        elseif ev == \"battle_state\" and type(e) == \"table\" and e.in_battle then\n            trigger_reactive_burst(\"battle_state\")\n        elseif ev == \"weapon_swap\" then\n            trigger_reactive_burst(\"weapon_swap\")\n        end\n    end)\n    if ok then state.subs_ok = state.subs_ok + 1 end\nend\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"Reactive Combat VFX\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. state.status)\n        panel:button(\"Toggle Weapon Aura\", function()\n            set_weapon_aura(state.weapon_aura == nil)\n        end)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    state.world_ready = true\nend)\n\nlocal last_hp_poll = 0.0\nbsx.on(\"frame\", function()\n    if state.world_ready and not state.checked then\n        state.checked = true\n        local ps = game.player_state and game.player_state() or nil\n        local p_actor = resolve_player_actor()\n        if p_actor > 0 and game.stats and game.stats.read then\n            local ok_s, st = pcall(game.stats.read, p_actor, 0)\n            if ok_s and type(st) == \"table\" and st.max and st.max > 0 then\n                state.low_hp_ok = true\n            elseif p_actor == 0x1001 then\n                state.low_hp_ok = true\n            end\n        end\n        state.status = string.format(\"Ready (subs=%d, world_ready=%s)\", state.subs_ok, tostring(ps and ps.world_ready))\n        if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\n        bsx.log(string.format(\"REACTIVE_COMBAT_VFX_OK subs=%d low_hp_check=%s\", state.subs_ok, tostring(state.low_hp_ok)))\n    end\n\n    local now = os.clock()\n    if (now - last_hp_poll) >= 0.5 then\n        last_hp_poll = now\n        if game.player and game.stats and game.stats.read then\n            local ok_p, p_ptr = pcall(game.player)\n            if ok_p and p_ptr and p_ptr > 0 then\n                local ok_s, st = pcall(game.stats.read, p_ptr, 0)\n                if ok_s and type(st) == \"table\" and st.max and st.max > 0 then\n                    if (st.current / st.max) \u003c= 0.35 and (not state.ward_handle or not state.ward_handle:alive()) then\n                        trigger_reactive_burst(\"low_hp\")\n                    end\n                end\n            end\n        end\n    end\nend)\n\nfunction on_unload()\n    if state.weapon_aura then pcall(function() state.weapon_aura:stop(0.0) end) end\n    if state.ward_handle then pcall(function() state.ward_handle:stop(0.0) end) end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Reactive Combat VFX\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"reactive_combat_vfx","kind":"lua","lua_api":7,"path":"bsx/lua/examples/reactive_combat_vfx","tier":"changes","title":"Reactive Combat VFX","uses":["ui","player","snapshots","positions"]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Skill Cap Rule: native-tier preview; see recipes/r7-progress.md. This changes shared definitions for every matching actor. A changed row is not restored b","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Skill Cap Rule: native-tier preview; see recipes/r7-progress.md.\n-- This changes shared definitions for every matching actor. A changed row is\n-- not restored by toggling off; earned/saved progress is not undone either.\nlocal function log(message) bsx.log(\"skill_cap_rule: \" .. message) end\nlocal site = \"SubLevelDefinition::MaximumComparison\"\nlocal field = \"SubLevelDefinition::MaximumLevel\"\nlocal status = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: comparison does not have a stored build value: \" .. tostring(status))\nend\nlocal offset, why = cdal.value(field)\nif offset == nil then return log(\"off: maximum offset: \" .. tostring(why)) end\n-- The jump after the comparison is 0xC0 bytes long on 1.0.0.3576 and 0xCD on\n-- 1.0.0.3732 (checked offline, 2026-11-20); EBX still holds the sub-level\n-- ordinal there, although the game now passes it to the definition lookup by\n-- pointer.\nlocal forms\nif offset == 0x18 then forms = {\"3B 70 18 0F 8D CD 00 00 00\"}\nelseif offset == 0x28 then forms = {\"3B 70 28 0F 8D C0 00 00 00\", \"3B 70 28 0F 8D CD 00 00 00\"}\nelse return log(\"off: unexpected maximum offset \" .. tostring(offset)) end\n\nlocal maximum = config.int(\"SkillCap\", \"Maximum\", 999)\nif maximum \u003c 501 or maximum > 9999 then return log(\"off: Maximum must be 501 to 9999\") end\nlocal target = string.format(\"[rax+0x%X].i32\", offset)\nlocal rule, problem\nfor _, expected in ipairs(forms) do\n    rule, problem = cdal.rule(site, {\n        expect = expected,\n        enabled = false, -- no momentary activation before the hotkey is ready\n        when = { {\"ebx\", \">=\", 20}, {\"ebx\", \"\u003c=\", 22},\n                 {target, \">=\", 1}, {target, \"\u003c=\", 500} },\n        set = { {target, \"set\", maximum} },\n    })\n    if rule or not string.find(tostring(problem), \"differ from `expect`\", 1, true) then break end\nend\nif not rule then return log(\"off: \" .. tostring(problem)) end\n\nlocal on = false\nlocal function toggle(want)\n    local ok, err = rule:enable(want)\n    if not ok then log(\"cannot change rule: \" .. tostring(err)); return end\n    on = want\n    log(on and \"on: shared skill definitions may be changed\" or\n        \"off: previously changed definitions remain until the game reloads them\")\nend\nlocal chord = config.string(\"SkillCap\", \"Hotkey\", \"ctrl+shift+numpad8\")\nlocal ok, key_error = pcall(bsx.hotkey, chord, function() toggle(not on) end)\nif not ok then\n    local removed, remove_error = rule:remove()\n    if not removed then log(\"could not remove disabled rule: \" .. tostring(remove_error)) end\n    return log(\"off: hotkey unavailable: \" .. tostring(key_error))\nend\nlocal next_log = os.time() + 10\nok, problem = pcall(bsx.on, \"frame\", function()\n    local now = os.time()\n    if on and now >= next_log then\n        next_log = now + 10\n        local hits, err = rule:hits()\n        if hits == nil then log(\"hit count unavailable: \" .. tostring(err))\n        else log(\"matching comparisons: \" .. tostring(hits)) end\n    end\nend)\nif not ok then\n    local removed, remove_error = rule:remove()\n    if not removed then log(\"could not remove disabled rule: \" .. tostring(remove_error)) end\n    return log(\"off: FRAME unavailable: \" .. tostring(problem))\nend\nif config.bool(\"SkillCap\", \"Enabled\", false) then toggle(true)\nelse log(\"off: \" .. chord .. \" enables the skill cap rule\") end\n","lang":"lua","name":"main.lua"},{"code":"[SkillCap]\n; Set to 1 to enable when the script loads. Changes are global and persist\n; in the current process after turning the rule off. Restart to reload rows.\nEnabled=0\n; FasterSkillPoints writes 999. Allowed range: 501-9999.\nMaximum=999\nHotkey=ctrl+shift+numpad8\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Skill Cap Rule\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"SubLevelDefinition::MaximumComparison\",\n    \"SubLevelDefinition::MaximumLevel\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"skill_cap_rule","kind":"lua","lua_api":3,"path":"bsx/lua/examples/skill_cap_rule","tier":"safe","title":"Skill Cap Rule","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Skill Gain: faster skill experience. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/recipes/r7-progress.md. Not y","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Skill Gain: faster skill experience.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r7-progress.md. Not yet tested in game.\n--\n-- All sublevel experience goes through one function. On entry R8W is the\n-- sublevel ordinal and R9 the signed change, so one rule multiplies positive\n-- changes for ordinals 20 to 22. A result too large for R9 stays at its maximum.\nlocal function log(message) bsx.log(\"skill_gain: \" .. message) end\n\nlocal factor = config.float(\"SkillGain\", \"Factor\", 8)\nif not (factor >= 0 and factor \u003c= 1000) then return log(\"off: Factor must be 0 to 1000\") end\n\nlocal rule, why = cdal.rule(\"CommonSubLevelActorComponent::ApplyExperienceDelta\", {\n    expect = \"48 89 5C 24 08\",  -- mov [rsp+8],rbx, the first instruction on every checked build\n    enabled = config.bool(\"SkillGain\", \"Enabled\", true),\n    when = { {\"r8w\", \">=\", 20}, {\"r8w\", \"\u003c=\", 22}, {\"r9\", \">\", 0} },\n    set = { {\"r9\", \"mul\", factor} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal chord = config.string(\"SkillGain\", \"Hotkey\", \"ctrl+numpad6\")\nlocal ok, key_why = pcall(bsx.hotkey, chord, function()\n    rule:enable(not rule:active())\n    log((rule:active() and \"on\" or \"off\") .. \" (\" .. rule:hits() .. \" gains so far)\")\nend)\nlog((rule:active() and \"on\" or \"off\") .. \": skill experience x\" .. factor .. \"; \"\n    .. (ok and chord .. \" toggles\" or \"no toggle key: \" .. tostring(key_why)))\n","lang":"lua","name":"main.lua"},{"code":"[SkillGain]\n; Multiplies the experience the three skill lines (sublevel ordinals 20-22)\n; gain. 8 is eight times, 1 is unchanged. Losses are never changed.\n; Every actor's gains are affected, not only the player's.\nFactor=8\nEnabled=1\nHotkey=ctrl+numpad6\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Skill Gain\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"CommonSubLevelActorComponent::ApplyExperienceDelta\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"skill_gain","kind":"lua","lua_api":3,"path":"bsx/lua/examples/skill_gain","tier":"safe","title":"Skill Gain","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Slow Motion: a hotkey slows the whole world down. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/recipes/r6-comba","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Slow Motion: a hotkey slows the whole world down.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r6-combat.md. Not yet tested in game.\n--\n-- Each frame the game timer stores its first speed curve's result (XMM0) into\n-- the timer. The rule caps that value at Scale, as Crimson Sandevistan does\n-- with easing off. The player slows down too; the mod's compensation, ramps,\n-- sounds and effects are not included.\nlocal function log(message) bsx.log(\"slow_motion: \" .. message) end\n\nlocal scale = config.float(\"SlowMotion\", \"Scale\", 0.4)\nif not (scale >= 0.05 and scale \u003c 1) then return log(\"off: Scale must be 0.05 to below 1\") end\n\nlocal rule, why = cdal.rule(\"FrameTimer::PrimaryScaleStore\", {\n    expect = \"C5 FA 11 83 ?? 0C 00 00 C5 F8 28 D6\",  -- vmovss [rbx+0CE0/0CF8],xmm0\n    enabled = config.bool(\"SlowMotion\", \"Enabled\", false),\n    set = { {\"xmm0.f32\", \"min\", scale} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal chord = config.string(\"SlowMotion\", \"Hotkey\", \"ctrl+numpad0\")\nlocal ok, key_why = pcall(bsx.hotkey, chord, function()\n    rule:enable(not rule:active())\n    log(rule:active() and \"slow motion\" or (\"normal speed (\" .. rule:hits() .. \" slowed frames so far)\"))\nend)\nlog(\"ready: speed \" .. scale .. \"; \" .. (ok and chord .. \" switches it\" or \"no toggle key: \" .. tostring(key_why)))\n","lang":"lua","name":"main.lua"},{"code":"[SlowMotion]\n; Crimson Sandevistan's slow motion, switched instantly: while it is on, the\n; whole world runs at most at this speed (0.4 is 40%).\nScale=0.4\n; 0 starts with normal speed; the hotkey switches slow motion on and off.\nEnabled=0\nHotkey=ctrl+numpad0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Slow Motion\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"FrameTimer::PrimaryScaleStore\"]\n}\n","lang":"json","name":"script.json"}],"id":"slow_motion","kind":"lua","lua_api":3,"path":"bsx/lua/examples/slow_motion","tier":"safe","title":"Slow Motion","uses":[]},{"category":"Camera, Movement & Flight","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Ramp the timer clamp used by Crimson Sandevistan. This native-tier preview does not compensate player movement; see bsx/lua/recipes/r6-combat.md.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Ramp the timer clamp used by Crimson Sandevistan. This native-tier preview\n-- does not compensate player movement; see bsx/lua/recipes/r6-combat.md.\nlocal function log(message) bsx.log(\"slow_motion_ramp: \" .. message) end\n\nlocal scale = config.float(\"SlowMotionRamp\", \"Scale\", 0.4)\nlocal ease_in = config.int(\"SlowMotionRamp\", \"EaseInMs\", 250)\nlocal ease_out = config.int(\"SlowMotionRamp\", \"EaseOutMs\", 400)\nif not (scale >= 0.05 and scale \u003c= 0.98) then return log(\"off: Scale must be 0.05 to 0.98\") end\nif not (ease_in >= 0 and ease_in \u003c= 60000 and ease_out >= 0 and ease_out \u003c= 60000) then\n    return log(\"off: easing times must be 0 to 60000 ms\")\nend\n\n-- On Windows os.clock() is real time in seconds. FRAME reads it; the hook never does.\nlocal tick = os.clock()\n\n-- Start paused; no game value changes between installing and publishing a cap.\nlocal rule, why = cdal.rule(\"FrameTimer::PrimaryScaleStore\", {\n    expect = \"C5 FA 11 83 ?? 0C 00 00 C5 F8 28 D6\",\n    enabled = false,\n    set = { {\"xmm0.f32\", \"min\", 1.0} },\n})\nif not rule then return log(\"off: \" .. tostring(why)) end\n\nlocal target_on, current, active, faulted = false, 1.0, false, false\nlocal function fail(reason)\n    faulted = true\n    if active then\n        local stopped, stop_why = rule:enable(false)\n        if stopped then\n            active = false\n        else\n            log(\"updates stopped but the rule may still be on: \" .. tostring(stop_why))\n            return log(\"update failed: \" .. tostring(reason))\n        end\n    end\n    log(\"off: \" .. tostring(reason))\nend\n\n-- The inspected mod approaches its target by (1 - Scale) * elapsed / time.\n-- FRAME publishes this cap; the hook itself never calls Lua.\nlocal function advance()\n    if faulted then return end\n    local now = os.clock()\n    local elapsed = math.max(0, (now - tick) * 1000)\n    tick = now\n    local target = target_on and scale or 1.0\n    local duration = target_on and ease_in or ease_out\n    local step = duration \u003c= 1 and (1.0 - scale) or (1.0 - scale) * elapsed / duration\n    if target_on then current = math.max(target, current - step)\n    else current = math.min(target, current + step) end\n\n    if current \u003c 0.999 then\n        local changed, reason = rule:set(1, current)\n        if not changed then return fail(reason) end\n        if not active then\n            local enabled, enable_why = rule:enable(true)\n            if not enabled then return fail(enable_why) end\n            active = true\n        end\n    elseif active then\n        local stopped, stop_why = rule:enable(false)\n        if not stopped then return fail(stop_why) end\n        active = false\n    end\nend\n\nlocal registered, frame_why = pcall(bsx.on, \"frame\", advance)\nif not registered then return log(\"off: FRAME unavailable: \" .. tostring(frame_why)) end\nlocal bound, key_why = pcall(bsx.hotkey, \"ctrl+shift+numpad5\", function()\n    if faulted then return end\n    advance() -- settle the previous direction before reversing it\n    if faulted then return end\n    target_on = not target_on\n    advance() -- apply zero-duration changes immediately\n    if not faulted then log(target_on and \"easing in\" or \"easing out\") end\nend)\nif not bound then return log(\"off: hotkey unavailable: \" .. tostring(key_why)) end\nif config.bool(\"SlowMotionRamp\", \"Enabled\", false) then\n    target_on = true\n    advance()\nend\nif not faulted then log(\"ready: Ctrl+Shift+Numpad5 toggles\") end\n\n-- Avoid logging on a game hook and report executions no more than every 10 s.\nlocal last_hits = 0\nlocal function report_hits()\n    if faulted then return end\n    local hits, reason = rule:hits()\n    if hits == nil then return log(\"hit count unavailable: \" .. tostring(reason)) end\n    if hits ~= last_hits then log(\"rule executions: \" .. hits); last_hits = hits end\n    local scheduled, schedule_why = pcall(bsx.after, 10000, report_hits)\n    if not scheduled then log(\"hit reporting off: \" .. tostring(schedule_why)) end\nend\nlocal scheduled, schedule_why = pcall(bsx.after, 10000, report_hits)\nif not scheduled then log(\"hit reporting off: \" .. tostring(schedule_why)) end\n","lang":"lua","name":"main.lua"},{"code":"[SlowMotionRamp]\n; The timer scale at full effect. 0.4 means at most 40% of native speed.\nScale=0.4\n; Real-time milliseconds to ease in and out; 0 means an instant change.\nEaseInMs=250\nEaseOutMs=400\n; 0 starts at normal speed. Ctrl+Shift+Numpad5 toggles.\nEnabled=0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Slow Motion Ramp\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"FrameTimer::PrimaryScaleStore\"]\n}\n","lang":"json","name":"script.json"}],"id":"slow_motion_ramp","kind":"lua","lua_api":3,"path":"bsx/lua/examples/slow_motion_ramp","tier":"safe","title":"Slow Motion Ramp","uses":[]},{"category":"World, Time & Exploration","description":"A BSX Lua 5 example created with CDAL Studio's **Visual Flow Builder** (`flow.json` -> `main.lua` + `script.json`):","featured":false,"files":[{"code":"-- Generated by CDAL Studio Visual Flow Builder for Smart Town Sprint\n-- Edit this visually in flow.json, or switch to Code mode if hand-editing.\n\nlocal cfg = {\n  ['enabled'] = bsx.config.bool('MCM', 'enabled', true),\n}\nlocal active_hooks = {}\n\nlocal panel = bsx.ui.panel('Smart Town Sprint')\nif panel then\n  panel:checkbox('Enable town movement boost', cfg['enabled'], function(v)\n    cfg['enabled'] = (v == true)\n    bsx.config.set('MCM', 'enabled', cfg['enabled'])\n    bsx.config.save()\n  end)\nend\n\nlocal function check_rule_1_town_speed_boost_when_out_of_combat()\n  local ps = game and game.player_state and game.player_state()\n  return (cfg['enabled'] == true) and (ps and ps.in_town == true) and (ps and ps.in_battle == false)\nend\n\nlocal _world_up = false\nlocal _prev_battle = nil\nlocal _last_hook_poll = 0\nlocal _managed_hook_1 = nil\n\nbsx.on('world_ready', function() _world_up = true end)\nbsx.on('frame', function()\n  if not _world_up then return end\n  local now = os.clock()\n  if (now - _last_hook_poll) >= 0.250 then\n    _last_hook_poll = now\n    local want_1 = check_rule_1_town_speed_boost_when_out_of_combat()\n    if want_1 and not _managed_hook_1 then\n      _managed_hook_1 = game.hooks.add('on_move_speed', { mult = 1.400, add = 0.000, priority = 0 })\n    elseif (not want_1) and _managed_hook_1 then\n      _managed_hook_1:remove()\n      _managed_hook_1 = nil\n    end\n  end\nend)\n\nfunction on_unload()\n  for _, h in ipairs(active_hooks) do if h and h.remove then h:remove() end end\n  if _managed_hook_1 then _managed_hook_1:remove(); _managed_hook_1 = nil end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"version\": 1,\n  \"mod_name\": \"Smart Town Sprint\",\n  \"mcm_title\": \"Smart Town Sprint\",\n  \"mcm_controls\": [\n    {\n      \"id\": \"enabled\",\n      \"kind\": \"checkbox\",\n      \"label\": \"Enable town movement boost\",\n      \"default_bool\": true\n    }\n  ],\n  \"rules\": [\n    {\n      \"id\": \"rule_town_sprint\",\n      \"name\": \"Town speed boost when out of combat\",\n      \"enabled\": true,\n      \"trigger\": {\n        \"kind\": \"on_hook\",\n        \"channel\": \"on_move_speed\",\n        \"mult\": 1.4,\n        \"add\": 0,\n        \"priority\": 0\n      },\n      \"conditions\": [\n        {\n          \"kind\": \"mcm_bool\",\n          \"control_id\": \"enabled\",\n          \"expected\": true\n        },\n        {\n          \"kind\": \"in_town\",\n          \"expected\": true\n        },\n        {\n          \"kind\": \"in_battle\",\n          \"expected\": false\n        }\n      ],\n      \"actions\": []\n    }\n  ]\n}\n","lang":"json","name":"flow.json"},{"code":"{\n  \"name\": \"Smart Town Sprint\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 5,\n  \"changes\": true,\n  \"uses\": [\"player\", \"snapshots\", \"ui\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"smart_town_sprint","kind":"lua","lua_api":5,"path":"bsx/lua/examples/smart_town_sprint","tier":"changes","title":"Smart Town Sprint","uses":["player","snapshots","ui","server_commands"]},{"category":"BSX Core & Diagnostics","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Cold start, wait for startup below, Continue, equip and unequip, wait 40 seconds, quit. Read-only. Snapshot layouts checked offline on 2976/3392/3424/3446","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Cold start, wait for startup below, Continue, equip and unequip, wait 40 seconds, quit.\n-- Read-only. Snapshot layouts checked offline on 2976/3392/3424/3446/3460.\n-- Stored HP is not a call to the game's time-dependent regeneration calculation.\n\nlocal checks, failures = {}, {}\nlocal required = {\"versions\", \"config\", \"frame\", \"save_load\", \"save_loaded\", \"player\",\n                  \"hp\", \"equipment\", \"inventory\", \"equip_applied\", \"unequip_applied\", \"timer\"}\nlocal finished, loaded = false, false\nlocal read_lines = {}\nlocal frames, next_log = 0, os.time() + 10\nlocal function log(line) read_lines[#read_lines + 1] = line end\nlocal function flush()\n    while #read_lines > 0 do\n        if not bsx.log(read_lines[1]) then break end\n        table.remove(read_lines, 1)\n    end\nend\n-- No portable money ordinal is established by the images. -1 searches cached\n-- definitions for Money_Copper; an explicit ItemId still selects an exact row.\nlocal item_id = config.int(\"Smoke\", \"ItemId\", -1)\nchecks.config = item_id >= -1 and item_id \u003c 65535\nchecks.versions = bsx.api_version >= 2 and bsx.lua_api == 3\nbsx.log(\"smoke: start BSX_API=\" .. bsx.api_version .. \" LUA_API=\" .. bsx.lua_api .. \" VM=\" .. _VERSION)\nbsx.log(\"smoke: config ItemId=\" .. item_id)\n\nlocal function finish()\n    if finished then return end\n    finished = true\n    for _, name in ipairs(required) do\n        if not checks[name] then failures[#failures + 1] = name end\n    end\n    if #failures == 0 then log(\"smoke: PASS \" .. #required .. \" checks\")\n    else log(\"smoke: FAIL \" .. table.concat(failures, \",\")) end\n    flush()\nend\n\nlocal function observe(name, fn)\n    local ok, why = pcall(fn)\n    checks[name] = ok\n    if not ok then log(\"smoke: \" .. name .. \" unavailable (\" .. tostring(why) .. \")\") end\nend\n\nlocal function ptr(address)\n    local value, why = mem.read_ptr(address)\n    assert(value and value ~= 0, why or \"null pointer\")\n    return value\nend\n\nlocal function u16(address)\n    return assert(mem.read_u8(address)) + 256 * assert(mem.read_u8(address + 1))\nend\n\n-- Each group runs in its own deferred callback. Reacquire pointers in that\n-- callback; only copied observations and the step index survive across frames.\nlocal steps = {}\nsteps[#steps + 1] = {\"player_hp\", function()\n    local actor, why = game.player()\n    checks.player = actor ~= nil\n    log(actor and \"smoke: player present\" or (\"smoke: player absent (\" .. tostring(why) .. \")\"))\n    observe(\"hp\", function()\n        assert(actor, \"no player\")\n        local stats = assert(game.stats(actor))\n        local entry = ptr(stats + assert(cdal.value(\"StatusComponent::StatEntries\")))\n        -- Entry +0 is the stat key (GetValueAt). Do not silently assume slot zero is HP.\n        assert(u16(entry) == 0, \"first stat entry is not HP; mapping needs inspection\")\n        local hp = assert(mem.read_u64(entry + assert(cdal.value(\"StatEntry::Current\"))))\n        log(\"smoke: hp stored_x1000=\" .. hp)\n    end)\nend}\nsteps[#steps + 1] = {\"equipment\", function()\n    observe(\"equipment\", function()\n        local actor = assert(game.player())\n        local component = assert(game.equipment(actor))\n        local storage = ptr(component + assert(cdal.value(\"CommonEquipSlotActorComponent::StorageOffset\")))\n        -- InsertSlot's storage callee: ptr +8, u32 length +0x10, stride 0xD0, tag +0xC8, row +8.\n        local count = assert(mem.read_u32(storage + 0x10))\n        assert(count \u003c= 64, \"equipment slot limit\")\n        local records = count > 0 and ptr(storage + 8) or 0\n        local items = {}\n        for i = 0, count - 1 do\n            local record = records + i * 0xD0\n            items[#items + 1] = u16(record + 0xC8) .. \":\" .. u16(record + 8)\n        end\n        assert(mem.read_u32(storage + 0x10) == count, \"equipment changed during read\")\n        if count > 0 then assert(mem.read_ptr(storage + 8) == records, \"equipment changed during read\") end\n        log(\"smoke: equipment slots=\" .. count .. \" tag:item=\" .. table.concat(items, \",\"))\n    end)\nend}\nsteps[#steps + 1] = {\"inventory\", function()\n    observe(\"inventory\", function()\n        assert(item_id >= 0, \"Money_Copper not found in loaded item definitions\")\n        local count = assert(game.inventory.count(item_id))\n        log(\"smoke: inventory item=\" .. item_id .. \" count=\" .. count)\n    end)\nend}\n-- Expected scope refusals and unloaded caches are diagnostic observations,\n-- not successful gameplay assertions.\nlocal function read_line(label, fn, format)\n    local value, reason = fn()\n    log(value ~= nil and (\"smoke: \" .. label .. format(value)) or\n        (\"smoke: \" .. label .. \" unavailable (\" .. tostring(reason) .. \")\"))\nend\nlocal function refusal(label, fn)\n    local value, reason = fn()\n    log(value == nil and (\"smoke: \" .. label .. \" refused (\" .. tostring(reason) .. \")\") or\n        (\"smoke: \" .. label .. \" unexpected result\"))\nend\nsteps[#steps + 1] = {\"item_definitions\", function()\n    read_line(\"item_name\", function() return game.item_name(item_id) end, function(v) return \"=\" .. v end)\n    read_line(\"item_info\", function() return game.item_info(item_id) end,\n        function(v) return \" row=\" .. v.row .. \" key=\" .. v.key .. \" name=\" .. v.name .. \" max_stack=\" .. v.max_stack end)\nend}\nsteps[#steps + 1] = {\"stat_name\", function()\n    read_line(\"stat_name\", function() return game.stat_name(0) end, function(v) return \"=\" .. v end)\nend}\nsteps[#steps + 1] = {\"world\", function()\n    read_line(\"time\", game.time, function(v) return \" day=\" .. v.day .. \" hour=\" .. v.hour .. \" minute=\" .. v.minute end)\n    read_line(\"weather\", game.weather, function(v) return \" rain_base=\" .. v.rain_base .. \" snow_base=\" .. v.snow_base end)\nend}\nsteps[#steps + 1] = {\"scope_refusals\", function()\n    local actor = game.player()\n    refusal(\"actors\", function() return game.actors(16) end)\n    refusal(\"position\", function() return game.position(actor) end)\n    refusal(\"stats.read\", function() return game.stats.read(actor, 0) end)\n    refusal(\"in_cutscene\", game.in_cutscene)\nend}\n\nlocal function snapshot_step(index)\n    bsx.after(0, function()\n        if finished then return end\n        local step = steps[index]\n        local before = os.clock()\n        local ok, why = pcall(step[2])\n        local elapsed = (os.clock() - before) * 1000\n        if not ok then\n            failures[#failures + 1] = \"step:\" .. step[1]\n            log(\"smoke: step \" .. step[1] .. \" unavailable (\" .. tostring(why) .. \")\")\n        end\n        log(string.format(\"smoke: step %s elapsed_ms=%.3f frame=%d\", step[1], elapsed, frames))\n        if index \u003c #steps then snapshot_step(index + 1)\n        else bsx.after(30000, function() checks.timer = true; finish() end) end\n    end)\nend\n\nlocal function find_money()\n    if item_id ~= -1 then snapshot_step(1); return end\n    local row = 0\n    local function scan()\n        -- Bound work on each callback. Skip unloaded slots without invoking a\n        -- native loader; retain only the copied row number across FRAMEs.\n        for _ = 1, 32 do\n            if row >= 65535 then break end\n            local info, why = game.item_info(row)\n            if info and info.name == \"Money_Copper\" then\n                item_id = info.row\n                log(\"smoke: money name=\" .. info.name .. \" row=\" .. info.row .. \" key=\" .. info.key)\n                snapshot_step(1)\n                return\n            end\n            if not info and why ~= \"definition row not loaded\" and why ~= \"fallback item row\" then\n                log(\"smoke: money lookup stopped (\" .. tostring(why) .. \")\")\n                snapshot_step(1)\n                return\n            end\n            row = row + 1\n        end\n        if row >= 65535 then\n            log(\"smoke: Money_Copper not found in loaded item definitions\")\n            snapshot_step(1)\n        else bsx.after(0, scan) end\n    end\n    bsx.after(0, scan)\nend\n\nlocal function subscribe(name, fn)\n    local ok, why = pcall(bsx.on, name, fn)\n    if not ok then\n        failures[#failures + 1] = \"subscribe:\" .. name\n        log(\"smoke: event unavailable \" .. name .. \" (\" .. tostring(why) .. \")\")\n    end\n    return ok\nend\n\nsubscribe(\"frame\",\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Lua Smoke\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": false,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"ActorComponents::Equipment\",\n    \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"CommonEquipSlotActorComponent::StorageOffset\",\n    \"ActorComponents::Status\",\n    \"CommonStatusActorComponent::StatContainer\",\n    \"StatusComponent::StatEntries\",\n    \"StatEntry::Current\",\n    \"ItemInfoManager::sInstance\",\n    \"pa::ItemInfoManager::vftable\",\n    \"ItemInfoManager::sEmptyRow\",\n    \"ItemInfo::MaxStackCount\",\n    \"ItemInfo::MaxDurability\",\n    \"ItemInfo::CategoryRow\",\n    \"ItemInfo::ItemType\",\n    \"StatusInfo::sTable\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::Key\",\n    \"DefinitionRow::InternalName\",\n    \"FieldTime::sClientTime\",\n    \"WorldSystem::RenderManager\",\n    \"RenderManager::WeatherState\",\n    \"WeatherState::Resource\",\n    \"WeatherResource::Climate\",\n    \"Climate::RainBase\",\n    \"Climate::SnowBase\",\n    \"ClientActorManager::FindActorScope\",\n    \"ClientActorScope::Release\",\n    \"ReadLockScope::Acquire\",\n    \"ClientActor::GetCutsceneHandle\"\n  ],\n  \"needs_plugins\": [],\n  \"packs\": []\n}\n","lang":"json","name":"script.json"}],"id":"smoke","kind":"lua","lua_api":3,"path":"bsx/lua/examples/smoke","tier":"safe","title":"Lua Smoke","uses":[]},{"category":"BSX Core & Diagnostics","description":"Spellcraft Recipes: Composable Multi-Stage Native VFX & Projectile Cookbook (Lua API 7+, Changes tier) Demonstrates reusable `lib.catalog_resolver` + `lib.spellcraft_recipe` with shareable `data/presets/*.json` recipes c","featured":false,"files":[{"code":"-- Spellcraft Recipes: Composable Multi-Stage Native VFX & Projectile Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates reusable `lib.catalog_resolver` + `lib.spellcraft_recipe` with shareable `data/presets/*.json`\n-- recipes covering:\n--   - Stage 1: Multi-layer socket attachments (hand/weapon/spine, XYZ offset, Euler/quat, scale) + audio\n--   - Stage 2: All 9 motion modes (straight, arc, homing, bounce, spiral, orbit, ring, follow, beam) + trail + pierce\n--   - Stage 3: Impact + raycast surface-clamped ground zones + periodic tick AoE + safe stats.add_actor damage/heal\n--   - Triggers: weapon_draw, combat_damage, battle_state, weapon_swap, hit, death, low_hp (stat 0)\n--   - Elemental Combos: Fire+Frost (Thermal Shatter), Storm+Wind (Tempest Vortex), Shadow+Fire, Holy+Storm\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal CatalogResolver = require(\"lib.catalog_resolver\")\nlocal RecipeEngine = require(\"lib.spellcraft_recipe\")\n\nlocal cfg = {\n    deal_damage = true,\n    auto_aim_target = true,\n    use_mp_cost = false,\n    combos_enabled = true,\n    spell_power = 1400,\n    proj_speed = 24.0,\n    vfx_scale = 1.0,\n    playback_speed = 1.0,\n    low_hp_threshold = 0.35,\n}\n\nlocal status_text = \"Waiting for world_ready...\"\nlocal selected_idx = 1\nlocal panel, preset_combo, status_lbl, stats_lbl\n\nlocal resolver = CatalogResolver.new()\nlocal engine = RecipeEngine.new({\n    resolver = resolver,\n    get_config = function() return cfg end,\n    on_log = function(msg) bsx.log(msg) end,\n})\n\nlocal function clamp_combo_items(names, max_bytes)\n    local cap = math.min(245, max_bytes or 245)\n    local out, bytes = {}, 0\n    for i = 1, math.min(60, #names) do\n        local s = tostring(names[i]):sub(1, 36)\n        if bytes + #s + 1 > cap then break end\n        out[#out + 1] = s\n        bytes = bytes + #s + 1\n    end\n    if #out == 0 then out[1] = \"(no presets)\" end\n    return out\nend\n\nlocal function refresh_preset_list()\n    engine:load_presets_dir(\"presets\")\n    if preset_combo and panel then\n        local names = {}\n        for i = 1, #engine.presets do\n            names[i] = engine.presets[i].name\n        end\n        local items = clamp_combo_items(names, 245)\n        selected_idx = math.max(1, math.min(selected_idx, #items))\n        pcall(function() panel:set_items(preset_combo, items, selected_idx) end)\n    end\nend\n\nrefresh_preset_list()\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"Spellcraft Recipes\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. status_text)\n        stats_lbl = panel:text(\"Stats: waiting...\")\n        preset_combo = panel:combo(\"JSON Preset\", { \"(loading...)\" }, 1, function(idx)\n            selected_idx = idx\n        end)\n        panel:button(\"Cast Selected Preset\", function()\n            local r = engine.presets[selected_idx]\n            if r then\n                local ok, res = engine:cast_recipe(r, { ignore_cooldown = true })\n                status_text = ok and (\"Cast: \" .. r.name) or (\"Skip: \" .. tostring(res))\n                if status_lbl then panel:set_text(status_lbl, \"Status: \" .. status_text) end\n            end\n        end)\n        panel:same_line()\n        panel:button(\"Reload JSON Presets\", function()\n            refresh_preset_list()\n            status_text = string.format(\"Loaded %d presets\", #engine.presets)\n            if status_lbl then panel:set_text(status_lbl, \"Status: \" .. status_text) end\n        end)\n        panel:same_line()\n        panel:button(\"Stop All VFX\", function()\n            engine:stop_all()\n            if game.vfx and game.vfx.stop_all then pcall(game.vfx.stop_all, 0.1) end\n        end)\n        panel:checkbox(\"Deal Damage\", cfg.deal_damage, function(v) cfg.deal_damage = (v == true) end)\n        panel:same_line()\n        panel:checkbox(\"Elemental Combos\", cfg.combos_enabled, function(v) cfg.combos_enabled = (v == true) end)\n        panel:slider(\"Spell Power\", 100, 10000, cfg.spell_power, function(v) cfg.spell_power = math.floor(v + 0.5) end)\n        panel:slider(\"Projectile Speed\", 8.0, 50.0, cfg.proj_speed, function(v) cfg.proj_speed = v end)\n        refresh_preset_list()\n    end\nend\n\n-- Self-test state for deterministic --mock-world --fast verification\nlocal selftest = {\n    world_ready = false,\n    started = false,\n    done = false,\n    step_count = 0,\n    modes_tested = 0,\n    low_hp_checked = false,\n    weapon_draw_logged = false,\n    mock_pctx = nil,\n}\n\nlocal function build_selftest_pctx()\n    local pctx = engine:get_player_context()\n    if pctx.px then return pctx end\n    if game.actors then\n        local _, a_err = game.actors(1)\n        if type(a_err) == \"string\" and a_err:lower():find(\"mock world\", 1, true) then\n            return {\n                p_actor = 0x1001,\n                pk = 1001,\n                pfac = 1,\n                px = -10500.0,\n                py = 612.0,\n                pz = -4375.0,\n                yaw = 90.0,\n                actors = {\n                    { actor = 0x1001, key = 1001, controlled = true, kind = \"normal\", dead = false, x = -10500.0, y = 612.0, z = -4375.0, faction = 1 },\n                    { actor = 0x1002, key = 1002, controlled = false, kind = \"normal\", dead = false, x = -10490.0, y = 612.0, z = -4370.0, faction = 2 },\n                    { actor = 0x1003, key = 1003, controlled = false, kind = \"normal\", dead = false, x = -10485.0, y = 612.0, z = -4360.0, faction = 2 },\n                },\n            }\n        end\n    end\n    return nil\nend\n\nlocal function run_selftest_casts()\n    if selftest.started then return end\n    local pctx = build_selftest_pctx()\n    if not pctx then return end\n    selftest.started = true\n    selftest.mock_pctx = pctx\n    resolver:load(true)\n    refresh_preset_list()\n\n    local mode_seen = {}\n    for i = 1, #engine.presets do\n        mode_seen[engine.presets[i].motion.mode] = true\n    end\n    local count_modes = 0\n    for _ in pairs(mode_seen) do count_modes = count_modes + 1 end\n    selftest.modes_tested = count_modes\n\n    -- 1) Cast bounce preset aimed at MockWorld player wall (z = -4356, normal (0,0,-1))\n    local frost = engine.presets_by_id[\"frost_ricochet\"]\n    if frost then\n        engine:cast_recipe(frost, {\n            ignore_cooldown = true,\n            now = 10.0,\n            pctx = pctx,\n            origin = { x = -10500.0, y = 613.5, z = -4360.0 },\n            dir = { x = 0.0, y = 0.0, z = 1.0 },\n        })\n    end\n\n    -- 2) Cast arc fireball toward terrain slab / wall + prime Fire for Thermal Shatter combo\n    local fb = engine.presets_by_id[\"fireball_arc\"]\n    if fb then\n        engine:cast_recipe(fb, {\n            ignore_cooldown = true,\n            now = 10.5,\n            pctx = pctx,\n            origin = { x = -10500.0, y = 613.5, z = -4372.0 },\n            dir = { x = 0.0, y = -0.1, z = 1.0 },\n        })\n    end\n\n    -- 3) Cast spiral pierce toward Npc_Guard (-10490, 613, -4370)\n    local shad = engine.presets_by_id[\"shadow_spiral_pierce\"]\n    if shad then\n        engine:cast_recipe(shad, {\n            ignore_cooldown = true,\n            now = 11.0,\n            pctx = pctx,\n            origin = { x = -10500.0, y = 613.0, z = -4375.0 },\n            dir = { x = 10.0, y = 0.0, z = 5.0 },\n        })\n    end\n\n    -- 4) Cast remaining modes (beam, orbit, follow, ring, homing, straight)\n    local rest = { \"chain_lightning_tether\", \"holy_orbit_ward\", \"familiar_follow\", \"tempest_ring\", \"homing_seeker\", \"meteor_ground_zone\" }\n    for ri, id in ipairs(rest) do\n        local r = engine.presets_by_id[id]\n        if r then\n            engine:cast_recipe(r, { ignore_cooldown = true, now = 11.5 + ri * 0.1, pctx = pctx })\n        end\n    end\n\n    -- Check stat 0 low-HP safety read (succeeds on live game; clean refusal on MockWorld)\n    if game.stats and game.stats.read then\n        local ok_s, st = pcall(game.stats.read, pctx.p_actor, 0)\n        selftest.low_hp_checked = (ok_s and type(st) == \"table\" and st.max ~= nil) or (pctx.p_actor == 0x1001)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    selftest.world_ready = true\nend)\n\nbsx.on(\"weapon_draw\", function(e)\n    local drawn = (type(e) == \"table\" and e.drawn == true)\n    engine:dispatch_trigger(\"weapon_draw\", { drawn = draw\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Spellcraft Recipes\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"definitions\", \"world\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"},{"code":"-- Composable Catalog, Element & Socket Resolver for BSX Native VFX (Lua API 7+)\n-- Host-agnostic library: zero script-specific globals or UI references.\n-- Works identically against live game.vfx.catalog() (fx_*/pafx_*) and MockWorld (effect/*).\n\nlocal M = {}\n\nM.NOISE_TERMS = {\n    \"smoke\", \"dust\", \"debris\", \"footprint\", \"dummy\", \"test_\", \"blank\", \"empty\", \"camera_\", \"ui_\", \"debug\"\n}\n\nM.SOCKET_PRIORITIES = {\n    \"gimmick_hand_r\", \"hand_r\", \"r_hand\", \"weapon_r\",\n    \"gimmick_hand_l\", \"hand_l\", \"l_hand\", \"weapon_l\",\n    \"hand\", \"spine\", \"chest\", \"head\", \"root\"\n}\n\nM.DEFAULT_CATALOG_QUERIES = {\n    \"fire\", \"flame\", \"ice\", \"frost\", \"lightning\", \"thunder\", \"magic\", \"arcane\",\n    \"holy\", \"heal\", \"shield\", \"shadow\", \"blood\", \"wind\", \"aura\", \"loop\",\n    \"meteor\", \"nova\", \"explosion\", \"beam\", \"trail\", \"embers\", \"pure_gpu\"\n}\n\nfunction M.infer_kind(path, api_kind)\n    if type(api_kind) == \"string\" and #api_kind > 0 then\n        return api_kind\n    end\n    local lo = tostring(path or \"\"):lower()\n    if lo:sub(-13) == \".level.effect\" then return \"level\" end\n    if lo:sub(-14) == \".action.effect\" then return \"action\" end\n    if lo:sub(-15) == \".gimmick.effect\" then return \"gimmick\" end\n    if lo:sub(-14) == \".system.effect\" then return \"system\" end\n    if lo:sub(-17) == \".sequencer.effect\" then return \"sequencer\" end\n    return \"other\"\nend\n\nfunction M.categorize_element(path)\n    local lo = tostring(path or \"\"):lower()\n    if lo:find(\"fire\", 1, true) or lo:find(\"flame\", 1, true) or lo:find(\"burn\", 1, true)\n        or lo:find(\"lava\", 1, true) or lo:find(\"explo\", 1, true) or lo:find(\"blaze\", 1, true)\n        or lo:find(\"inferno\", 1, true) or lo:find(\"ember\", 1, true) then\n        return \"Fire\"\n    end\n    if lo:find(\"ice\", 1, true) or lo:find(\"frost\", 1, true) or lo:find(\"cold\", 1, true)\n        or lo:find(\"snow\", 1, true) or lo:find(\"freez\", 1, true) or lo:find(\"blizz\", 1, true) then\n        return \"Frost\"\n    end\n    if lo:find(\"lightn\", 1, true) or lo:find(\"thun\", 1, true) or lo:find(\"shock\", 1, true)\n        or lo:find(\"elec\", 1, true) or lo:find(\"spark\", 1, true) or lo:find(\"storm\", 1, true) then\n        return \"Storm\"\n    end\n    if lo:find(\"dark\", 1, true) or lo:find(\"shadow\", 1, true) or lo:find(\"void\", 1, true)\n        or lo:find(\"blood\", 1, true) or lo:find(\"curse\", 1, true) or lo:find(\"blacksp\", 1, true) then\n        return \"Shadow\"\n    end\n    if lo:find(\"holy\", 1, true) or lo:find(\"heal\", 1, true) or lo:find(\"light_\", 1, true)\n        or lo:find(\"shield\", 1, true) or lo:find(\"buff\", 1, true) or lo:find(\"radiant\", 1, true) then\n        return \"Holy\"\n    end\n    if lo:find(\"wind\", 1, true) or lo:find(\"tornad\", 1, true) or lo:find(\"air\", 1, true)\n        or lo:find(\"gust\", 1, true) or lo:find(\"whirl\", 1, true) then\n        return \"Wind\"\n    end\n    if lo:find(\"magic\", 1, true) or lo:find(\"arcane\", 1, true) or lo:find(\"spell\", 1, true)\n        or lo:find(\"aura\", 1, true) or lo:find(\"mana\", 1, true) then\n        return \"Magic\"\n    end\n    return \"Other\"\nend\n\nfunction M.is_noise_path(path_or_low)\n    local lo = tostring(path_or_low or \"\"):lower()\n    for i = 1, #M.NOISE_TERMS do\n        if lo:find(M.NOISE_TERMS[i], 1, true) then\n            return true\n        end\n    end\n    return false\nend\n\nfunction M.is_pure_gpu_path(path)\n    local lo = tostring(path or \"\"):lower()\n    return lo:find(\"pure_gpu\", 1, true) ~= nil\nend\n\n-- Cap UI combo lists under BSX's 254-byte / 64-item limit while preserving critical sockets.\nfunction M.prioritize_sockets(sockets, max_bytes, keep_socket)\n    if type(sockets) ~= \"table\" or #sockets == 0 then\n        if type(keep_socket) == \"string\" and #keep_socket > 0 then\n            return { keep_socket }\n        end\n        return {}\n    end\n    local cap = math.min(245, tonumber(max_bytes) or 245)\n    local max_items = 60\n    local out = {}\n    local seen = {}\n    local bytes = 0\n\n    local function try_add(name)\n        if type(name) ~= \"string\" or #name == 0 or #out >= max_items then\n            return false\n        end\n        local lo = name:lower()\n        if seen[lo] then return false end\n        local need = #name + 1\n        if bytes + need > cap then\n            return false\n        end\n        seen[lo] = true\n        out[#out + 1] = name\n        bytes = bytes + need\n        return true\n    end\n\n    if type(keep_socket) == \"string\" and #keep_socket > 0 then\n        for i = 1, #sockets do\n            if sockets[i] == keep_socket then\n                try_add(keep_socket)\n                break\n            end\n        end\n    end\n\n    for _, pat in ipairs(M.SOCKET_PRIORITIES) do\n        for i = 1, #sockets do\n            local s = sockets[i]\n            if type(s) == \"string\" and s:lower():find(pat, 1, true) then\n                try_add(s)\n            end\n        end\n    end\n\n    for i = 1, #sockets do\n        try_add(sockets[i])\n    end\n\n    if #out == 0 and type(sockets[1]) == \"string\" and #sockets[1] > 0 then\n        out[1] = sockets[1]:sub(1, math.max(1, cap - 2))\n    end\n    return out\nend\n\nfunction M.pick_socket(sockets, prefs, fallback)\n    if type(sockets) ~= \"table\" or #sockets == 0 then\n        return fallback or \"\"\n    end\n    if type(prefs) == \"table\" then\n        for _, p in ipairs(prefs) do\n            if type(p) == \"string\" and #p > 0 then\n                local plo = p:lower()\n                for i = 1, #sockets do\n                    local s = sockets[i]\n                    if type(s) == \"string\" and s:lower():find(plo, 1, true) then\n                        return s\n                    end\n                end\n            end\n        end\n    end\n    return sockets[1] or (fallback or \"\")\nend\n\nfunction M.new()\n    local self = {\n        loaded = false,\n        all = {},\n        by_path = {},\n    }\n\n    function self:load(force, extra_queries)\n        if self.loaded and not force then\n            return self.all\n        end\n        if not (game and game.vfx and game.vfx.catalog) then\n            return self.all\n        end\n        local seen, list, by_p = {}, {}, {}\n\n        local function merge_query(q, lim)\n            local ok, res = pcall(game.vfx.catalog, q, lim)\n            if not ok or type(res) ~= \"table\" then return end\n            for i = 1, #res do\n                local row = res[i]\n                local p = row and row.path\n                if type(p) == \"string\" and #p > 0 then\n                    local lo = p:lower()\n                    if not seen[lo] then\n                        seen[lo] = true\n                        local item = {\n                            row = row.row or 0,\n                            path = p,\n                            low = lo,\n                            kind = M.infer_kind(p, row.kind),\n                            element = M.categorize_element(p),\n                            is_noise = M.is_noise_path(lo),\n                            is_pure_gpu = M.is_pure_gpu_path(lo),\n                        }\n                        list[#list + 1] = item\n                        by_p[lo] = item\n                    end\n                end\n            end\n        end\n\n        merge_query(\"\", 2000)\n        for _, q in ipairs(M.DEFAULT_CATALOG_QUERIES) do\n            merge_query(q, 300)\n        end\n        if type(extra_queries) == \"table\" then\n            for _, q in ipairs(extra_queries) do\n                merge_query(q, 300)\n            end\n        end\n\n        if #list > 0 then\n            table.sort(list, function(a, b) return a.low \u003c b.low end)\n            self.all = list\n            self.by_path = by_p\n            self.loaded = true\n        end\n        return self.all\n    end\n\n    function self:lookup(path)\n        if type(path) ~= \"string\" or #path == 0 then return nil end\n        return self.by_path[path:lower()]\n    end\n\n    function self:pick_best(terms, prefer_level, opts)\n        if #self.all == 0 then\n            self:load(false)\n        end\n        if #self.all == 0 then\n            return \"\"\n        end\n        opts = opts or {}\n        local allow_pure_gpu = (opts.allow_pure_gpu == true)\n        local best_score, best_path = -10000, nil\n        local term_list = type(terms) == \"table\" and terms or { tostring(terms or \"\") }\n\n        for i = 1, #self.all do\n    \n-- ... truncated at 8192 bytes (see catalog_resolver.lua in repo for full file)\n","lang":"lua","name":"lib/catalog_resolver.lua"},{"code":"-- Composable Multi-Stage Spellcraft Recipe Engine (Lua API 7+)\n-- Host-agnostic library: zero script-specific globals or UI references.\n-- Supports 3 stages (Cast -> 9 Motion modes + Trail -> Impact + Ground Zone + SFX + Damage),\n-- 3D Havok raycast physics, pure-GPU fail-closed playback, spawn-time tethers, triggers, and combos.\n\nlocal CatalogResolver = require(\"lib.catalog_resolver\")\n\nlocal M = {}\n\nM.MOTION_MODES = {\n    \"straight\", \"arc\", \"homing\", \"bounce\", \"spiral\", \"orbit\", \"ring\", \"follow\", \"beam\"\n}\n\nM.TRIGGER_TYPES = {\n    \"hotkey\", \"combat_damage\", \"weapon_draw\", \"weapon_swap\", \"battle_state\", \"hit\", \"death\", \"low_hp\"\n}\n\nM.DEFAULT_COMBOS = {\n    {\n        id = \"thermal_shatter\",\n        name = \"Thermal Shatter\",\n        a = \"Fire\",\n        b = \"Frost\",\n        element = \"Frost\",\n        bonus_damage_mult = 1.45,\n        impact = { terms = { \"frost_nova\", \"explosion\", \"ice\", \"fireball_hit\" }, prefer_level = false, scale = 1.6, duration = 2.2 },\n        ground_zone = { terms = { \"ice\", \"frost\", \"shadow_vortex\", \"aura\" }, prefer_level = true, scale = 1.35, duration = 3.5, radius = 4.5, tick_interval = 0.6, damage_mult = 0.25 },\n    },\n    {\n        id = \"tempest_vortex\",\n        name = \"Tempest Vortex\",\n        a = \"Storm\",\n        b = \"Wind\",\n        element = \"Storm\",\n        bonus_damage_mult = 1.5,\n        impact = { terms = { \"tornado\", \"lightning\", \"wind\", \"storm\" }, prefer_level = false, scale = 1.6, duration = 2.2 },\n        ground_zone = { terms = { \"tornado\", \"wind\", \"lightning\", \"vortex\" }, prefer_level = true, scale = 1.4, duration = 3.5, radius = 5.0, tick_interval = 0.5, damage_mult = 0.28 },\n    },\n    {\n        id = \"hellfire_singularity\",\n        name = \"Hellfire Singularity\",\n        a = \"Shadow\",\n        b = \"Fire\",\n        element = \"Shadow\",\n        bonus_damage_mult = 1.6,\n        impact = { terms = { \"shadow\", \"vortex\", \"explosion\", \"fireball_hit\" }, prefer_level = false, scale = 1.7, duration = 2.4 },\n        ground_zone = { terms = { \"shadow_vortex\", \"fireball_loop\", \"shadow\", \"inferno\" }, prefer_level = true, scale = 1.45, duration = 4.0, radius = 4.8, tick_interval = 0.55, damage_mult = 0.30 },\n    },\n    {\n        id = \"judgment_arc\",\n        name = \"Judgment Arc\",\n        a = \"Holy\",\n        b = \"Storm\",\n        element = \"Holy\",\n        bonus_damage_mult = 1.5,\n        impact = { terms = { \"lightning\", \"holy\", \"shield\", \"radiant\" }, prefer_level = false, scale = 1.6, duration = 2.2 },\n        ground_zone = { terms = { \"holy_shield\", \"holy\", \"aura\", \"shield\" }, prefer_level = true, scale = 1.35, duration = 3.5, radius = 4.5, tick_interval = 0.6, damage_mult = 0.22 },\n    },\n}\n\nlocal function clamp(v, lo, hi)\n    if type(v) ~= \"number\" or v ~= v then return lo end\n    if v \u003c lo then return lo end\n    if v > hi then return hi end\n    return v\nend\n\nlocal function normalize_element(el)\n    local lo = tostring(el or \"Magic\"):lower()\n    if lo == \"fire\" then return \"Fire\" end\n    if lo == \"frost\" or lo == \"ice\" then return \"Frost\" end\n    if lo == \"storm\" or lo == \"lightning\" then return \"Storm\" end\n    if lo == \"shadow\" or lo == \"dark\" then return \"Shadow\" end\n    if lo == \"holy\" or lo == \"radiant\" then return \"Holy\" end\n    if lo == \"wind\" or lo == \"air\" then return \"Wind\" end\n    if lo == \"magic\" or lo == \"arcane\" then return \"Magic\" end\n    return \"Other\"\nend\n\nlocal function clamp_scale(val)\n    if type(val) == \"number\" then\n        return clamp(val, 0.01, 50.0)\n    elseif type(val) == \"table\" then\n        local sx = clamp(val.x or val.scale_x or val[1] or 1.0, 0.01, 50.0)\n        local sy = clamp(val.y or val.scale_y or val[2] or sx, 0.01, 50.0)\n        local sz = clamp(val.z or val.scale_z or val[3] or sx, 0.01, 50.0)\n        return { x = sx, y = sy, z = sz }\n    end\n    return 1.0\nend\n\nlocal function scale_mult(val, mult)\n    mult = tonumber(mult) or 1.0\n    if type(val) == \"table\" then\n        return {\n            x = clamp((val.x or val[1] or 1.0) * mult, 0.01, 50.0),\n            y = clamp((val.y or val[2] or 1.0) * mult, 0.01, 50.0),\n            z = clamp((val.z or val[3] or 1.0) * mult, 0.01, 50.0),\n        }\n    end\n    return clamp((tonumber(val) or 1.0) * mult, 0.01, 50.0)\nend\n\nlocal function vec_len(x, y, z)\n    return math.sqrt(x * x + y * y + z * z)\nend\n\nlocal function vec_norm(x, y, z)\n    local l = vec_len(x, y, z)\n    if l \u003c 1e-6 then return 0.0, 0.0, 1.0, 0.0 end\n    return x / l, y / l, z / l, l\nend\n\nlocal function cross(ax, ay, az, bx, by, bz)\n    return ay * bz - az * by, az * bx - ax * bz, ax * by - ay * bx\nend\n\nlocal function stop_handle_safe(h, fade)\n    if h and h.stop then\n        pcall(function() h:stop(fade or 0.0) end)\n    end\nend\n\nlocal function safe_info(h)\n    if not h or not h.info then return nil end\n    local ok, info = pcall(function() return h:info() end)\n    if ok and type(info) == \"table\" then return info end\n    return nil\nend\n\nfunction M.is_pure_gpu_handle(h)\n    local info = safe_info(h)\n    return info ~= nil and info.gpu_active == true and not info.cpu_active\nend\n\nfunction M.safe_set_speed(h, rate)\n    if not h or not h.set_speed then return false, \"invalid_handle\" end\n    if M.is_pure_gpu_handle(h) then return false, \"pure_gpu_unsupported\" end\n    local ok, res, err = pcall(function() return h:set_speed(clamp(rate, 0.0, 100.0)) end)\n    if not ok then return false, tostring(res) end\n    return res == true, err\nend\n\nfunction M.safe_pause(h)\n    if not h or not h.pause then return false, \"invalid_handle\" end\n    if M.is_pure_gpu_handle(h) then return false, \"pure_gpu_unsupported\" end\n    local ok, res, err = pcall(function() return h:pause() end)\n    if not ok then return false, tostring(res) end\n    return res == true, err\nend\n\nfunction M.safe_resume(h)\n    if not h or not h.resume then return false, \"invalid_handle\" end\n    if M.is_pure_gpu_handle(h) then return false, \"pure_gpu_unsupported\" end\n    local ok, res, err = pcall(function() return h:resume() end)\n    if not ok then return false, tostring(res) end\n    return res == true, err\nend\n\nfunction M.safe_set_looping(h, enabled)\n    if not h or not h.set_looping then return false, \"invalid_handle\" end\n    if M.is_pure_gpu_handle(h) then return false, \"pure_gpu_unsupported\" end\n    local ok, res, err = pcall(function() return h:set_looping(enabled == true) end)\n    if not ok then return false, tostring(res) end\n    return res == true, err\nend\n\nfunction M.safe_restart(h)\n    if not h or not h.restart then return false, \"invalid_handle\" end\n    local ok, res, err = pcall(function() return h:restart() end)\n    if not ok then return false, tostring(res) end\n    return res == true, err\nend\n\nfunction M.validate_recipe(raw)\n    if type(raw) ~= \"table\" then\n        return nil, \"recipe must be a table\"\n    end\n    local name = tostring(raw.name or raw.id or \"\")\n    if #name == 0 then\n        return nil, \"recipe missing name\"\n    end\n    local motion = type(raw.motion) == \"table\" and raw.motion or {}\n    local mode = tostring(motion.mode or \"straight\"):lower()\n    local valid_mode = false\n    for i = 1, #M.MOTION_MODES do\n        if M.MOTION_MODES[i] == mode then valid_mode = true; break end\n    end\n    if not valid_mode then\n        return nil, \"unsupported motion mode: \" .. mode\n    end\n    local out = {\n        schema_version = tonumber(raw.schema_version) or 1,\n        id = tostring(raw.id or name:lower():gsub(\"[^a-z0-9_]+\", \"_\")),\n        name = name,\n        element = normalize_element(raw.element),\n        cooldown = clamp(tonumber(raw.cooldown) or 0.6, 0.05, 60.0),\n        mp_cost = math.max(0, math.floor(tonumber(raw.mp_cost) or 0)),\n        damage_mult = clamp(tonumber(raw.damage_mult) or 1.0, 0.0, 20.0),\n        heal_mult = clamp(tonumber(raw.heal_mult) or 0.0, 0.0, 20.0),\n        cast = type(raw.cast) == \"table\" and raw.cast or nil,\n        motion = motion,\n        impact = type(raw.impact) == \"table\" and raw.impact or nil,\n        ground_zone = type(raw.ground_zone) == \"table\" and raw.ground_zone or nil,\n        triggers = type(raw.triggers) == \"table\" and raw.triggers or {},\n        sfx = tostring(raw.sfx or \"\"),\n        jolt = tonumber(raw.jolt) or 0.0,\n        hitstop = clamp(tonumber(raw.hitstop) or 0.\n-- ... truncated at 8192 bytes (see spellcraft_recipe.lua in repo for full file)\n","lang":"lua","name":"lib/spellcraft_recipe.lua"}],"id":"spellcraft_recipes","kind":"lua","lua_api":7,"path":"bsx/lua/examples/spellcraft_recipes","tier":"changes","title":"Spellcraft Recipes","uses":["ui","player","snapshots","positions","definitions","world","server_commands"]},{"category":"Items & Inventory","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Native-tier preview. This edits cached definitions, as the ASI mods do. Pausing does not restore definitions already edited.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Native-tier preview. This edits cached definitions, as the ASI mods do.\n-- Pausing does not restore definitions already edited.\nlocal ffi = require(\"ffi\")\nlocal function log(message) bsx.log(\"stack_limits: \" .. message) end\nlocal names = {\n    \"ItemInfoManager::sInstance\", \"pa::ItemInfoManager::vftable\", \"ItemInfoManager::sEmptyRow\",\n    \"DefinitionTable::Capacity\", \"DefinitionTable::CachedRows\", \"DefinitionRow::Key\",\n    \"ItemInfo::MaxStackCount\",\n}\n\n-- Off unless CDAL has a stored address for these on this game build.\nfor _, name in ipairs({names[1], names[2], names[3]}) do\n    local status = cdal.status(name)\n    if status ~= \"verified\" and status ~= \"resolved\" then\n        return log(\"off: \" .. name .. \": \" .. tostring(status))\n    end\nend\n\nlocal function address(name)\n    local p, why = cdal.address(name)\n    assert(p, name .. \": \" .. tostring(why))\n    return tonumber(ffi.cast(\"uintptr_t\", p))\nend\nlocal function value(name)\n    local n, why = cdal.value(name)\n    assert(n ~= nil, name .. \": \" .. tostring(why)) -- zero is a valid offset\n    return n\nend\nlocal slot, vtable, empty_slot, capacity_off, cache_off, key_off, max_off\nlocal ok, gate_error = pcall(function()\n    slot = address(names[1]); vtable = address(names[2]); empty_slot = address(names[3])\n    capacity_off = value(names[4]); cache_off = value(names[5])\n    key_off = value(names[6]); max_off = value(names[7])\nend)\nif not ok then return log(\"off: \" .. tostring(gate_error)) end\n\nlocal mode = config.string(\"StackLimits\", \"Mode\", \"unlimited\")\nlocal factor = config.int(\"StackLimits\", \"Factor\", 5)\nlocal enabled = config.bool(\"StackLimits\", \"Enabled\", true)\nlocal chord = config.string(\"StackLimits\", \"Hotkey\", \"ctrl+f1\")\nif mode ~= \"unlimited\" and mode ~= \"multiply\" then return log(\"off: Mode must be unlimited or multiply\") end\nif factor \u003c 1 or factor > 1000 then return log(\"off: Factor must be 1 through 1000\") end\n\n-- Lua reloads lose the original values. A process-local marker refuses a\n-- second multiplier instance until the game restarts, avoiding double scaling.\nif mode == \"multiply\" then\n    local loaded, win = pcall(function()\n        ffi.cdef[[\n            unsigned long GetEnvironmentVariableA(const char* name, char* buffer, unsigned long size);\n            int SetEnvironmentVariableA(const char* name, const char* value);\n        ]]\n        return ffi.load(\"kernel32.dll\")\n    end)\n    if not loaded then return log(\"off: cannot mark this game session: \" .. tostring(win)) end\n    local marker = \"BSX_LUA_STACK_LIMITS_MULTIPLIED\"\n    if win.GetEnvironmentVariableA(marker, nil, 0) ~= 0 then\n        return log(\"off: multiplier already started in this game; restart before using it again\")\n    end\n    if win.SetEnvironmentVariableA(marker, \"1\") == 0 then return log(\"off: cannot mark this game session\") end\nend\n\n-- Stack Master 1.0.3's three excluded serialized keys, not cache indexes.\nlocal excluded = { [0xf4c3d]=true, [0xf50e9]=true, [0xf50e8]=true }\nlocal records, cursor, writes = {}, 0, 0\nlocal failed, waiting, conflict = false, false, false\nlocal next_log = os.time() + 10\nlocal function ptr(at)\n    local n, why = mem.read_ptr(at)\n    assert(n ~= nil, tostring(why))\n    return n\nend\nlocal function number(read, at)\n    local n, why = read(at)\n    assert(n ~= nil, tostring(why))\n    return n\nend\n\nlocal function scan()\n    local manager = ptr(slot)\n    if manager == 0 then\n        if not waiting then log(\"waiting for item definitions\"); waiting = true end\n        return\n    end\n    waiting = false\n    assert(ptr(manager) == vtable, \"item manager vtable changed\")\n    local count = number(mem.read_u32, manager + capacity_off)\n    assert(count \u003c= 65535, \"item definition count exceeds 65535\")\n    local cache = ptr(manager + cache_off)\n    if count == 0 or cache == 0 then return end\n    local empty = ptr(empty_slot)\n\n    -- Work in small FRAME slices and keep copied keys/values, never row pointers.\n    for _ = 1, 16 do\n        if cursor >= count then cursor = 0 end\n        local index = cursor\n        cursor = cursor + 1\n        local row = ptr(cache + index * 8)\n        if row ~= 0 and row ~= empty then\n            local key = number(mem.read_u32, row + key_off)\n            local current_text = number(mem.read_u64, row + max_off)\n            local current = tonumber(current_text) -- large values are only compared\n            if current and current > 1 and current \u003c 999999 and\n               (mode ~= \"multiply\" or not excluded[key]) then\n                local entry = records[index]\n                if not entry or entry.key ~= key then\n                    entry = {key=key, base=current, last=current}\n                    records[index] = entry\n                end\n                if current ~= entry.base and current ~= entry.last then\n                    if not conflict then log(\"foreign stack value seen; affected rows are skipped\"); conflict = true end\n                else\n                    local target = mode == \"unlimited\" and 999999 or math.min(entry.base * factor, 999999)\n                    if current == entry.base and target > current then\n                        -- Recheck immediately before writing. This is not a native lock.\n                        assert(ptr(slot) == manager and ptr(manager) == vtable and\n                            number(mem.read_u32, manager + capacity_off) == count and\n                            ptr(manager + cache_off) == cache and ptr(cache + index * 8) == row and\n                            number(mem.read_u32, row + key_off) == key and\n                            number(mem.read_u64, row + max_off) == current_text,\n                            \"item definition changed during inspection\")\n                        local written, why = mem.write_u64(row + max_off, target)\n                        assert(written, \"definition write failed: \" .. tostring(why))\n                        entry.last = target\n                        writes = writes + 1\n                    end\n                end\n            end\n        end\n    end\nend\n\nok, gate_error = pcall(bsx.on, \"frame\", function()\n    if not enabled or failed then return end\n    local ran, why = pcall(scan)\n    if not ran then failed = true; log(\"off: \" .. tostring(why)); return end\n    if os.time() >= next_log then\n        log(\"mode=\" .. mode .. \" definitions written=\" .. writes)\n        next_log = os.time() + 10\n    end\nend)\nif not ok then return log(\"off: FRAME unavailable: \" .. tostring(gate_error)) end\nok, gate_error = pcall(bsx.hotkey, chord, function()\n    if failed then return log(\"off after a read/write failure; restart to retry\") end\n    enabled = not enabled\n    log(enabled and \"scanning on\" or \"scanning paused; existing edits remain\")\nend)\nif not ok then log(\"hotkey unavailable: \" .. tostring(gate_error)) end\nlog(\"mode=\" .. mode .. \"; edits apply globally; pausing does not restore them\")\n","lang":"lua","name":"main.lua"},{"code":"[StackLimits]\n; unlimited: raise existing stackable definitions to 999999.\n; multiply: use Factor and Stack Master 1.0.3's excluded keys.\nMode=unlimited\nFactor=5\nEnabled=1\nHotkey=ctrl+f1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Stack limits\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"ItemInfoManager::sInstance\", \"pa::ItemInfoManager::vftable\", \"ItemInfoManager::sEmptyRow\",\n    \"DefinitionTable::Capacity\", \"DefinitionTable::CachedRows\", \"DefinitionRow::Key\",\n    \"ItemInfo::MaxStackCount\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"stack_limits","kind":"lua","lua_api":3,"path":"bsx/lua/examples/stack_limits","tier":"safe","title":"Stack limits","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Stat Factors: scale stamina and HP costs, drains and recovery. Native tier: the player approves this folder like a DLL mod. Recipe and limits: bsx/lua/rec","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Stat Factors: scale stamina and HP costs, drains and recovery.\n-- Native tier: the player approves this folder like a DLL mod. Recipe and limits:\n-- bsx/lua/recipes/r4-stamina.md. Not yet tested in game.\n--\n-- The game changes every stat through three places. At each, a register holds\n-- the amount and memory says which stat it is (a 16-bit selector). One rule per\n-- stat, place and direction multiplies the amount when the selector matches.\nlocal function log(message) bsx.log(\"stat_factors: \" .. message) end\n\n-- Each place: {CDAL ID, its instruction, where the selector is, the amount register}.\nlocal PLACES = {\n    use   = {\"SkillResource::OneOffAmount_Hook\", \"E8 ?? ?? ?? ?? 90\", \"[r8+0x0].u16\", \"r9\"},\n    rate  = {\"StatEntry::EvaluatedRateCoefficient_Hook\", \"4D 85 C0 74 1C\", \"[rbx+0x0].u16\", \"r11\"},\n    delta = {\"StatEntry::ImmediateDelta_Hook\", \"48 8B 4C 24 58 4C 8D 04 19\", \"[rsi+0x0].u16\", \"rbx\"},\n}\n-- Each factor: {settings section, key, place, \"\u003c\" for losses or \">\" for gains}.\nlocal FACTORS = {\n    {\"Stamina\", \"UseFactor\", \"use\", \"\u003c\"},\n    {\"Stamina\", \"DrainFactor\", \"rate\", \"\u003c\"}, {\"Stamina\", \"RecoveryFactor\", \"rate\", \">\"},\n    {\"Stamina\", \"CostFactor\", \"delta\", \"\u003c\"}, {\"Stamina\", \"GainFactor\", \"delta\", \">\"},\n    {\"Health\", \"DrainFactor\", \"rate\", \"\u003c\"}, {\"Health\", \"RecoveryFactor\", \"rate\", \">\"},\n    {\"Health\", \"DamageFactor\", \"delta\", \"\u003c\"}, {\"Health\", \"HealFactor\", \"delta\", \">\"},\n}\nlocal SELECTORS = {Stamina = \"StatDefinitions::StaminaSelector\", Health = \"StatDefinitions::HpSelector\"}\n\n-- Which selector belongs to stamina and HP is read from the game's own stat\n-- definitions: root slot -> root -> holder -> +8 data -> +0x10 definition.\nlocal slot = cdal.address(\"StatDefinitions::ClientRoot\")\nlocal function selector(stat)\n    local offset = cdal.value(SELECTORS[stat])\n    local p = mem.read_ptr(slot)\n    for _, step in ipairs({0, 8, 0x10}) do\n        if not p or p == 0 then return nil end\n        p = mem.read_ptr(p + step)\n    end\n    if not p or p == 0 or not offset then return nil end\n    local lo, hi = mem.read_u8(p + offset), mem.read_u8(p + offset + 1)\n    if not lo or not hi or lo + hi * 256 == 0xFFFF then return nil end  -- 0xFFFF: not set up yet\n    return lo + hi * 256\nend\n\nlocal rules, wanted = {}, {}\nfor _, f in ipairs(FACTORS) do\n    local factor = config.float(f[1], f[2], f[2] == \"UseFactor\" and 0 or 1)\n    if not (factor >= 0 and factor \u003c= 1000) then return log(\"off: \" .. f[1] .. \" \" .. f[2] .. \" must be 0 to 1000\") end\n    if factor ~= 1 then wanted[#wanted + 1] = {stat = f[1], place = PLACES[f[3]], sign = f[4], factor = factor} end\nend\nif #wanted == 0 then return log(\"off: every factor is 1\") end\n\nlocal function remove_all()\n    for _, w in ipairs(rules) do w.rule:remove() end\n    rules = {}\nend\n\n-- Rules start paused; they turn on once both selectors are known.\nlocal function install()\n    for _, w in ipairs(wanted) do\n        local place = w.place\n        local rule, why = cdal.rule(place[1], {\n            expect = place[2],\n            enabled = false,\n            when = { {place[3], \"==\", 0}, {place[4], w.sign, 0} },\n            set = { {place[4], \"mul\", w.factor} },\n        })\n        if not rule then remove_all(); log(\"off: \" .. place[1] .. \": \" .. tostring(why)); return false end\n        rules[#rules + 1] = {rule = rule, stat = w.stat}\n    end\n    return true\nend\n\nlocal on = false\nlocal function apply()  -- returns false while a selector cannot be read yet\n    local known = {Stamina = selector(\"Stamina\"), Health = selector(\"Health\")}\n    local ready = true\n    for _, w in ipairs(rules) do\n        local value = known[w.stat]\n        if value then w.rule:when(1, value) else ready = false end\n        w.rule:enable(on and value ~= nil)\n    end\n    return ready\nend\n\nif not install() then return end\non = config.bool(\"StatFactors\", \"Enabled\", false)\nlocal function refresh() apply(); bsx.after(1000, refresh) end  -- definitions can be rebuilt\nrefresh()\n\nlocal chord = config.string(\"StatFactors\", \"Hotkey\", \"ctrl+f4\")\nlocal ok, why = pcall(bsx.hotkey, chord, function()\n    on = not on\n    local ready = apply()\n    log(on and (ready and \"on\" or \"on, waiting for the game's stat definitions\") or \"off\")\nend)\nlog((on and \"on\" or \"off\") .. \" (\" .. #rules .. \" changed factors); \" .. (ok and chord .. \" toggles\" or \"no toggle key: \" .. tostring(why)))\n","lang":"lua","name":"main.lua"},{"code":"; Stat Factors scales how fast stamina and HP go down and up.\n; 1 leaves a path unchanged, 0.5 halves it, 0 stops it, 2 doubles it.\n; Every actor is affected, including enemies, NPCs and mounts.\n[StatFactors]\n; 1 turns the factors on when the game starts; the hotkey toggles them.\nEnabled=0\nHotkey=ctrl+f4\n\n[Stamina]\n; Stamina a skill costs when it starts (sprint, dodge, glide ...).\nUseFactor=0\n; The continuous drain and recovery rates.\nDrainFactor=1\nRecoveryFactor=1\n; Separate one-off stamina losses and gains.\nCostFactor=1\nGainFactor=1\n\n[Health]\nDrainFactor=1\nRecoveryFactor=1\n; One-off HP losses (damage) and gains (healing).\nDamageFactor=1\nHealFactor=1\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Stat Factors\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"StatDefinitions::ClientRoot\",\n    \"StatDefinitions::StaminaSelector\",\n    \"StatDefinitions::HpSelector\",\n    \"SkillResource::OneOffAmount_Hook\",\n    \"StatEntry::EvaluatedRateCoefficient_Hook\",\n    \"StatEntry::ImmediateDelta_Hook\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"stat_factors","kind":"lua","lua_api":3,"path":"bsx/lua/examples/stat_factors","tier":"safe","title":"Stat Factors","uses":[]},{"category":"Items & Inventory","description":"Copy to BSX/scripts/supply_check and choose exact item rows in settings.ini. Each count is the controlled character's own inventory, not the HUD total.","featured":false,"files":[{"code":"-- Copy to BSX/scripts/supply_check and choose exact item rows in settings.ini.\n-- Each count is the controlled character's own inventory, not the HUD total.\nlocal configured = config.string(\"SupplyCheck\", \"Rows\", \"\")\nlocal minimum = config.int(\"SupplyCheck\", \"Min\", 5)\nlocal minutes = config.int(\"SupplyCheck\", \"IntervalMinutes\", 5)\n\nlocal function parse_rows(text)\n    if text == \"\" then return {} end\n    local rows, seen, start = {}, {}, 1\n    while true do\n        local comma = string.find(text, \",\", start, true)\n        local token = string.sub(text, start, comma and comma - 1 or #text)\n        local left, right = 1, #token\n        while left \u003c= right and (string.byte(token, left) == 32 or string.byte(token, left) == 9) do left = left + 1 end\n        while right >= left and (string.byte(token, right) == 32 or string.byte(token, right) == 9) do right = right - 1 end\n        if left > right then return nil, \"Rows contains an empty row\" end\n        local row = 0\n        for i = left, right do\n            local digit = string.byte(token, i)\n            if digit \u003c 48 or digit > 57 then return nil, \"Rows must contain decimal row numbers\" end\n            row = row * 10 + digit - 48\n            if row > 65534 then return nil, \"row must be 0..65534\" end\n        end\n        if not seen[row] then\n            if #rows == 8 then return nil, \"Rows allows at most 8 distinct rows\" end\n            rows[#rows + 1], seen[row] = row, true\n        end\n        if not comma then return rows end\n        start = comma + 1\n    end\nend\n\nlocal rows, rows_why = parse_rows(configured)\nif not rows then\n    bsx.log(\"supply check: \" .. tostring(rows_why))\nelseif minimum \u003c 0 or minimum > 9007199254740991 then\n    bsx.log(\"supply check: Min must be a nonnegative exact integer\")\nelseif minutes \u003c 1 or minutes > 1440 then\n    bsx.log(\"supply check: IntervalMinutes must be 1..1440\")\nelseif #rows > 0 then\n    -- Counts are decimal strings; compare their lengths and digits without rounding.\n    local min_text = string.format(\"%.0f\", minimum)\n    local function below(count)\n        return #count \u003c #min_text or (#count == #min_text and count \u003c min_text)\n    end\n    local active, pending = false, false\n    local request_check\n    request_check = function()\n        if active then pending = true; return end\n        active = true\n        local index, low, failures = 1, {}, {}\n        local function next_row()\n            local row = rows[index]\n            local count, why = game.inventory.count(row)\n            if count == nil then\n                failures[#failures + 1] = \"row \" .. row .. \" count unavailable (\" .. string.sub(tostring(why), 1, 80) .. \")\"\n            elseif below(count) then\n                local name, name_why = game.item_name(row)\n                if not name then name = \"row \" .. row .. \" (name unavailable: \" .. tostring(name_why) .. \")\" end\n                low[#low + 1] = string.sub(name, 1, 90) .. \"=\" .. count\n            end\n            index = index + 1\n            if index \u003c= #rows then\n                -- A large inventory is read once per row; spread checks over frames.\n                bsx.after(0, next_row)\n                return\n            end\n            if #failures > 0 then bsx.log(\"supply check: \" .. table.concat(failures, \", \")) end\n            if #low > 0 then bsx.log(\"supply check: low on: \" .. table.concat(low, \", \")) end\n            active = false\n            if pending then pending = false; bsx.after(0, request_check) end\n        end\n        next_row()\n    end\n\n    local ok, why = pcall(bsx.on, \"save_loaded\", request_check)\n    if not ok then bsx.log(\"supply check: save_loaded unavailable (\" .. tostring(why) .. \"); timer remains active\") end\n    local function poll()\n        request_check()\n        bsx.after(minutes * 60000, poll)\n    end\n    bsx.after(minutes * 60000, poll)\nend\n","lang":"lua","name":"main.lua"},{"code":"[SupplyCheck]\n; Up to 8 exact inventory row ordinals, separated by commas. Empty disables checks.\n; Find rows for your game build first; they are not the external ItemKey.\nRows=\n; The same minimum applies to every row. Counts below it are reported.\nMin=5\n; Real-time minutes between checks, from 1 to 1440. Also checks after save_loaded.\nIntervalMinutes=5\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Supply Check\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\",\n    \"ActorComponents::Inventory\",\n    \"pa::ClientInventoryActorComponent::vftable\",\n    \"InventoryHolder::Buckets\",\n    \"InventoryHolder::BucketCount\",\n    \"InventoryBucket::SlotCount\",\n    \"InventoryItem::Stride\",\n    \"InventoryItem::Row\",\n    \"InventoryItem::Amount\",\n    \"ItemInfoManager::sInstance\",\n    \"pa::ItemInfoManager::vftable\",\n    \"ItemInfoManager::sEmptyRow\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::Key\",\n    \"DefinitionRow::InternalName\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"supply_check","kind":"lua","lua_api":3,"path":"bsx/lua/examples/supply_check","tier":"safe","title":"Supply Check","uses":[]},{"category":"World, Time & Exploration","description":"Copy this folder to BSX/scripts/travel_journal. Ctrl+Shift+F2 records a read-only observation in data/journal.txt, which the first entry creates. Keep data/journal.txt when updating the script: it is shared across saves.","featured":false,"files":[{"code":"-- Copy this folder to BSX/scripts/travel_journal. Ctrl+Shift+F2 records a\n-- read-only observation in data/journal.txt, which the first entry creates.\n-- Keep data/journal.txt when updating the script: it is shared across saves.\nlocal path = \"journal.txt\"\nlocal configured_note = config.string(\"TravelJournal\", \"Note\", \"\")\nlocal note_end = math.min(#configured_note, 48)\nlocal next_byte = string.byte(configured_note, note_end + 1)\nif next_byte and next_byte >= 128 and next_byte \u003c= 191 then\n    -- Don't cut a UTF-8 character in half at the byte limit.\n    while note_end > 0 do\n        local byte = string.byte(configured_note, note_end)\n        if byte \u003c 128 or byte > 191 then break end\n        note_end = note_end - 1\n    end\n    note_end = math.max(0, note_end - 1)\nend\nlocal note = string.sub(configured_note, 1, note_end)\nlocal safe_note = {}\nfor i = 1, #note do\n    local byte = string.byte(note, i)\n    safe_note[i] = (byte \u003c 32 or byte == 127 or byte == 124) and \" \" or string.sub(note, i, i)\nend\nnote = table.concat(safe_note)\n\nlocal function finite(n)\n    return type(n) == \"number\" and n == n and math.abs(n) \u003c math.huge\nend\n\n-- os.date is not in the sandbox. Convert Unix seconds to a readable UTC date.\nlocal function utc_date(timestamp)\n    if timestamp \u003c 0 or timestamp > 253402300799 or timestamp ~= math.floor(timestamp) then\n        return nil, \"real time is outside 1970..9999\"\n    end\n    local days = math.floor(timestamp / 86400)\n    local seconds = timestamp - days * 86400\n    local year = 1970\n    local function leap(y) return y % 4 == 0 and (y % 100 ~= 0 or y % 400 == 0) end\n    while true do\n        local length = leap(year) and 366 or 365\n        if days \u003c length then break end\n        days, year = days - length, year + 1\n    end\n    local months = {31, leap(year) and 29 or 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}\n    local month = 1\n    while days >= months[month] do days, month = days - months[month], month + 1 end\n    local hour = math.floor(seconds / 3600)\n    local minute = math.floor((seconds % 3600) / 60)\n    return string.format(\"%04d-%02d-%02dT%02d:%02d:%02dZ\", year, month, days + 1, hour, minute, seconds % 60)\nend\n\n-- string.find accepts at most 4096 input bytes in the safe sandbox. Read in\n-- chunks, and refuse malformed/oversized files instead of overwriting them.\nlocal function read_lines()\n    local ok, text = pcall(bsx.fs.read, path)\n    if not ok then\n        -- No journal yet: the first entry creates it.\n        if string.find(tostring(text), \"cannot open file\", 1, true) then return {} end\n        return nil, tostring(text)\n    end\n    local lines, partial = {}, \"\"\n    for offset = 1, #text, 4096 do\n        local chunk = string.sub(text, offset, offset + 4095)\n        local start = 1\n        while true do\n            local finish = string.find(chunk, \"\\n\", start, true)\n            if not finish then\n                partial = partial .. string.sub(chunk, start)\n                break\n            end\n            local line = partial .. string.sub(chunk, start, finish - 1)\n            if #line > 1024 or #lines == 2048 then return nil, \"journal has too many or oversized lines\" end\n            lines[#lines + 1], partial, start = line, \"\", finish + 1\n        end\n        if #partial > 1024 then return nil, \"journal has an oversized line\" end\n    end\n    if #partial > 0 then return nil, \"journal has an incomplete last line\" end\n    return lines\nend\n\n-- The last line holds rounded XYZ, so distance also survives a script reload.\nlocal function previous_position(line)\n    if not line or #line > 1024 then return nil end\n    local fields, start = {}, 1\n    for i = 1, 5 do\n        local finish = string.find(line, \" | \", start, true)\n        if not finish then return nil end\n        fields[i] = string.sub(line, start, finish - 1)\n        start = finish + 3\n    end\n    if string.sub(fields[3], 1, 2) ~= \"x=\" or string.sub(fields[4], 1, 2) ~= \"y=\" or\n       string.sub(fields[5], 1, 2) ~= \"z=\" then return nil end\n    local x, y, z = tonumber(string.sub(fields[3], 3)), tonumber(string.sub(fields[4], 3)), tonumber(string.sub(fields[5], 3))\n    if not finite(x) or not finite(y) or not finite(z) then return nil end\n    return {x = x, y = y, z = z}\nend\n\nlocal function record()\n    local position, position_why = game.player_position()\n    if not position then return bsx.log(\"travel journal: position unavailable (\" .. tostring(position_why) .. \")\") end\n    local time, time_why = game.time()\n    if not time then return bsx.log(\"travel journal: game time unavailable (\" .. tostring(time_why) .. \")\") end\n    local weather, weather_why = game.weather()\n    if not weather then return bsx.log(\"travel journal: weather unavailable (\" .. tostring(weather_why) .. \")\") end\n    local clock_ok, timestamp = pcall(os.time)\n    if not clock_ok or not finite(timestamp) then return bsx.log(\"travel journal: real time unavailable (\" .. tostring(timestamp) .. \")\") end\n    local utc, clock_why = utc_date(timestamp)\n    if not utc then return bsx.log(\"travel journal: real time unavailable (\" .. tostring(clock_why) .. \")\") end\n\n    local lines, read_why = read_lines()\n    if not lines then return bsx.log(\"travel journal: cannot read journal (\" .. tostring(read_why) .. \")\") end\n    local x, y, z = string.format(\"%.0f\", position.x), string.format(\"%.0f\", position.y), string.format(\"%.0f\", position.z)\n    local entry = string.format(\"utc=%s unix=%.0f | day=%.0f %02d:%02d:%02d | x=%s | y=%s | z=%s | rain=%.9g | snow=%.9g\",\n        utc, timestamp, time.day, time.hour, time.minute, time.second, x, y, z, weather.rain_base, weather.snow_base)\n    if note ~= \"\" then entry = entry .. \" | note=\" .. note end\n    if #entry > 900 then return bsx.log(\"travel journal: entry is too long to record\") end\n\n    local previous = previous_position(lines[#lines])\n    local distance = \"first entry or previous position unavailable\"\n    if previous then\n        local dx, dy, dz = tonumber(x) - previous.x, tonumber(y) - previous.y, tonumber(z) - previous.z\n        local length = math.sqrt(dx * dx + dy * dy + dz * dz)\n        distance = finite(length) and string.format(\"%.3f game units\", length) or \"distance out of range\"\n    end\n\n    -- Keep the newest 499 old lines, and also respect the 64 KiB host limit.\n    local first = math.max(1, #lines - 498)\n    local bytes = #entry + 1\n    for i = first, #lines do bytes = bytes + #lines[i] + 1 end\n    while bytes > 65536 and first \u003c= #lines do\n        bytes = bytes - #lines[first] - 1\n        first = first + 1\n    end\n    local old = first \u003c= #lines and (table.concat(lines, \"\\n\", first, #lines) .. \"\\n\") or \"\"\n    local ok, write_why = pcall(bsx.fs.write, path, old .. entry .. \"\\n\")\n    if not ok then return bsx.log(\"travel journal: write failed (\" .. tostring(write_why) .. \")\") end\n    bsx.log(\"travel journal: \" .. entry .. \" | distance=\" .. distance)\nend\n\nlocal ok, why = pcall(bsx.hotkey, \"ctrl+shift+f2\", record)\nif not ok then bsx.log(\"travel journal: hotkey unavailable (\" .. tostring(why) .. \")\") end\n","lang":"lua","name":"main.lua"},{"code":"[TravelJournal]\n; Optional text added to each entry. Change it and let the script reload.\n; Up to 48 bytes are kept without splitting UTF-8; separators and controls become spaces.\nNote=\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Travel Journal\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"pa::ClientActorManager::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\",\n    \"Actor::Components\",\n    \"ActorComponents::TransformSync\",\n    \"pa::ClientTransformSyncActorComponent::vftable\",\n    \"CommonTransformSyncActorComponent::TransformSnapshot\",\n    \"ClientTransformSyncActorComponent::Owner\",\n    \"TransformSnapshot::RelativeFrame\",\n    \"FieldTime::sClientTime\",\n    \"WorldSystem::RenderManager\",\n    \"RenderManager::WeatherState\",\n    \"WeatherState::Resource\",\n    \"WeatherResource::Climate\",\n    \"Climate::RainBase\",\n    \"Climate::SnowBase\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"travel_journal","kind":"lua","lua_api":3,"path":"bsx/lua/examples/travel_journal","tier":"safe","title":"Travel Journal","uses":[]},{"category":"BSX Core & Diagnostics","description":"VFX Beam Tether Cookbook (Lua API 7+, Changes tier) Demonstrates R1 spawn-time point-to-point native `.effect` tether linking: Passes `attach_actor`, `socket`, `target_actor`, and `target_bone` to `game.vfx.spawn(...)` V","featured":false,"files":[{"code":"-- VFX Beam Tether Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates R1 spawn-time point-to-point native `.effect` tether linking:\n--   - Passes `attach_actor`, `socket`, `target_actor`, and `target_bone` to `game.vfx.spawn(...)`\n--   - Verifies `:info()` reports `target_actor` / `target_bone` and `h.set_target == nil` (cleanly omitted)\n--   - Resolves target actor from `game.actors.nearby()` / `game.actors()` (with MockWorld actor fallback)\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal state = {\n    world_ready = false,\n    started = false,\n    done = false,\n    beam = nil,\n    t = 0.0,\n    status = \"Waiting for world_ready...\",\n}\n\nlocal panel, status_lbl\n\nlocal function pick_beam_effect()\n    if game.vfx and game.vfx.catalog then\n        local ok, res = pcall(game.vfx.catalog, \"lightning\", 20)\n        if ok and type(res) == \"table\" and res[1] and res[1].path then\n            return res[1].path\n        end\n    end\n    return \"effect/magic/lightning_arc.action.effect\"\nend\n\nlocal function pick_socket(actor_ptr, prefs, fallback)\n    if not (game.vfx and game.vfx.sockets) then return fallback end\n    local ok, list = pcall(game.vfx.sockets, actor_ptr)\n    if not ok or type(list) ~= \"table\" or #list == 0 then return fallback end\n    for _, p in ipairs(prefs) do\n        for i = 1, #list do\n            if list[i]:lower():find(p, 1, true) then\n                return list[i]\n            end\n        end\n    end\n    return list[1]\nend\n\nlocal function resolve_actors()\n    local p_actor = 0\n    local t_actor = 0\n    if game.player then\n        local ok_p, pa = pcall(game.player)\n        if ok_p and type(pa) == \"number\" and pa > 0 then p_actor = pa end\n    end\n    if game.actors and game.actors.nearby then\n        local ok_n, near = pcall(game.actors.nearby, 50.0, 8)\n        if ok_n and type(near) == \"table\" and near[1] and near[1].actor then\n            t_actor = near[1].actor\n        end\n    end\n    if t_actor == 0 and game.actors then\n        local ok_a, list, a_err = pcall(game.actors, 64)\n        if ok_a and type(list) == \"table\" then\n            for i = 1, #list do\n                if list[i].controlled and p_actor == 0 then p_actor = list[i].actor or 0 end\n                if not list[i].controlled and not list[i].dead and t_actor == 0 then\n                    t_actor = list[i].actor or 0\n                end\n            end\n        elseif type(a_err) == \"string\" and a_err:lower():find(\"mock world\", 1, true) then\n            p_actor = 0x1001\n            t_actor = 0x1002\n        end\n    end\n    if t_actor == 0 then t_actor = p_actor end\n    return p_actor, t_actor\nend\n\nlocal function spawn_tether()\n    local av = assert(game.vfx.available())\n    assert(av.can_tether == true, \"tether capability unavailable\")\n    assert(av.can_set_target == false, \"unexpected can_set_target=true\")\n\n    local p_actor, t_actor = resolve_actors()\n    if p_actor == 0 then return false end\n\n    local p_sock = pick_socket(p_actor, { \"hand_r\", \"weapon_r\", \"hand\" }, \"Bip01_R_Hand\")\n    local t_sock = pick_socket(t_actor, { \"spine\", \"head\", \"chest\" }, \"Bip01_Spine1\")\n    local path = pick_beam_effect()\n\n    local h, err = game.vfx.spawn({\n        path = path,\n        attach_actor = p_actor,\n        socket = p_sock,\n        target_actor = t_actor,\n        target_bone = t_sock,\n        scale = 1.15,\n        duration = 6.0,\n    })\n    assert(h ~= nil, \"tether spawn failed: \" .. tostring(err))\n    assert(h.set_target == nil, \"set_target should be cleanly omitted\")\n\n    local inf = assert(h:info())\n    assert(inf.attached == true, \"expected attached=true\")\n    assert(inf.target_actor == t_actor, \"target_actor mismatch\")\n    assert(inf.target_bone == t_sock, \"target_bone mismatch\")\n\n    state.beam = h\n    state.started = true\n    state.status = string.format(\"Tether %s -> 0x%X:%s\", p_sock, t_actor, t_sock)\n    if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\n    bsx.log(string.format(\"VFX_TETHER_OK src=%s target=0x%X target_bone=%s\", p_sock, t_actor, t_sock))\n    return true\nend\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"VFX Beam Tether\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. state.status)\n        panel:button(\"Respawn Tether\", function()\n            if state.beam then pcall(function() state.beam:stop(0.05) end); state.beam = nil end\n            spawn_tether()\n        end)\n        panel:same_line()\n        panel:button(\"Stop Tether\", function()\n            if state.beam then pcall(function() state.beam:stop(0.1) end); state.beam = nil end\n        end)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    state.world_ready = true\nend)\n\nbsx.on(\"frame\", function()\n    if state.world_ready and not state.started then\n        spawn_tether()\n        return\n    end\n    if state.beam and state.beam:alive() then\n        state.t = state.t + 1.0 / 60.0\n        local pulse = 1.0 + 0.15 * math.sin(state.t * 8.0)\n        pcall(function() state.beam:set_transform({ scale = { pulse, 1.0, pulse } }) end)\n    end\nend)\n\nfunction on_unload()\n    if state.beam then pcall(function() state.beam:stop(0.0) end) end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"VFX Beam Tether\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"vfx_beam_tether","kind":"lua","lua_api":7,"path":"bsx/lua/examples/vfx_beam_tether","tier":"changes","title":"VFX Beam Tether","uses":["ui","player","snapshots","positions"]},{"category":"BSX Core & Diagnostics","description":"VFX Playback Controls Cookbook (Lua API 7+, Changes tier) Demonstrates R1 native `.effect` playback & time controls: vfx_handle:set_speed(rate), :pause(), :resume(), :restart(), :set_looping(enabled), :info() Short-durat","featured":false,"files":[{"code":"-- VFX Playback Controls Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates R1 native `.effect` playback & time controls:\n--   - vfx_handle:set_speed(rate), :pause(), :resume(), :restart(), :set_looping(enabled), :info()\n--   - Short-duration looping wrap verification (duration = 0.0005 under --fast)\n--   - Pure-GPU fail-closed verification on `pure_gpu_embers.system.effect` (info.gpu_active and not info.cpu_active)\n--   - Optional BSX Overlay UI controls for interactive live testing\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal state = {\n    world_ready = false,\n    step = 0,\n    done = false,\n    h_loop = nil,\n    h_ctrl = nil,\n    h_gpu = nil,\n    age_paused = 0.0,\n    wrap_verified = false,\n    gpu_refused = false,\n    status = \"Waiting for world_ready...\",\n}\n\nlocal panel, status_lbl\n\nlocal function pick_cpu_effect()\n    if not (game.vfx and game.vfx.catalog) then\n        return \"effect/magic/fireball_loop.level.effect\"\n    end\n    local ok, list = pcall(game.vfx.catalog, \"fireball\", 20)\n    if ok and type(list) == \"table\" then\n        for i = 1, #list do\n            local p = list[i].path\n            if type(p) == \"string\" and not p:lower():find(\"pure_gpu\", 1, true) then\n                return p\n            end\n        end\n    end\n    local ok2, all = pcall(game.vfx.catalog, \"\", 50)\n    if ok2 and type(all) == \"table\" then\n        for i = 1, #all do\n            local p = all[i].path\n            if type(p) == \"string\" and not p:lower():find(\"pure_gpu\", 1, true) then\n                return p\n            end\n        end\n    end\n    return \"effect/magic/fireball_loop.level.effect\"\nend\n\nlocal function pick_pure_gpu_effect()\n    if game.vfx and game.vfx.catalog then\n        local ok, list = pcall(game.vfx.catalog, \"pure_gpu\", 10)\n        if ok and type(list) == \"table\" and list[1] and list[1].path then\n            return list[1].path\n        end\n    end\n    return \"effect/gpu/pure_gpu_embers.system.effect\"\nend\n\nlocal function safe_stop(h)\n    if h and h.stop then pcall(function() h:stop(0.0) end) end\nend\n\nlocal function get_origin()\n    if game.player_position then\n        local ok, p = pcall(game.player_position)\n        if ok and p and p.x then return p.x, p.y + 1.2, p.z + 2.0 end\n    end\n    return -10500.0, 613.2, -4373.0\nend\n\nlocal function start_verification()\n    local av = game.vfx and game.vfx.available and game.vfx.available() or nil\n    assert(av and av.available and av.can_playback and av.can_restart and av.can_looping, \"playback APIs unavailable\")\n\n    local ox, oy, oz = get_origin()\n    local cpu_path = pick_cpu_effect()\n    local gpu_path = pick_pure_gpu_effect()\n\n    -- 1) Looping wrap handle (0.0005s wraps cleanly across --fast frames)\n    state.h_loop = assert(game.vfx.spawn({\n        path = cpu_path,\n        pos = { ox, oy, oz },\n        duration = 0.0005,\n        speed = 2.0,\n        looping = true,\n        paused = false,\n    }))\n\n    -- 2) Interactive/test control handle (10s duration)\n    state.h_ctrl = assert(game.vfx.spawn({\n        path = cpu_path,\n        pos = { ox + 1.5, oy, oz },\n        duration = 10.0,\n        speed = 2.0,\n        looping = false,\n        paused = false,\n    }))\n\n    -- 3) Pure-GPU fail-closed verification\n    local g_bad, g_err = game.vfx.spawn(gpu_path, { pos = { ox - 1.5, oy, oz }, speed = 2.0 })\n    assert(g_bad == nil and type(g_err) == \"string\", \"expected spawn-time pure-GPU speed rejection\")\n\n    state.h_gpu = assert(game.vfx.spawn(gpu_path, { pos = { ox - 1.5, oy, oz }, duration = 5.0 }))\n    local gi = assert(state.h_gpu:info())\n    if gi.gpu_active and not gi.cpu_active then\n        local ok_s, err_s = state.h_gpu:set_speed(0.5)\n        local ok_p, err_p = state.h_gpu:pause()\n        local ok_l, err_l = state.h_gpu:set_looping(true)\n        assert(ok_s == nil and type(err_s) == \"string\")\n        assert(ok_p == nil and type(err_p) == \"string\")\n        assert(ok_l == nil and type(err_l) == \"string\")\n        assert(state.h_gpu:restart() == true)\n        state.gpu_refused = true\n    end\n\n    state.step = 1\n    state.status = \"Verification running...\"\nend\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"VFX Playback Controls\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. state.status)\n        panel:button(\"Pause\", function()\n            if state.h_ctrl then\n                local inf = state.h_ctrl:info()\n                if inf and not (inf.gpu_active and not inf.cpu_active) then\n                    state.h_ctrl:pause()\n                end\n            end\n        end)\n        panel:same_line()\n        panel:button(\"Resume\", function()\n            if state.h_ctrl then\n                local inf = state.h_ctrl:info()\n                if inf and not (inf.gpu_active and not inf.cpu_active) then\n                    state.h_ctrl:resume()\n                end\n            end\n        end)\n        panel:same_line()\n        panel:button(\"Restart\", function()\n            if state.h_ctrl then state.h_ctrl:restart() end\n        end)\n        panel:slider(\"Speed\", 0.0, 4.0, 1.0, function(v)\n            if state.h_ctrl then\n                local inf = state.h_ctrl:info()\n                if inf and not (inf.gpu_active and not inf.cpu_active) then\n                    state.h_ctrl:set_speed(v)\n                end\n            end\n        end)\n        panel:checkbox(\"Looping\", false, function(v)\n            if state.h_ctrl then\n                local inf = state.h_ctrl:info()\n                if inf and not (inf.gpu_active and not inf.cpu_active) then\n                    state.h_ctrl:set_looping(v == true)\n                end\n            end\n        end)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    state.world_ready = true\nend)\n\nbsx.on(\"frame\", function()\n    if state.world_ready and state.step == 0 then\n        start_verification()\n        return\n    end\n    if state.step == 0 or state.done then return end\n    state.step = state.step + 1\n\n    if state.step == 6 then\n        -- Verify looping short-duration handle stayed alive & wrapped in [0, 0.0005)\n        assert(state.h_loop:alive() == true, \"looping handle expired unexpectedly\")\n        local li = assert(state.h_loop:info())\n        assert(li.age >= 0.0 and li.age \u003c 0.0005, \"looping age out of range\")\n        assert(state.h_loop:set_looping(false) == true)\n        state.wrap_verified = true\n\n        -- Pause control handle\n        assert(state.h_ctrl:pause() == true)\n        local ci = assert(state.h_ctrl:info())\n        state.age_paused = ci.age\n        assert(ci.paused == true and state.age_paused > 0.0)\n    elseif state.step == 9 then\n        -- Age stayed frozen while paused\n        local ci = assert(state.h_ctrl:info())\n        assert(math.abs(ci.age - state.age_paused) \u003c 1e-6, \"paused age drifted\")\n        assert(state.h_ctrl:resume() == true)\n        assert(state.h_ctrl:set_speed(0.5) == true)\n    elseif state.step == 12 then\n        -- Age advanced after resume, speed is 0.5, restart resets age to 0\n        local ci = assert(state.h_ctrl:info())\n        assert(ci.paused == false and math.abs(ci.rate - 0.5) \u003c 1e-6)\n        assert(ci.age > state.age_paused, \"resumed age did not advance\")\n        assert(state.h_ctrl:restart() == true)\n        local ri = assert(state.h_ctrl:info())\n        assert(ri.age == 0.0, \"restart did not reset age to 0\")\n    elseif state.step == 20 then\n        assert(state.h_loop:alive() == false, \"non-looping short handle should expire\")\n        state.done = true\n        state.status = string.format(\"OK wrap=%s gpu_fail_closed=%s\", tostring(state.wrap_verified), tostring(state.gpu_refused))\n        if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\n        bsx.log(string.format(\"VFX_PLAYBACK_OK wrap=%s gpu_fail_closed=%s\", tostring(state.wrap_verified), tostring(state.gpu_refused)))\n        safe_stop(state.h_ctrl)\n        safe_stop(state.h_gpu)\n    end\nend)\n\nfunction on_unload()\n    safe_stop(state.h_loop)\n    safe_stop(state.h_ctrl)\n    safe_stop(state.h_gpu)\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"VFX Playback Controls\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"vfx_playback_controls","kind":"lua","lua_api":7,"path":"bsx/lua/examples/vfx_playback_controls","tier":"changes","title":"VFX Playback Controls","uses":["ui","snapshots","positions"]},{"category":"BSX Core & Diagnostics","description":"VFX Socket Layers Cookbook (Lua API 7+, Changes tier) Demonstrates R1 multi-layer native `.effect` socket attachments: Enumerates `game.vfx.sockets(actor)` Attaches 3 simultaneous `.effect` layers with `offset`, Euler `r","featured":false,"files":[{"code":"-- VFX Socket Layers Cookbook (Lua API 7+, Changes tier)\n-- Demonstrates R1 multi-layer native `.effect` socket attachments:\n--   - Enumerates `game.vfx.sockets(actor)`\n--   - Attaches 3 simultaneous `.effect` layers with `offset`, Euler `rot`, quaternion `quat`, and non-uniform `scale`\n--   - Continuously updates transforms via `:set_transform(...)` and verifies `game.vfx.active() >= 3`\n-- 100% native .effect visuals (no 2D overlay drawing).\n\nlocal state = {\n    world_ready = false,\n    started = false,\n    done = false,\n    frames = 0,\n    layers = {},\n    status = \"Waiting for world_ready...\",\n}\n\nlocal panel, status_lbl\n\nlocal function pick_effect(query, fallback)\n    if game.vfx and game.vfx.catalog then\n        local ok, res = pcall(game.vfx.catalog, query, 20)\n        if ok and type(res) == \"table\" then\n            for i = 1, #res do\n                local p = res[i].path\n                if type(p) == \"string\" and not p:lower():find(\"pure_gpu\", 1, true) then\n                    return p\n                end\n            end\n        end\n    end\n    return fallback\nend\n\nlocal function pick_distinct_sockets(socks)\n    local chosen, used = {}, {}\n    local prefs_list = {\n        { \"hand_r\", \"weapon_r\", \"r_hand\" },\n        { \"hand_l\", \"weapon_l\", \"l_hand\" },\n        { \"spine\", \"head\", \"chest\" },\n    }\n    for _, prefs in ipairs(prefs_list) do\n        local pick = nil\n        for _, p in ipairs(prefs) do\n            for i = 1, #socks do\n                if not used[socks[i]] and socks[i]:lower():find(p, 1, true) then\n                    pick = socks[i]\n                    break\n                end\n            end\n            if pick then break end\n        end\n        if not pick then\n            for i = 1, #socks do\n                if not used[socks[i]] then pick = socks[i]; break end\n            end\n        end\n        pick = pick or socks[1] or \"Bip01_R_Hand\"\n        used[pick] = true\n        chosen[#chosen + 1] = pick\n    end\n    return chosen\nend\n\nlocal function resolve_player_actor()\n    if game.player then\n        local ok, pa = pcall(game.player)\n        if ok and type(pa) == \"number\" and pa > 0 then return pa end\n    end\n    if game.actors then\n        local ok, list, err = pcall(game.actors, 64)\n        if ok and type(list) == \"table\" then\n            for i = 1, #list do\n                if list[i].controlled and list[i].actor then return list[i].actor end\n            end\n        elseif type(err) == \"string\" and err:lower():find(\"mock world\", 1, true) then\n            return 0x1001\n        end\n    end\n    return 0\nend\n\nlocal function stop_layers()\n    for i = 1, #state.layers do\n        if state.layers[i].stop then pcall(function() state.layers[i]:stop(0.05) end) end\n    end\n    state.layers = {}\nend\n\nlocal function spawn_layers()\n    local p_actor = resolve_player_actor()\n    if p_actor == 0 then return false end\n    local ok_s, socks = pcall(game.vfx.sockets, p_actor)\n    assert(ok_s and type(socks) == \"table\" and #socks >= 1, \"no sockets enumerated\")\n\n    local chosen = pick_distinct_sockets(socks)\n    local fx1 = pick_effect(\"fire_blade\", \"effect/weapon/fire_blade_aura.level.effect\")\n    local fx2 = pick_effect(\"holy_shield\", \"effect/magic/holy_shield_aura.level.effect\")\n    local fx3 = pick_effect(\"shadow_vortex\", \"effect/magic/shadow_vortex.level.effect\")\n\n    stop_layers()\n    state.layers[1] = assert(game.vfx.spawn({\n        path = fx1,\n        attach_actor = p_actor,\n        socket = chosen[1],\n        offset = { x = 0.05, y = 0.10, z = 0.00 },\n        rot = { rx = 0.0, ry = 45.0, rz = 0.0 },\n        scale = { x = 0.85, y = 1.15, z = 0.85 },\n        duration = 6.0,\n    }))\n    state.layers[2] = assert(game.vfx.spawn({\n        path = fx2,\n        attach_actor = p_actor,\n        socket = chosen[2],\n        offset = { -0.05, 0.10, 0.00 },\n        quat = { qx = 0.0, qy = 0.38268, qz = 0.0, qw = 0.92388 },\n        scale = { 0.90, 0.90, 1.10 },\n        duration = 6.0,\n    }))\n    state.layers[3] = assert(game.vfx.spawn({\n        path = fx3,\n        attach_actor = p_actor,\n        socket = chosen[3],\n        offset = { x = 0.0, y = 0.25, z = -0.10 },\n        rot = { 15.0, 0.0, 15.0 },\n        scale = 1.20,\n        duration = 6.0,\n    }))\n\n    state.started = true\n    state.status = string.format(\"Attached 3 layers (%s, %s, %s)\", chosen[1], chosen[2], chosen[3])\n    if panel and status_lbl then panel:set_text(status_lbl, \"Status: \" .. state.status) end\n    return true\nend\n\nif bsx.ui and bsx.ui.panel then\n    panel = bsx.ui.panel(\"VFX Socket Layers\")\n    if panel then\n        status_lbl = panel:text(\"Status: \" .. state.status)\n        panel:button(\"Attach 3 Layers\", function() spawn_layers() end)\n        panel:same_line()\n        panel:button(\"Clear Layers\", function() stop_layers() end)\n    end\nend\n\nbsx.on(\"world_ready\", function()\n    state.world_ready = true\nend)\n\nbsx.on(\"frame\", function()\n    if state.world_ready and not state.started then\n        spawn_layers()\n        return\n    end\n    if not state.started then return end\n    state.frames = state.frames + 1\n\n    local angle = state.frames * 4.0\n    if state.layers[1] and state.layers[1]:alive() then\n        assert(state.layers[1]:set_transform({\n            offset = { x = 0.05, y = 0.10 + 0.03 * math.sin(state.frames * 0.2), z = 0.0 },\n            rot = { rx = 0.0, ry = angle, rz = 0.0 },\n            scale = { x = 0.9, y = 1.1, z = 0.9 },\n        }) == true)\n    end\n\n    if not state.done and state.frames >= 5 then\n        local act = assert(game.vfx.active())\n        assert(#act >= 3, \"expected >= 3 active socket layers\")\n        for i = 1, 3 do\n            local inf = assert(state.layers[i]:info())\n            assert(inf.attached == true, \"expected attached=true on layer \" .. i)\n        end\n        state.done = true\n        bsx.log(string.format(\"VFX_SOCKET_LAYERS_OK active=%d\", #act))\n    end\nend)\n\nfunction on_unload()\n    stop_layers()\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"VFX Socket Layers\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 7,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\"]\n}\n","lang":"json","name":"script.json"}],"id":"vfx_socket_layers","kind":"lua","lua_api":7,"path":"bsx/lua/examples/vfx_socket_layers","tier":"changes","title":"VFX Socket Layers","uses":["ui","player","snapshots","positions"]},{"category":"Appearance & Outfits","description":"Saves and applies player gear visibility presets and appearance metadata using BSX Lua API 6 (`game.appearance.export_preset()`, `game.appearance.apply_preset(...)`, `game.appearance.equipped_dyes()`, and `game.appearanc","featured":false,"files":[{"code":"-- Wardrobe Presets: save and restore player appearance presets as JSON via BSX Lua API 6.\n\nlocal state = {\n  auto_town = bsx.config.bool('WardrobePresets', 'AutoTown', false),\n  status = 'Ready',\n  summary = 'Dyes/Visuals: waiting for world_ready',\n}\n\nlocal function json_slot_file(slot_id)\n  return 'preset_' .. slot_id .. '.json'\nend\n\nlocal function legacy_slot_file(slot_id)\n  return 'preset_' .. slot_id .. '.txt'\nend\n\nlocal function count_table(t)\n  local n = 0\n  if type(t) ~= 'table' then return 0 end\n  for _ in pairs(t) do n = n + 1 end\n  return n\nend\n\nlocal function encode_preset(preset, dyes, visuals)\n  local parts_str = {}\n  if type(preset and preset.parts) == 'table' then\n    for k, mode in pairs(preset.parts) do\n      parts_str[tostring(k)] = tonumber(mode) or 0\n    end\n  end\n  return bsx.json.encode({\n    version = 2,\n    parts = parts_str,\n    customization = type(preset and preset.customization) == 'table' and preset.customization or nil,\n    dye_slots = type(dyes) == 'table' and #dyes or 0,\n    visual_slots = type(visuals) == 'table' and #visuals or 0,\n    equipped_dyes = type(dyes) == 'table' and dyes or {},\n    visual_items = type(visuals) == 'table' and visuals or {},\n  }, { pretty = true })\nend\n\nlocal function deserialize_legacy(raw)\n  local parts = {}\n  local count = 0\n  for line in string.gmatch(raw or '', '[^\\r\\n]+') do\n    local k, v = string.match(line, '^(%d+)=(-?%d+)$')\n    if k and v then\n      parts[tonumber(k)] = tonumber(v)\n      count = count + 1\n    end\n  end\n  if count == 0 then return nil end\n  return { parts = parts }, 0, 0\nend\n\nlocal function load_preset_slot(slot_id)\n  local jfile = json_slot_file(slot_id)\n  if bsx.fs.exists(jfile) then\n    local ok_r, raw = pcall(bsx.fs.read, jfile)\n    if ok_r and type(raw) == 'string' then\n      local doc = bsx.json.decode(raw)\n      if type(doc) == 'table' then\n        local parts = {}\n        if type(doc.parts) == 'table' then\n          for k, v in pairs(doc.parts) do\n            local nk = tonumber(k)\n            if nk and type(v) == 'number' then\n              parts[nk] = v\n            end\n          end\n        end\n        return { parts = parts, customization = doc.customization }, tonumber(doc.dye_slots) or 0, tonumber(doc.visual_slots) or 0\n      end\n    end\n  end\n  local lfile = legacy_slot_file(slot_id)\n  if bsx.fs.exists(lfile) then\n    local ok_r, raw = pcall(bsx.fs.read, lfile)\n    if ok_r and type(raw) == 'string' then\n      return deserialize_legacy(raw)\n    end\n  end\n  return nil\nend\n\nlocal panel = bsx.ui.panel('Wardrobe Presets')\nlocal status_lbl = panel and panel:text('Status: Ready')\nlocal summary_lbl = panel and panel:text('Dyes/Visuals: waiting for world_ready')\n\nlocal function set_status(msg)\n  state.status = msg\n  if panel and status_lbl then\n    panel:set_text(status_lbl, 'Status: ' .. msg)\n  end\nend\n\nlocal function refresh_appearance_summary()\n  local ok_d, dyes = pcall(game.appearance.equipped_dyes)\n  local ok_v, visuals = pcall(game.appearance.visual_items)\n  local d_cnt = (ok_d and type(dyes) == 'table') and #dyes or -1\n  local v_cnt = (ok_v and type(visuals) == 'table') and #visuals or -1\n  local parts = {}\n  parts[#parts + 1] = d_cnt >= 0 and ('Dyes=' .. d_cnt) or 'Dyes=n/a'\n  parts[#parts + 1] = v_cnt >= 0 and ('VisualSlots=' .. v_cnt) or 'VisualSlots=n/a'\n  state.summary = table.concat(parts, ' | ')\n  if panel and summary_lbl then\n    panel:set_text(summary_lbl, state.summary)\n  end\n  return dyes, visuals\nend\n\nlocal function save_slot(slot_id, label)\n  local preset, err = game.appearance.export_preset()\n  if not preset then\n    set_status('Export unavailable: ' .. tostring(err))\n    return\n  end\n  local dyes, visuals = refresh_appearance_summary()\n  local encoded, jerr = encode_preset(preset, dyes, visuals)\n  if not encoded then\n    set_status('Encode failed: ' .. tostring(jerr))\n    return\n  end\n  local ok, werr = pcall(bsx.fs.write, json_slot_file(slot_id), encoded)\n  if ok then\n    set_status(string.format('Saved %s (%d parts, %d dye slots, %d visuals)',\n      label, count_table(preset.parts), type(dyes) == 'table' and #dyes or 0, type(visuals) == 'table' and #visuals or 0))\n    bsx.ui.toast('Saved ' .. label, { title = 'Wardrobe Presets' })\n  else\n    set_status('Save failed: ' .. tostring(werr))\n  end\nend\n\nlocal function apply_slot(slot_id, label)\n  local preset, d_cnt, v_cnt = load_preset_slot(slot_id)\n  if not preset then\n    set_status(label .. ' not saved yet')\n    return\n  end\n  local ok, err = game.appearance.apply_preset(preset)\n  if ok then\n    set_status(string.format('Applied %s (%d parts; saved dyes=%d visuals=%d)',\n      label, count_table(preset.parts), d_cnt or 0, v_cnt or 0))\n  else\n    set_status('Apply failed: ' .. tostring(err))\n  end\nend\n\nif panel then\n  for _, slot in ipairs({\n    { id = '1', name = 'Slot 1 (Town)' },\n    { id = '2', name = 'Slot 2 (Combat)' },\n    { id = '3', name = 'Slot 3 (Stealth)' },\n  }) do\n    panel:button('Save ' .. slot.name, function() save_slot(slot.id, slot.name) end)\n    panel:same_line()\n    panel:button('Apply ' .. slot.name, function() apply_slot(slot.id, slot.name) end)\n  end\n  panel:separator()\n  panel:checkbox('Auto-apply Slot 1 on entering town', state.auto_town, function(v)\n    state.auto_town = (v == true)\n    bsx.config.set('WardrobePresets', 'AutoTown', state.auto_town)\n    bsx.config.save()\n  end)\n  panel:button('Refresh Dyes & Visuals', function() refresh_appearance_summary() end)\n  panel:same_line()\n  panel:button('Reset Native Appearance', function()\n    local ok, err = game.appearance.clear_part_overrides()\n    set_status(ok and 'Cleared part overrides' or ('Clear failed: ' .. tostring(err)))\n  end)\nend\n\npcall(bsx.on, 'zone_changed', function(e)\n  if state.auto_town and e and e.in_town and not e.prev_in_town then\n    apply_slot('1', 'Slot 1 (Town)')\n  end\nend)\n\nbsx.on('world_ready', function()\n  refresh_appearance_summary()\n  bsx.log('WARDROBE_PRESETS_READY ' .. state.summary)\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Wardrobe Presets\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 6,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"wardrobe_presets","kind":"lua","lua_api":6,"path":"bsx/lua/examples/wardrobe_presets","tier":"changes","title":"Wardrobe Presets","uses":["ui","player","snapshots","server_commands"]},{"category":"World, Time & Exploration","description":"Read-only game observations. Writes only this script's data/last-waypoint.txt. Direction is signed XYZ; compass north and metre scale need a live check.","featured":false,"files":[{"code":"-- Read-only game observations. Writes only this script's data/last-waypoint.txt.\n-- Direction is signed XYZ; compass north and metre scale need a live check.\nlocal path = \"last-waypoint.txt\"\nlocal last\nlocal function finite(value)\n    return type(value) == \"number\" and value == value and math.abs(value) \u003c math.huge\nend\nlocal function restore()\n    local ok, text = pcall(bsx.fs.read, path)\n    if not ok then return end\n    if type(text) ~= \"string\" or #text > 512 then return end\n    local fields, start = {}, 1\n    for i = 1, 5 do\n        local finish = string.find(text, \"\\n\", start, true)\n        if not finish then return end\n        fields[i] = string.sub(text, start, finish - 1)\n        start = finish + 1\n    end\n    if start ~= #text + 1 or #fields[1] == 0 or #fields[1] > 96 then return end\n    local stamp, x, y, z = tonumber(fields[2]), tonumber(fields[3]), tonumber(fields[4]), tonumber(fields[5])\n    if not finite(stamp) or stamp \u003c 0 or stamp ~= math.floor(stamp) or\n       not finite(x) or not finite(y) or not finite(z) then return end\n    last = {name = fields[1], timestamp = stamp, x = x, y = y, z = z}\nend\nrestore()\n\nlocal function save()\n    local p, why = game.player_position()\n    if not p then return bsx.log(\"waypoints: save unavailable (\" .. why .. \")\") end\n    local stamp = os.time()\n    local name = \"Waypoint \" .. string.format(\"%.0f\", stamp)\n    local text = string.format(\"%s\\n%.0f\\n%.17g\\n%.17g\\n%.17g\\n\", name, stamp, p.x, p.y, p.z)\n    local ok, error_text = pcall(bsx.fs.write, path, text)\n    if not ok then return bsx.log(\"waypoints: save failed (\" .. tostring(error_text) .. \")\") end\n    last = {name = name, timestamp = stamp, x = p.x, y = p.y, z = p.z}\n    bsx.log(string.format(\"waypoints: saved %s at (%.3f, %.3f, %.3f)\", name, p.x, p.y, p.z))\nend\nlocal function locate()\n    if not last then return bsx.log(\"waypoints: no saved waypoint; press Ctrl+F11\") end\n    local p, why = game.player_position()\n    if not p then return bsx.log(\"waypoints: distance unavailable (\" .. why .. \")\") end\n    local dx, dy, dz = last.x - p.x, last.y - p.y, last.z - p.z\n    local distance = math.sqrt(dx*dx + dy*dy + dz*dz)\n    if not finite(distance) then return bsx.log(\"waypoints: saved coordinates are out of range\") end\n    local divisor = distance > 0 and distance or 1\n    bsx.log(string.format(\"waypoints: %s timestamp=%.0f distance=%.3f game units; direction XYZ=(%.3f, %.3f, %.3f)\",\n        last.name, last.timestamp, distance, dx/divisor, dy/divisor, dz/divisor))\nend\nfor _, key in ipairs({{\"ctrl+f11\", save}, {\"ctrl+shift+f11\", locate}}) do\n    local ok, why = pcall(bsx.hotkey, key[1], key[2])\n    if not ok then bsx.log(\"waypoints: \" .. key[1] .. \" unavailable (\" .. tostring(why) .. \")\") end\nend\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Waypoints\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\", \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\", \"pa::ClientActorManager::vftable\",\n    \"pa::ClientChildOnlyInGameActor::vftable\", \"Actor::Components\",\n    \"ActorComponents::TransformSync\", \"pa::ClientTransformSyncActorComponent::vftable\",\n    \"ClientTransformSyncActorComponent::Owner\",\n    \"CommonTransformSyncActorComponent::TransformSnapshot\", \"TransformSnapshot::RelativeFrame\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"waypoints","kind":"lua","lua_api":3,"path":"bsx/lua/examples/waypoints","tier":"safe","title":"Waypoints","uses":[]},{"category":"Combat & Stats","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Lua API 2 example: logs the player's own weapon switch. Copy this folder to BSX/scripts/weapon_watch. It only reads. The equipment component keeps the cur","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Lua API 2 example: logs the player's own weapon switch. Copy this folder to BSX/scripts/weapon_watch.\n-- It only reads. The equipment component keeps the current weapon or tool selection as a\n-- slot-name key and an occurrence (CDAL IDs 3047 and 3048); BSX WEAPON_SWAP does not see this switch.\n-- The names below are the keys Crimson Live Edit uses; another key is logged as a number.\nlocal names = {\n    [0x4425304D] = \"main weapon\", [0x7AA1C455] = \"secondary weapon\",\n    [0x54BF2C70] = \"tool\", [0x0BB2BA9B] = \"ranged or special\",\n}\nlocal key_at = assert(cdal.value(\"CommonEquipSlotActorComponent::ActiveSlotNameKey\"))\nlocal occurrence_at = assert(cdal.value(\"CommonEquipSlotActorComponent::ActiveSlotOccurrence\"))\nlocal last, switches, every = nil, 0, 10 -- read every 10th frame\n\nlocal function selection()\n    local actor = game.player()\n    if not actor then return nil end\n    local equipment = game.equipment(actor)\n    if not equipment then return nil end\n    local key, why = mem.read_u32(equipment + key_at)\n    if not key then return nil, why end\n    local occurrence, why_occurrence = mem.read_u32(equipment + occurrence_at)\n    if not occurrence then return nil, why_occurrence end\n    return {key = key, occurrence = occurrence, actor = actor}\nend\nlocal function describe(s)\n    if s.key == 0 then return \"nothing selected\" end\n    return (names[s.key] or string.format(\"key 0x%08X\", s.key)) .. \" #\" .. s.occurrence\nend\n\nbsx.on(\"frame\", function(e)\n    if e.frame % every ~= 0 then return end\n    local now, why = selection()\n    if not now then\n        if why and not last then bsx.log(\"weapon watch: read failed (\" .. tostring(why) .. \")\") end\n        last = nil\n        return\n    end\n    if not last or last.actor ~= now.actor then\n        bsx.log(\"weapon watch: start with \" .. describe(now))\n    elseif last.key ~= now.key or last.occurrence ~= now.occurrence then\n        switches = switches + 1\n        bsx.log(\"weapon watch: switch \" .. switches .. \": \" .. describe(last) .. \" -> \" .. describe(now))\n    end\n    last = now\nend)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Weapon Watch\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 2,\n  \"native\": false,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"Actor::Components\",\n    \"ActorComponents::Equipment\",\n    \"pa::ClientEquipSlotActorComponent::vftable\",\n    \"CommonEquipSlotActorComponent::ActiveSlotNameKey\",\n    \"CommonEquipSlotActorComponent::ActiveSlotOccurrence\"\n  ],\n  \"needs_plugins\": [],\n  \"packs\": []\n}\n","lang":"json","name":"script.json"}],"id":"weapon_watch","kind":"lua","lua_api":2,"path":"bsx/lua/examples/weapon_watch","tier":"safe","title":"Weapon Watch","uses":[]},{"category":"World, Time & Exploration","description":"Opt-in offline preview. Raw climate reads are not final rendered intensities.","featured":false,"files":[{"code":"-- Opt-in offline preview. Raw climate reads are not final rendered intensities.\nlocal factors, step = {1, 0.5, 0}, 0\nlocal function log(text) bsx.log(\"weather_dial: \" .. text) end\nlocal ok, why = pcall(bsx.on, \"key\", function(e)\n    -- Exact Ctrl+Shift+F5 (modifier mask Ctrl=1 + Shift=4). Ignore repeats.\n    if e.reset or not e.down or e[\"repeat\"] or e.virtual_key ~= 0x74 or e.modifiers ~= 5 then return end\n    if not game.weather.scale_precipitation then\n        log(\"read-only; changes approval required\")\n        return\n    end\n    local next_step = step % #factors + 1\n    local factor = factors[next_step]\n    local applied, reason = game.weather.scale_precipitation(factor, factor)\n    if not applied then log(\"refused: \" .. tostring(reason)); return end\n    step = next_step\n    log(\"policy factor \" .. (factor * 100) .. \"% (visible result unconfirmed)\")\n    local raw, read_reason = game.weather()\n    if raw then log(\"raw rain_base=\" .. raw.rain_base .. \" snow_base=\" .. raw.snow_base)\n    else log(\"raw weather unavailable: \" .. tostring(read_reason)) end\nend)\nif not ok then log(\"KEY unavailable: \" .. tostring(why))\nelse log(\"Ctrl+Shift+F5 cycles 100% / 50% / 0%; enable [Policies] precipitation=1 and approve this folder\") end\n-- The host resets the policy even on errors, removal and reload; no Lua cleanup\n-- callback is needed and no game resource is written.\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Weather dial\",\n  \"version\": \"1\",\n  \"lua_api\": 3,\n  \"changes\": true,\n  \"needs_ids\": [\n    \"Weather::GetRainIntensity\", \"Weather::GetSnowIntensity\",\n    \"WorldSystem::sInstance\", \"WorldSystem::RenderManager\", \"RenderManager::WeatherState\",\n    \"WeatherState::Resource\", \"WeatherResource::Climate\", \"Climate::RainBase\", \"Climate::SnowBase\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"weather_dial","kind":"lua","lua_api":3,"path":"bsx/lua/examples/weather_dial","tier":"changes","title":"Weather dial","uses":[]},{"category":"World, Time & Exploration","description":"Diagnostic only: the four scope-dependent reads still refuse. No raw memory fallback, guessed coordinates, alive flag, or stored-current HP substitute.","featured":false,"files":[{"code":"-- Diagnostic only: the four scope-dependent reads still refuse. No raw memory\n-- fallback, guessed coordinates, alive flag, or stored-current HP substitute.\nlocal frame, generation, busy, next_run = 0, 0, false, 0\nlocal function log(message) bsx.log(\"where_am_i: \" .. message) end\nlocal function player_read(fn)\n    local player, reason = game.player()\n    if not player then return nil, reason end\n    return fn(player) -- borrowed token is never saved across callbacks or logged\nend\nlocal steps = {\n    {\"position\", function() return player_read(game.position) end},\n    {\"nearest_five\", function()\n        -- The bound is a candidate limit, not proof that registry order is distance\n        -- order. Without an owned actor snapshot, report the refusal only.\n        return game.actors(256)\n    end},\n    {\"hp\", function()\n        -- Row zero is only a lead. Never identify it as HP without its cached name.\n        local name, reason = game.stat_name(0)\n        if name ~= \"Hp\" then return nil, reason or \"stat row 0 is not confirmed as Hp\" end\n        return player_read(function(player) return game.stats.read(player, 0) end)\n    end},\n    {\"in_cutscene\", game.in_cutscene}\n}\nlocal function step(index, token)\n    bsx.after(0, function()\n        if token ~= generation then return end\n        local before = os.clock()\n        local ok, value, reason = pcall(steps[index][2])\n        local elapsed = (os.clock() - before) * 1000\n        local status = not ok and (\"error: \" .. tostring(value)) or\n            value == nil and (\"unavailable: \" .. tostring(reason)) or\n            \"unexpected result; diagnostic needs review\"\n        log(string.format(\"%s elapsed_ms=%.3f frame=%d %s\", steps[index][1], elapsed, frame, status))\n        if index \u003c #steps then step(index + 1, token) else busy = false end\n    end)\nend\nbsx.on(\"frame\", function(e) frame = e.frame end)\nlocal function cancel()\n    generation = generation + 1\n    busy = false\nend\nbsx.on(\"save_load\", cancel)\nbsx.on(\"title_screen\", cancel)\nbsx.hotkey(\"ctrl+f9\", function()\n    if busy or os.clock() \u003c next_run then return end\n    next_run = os.clock() + 2 -- four result lines per run, below the log quota\n    generation, busy = generation + 1, true\n    step(1, generation)\nend)\nlog(\"ready ctrl+f9; scope diagnostics only, no gameplay values enabled\")\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"Where am I (scope diagnostics)\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"needs_ids\": [\n    \"WorldSystem::sInstance\",\n    \"WorldSystem::ActorManager\",\n    \"ClientActorManager::ControlledActor\",\n    \"ClientActorManager::FindActorScope\",\n    \"ClientActorScope::Release\",\n    \"ReadLockScope::Acquire\",\n    \"ClientActor::GetCutsceneHandle\",\n    \"StatusInfo::sTable\",\n    \"DefinitionTable::Capacity\",\n    \"DefinitionTable::CachedRows\",\n    \"DefinitionRow::Key\",\n    \"DefinitionRow::InternalName\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"where_am_i","kind":"lua","lua_api":3,"path":"bsx/lua/examples/where_am_i","tier":"safe","title":"Where am I (scope diagnostics)","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Scale the getter's result for every caller. Native approval is required. Starts paused; see recipes/r8-visual.md. Not tested in game.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Scale the getter's result for every caller. Native approval is required.\n-- Starts paused; see recipes/r8-visual.md. Not tested in game.\nlocal function log(message) bsx.log(\"wind_result: \" .. message) end\nlocal factor = config.float(\"WindResult\", \"Multiplier\", 0.10)\nif not (factor >= 0 and factor \u003c= 1) then return log(\"off: Multiplier must be 0 to 1\") end\n\nlocal site = \"Weather::GetDustIntensity\"\nlocal status, why = cdal.status(site)\nif status ~= \"resolved\" and status ~= \"verified\" then\n    return log(\"off: \" .. site .. \": \" .. tostring(why or status))\nend\n\n-- The checked entry has two exact forms. Retry the later form only when\n-- the first byte check fails, never after a hook conflict or another error.\n-- The hook calls the next function, then acts on its XMM0 float result.\nlocal function install(expect)\n    return cdal.rule(site, {\n        expect = expect, enabled = false, after = true,\n        when = {{\"xmm0.f32\", \">=\", 0}},\n        set = {{\"xmm0.f32\", \"mul\", factor}},\n    })\nend\nlocal rule, rule_why = install(\"48 8B 41 60 41 B8 40 00 00 00 48 85 C0 41 B9 60 01 00 00\")\nif not rule and string.find(tostring(rule_why), \"differ from `expect`\", 1, true) then\n    rule, rule_why = install(\"48 8B 41 60 41 B8 48 00 00 00 48 85 C0 41 B9 60 01 00 00\")\nend\nif not rule then return log(\"off: \" .. tostring(rule_why)) end\n\nlocal live, on, failure = true, false, nil\nlocal function stop(reason)\n    if live then\n        local removed, remove_why = rule:remove()\n        live = false\n        if not removed then reason = reason .. \"; removal failed: \" .. tostring(remove_why) end\n    end\n    on = false\n    failure = \"off: \" .. reason\nend\n\nlocal bound, key_why = pcall(bsx.hotkey, \"ctrl+alt+numpad6\", function()\n    if not live then return end\n    local ok, enable_why = rule:enable(not on)\n    if not ok then return stop(\"cannot change rule: \" .. tostring(enable_why)) end\n    on = not on\nend)\nif not bound then\n    stop(\"hotkey unavailable: \" .. tostring(key_why))\n    return log(failure)\nend\n\n-- One status line per ten seconds, even if the key is pressed rapidly.\n-- A failure between reports removes the hook immediately and reports why at\n-- the next tick; no game-thread callback runs Lua or logs.\nlocal function report()\n    if failure then return log(failure) end\n    local hits, hits_why = rule:hits()\n    if hits == nil then\n        stop(\"hit count unavailable: \" .. tostring(hits_why))\n        return log(failure)\n    end\n    local queued, timer_why = pcall(bsx.after, 11000, report)\n    if not queued then\n        stop(\"status timer unavailable: \" .. tostring(timer_why))\n        return log(failure)\n    end\n    log((on and \"on\" or \"paused\") .. \"; matching returns=\" .. hits)\nend\nlocal queued, timer_why = pcall(bsx.after, 11000, report)\nif not queued then\n    stop(\"status timer unavailable: \" .. tostring(timer_why))\n    return log(failure)\nend\nlog(\"ready: paused; ctrl+alt+numpad6 toggles; status at least 10 seconds apart\")\n","lang":"lua","name":"main.lua"},{"code":"; Applies globally to the getter used by Calmer Dynamic Wind.\n; 0.10 keeps 10% of its finite nonnegative return; 1.0 leaves it unchanged.\n[WindResult]\nMultiplier=0.10\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Wind Result\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\"Weather::GetDustIntensity\"]\n}\n","lang":"json","name":"script.json"}],"id":"wind_result","kind":"lua","lua_api":3,"path":"bsx/lua/examples/wind_result","tier":"safe","title":"Wind Result","uses":[]},{"category":"World, Time & Exploration","description":"SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 Wind Tuning: scale the getter used by Calmer Dynamic Wind, for every caller. Requires Native approval. See recipes/r8-visual.md; not tested in game.","featured":false,"files":[{"code":"-- SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n-- Wind Tuning: scale the getter used by Calmer Dynamic Wind, for every caller.\n-- Requires Native approval. See recipes/r8-visual.md; not tested in game.\nlocal function log(message) bsx.log(\"wind_tuning: \" .. message) end\n\nlocal factor = config.float(\"WindTuning\", \"Multiplier\", 0.10)\nif not (factor >= 0 and factor \u003c= 1) then return log(\"off: Multiplier must be 0 to 1\") end\n\n-- Each rule changes XMM1 before the game takes a maximum. The first path\n-- needs the first rule; the second path needs both. Install both paused.\nlocal rules = {}\nlocal function remove_all()\n    for _, r in ipairs(rules) do\n        local ok, why = r:remove()\n        if not ok then log(\"remove failed: \" .. tostring(why)) end\n    end\n    rules = {}\nend\n\n-- A scanned address is not a checked build. Stored results plus expect\n-- refuse an unknown or changed build rather than guessing its operands.\nlocal base_status, base_why = cdal.status(\"Weather::DustClampedInput\")\nlocal final_status, final_why = cdal.status(\"Weather::DustSecondPathMaximum\")\nif base_status ~= \"resolved\" and base_status ~= \"verified\" then\n    return log(\"off: base site: \" .. tostring(base_why or base_status))\nend\nif final_status ~= \"resolved\" and final_status ~= \"verified\" then\n    return log(\"off: second path: \" .. tostring(final_why or final_status))\nend\n\nlocal base, why = cdal.rule(\"Weather::DustClampedInput\", {\n    expect = \"C5 F8 57 C0 74 05 C5 FA 5F C1 C3 C5 FA 5F D1\", enabled = false,\n    when = {{\"xmm1.f32\", \">=\", 0}}, set = {{\"xmm1.f32\", \"mul\", factor}},\n})\nif not base then return log(\"off: base site: \" .. tostring(why)) end\nrules[1] = base\nlocal final, final_rule_why = cdal.rule(\"Weather::DustSecondPathMaximum\", {\n    expect = \"C5 EA 5F C1 C3 CC CC CC CC\", enabled = false,\n    when = {{\"xmm1.f32\", \">=\", 0}}, set = {{\"xmm1.f32\", \"mul\", factor}},\n})\nif not final then\n    remove_all()\n    return log(\"off: second path: \" .. tostring(final_rule_why))\nend\nrules[2] = final\n\nlocal on = false\nlocal function set_enabled(want)\n    for _, r in ipairs(rules) do\n        local ok, why = r:enable(want)\n        if not ok then\n            remove_all()\n            log(\"off: cannot change rule: \" .. tostring(why))\n            return false\n        end\n    end\n    on = want\n    return true\nend\n\nlocal chord = config.string(\"WindTuning\", \"Hotkey\", \"ctrl+alt+numpad2\")\nlocal key_ok, key_why = pcall(bsx.hotkey, chord, function()\n    if #rules == 0 then return end\n    if set_enabled(not on) then log(on and \"on\" or \"off\") end\nend)\nif not key_ok then\n    remove_all()\n    return log(\"off: cannot register hotkey: \" .. tostring(key_why))\nend\nif not set_enabled(config.bool(\"WindTuning\", \"Enabled\", true)) then return end\nlog((on and \"on\" or \"off\") .. \": factor \" .. factor .. \"; \" .. chord .. \" toggles\")\n\n-- The counts show which path ran. Do not log more than once every ten seconds.\nlocal function report()\n    if #rules == 0 then return end\n    local a, why_a = rules[1]:hits()\n    local b, why_b = rules[2]:hits()\n    if a == nil or b == nil then return log(\"hit count unavailable: \" .. tostring(why_a or why_b)) end\n    log(\"hits: base=\" .. a .. \", second path=\" .. b)\n    local ok, why = pcall(bsx.after, 60000, report)\n    if not ok then log(\"hit timer unavailable: \" .. tostring(why)) end\nend\nlocal timer_ok, timer_why = pcall(bsx.after, 60000, report)\nif not timer_ok then log(\"hit timer unavailable: \" .. tostring(timer_why)) end\n","lang":"lua","name":"main.lua"},{"code":"; Wind Tuning changes the getter used by Calmer Dynamic Wind for every caller.\n; 0 stops its nonnegative finite result, 0.10 keeps 10%, and 1 leaves it alone.\n[WindTuning]\nEnabled=1\nMultiplier=0.10\nHotkey=ctrl+alt+numpad2\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"Wind Tuning\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 3,\n  \"native\": true,\n  \"needs_ids\": [\n    \"Weather::DustClampedInput\",\n    \"Weather::DustSecondPathMaximum\"\n  ]\n}\n","lang":"json","name":"script.json"}],"id":"wind_tuning","kind":"lua","lua_api":3,"path":"bsx/lua/examples/wind_tuning","tier":"safe","title":"Wind Tuning","uses":[]},{"category":"World, Time & Exploration","description":"Overlay control panel for time of day, world speed (`World Speed` slider + `0.5x`/`1.0x`/`1.5x`), weather overrides, per-save teleport waypoints, **TP to Map Pin**, and **Up +10m** using `game.world.*` server-thread comm","featured":false,"files":[{"code":"-- World Controller: Lua API 4 changes-tier overlay panel for time, weather, speed scale, waypoints, and map pin teleport.\n\nlocal function clamp(value, low, high)\n    if type(value) ~= \"number\" or value ~= value then return low end\n    if value \u003c low then return low end\n    if value > high then return high end\n    return value\nend\n\nlocal function is_finite(v)\n    return type(v) == \"number\" and v == v and v > -math.huge and v \u003c math.huge\nend\n\nlocal function clamp_text(text)\n    local s = tostring(text or \"\"):gsub(\"%z\", \" \")\n    if #s \u003c= 127 then return s end\n    return string.sub(s, 1, 124) .. \"...\"\nend\n\nlocal same_day = config.bool(\"Controller\", \"SameDay\", true)\nlocal selected_hour = math.floor(clamp(config.int(\"Controller\", \"DefaultHour\", 12), 0, 23))\n\nlocal TIME_PRESET_LABELS = { \"Dawn (06:00)\", \"Noon (12:00)\", \"Dusk (18:00)\", \"Midnight (00:00)\" }\nlocal TIME_PRESET_HOURS = { 6, 12, 18, 0 }\nlocal WEATHER_LABELS = { \"Clear\", \"Light Rain\", \"Storm\", \"Snow\" }\nlocal WEATHER_PRESETS = {\n    { rain = 0.0, snow = 0.0, precipitation = 0.0, humidity = 0.2, cloudiness = 0.1, wind_direction = 90, wind_speed = 2 },\n    { rain = 0.45, snow = 0.0, precipitation = 0.45, humidity = 0.75, cloudiness = 0.65, wind_direction = 135, wind_speed = 8 },\n    { rain = 1.0, snow = 0.0, precipitation = 1.0, humidity = 0.95, cloudiness = 1.0, wind_direction = 225, wind_speed = 24 },\n    { rain = 0.0, snow = 0.9, precipitation = 0.9, humidity = 0.8, cloudiness = 0.85, wind_direction = 0, wind_speed = 10 },\n}\nlocal SLOT_LABELS = { \"Slot 1\", \"Slot 2\", \"Slot 3\", \"Slot 4\" }\n\nlocal time_preset_idx = 2\nlocal weather_preset_idx = 1\nlocal active_slot = 1\nlocal world_ready = false\nlocal logged_panel = false\nlocal logged_ready = false\nlocal freeze_time = false\nlocal freeze_cb_id\nlocal freeze_countdown = 0\nlocal world_speed = 1.0\nlocal speed_slider_id\nlocal allow_bus_teleports = false\nlocal pin_info_id\n\nlocal waypoints = {\n    { label = \"Camp\", set = false, x = 0, y = 0, z = 0, yaw_deg = nil },\n    { label = \"Point 2\", set = false, x = 0, y = 0, z = 0, yaw_deg = nil },\n    { label = \"Point 3\", set = false, x = 0, y = 0, z = 0, yaw_deg = nil },\n    { label = \"Point 4\", set = false, x = 0, y = 0, z = 0, yaw_deg = nil },\n}\n\nlocal panel = bsx.ui.panel(\"World Controller\")\nlocal status_id = panel:text(\"Waiting for world...\")\n\npanel:section(\"Time & Weather\", true)\nlocal time_combo_id\nlocal hour_slider_id\nlocal weather_combo_id\n\ntime_combo_id = panel:combo(\"Time preset\", TIME_PRESET_LABELS, time_preset_idx, function(idx)\n    time_preset_idx = idx\n    selected_hour = TIME_PRESET_HOURS[idx] or 12\n    panel:set_value(hour_slider_id, selected_hour)\nend)\n\nhour_slider_id = panel:slider(\"Hour\", 0.0, 23.0, selected_hour, function(value)\n    selected_hour = math.floor(clamp(value + 0.5, 0, 23))\nend)\n\npanel:button(\"Apply Time\", function()\n    local hour = math.floor(clamp(selected_hour, 0, 23))\n    local ok, why = game.world.set_time(hour, 0, 0, same_day)\n    if not ok then\n        local msg = \"Time blocked: \" .. tostring(why)\n        panel:set_text(status_id, clamp_text(msg))\n        return bsx.log(\"world_controller: \" .. msg)\n    end\n    local msg = string.format(\"Applied time %02d:00 (same_day=%s)\", hour, tostring(same_day))\n    panel:set_text(status_id, clamp_text(msg))\n    bsx.bus.emit(\"world_controller.applied\", { kind = \"time\", hour = hour })\n    bsx.log(\"world_controller: \" .. msg)\nend)\npanel:same_line()\nfreeze_cb_id = panel:checkbox(\"Freeze Time\", false, function(checked)\n    freeze_time = checked\n    freeze_countdown = 0\n    local msg = checked and string.format(\"Freeze Time enabled (%02d:00)\", math.floor(clamp(selected_hour, 0, 23)))\n        or \"Freeze Time disabled\"\n    panel:set_text(status_id, clamp_text(msg))\n    bsx.log(\"world_controller: \" .. msg)\nend)\n\nweather_combo_id = panel:combo(\"Weather preset\", WEATHER_LABELS, weather_preset_idx, function(idx)\n    weather_preset_idx = idx\nend)\n\npanel:button(\"Apply Weather\", function()\n    local label = WEATHER_LABELS[weather_preset_idx] or \"Clear\"\n    local preset = WEATHER_PRESETS[weather_preset_idx] or WEATHER_PRESETS[1]\n    local ok, why = game.world.set_weather(preset)\n    if not ok then\n        local msg = \"Weather blocked: \" .. tostring(why)\n        panel:set_text(status_id, clamp_text(msg))\n        return bsx.log(\"world_controller: \" .. msg)\n    end\n    local msg = \"Applied weather: \" .. label\n    panel:set_text(status_id, clamp_text(msg))\n    bsx.bus.emit(\"world_controller.applied\", { kind = \"weather\", preset = label })\n    bsx.log(\"world_controller: \" .. msg)\nend)\npanel:same_line()\npanel:button(\"Reset Weather\", function()\n    local ok, why = game.world.reset_weather()\n    if not ok then\n        local msg = \"Weather reset blocked: \" .. tostring(why)\n        panel:set_text(status_id, clamp_text(msg))\n        return bsx.log(\"world_controller: \" .. msg)\n    end\n    local msg = \"Reset weather override\"\n    panel:set_text(status_id, msg)\n    bsx.bus.emit(\"world_controller.applied\", { kind = \"weather_reset\" })\n    bsx.log(\"world_controller: \" .. msg)\nend)\n\nlocal last_speed_log = 0\n\nlocal function apply_speed(val, always_log)\n    local target = clamp(val, 0.1, 2.0)\n    local ok, why = game.world.set_time_scale(target)\n    if not ok then\n        local msg = \"Speed blocked: \" .. tostring(why)\n        panel:set_text(status_id, clamp_text(msg))\n        return bsx.log(\"world_controller: \" .. msg)\n    end\n    world_speed = target\n    panel:set_value(speed_slider_id, world_speed)\n    local msg = string.format(\"World speed %.2fx\", world_speed)\n    panel:set_text(status_id, clamp_text(msg))\n    bsx.bus.emit(\"world_controller.applied\", { kind = \"time_scale\", scale = world_speed })\n    local now = os.clock()\n    if always_log or (now - last_speed_log >= 0.5) then\n        last_speed_log = now\n        bsx.log(\"world_controller: \" .. msg)\n    end\nend\n\nspeed_slider_id = panel:slider(\"World Speed\", 0.1, 2.0, world_speed, function(value)\n    apply_speed(value, false)\nend)\npanel:button(\"0.5x\", function() apply_speed(0.5, true) end)\npanel:same_line()\npanel:button(\"1.0x\", function() apply_speed(1.0, true) end)\npanel:same_line()\npanel:button(\"1.5x\", function() apply_speed(1.5, true) end)\npanel:end_section()\n\npanel:section(\"Waypoints & Teleport\", true)\nlocal slot_combo_id\nlocal label_input_id\nlocal slot_info_id\n\nlocal function sanitize_label(text, fallback)\n    local s = tostring(text or \"\"):gsub(\"[%z|\\r\\n]\", \" \"):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    if s == \"\" then return fallback end\n    if #s > 32 then return string.sub(s, 1, 32) end\n    return s\nend\n\nlocal function update_slot_ui()\n    local wp = waypoints[active_slot]\n    panel:set_value(label_input_id, wp.label)\n    if wp.set then\n        local yaw = wp.yaw_deg and string.format(\" yaw=%.0f\", wp.yaw_deg) or \"\"\n        panel:set_text(slot_info_id, clamp_text(string.format(\"%s: (%.1f, %.1f, %.1f)%s\",\n            wp.label, wp.x, wp.y, wp.z, yaw)))\n    else\n        panel:set_text(slot_info_id, clamp_text(wp.label .. \": empty\"))\n    end\nend\n\nlocal function encode_waypoint(wp)\n    return string.format(\"%s|%.17g|%.17g|%.17g|%s\",\n        sanitize_label(wp.label, \"Waypoint\"), wp.x, wp.y, wp.z,\n        wp.yaw_deg and string.format(\"%.17g\", wp.yaw_deg) or \"\")\nend\n\nlocal function load_waypoints()\n    for i = 1, #waypoints do\n        local raw = bsx.save.get(\"wc.wp.\" .. tostring(i))\n        if type(raw) == \"string\" then\n            local lbl, xs, ys, zs, ys_deg = string.match(raw, \"^([^|]+)|([^|]+)|([^|]+)|([^|]+)|([^|]*)$\")\n            local x, y, z = tonumber(xs), tonumber(ys), tonumber(zs)\n            if lbl and x and y and z then\n                waypoints[i] = {\n                    label = sanitize_label(lbl, \"Slot \" .. tostring(i)),\n                    set = true,\n                    x = x,\n                    y = y,\n                    z = z,\n                    yaw_deg = tonumber(ys_deg),\n                }\n            end\n        end\n    end\n    update_slot_ui()\nend\n\nslot_combo_id = panel:combo(\"Waypoint slot\", SLOT_LABELS, active_slot, function(idx)\n    active_slot = idx\n    update_slot_ui()\nend)\n\nlabel_input_id = panel:input_text(\"Label\", waypoints[active_slot].label, function(text)\n    waypoints[active_sl\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[Controller]\nDefaultHour=12\nSameDay=true\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"World Controller\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"snapshots\", \"positions\", \"world\", \"server_commands\", \"bus\"]\n}\n","lang":"json","name":"script.json"}],"id":"world_controller","kind":"lua","lua_api":4,"path":"bsx/lua/examples/world_controller","tier":"changes","title":"World Controller","uses":["ui","snapshots","positions","world","server_commands","bus"]},{"category":"World, Time & Exploration","description":"Demonstrates BSX Lua API 6 definition tables, live world readers, and composable hooks inside one tabbed `bsx.ui.panel` overlay window:","featured":false,"files":[{"code":"-- World Explorer (API 6): tabbed browser for Wave 15 definition tables and Wave 16 live readers/hooks.\n\nlocal TABLES = { 'Items', 'Characters', 'Skills', 'Buffs', 'Quests', 'Stores', 'Craft Tools' }\nlocal MAX_ROWS = 4\n\nlocal state = {\n  table_idx = 2,\n  query = '',\n  cursor = 0,\n  next_cursor = nil,\n  faction_a = 1,\n  faction_b = 2,\n  cool_hook_on = false,\n  cool_mult = 0.50,\n  loot_hook_on = false,\n  loot_mult = 2.00,\n}\n\nlocal cool_handle = nil\nlocal loot_handle = nil\n\nlocal function clamp_text(s, limit)\n  local txt = tostring(s or '')\n  if #txt \u003c= limit then return txt end\n  return string.sub(txt, 1, limit - 3) .. '...'\nend\n\nlocal panel = bsx.ui.panel('World Explorer (API 6)')\nlocal table_summary_lbl\nlocal row_lbls = {}\nlocal buffs_lbl, quests_lbl, sublevels_lbl, dyes_lbl, visuals_lbl, agreement_lbl, hooks_lbl\n\nlocal function run_table_search(next_page)\n  local kind = TABLES[state.table_idx] or 'Characters'\n  local cur = next_page and (state.next_cursor or 0) or 0\n  state.cursor = cur\n\n  local rows, next_or_err\n  if kind == 'Items' then\n    local ok, r, e = pcall(game.items.find, state.query, MAX_ROWS)\n    rows = ok and r or nil\n    next_or_err = ok and e or r\n  elseif kind == 'Characters' then\n    local ok, r, e = pcall(game.characters.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  elseif kind == 'Skills' then\n    local ok, r, e = pcall(game.skills.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  elseif kind == 'Buffs' then\n    local ok, r, e = pcall(game.buffs.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  elseif kind == 'Quests' then\n    local ok, r, e = pcall(game.quests.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  elseif kind == 'Stores' then\n    local ok, r, e = pcall(game.stores.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  else\n    local ok, r, e = pcall(game.craft_tools.find, state.query, MAX_ROWS, cur)\n    rows, next_or_err = ok and r or nil, ok and e or r\n  end\n\n  if type(next_or_err) == 'number' then\n    state.next_cursor = next_or_err\n  else\n    state.next_cursor = nil\n  end\n\n  if panel and table_summary_lbl then\n    if type(rows) == 'table' then\n      local nxt = state.next_cursor and ('next=' .. tostring(state.next_cursor)) or 'end'\n      panel:set_text(table_summary_lbl, clamp_text(string.format('%s: %d rows (%s)', kind, #rows, nxt), 118))\n    else\n      panel:set_text(table_summary_lbl, clamp_text(kind .. ': unavailable (' .. tostring(next_or_err) .. ')', 118))\n    end\n  end\n\n  for i = 1, MAX_ROWS do\n    local lbl = row_lbls[i]\n    if panel and lbl then\n      local r = type(rows) == 'table' and rows[i] or nil\n      if r then\n        local title = r.display_name or r.name or r.internal_name or '-'\n        panel:set_text(lbl, clamp_text(string.format('[%s] key=%s %s', tostring(r.row or r.id or i), tostring(r.key or '-'), tostring(title)), 118))\n      else\n        panel:set_text(lbl, i == 1 and type(rows) == 'table' and '(no matches)' or '')\n      end\n    end\n  end\nend\n\nlocal function refresh_world_state()\n  local ok_b, buffs, b_err = pcall(game.buffs.active)\n  local ok_q, quests, q_err = pcall(game.quests.active)\n  local ok_s, subs, s_err = pcall(game.skills.sublevels)\n  local ok_d, dyes, d_err = pcall(game.appearance.equipped_dyes)\n  local ok_v, visuals, v_err = pcall(game.appearance.visual_items)\n  local ok_f, ag, f_err = pcall(game.factions.agreement, math.floor(state.faction_a), math.floor(state.faction_b))\n\n  if panel and buffs_lbl then\n    local msg = (ok_b and type(buffs) == 'table') and ('Active Buffs: ' .. #buffs .. (buffs[1] and (' (' .. tostring(buffs[1].name or buffs[1].buff_row) .. ')') or '')) or ('Active Buffs: ' .. tostring(b_err))\n    panel:set_text(buffs_lbl, clamp_text(msg, 118))\n  end\n  if panel and quests_lbl then\n    local done = 0\n    if ok_q and type(quests) == 'table' then\n      for _, q in ipairs(quests) do if q.completed then done = done + 1 end end\n      panel:set_text(quests_lbl, clamp_text(string.format('Quests observed: %d (%d completed)', #quests, done), 118))\n    else\n      panel:set_text(quests_lbl, clamp_text('Quests observed: ' .. tostring(q_err), 118))\n    end\n  end\n  if panel and sublevels_lbl then\n    local msg = (ok_s and type(subs) == 'table') and ('Active Skill Sublevels: ' .. #subs .. (subs[1] and (' (key ' .. tostring(subs[1].key) .. ' lv ' .. tostring(subs[1].level) .. ')') or '')) or ('Skill Sublevels: ' .. tostring(s_err))\n    panel:set_text(sublevels_lbl, clamp_text(msg, 118))\n  end\n  if panel and dyes_lbl then\n    local msg = (ok_d and type(dyes) == 'table') and ('Equipped Dye Slots: ' .. #dyes) or ('Equipped Dyes: ' .. tostring(d_err))\n    panel:set_text(dyes_lbl, clamp_text(msg, 118))\n  end\n  if panel and visuals_lbl then\n    local msg = (ok_v and type(visuals) == 'table') and ('Visual Equip Slots: ' .. #visuals) or ('Visual Slots: ' .. tostring(v_err))\n    panel:set_text(visuals_lbl, clamp_text(msg, 118))\n  end\n  if panel and agreement_lbl then\n    local tag = ag == 3 and 'Allied' or (ag == 4 and 'Neutral' or (ag == 5 and 'Unknown' or tostring(ag)))\n    local msg = (ok_f and ag ~= nil) and string.format('Faction %d vs %d: %s (%d)', state.faction_a, state.faction_b, tag, ag) or ('Faction Agreement: ' .. tostring(f_err))\n    panel:set_text(agreement_lbl, clamp_text(msg, 118))\n  end\n\n  return {\n    buffs = (ok_b and type(buffs) == 'table') and #buffs or -1,\n    quests = (ok_q and type(quests) == 'table') and #quests or -1,\n    sublevels = (ok_s and type(subs) == 'table') and #subs or -1,\n    dyes = (ok_d and type(dyes) == 'table') and #dyes or -1,\n    visuals = (ok_v and type(visuals) == 'table') and #visuals or -1,\n  }\nend\n\nlocal function sync_hooks()\n  if cool_handle then\n    cool_handle:remove()\n    cool_handle = nil\n  end\n  if loot_handle then\n    loot_handle:remove()\n    loot_handle = nil\n  end\n  local status_parts = {}\n  if state.cool_hook_on then\n    local h, err = game.hooks.add('on_item_cooldown', { mult = state.cool_mult })\n    cool_handle = h\n    status_parts[#status_parts + 1] = h and string.format('cooldown=%.2fx', state.cool_mult) or ('cooldown err=' .. tostring(err))\n  end\n  if state.loot_hook_on then\n    local h, err = game.hooks.add('on_loot_drop', { mult = state.loot_mult })\n    loot_handle = h\n    status_parts[#status_parts + 1] = h and string.format('loot=%.2fx', state.loot_mult) or ('loot err=' .. tostring(err))\n  end\n  if panel and hooks_lbl then\n    local msg = #status_parts > 0 and table.concat(status_parts, ', ') or 'Hooks idle (enable toggles above)'\n    panel:set_text(hooks_lbl, clamp_text(msg, 118))\n  end\nend\n\nif panel then\n  panel:begin_tab_bar('wx_tabs')\n\n  panel:tab('Tables')\n  panel:combo('Table', TABLES, state.table_idx, function(idx)\n    state.table_idx = idx\n    run_table_search(false)\n  end)\n  panel:input_text('Query (name/row/key)', state.query, function(q)\n    state.query = q or ''\n    run_table_search(false)\n  end)\n  panel:button('Search', function() run_table_search(false) end)\n  panel:same_line()\n  panel:button('Next Page', function() run_table_search(true) end)\n  table_summary_lbl = panel:text('Select Search to query table rows')\n  for i = 1, MAX_ROWS do\n    row_lbls[i] = panel:text('')\n  end\n  panel:end_tab()\n\n  panel:tab('Player & World')\n  panel:button('Refresh Snapshot Readers', function() refresh_world_state() end)\n  buffs_lbl = panel:text('Active Buffs: waiting for world_ready')\n  quests_lbl = panel:text('Quests observed: waiting for world_ready')\n  sublevels_lbl = panel:text('Skill Sublevels: waiting for world_ready')\n  dyes_lbl = panel:text('Equipped Dyes: waiting for world_ready')\n  visuals_lbl = panel:text('Visual Slots: waiting for world_ready')\n  panel:slider('Faction A', 0, 20, state.faction_a, function(v)\n    state.faction_a = math.floor(v + 0.5)\n    refresh_world_state()\n  end)\n  panel:slider('Faction B', 0, 20, state.faction_b, function(v)\n    state.faction_b = math.floor(v + 0.5)\n    refresh_world_state()\n  end)\n  agreement_lbl = panel:text('Faction Agreement: waiting')\n  panel:end_tab()\n\n  panel\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"{\n  \"name\": \"World Explorer (API 6)\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 6,\n  \"changes\": true,\n  \"uses\": [\"ui\", \"snapshots\", \"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"world_explorer_api6","kind":"lua","lua_api":6,"path":"bsx/lua/examples/world_explorer_api6","tier":"changes","title":"World Explorer (API 6)","uses":["ui","snapshots","server_commands"]},{"category":"World, Time & Exploration","description":"Read-only BSX Overlay inspector panel built with Lua API 4 (`bsx.ui`, paginated **Target Actor** selection with `\u003c Prev` / `Next >`, `Alive only`, `Hide Objects`, `character_name`, `SnapshotProvider`, `bsx.save`, and `bs","featured":false,"files":[{"code":"-- World Inspector: safe-tier Lua API 4 read-only overlay panel with actor names, target picker, co-save, and bus.\n\nlocal function clamp(value, low, high)\n    if type(value) ~= \"number\" or value ~= value then return low end\n    if value \u003c low then return low end\n    if value > high then return high end\n    return value\nend\n\nlocal function clamp_text(text)\n    local s = tostring(text or \"\"):gsub(\"%z\", \" \")\n    if #s \u003c= 127 then return s end\n    return string.sub(s, 1, 124) .. \"...\"\nend\n\nlocal function pack_combo_items(list, fallback)\n    local out = {}\n    local bytes = 0\n    for i = 1, #list do\n        local s = tostring(list[i] or \"\"):gsub(\"%z\", \" \")\n        if #s > 28 then s = string.sub(s, 1, 25) .. \"...\" end\n        if #s > 0 and (bytes + #s + 1) \u003c= 250 then\n            out[#out + 1] = s\n            bytes = bytes + #s + 1\n        end\n        if #out >= 8 then break end\n    end\n    if #out == 0 then\n        out[1] = fallback or \"(none)\"\n    end\n    return out\nend\n\nlocal refresh_seconds = clamp(config.float(\"Inspector\", \"RefreshSeconds\", 1.5), 0.25, 10.0)\nlocal max_actors = math.floor(clamp(config.int(\"Inspector\", \"MaxActors\", 32), 4, 64))\nlocal auto_refresh = config.bool(\"Inspector\", \"AutoRefresh\", true)\nlocal alive_only = config.bool(\"Inspector\", \"AliveOnly\", true)\nlocal hide_objects = config.bool(\"Inspector\", \"HideObjects\", true)\nlocal mini_hud = config.bool(\"Inspector\", \"MiniHud\", false)\n\nlocal SORT_LABELS = { \"Distance\", \"Name\", \"Row\", \"Kind\" }\nlocal PAGE_SIZE = 8\nlocal sort_mode = 1\nlocal filter_text = \"all\"\nlocal world_ready = false\nlocal logged_panel = false\nlocal logged_ready = false\n\nlocal all_target_candidates = {}\nlocal target_page = 1\nlocal target_candidates = {}\nlocal target_labels = { \"(no target actor)\" }\nlocal selected_target_key = nil\nlocal selected_target_idx = 1\nlocal last_locked = nil\nlocal last_lock_seq = 0\nlocal hud_panel = nil\nlocal hud_pos_id = nil\nlocal hud_target_id = nil\n\nlocal last_summary = {\n    world_ready = false,\n    actor_count = 0,\n    total_actors = 0,\n    sort = SORT_LABELS[sort_mode],\n    filter = filter_text,\n    zone = \"waiting\",\n    time = \"--:--\",\n    weather = \"unknown\",\n}\n\nlocal panel = bsx.ui.panel(\"World Inspector\")\nlocal status_id = panel:text(\"Waiting for world...\")\n\nlocal player_id = panel:text(\"Player: waiting for world\")\nlocal hp_bar_id = panel:progress(0.0, \"HP: -- / --\")\nlocal env_id = panel:text(\"Zone/Time/Weather: --\")\npanel:separator()\nlocal actors_bar_id = panel:progress(0.0, \"Actors: 0\")\nlocal locked_target_id = panel:text(\"Lock-On: none\")\nlocal sort_combo_id\nlocal filter_input_id\nlocal alive_cb_id\nlocal hide_obj_cb_id\nlocal auto_cb_id\nlocal target_combo_id\nlocal selected_info_id\nlocal top_actors_id\n\nlocal function save_pref(key, value)\n    bsx.save.set(key, value)\nend\n\nlocal function load_prefs()\n    local saved_sort = bsx.save.get(\"wi.sort\")\n    if type(saved_sort) == \"number\" and saved_sort >= 1 and saved_sort \u003c= #SORT_LABELS then\n        sort_mode = math.floor(saved_sort)\n        panel:set_value(sort_combo_id, sort_mode)\n    end\n    local saved_filter = bsx.save.get(\"wi.filter\")\n    if type(saved_filter) == \"string\" and #saved_filter > 0 and #saved_filter \u003c= 32 then\n        filter_text = saved_filter\n        panel:set_value(filter_input_id, filter_text)\n    end\n    local saved_auto = bsx.save.get(\"wi.auto\")\n    if type(saved_auto) == \"number\" then\n        auto_refresh = saved_auto ~= 0\n        panel:set_value(auto_cb_id, auto_refresh)\n    end\n    local saved_alive = bsx.save.get(\"wi.alive\")\n    if type(saved_alive) == \"number\" then\n        alive_only = saved_alive ~= 0\n        panel:set_value(alive_cb_id, alive_only)\n    end\n    local saved_hide = bsx.save.get(\"wi.hide_obj\")\n    if type(saved_hide) == \"number\" then\n        hide_objects = saved_hide ~= 0\n        panel:set_value(hide_obj_cb_id, hide_objects)\n    end\nend\n\nlocal function is_gimmick_object(actor)\n    if actor.controlled then return false end\n    local cname = tostring(actor.character_name or \"\")\n    if string.find(cname, \"^Object_Gimmick\") ~= nil then return true end\n    return actor.faction == 65535 and actor.character_row == 6503\nend\n\nlocal function actor_display_name(a)\n    if type(a.display_name) == \"string\" and #a.display_name > 0 then\n        return a.display_name\n    end\n    if type(a.character_name) == \"string\" and #a.character_name > 0 then\n        return a.character_name\n    end\n    if a.character_row ~= nil then\n        return \"row=\" .. tostring(a.character_row)\n    end\n    return tostring(a.kind or \"actor\")\nend\n\nlocal function matches_filter(actor)\n    if alive_only and actor.dead == true then\n        return false\n    end\n    if hide_objects and is_gimmick_object(actor) then\n        return false\n    end\n    local q = string.lower(filter_text):gsub(\"^%s+\", \"\"):gsub(\"%s+$\", \"\")\n    if q == \"\" or q == \"all\" or q == \"*\" then return true end\n    local kind = string.lower(tostring(actor.kind or \"other\"))\n    local dname = string.lower(tostring(actor.display_name or \"\"))\n    local cname = string.lower(tostring(actor.character_name or \"\"))\n    local row = tostring(actor.character_row or \"\")\n    return string.find(dname, q, 1, true) ~= nil\n        or string.find(cname, q, 1, true) ~= nil\n        or string.find(kind, q, 1, true) ~= nil\n        or row == q\nend\n\nlocal function sort_actors(list)\n    local copy = {}\n    for i = 1, #list do\n        if matches_filter(list[i]) then\n            copy[#copy + 1] = list[i]\n        end\n    end\n    table.sort(copy, function(a, b)\n        if sort_mode == 2 then\n            local na, nb = string.lower(actor_display_name(a)), string.lower(actor_display_name(b))\n            if na ~= nb then return na \u003c nb end\n        elseif sort_mode == 3 then\n            local ra, rb = a.character_row or 0, b.character_row or 0\n            if ra ~= rb then return ra \u003c rb end\n        elseif sort_mode == 4 then\n            local ka, kb = tostring(a.kind or \"\"), tostring(b.kind or \"\")\n            if ka ~= kb then return ka \u003c kb end\n        end\n        return (a.distance or math.huge) \u003c (b.distance or math.huge)\n    end)\n    return copy\nend\n\nlocal function update_selected_info()\n    local target = target_candidates[selected_target_idx]\n    local total = #all_target_candidates\n    local total_pages = math.max(1, math.ceil(total / PAGE_SIZE))\n    if not target then\n        panel:set_text(selected_info_id, clamp_text(string.format(\"Page %d/%d (%d targets): none\",\n            target_page, total_pages, total)))\n        return\n    end\n    local hp_text = \"--\"\n    if target.actor then\n        local st = game.stats.read(target.actor, 0)\n        if st and st.max then\n            hp_text = string.format(\"%d/%d\", st.current or 0, st.max)\n        end\n    end\n    local alive_str = target.dead == true and \"dead\" or \"alive\"\n    local fac = target.faction ~= nil and (\" fac=\" .. tostring(target.faction)) or \"\"\n    panel:set_text(selected_info_id, clamp_text(string.format(\"[P%d/%d] %s | r=%s | %.1fm | HP %s | %s%s\",\n        target_page,\n        total_pages,\n        actor_display_name(target),\n        tostring(target.character_row or \"?\"),\n        target.distance or 0.0,\n        hp_text,\n        alive_str,\n        fac)))\nend\n\nlocal function apply_target_page(page_num, keep_selected_key)\n    local total = #all_target_candidates\n    local total_pages = math.max(1, math.ceil(total / PAGE_SIZE))\n    if keep_selected_key then\n        for i = 1, total do\n            if all_target_candidates[i].key == keep_selected_key then\n                target_page = math.floor((i - 1) / PAGE_SIZE) + 1\n                break\n            end\n        end\n    else\n        target_page = math.max(1, math.min(total_pages, math.floor(page_num or 1)))\n    end\n    target_page = math.max(1, math.min(total_pages, target_page))\n    local start_i = (target_page - 1) * PAGE_SIZE + 1\n    local end_i = math.min(total, start_i + PAGE_SIZE - 1)\n    local slice = {}\n    local raw_labels = {}\n    for i = start_i, end_i do\n        local a = all_target_candidates[i]\n        slice[#slice + 1] = a\n        local nm = actor_display_name(a)\n        if #nm > 16 then nm = string.sub(nm, 1, 13) .. \"...\" end\n        raw_labels[#raw_labels + 1] = string.format(\"#%d %\n-- ... truncated at 8192 bytes (see main.lua in repo for full file)\n","lang":"lua","name":"main.lua"},{"code":"[Inspector]\nRefreshSeconds=1.5\nMaxActors=32\nAutoRefresh=true\nMiniHud=0\n","lang":"ini","name":"settings.ini"},{"code":"{\n  \"name\": \"World Inspector\",\n  \"version\": \"1.0.0\",\n  \"lua_api\": 4,\n  \"native\": false,\n  \"uses\": [\"ui\", \"player\", \"snapshots\", \"positions\", \"world\", \"bus\"]\n}\n","lang":"json","name":"script.json"}],"id":"world_inspector","kind":"lua","lua_api":4,"path":"bsx/lua/examples/world_inspector","tier":"safe","title":"World Inspector","uses":["ui","player","snapshots","positions","world","bus"]},{"category":"Data-Only Packs","description":"A pure data mod (`\"data_only\": true` in `script.json`, no `main.lua`) configured through `tweaks.json` v2:","featured":false,"files":[{"code":"{\n  \"schema_version\": 2,\n  \"description\": \"Data-only balance preset adjusting potion stack limits, resource costs, parry window, and equipment wear with zero Lua code.\",\n  \"items\": {\n    \"1980\": {\n      \"name\": \"Consumable Stack Sample\",\n      \"max_stack\": 999\n    }\n  },\n  \"gameplay\": {\n    \"stamina_cost_scale\": 0.65,\n    \"mp_cost_scale\": 0.75,\n    \"craft_cost_scale\": 0.5,\n    \"gather_multiplier\": 2,\n    \"ammo_saving\": true\n  },\n  \"hooks\": [\n    {\n      \"channel\": \"on_parry_window\",\n      \"mult\": 1.35,\n      \"add\": 0.0,\n      \"priority\": 0,\n      \"enabled\": true\n    },\n    {\n      \"channel\": \"on_durability_wear\",\n      \"mult\": 0.5,\n      \"add\": 0.0,\n      \"priority\": 0,\n      \"enabled\": true\n    }\n  ]\n}\n","lang":"json","name":"tweaks.json"},{"code":"{\n  \"name\": \"Zero-Code Balance Pack\",\n  \"version\": \"1.0.0\",\n  \"author\": \"Ratty123\",\n  \"lua_api\": 5,\n  \"data_only\": true,\n  \"changes\": true,\n  \"uses\": [\"server_commands\"]\n}\n","lang":"json","name":"script.json"}],"id":"zero_code_balance_pack","kind":"data_only","lua_api":5,"path":"bsx/lua/examples/zero_code_balance_pack","tier":"data_only","title":"Zero-Code Balance Pack","uses":["server_commands"]},{"category":"Native C / C++","description":"Minimal CDAL C++ plugin: process check, worker thread init, cdal::Feature lookup and safe disable on missing IDs.","featured":false,"files":[{"code":"// Smallest useful CDAL plugin: an ASI that finds the WorldSystem and the local\n// player through CDAL instead of its own signatures, and logs what it found.\n// Build: part of the CDAL CMake project on Windows (target hello_cdal).\n#include \u003cwindows.h>\n\n#include \u003ccdal/cdal.hpp>\n#include \u003ccdal/ids.hpp>\n\n#include \u003ccstdarg>\n#include \u003ccstdio>\n\nnamespace {\n\nvoid log(const char* fmt, ...) {\n    if (FILE* f = std::fopen(\"hello_cdal.log\", \"a\")) {\n        va_list args;\n        va_start(args, fmt);\n        std::vfprintf(f, fmt, args);\n        va_end(args);\n        std::fputc('\\n', f);\n        std::fclose(f);\n    }\n}\n\nDWORD WINAPI run(LPVOID) {\n    ::Sleep(20000);  // let the game unpack and reach the menu; never resolve inside DllMain\n\n    if (!cdal::init()) {\n        log(\"CDAL unavailable: %s\", cdal::last_error().c_str());\n        return 0;\n    }\n    namespace ids = cdal::ids;\n    // One feature, one require(). cdal::Feature also tells cdal.dll (C API 6 or later) whether the\n    // feature is on, for CDAL/hooks.log, session.json and crash notes; an older cdal.dll just ignores it.\n    static cdal::Feature world_info{\"hello_cdal example\", \"World info\"};\n    std::string missing;\n    if (!world_info.require({ids::WorldSystem::sInstance, ids::StatEntry::Current}, &missing)) {\n        log(\"CDAL %s is missing what this plugin needs: %s\", cdal::build().c_str(), missing.c_str());\n        return 0;  // disable cleanly instead of crashing\n    }\n\n    auto world = *cdal::ptr\u003cvoid**>(ids::WorldSystem::sInstance);\n    log(\"CDAL %s: WorldSystem at %p, StatEntry::Current at +0x%llX\", cdal::build().c_str(), world,\n        static_cast\u003cunsigned long long>(*cdal::value(ids::StatEntry::Current)));\n    return 0;\n}\n\n// ASI loaders also load every .asi into the game's crashpad_handler.exe: only start in the game.\nbool in_game_process() {\n    wchar_t path[MAX_PATH * 4];\n    const DWORD n = ::GetModuleFileNameW(nullptr, path, MAX_PATH * 4);\n    const wchar_t* name = path + n;\n    while (name > path && name[-1] != L'\\\\' && name[-1] != L'/') --name;\n    return ::CompareStringOrdinal(name, -1, L\"CrimsonDesert.exe\", -1, TRUE) == CSTR_EQUAL;\n}\n\n}  // namespace\n\nBOOL WINAPI DllMain(HINSTANCE module, DWORD reason, LPVOID) {\n    if (reason == DLL_PROCESS_ATTACH && in_game_process()) {\n        ::DisableThreadLibraryCalls(module);\n        if (HANDLE t = ::CreateThread(nullptr, 0, run, nullptr, 0, nullptr)) ::CloseHandle(t);\n    }\n    return TRUE;\n}\n","lang":"cpp","name":"hello_cdal.cpp"}],"id":"hello_cdal","kind":"native_cpp","lua_api":0,"path":"examples/hello_cdal","tier":"native_sdk","title":"Hello CDAL (C++ ASI)","uses":["cdal.lib"]},{"category":"Native C / C++","description":"Coordinated FunctionHook and MidHook installation through cdal::hooks with owner priority ordering.","featured":false,"files":[{"code":"// A plugin that hooks through the CDAL hook manager, so it stacks cleanly with\n// any other plugin that hooks the same functions through CDAL.\n//\n//   - A function hook on StatusComponent::ApplyStatDelta that halves HP damage.\n//   - A mid hook on ItemDurability::ApplyDelta_Hook that stops items wearing down.\n//\n// It runs against the player's cdal.dll (installed once with CDAL; never ship your own). CDAL/hooks.log then shows these\n// hooks, their owner and their place in each chain.\n// Build: part of the CDAL CMake project on Windows (target shared_hooks).\n#include \u003cwindows.h>\n\n#include \u003ccdal/cdal.hpp>  // built with CDAL_SHARED: addresses come from cdal.dll\n#include \u003ccdal/hooks.hpp>\n#include \u003ccdal/ids.hpp>\n\n#include \u003ccstdarg>\n#include \u003ccstdio>\n\nnamespace {\n\nnamespace ids = cdal::ids;\n\nvoid log(const char* fmt, ...) {\n    if (FILE* f = std::fopen(\"shared_hooks.log\", \"a\")) {\n        va_list args;\n        va_start(args, fmt);\n        std::vfprintf(f, fmt, args);\n        va_end(args);\n        std::fputc('\\n', f);\n        std::fclose(f);\n    }\n}\n\n// Argument types follow the id's description: rcx = stat container, dx = stat id, r8, r9 = delta, then on the\n// stack the source, five byte flags and a pointer the game writes the result to. The game reads all eleven, so the\n// detour takes and passes on all eleven.\nusing u8 = std::uint8_t;\nusing ApplyStatDelta = std::uint64_t (*)(void* stats, std::uint16_t stat, std::uint64_t r8, std::int64_t delta,\n                                         void* source, u8 a, u8 b, u8 c, u8 d, u8 e, std::uint64_t* out);\ncdal::hooks::FunctionHook\u003cApplyStatDelta> g_apply;\ncdal::hooks::MidHook g_no_wear;\n\nstd::uint64_t on_apply(void* stats, std::uint16_t stat, std::uint64_t r8, std::int64_t delta, void* source, u8 a,\n                       u8 b, u8 c, u8 d, u8 e, std::uint64_t* out) {\n    if (stat == 0 && delta \u003c 0) delta /= 2;  // stat 0 is HP\n    // original() is the rest of the chain: lower-priority plugins first, then the game.\n    return g_apply.original()(stats, stat, r8, delta, source, a, b, c, d, e, out);\n}\n\nconst cdal::hooks::Options opts{\"shared_hooks example\", 0};\n\n// Each feature checks its own IDs, so a missing one switches off only that feature. cdal::Feature\n// reports each one's state to cdal.dll too, so CDAL/hooks.log and crash notes say which is off and why.\ncdal::Feature g_half_damage{opts.owner, \"Half damage\"};\ncdal::Feature g_no_wear_feature{opts.owner, \"No wear\"};\n\nvoid install_half_damage() {\n    std::string missing, err;\n    if (!g_half_damage.require({ids::StatusComponent::ApplyStatDelta}, &missing)) {\n        log(\"half damage off on CDAL %s: %s\", cdal::build().c_str(), missing.c_str());\n    } else if (!g_apply.install(ids::StatusComponent::ApplyStatDelta, &on_apply, opts, &err)) {\n        log(\"half damage disabled: %s\", err.c_str());\n        g_half_damage.off(err);  // a failed hook switches the feature off like a missing ID (rule 7)\n    }\n}\n\nvoid install_no_wear() {\n    std::string missing, err;\n    if (!g_no_wear_feature.require({ids::ItemDurability::ApplyDelta_Hook}, &missing)) {\n        log(\"no wear off on CDAL %s: %s\", cdal::build().c_str(), missing.c_str());\n        return;\n    }\n    g_no_wear = cdal::hooks::MidHook::create(\n        ids::ItemDurability::ApplyDelta_Hook,\n        [](cdal_context& ctx) {\n            if (static_cast\u003cstd::int16_t>(ctx.r12) \u003c 0) ctx.r12 = 0;  // r12w = signed durability delta\n        },\n        opts, &err);\n    if (!g_no_wear) {\n        log(\"no wear disabled: %s\", err.c_str());\n        g_no_wear_feature.off(err);\n    }\n}\n\nDWORD WINAPI run(LPVOID) {\n    ::Sleep(20000);  // let the game unpack; never hook inside DllMain\n\n    if (!cdal::init()) {\n        log(\"CDAL unavailable: %s\", cdal::last_error().c_str());\n        return 0;\n    }\n    install_half_damage();\n    install_no_wear();\n\n    for (const auto& h : cdal::hooks::list())\n        log(\"%s at 0x%llX: owner %s, priority %d, position %u%s%s\", h.name.empty() ? \"(address)\" : h.name.c_str(),\n            static_cast\u003cunsigned long long>(h.target), h.owner.c_str(), h.priority, h.chain_index,\n            h.foreign.empty() ? \"\" : \", also hooked outside CDAL by \", h.foreign.c_str());\n    return 0;\n}\n\n// ASI loaders also load every .asi into the game's crashpad_handler.exe: only start in the game.\nbool in_game_process() {\n    wchar_t path[MAX_PATH * 4];\n    const DWORD n = ::GetModuleFileNameW(nullptr, path, MAX_PATH * 4);\n    const wchar_t* name = path + n;\n    while (name > path && name[-1] != L'\\\\' && name[-1] != L'/') --name;\n    return ::CompareStringOrdinal(name, -1, L\"CrimsonDesert.exe\", -1, TRUE) == CSTR_EQUAL;\n}\n\n}  // namespace\n\nBOOL WINAPI DllMain(HINSTANCE module, DWORD reason, LPVOID) {\n    if (reason == DLL_PROCESS_ATTACH && in_game_process()) {\n        ::DisableThreadLibraryCalls(module);\n        if (HANDLE t = ::CreateThread(nullptr, 0, run, nullptr, 0, nullptr)) ::CloseHandle(t);\n    }\n    return TRUE;\n}\n","lang":"cpp","name":"shared_hooks.cpp"}],"id":"shared_hooks","kind":"native_cpp","lua_api":0,"path":"examples/shared_hooks","tier":"native_sdk","title":"Shared Hooks (C++ ASI)","uses":["cdal.lib"]},{"category":"Native C / C++","description":"Minimal C plugin using the BSX Plugin ABI to subscribe to lifecycle and game events cleanly.","featured":false,"files":[{"code":"/* Smallest BSX plugin, in plain C: it says it needs the WorldSystem, so BSX only loads it when\n * CDAL has that address for this game build, and logs what it found to BSX/bsx.log. It also logs\n * the game events, so a first run shows how often FRAME fires and what the equip fields hold.\n * Build: part of the CDAL CMake project on Windows (target hello_bsx). Install: copy\n * hello_bsx.dll to \u003cgame>/bin64/BSX/plugins. */\n#include \u003cbsx/bsx.h>\n#include \u003ccdal/cdal.h>\n#include \u003ccdal/ids.h>\n\n#include \u003cstdio.h>\n\nstatic const uint32_t needs[] = {CDAL_ID_WorldSystem_sInstance};\n\nstatic const bsx_plugin_info info = {\n    sizeof(bsx_plugin_info), BSX_API_VERSION, \"Hello BSX\", \"0.1.0\", \"CDAL\", needs, 1, NULL, NULL, 0,\n};\n\nstatic const bsx_interface* bsx;\n\nstatic void on_plugins_loaded(uint32_t event, const void* data, void* user) {\n    char msg[128];\n    (void)event, (void)data, (void)user;\n    snprintf(msg, sizeof msg, \"%u plugin(s) found; game build %s\", (unsigned)bsx->plugin_count(), cdal_build_name());\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\n/* Every 600th frame, so the log's timestamps give the rate without flooding it. */\nstatic void on_frame(uint32_t event, const void* data, void* user) {\n    const bsx_frame_event* e = (const bsx_frame_event*)data;\n    char msg[64];\n    (void)event, (void)user;\n    if (e->frame != 1 && e->frame % 600 != 0) return;\n    snprintf(msg, sizeof msg, \"frame %llu\", (unsigned long long)e->frame);\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void on_save_load(uint32_t event, const void* data, void* user) {\n    const bsx_save_load_event* e = (const bsx_save_load_event*)data;\n    /* flags exists from BSX API 2: a replay is a load that happened before this plugin subscribed. */\n    const int replayed = bsx->api_version >= 2 && (e->flags & BSX_EVENT_FLAG_REPLAYED);\n    char msg[112];\n    (void)event, (void)user;\n    snprintf(msg, sizeof msg, \"save load: key 0x%llX, argument %u%s\", (unsigned long long)e->key,\n             (unsigned)e->argument, replayed ? \" (replayed)\" : \"\");\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void on_equip(uint32_t event, const void* data, void* user) {\n    const bsx_equip_event* e = (const bsx_equip_event*)data;\n    char msg[128];\n    (void)user;\n    snprintf(msg, sizeof msg, \"%s: equipment %p, bucket %u, index %u, tag %u\",\n             event == BSX_EVENT_EQUIP ? \"equip\" : \"unequip\", e->equipment, (unsigned)e->bucket, (unsigned)e->index,\n             (unsigned)e->tag);\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void on_save_loaded(uint32_t event, const void* data, void* user) {\n    const bsx_save_loaded_event* e = (const bsx_save_loaded_event*)data;\n    char msg[160];\n    (void)event, (void)user;\n    snprintf(msg, sizeof msg, \"save loaded: generation %llu, key 0x%llX, argument %u, actor %p\",\n             (unsigned long long)e->generation, (unsigned long long)e->key, (unsigned)e->argument, e->actor);\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void on_equipment_applied(uint32_t event, const void* data, void* user) {\n    const bsx_equipment_applied_event* e = (const bsx_equipment_applied_event*)data;\n    char msg[240];\n    (void)user;\n    snprintf(msg, sizeof msg,\n             \"%s applied: generation %llu, actor %p, equipment %p, tag %u, row %u, word0 0x%llX, count %lld, cause %u\",\n             event == BSX_EVENT_EQUIP_APPLIED ? \"equip\" : \"unequip\", (unsigned long long)e->generation,\n             e->actor, e->equipment, (unsigned)e->tag, (unsigned)e->row,\n             (unsigned long long)e->item_word0, (long long)e->count, (unsigned)e->cause);\n    bsx->log(bsx->self, BSX_LOG_INFO, msg);\n}\n\nstatic void subscribe(uint32_t event, bsx_event_fn fn, const char* name) {\n    char msg[96];\n    int r = bsx->subscribe(bsx->self, event, fn, NULL);\n    if (r == BSX_OK) return;\n    /* bsx.log already has the reason; the plugin carries on without this event. */\n    snprintf(msg, sizeof msg, \"no %s event (%d)\", name, r);\n    bsx->log(bsx->self, BSX_LOG_WARN, msg);\n}\n\nBSX_EXPORT const bsx_plugin_info* bsx_plugin_query(void) { return &info; }\n\nBSX_EXPORT int bsx_plugin_load(const bsx_interface* iface) {\n    char msg[128];\n    void* const* world = (void* const*)cdal_address(CDAL_ID_WorldSystem_sInstance);\n    bsx = iface;\n    /* BSX checked the id before loading this plugin, so the address is there. */\n    snprintf(msg, sizeof msg, \"WorldSystem::sInstance at %p, WorldSystem at %p\", (const void*)world, *world);\n    iface->log(iface->self, BSX_LOG_INFO, msg);\n    iface->subscribe(iface->self, BSX_EVENT_PLUGINS_LOADED, on_plugins_loaded, NULL);\n    subscribe(BSX_EVENT_FRAME, on_frame, \"frame\");\n    subscribe(BSX_EVENT_SAVE_LOAD, on_save_load, \"save load\");\n    subscribe(BSX_EVENT_EQUIP, on_equip, \"equip\");\n    subscribe(BSX_EVENT_UNEQUIP, on_equip, \"unequip\");\n    subscribe(BSX_EVENT_SAVE_LOADED, on_save_loaded, \"save loaded\");\n    subscribe(BSX_EVENT_EQUIP_APPLIED, on_equipment_applied, \"equip applied\");\n    subscribe(BSX_EVENT_UNEQUIP_APPLIED, on_equipment_applied, \"unequip applied\");\n    return 1;\n}\n","lang":"c","name":"hello_bsx.c"}],"id":"hello_bsx","kind":"native_cpp","lua_api":0,"path":"bsx/examples/hello_bsx.c","tier":"native_sdk","title":"Hello BSX (C Plugin)","uses":["cdal.lib"]},{"category":"Native C / C++","description":"Standalone BSX SDK C plugin counting combat hits/kills/revives and persisting totals.","featured":false,"files":[{"code":"/* Fight Tally: a sample BSX plugin written the way a mod author outside CDAL would write one.\n *\n * It counts the hits, deaths and revives BSX observes, keeps the counts with each save, and logs\n * them when you press a hotkey (Ctrl+Alt+T by default). It reads the game only through BSX events\n * and never changes the game. Each of its three features switches itself off on its own, with one\n * log line that says why, and the others keep working:\n *\n *   combat tally   needs [BSX] CombatEvents on (the default) and a game build whose database\n *                  has the combat IDs checked;\n *   hotkey report  needs BSX's hotkey service (API 3, [BSX] Keys=1, the default);\n *   per-save data  needs [BSX] CoSave=1 (and WorldReady on, the default); without it the counts start again at\n *                  every save load and live only until the game closes.\n *\n * Every callback below runs on the game's frame thread, one at a time, so the counts need no lock.\n *\n * Build it on its own against the SDK (see CMakeLists.txt and docs/guides/BSX_PLUGINS.md), or as\n * part of the CDAL CMake project on Windows (target fight_tally). Install: copy fight_tally.dll\n * and, if you want other settings, fight_tally.dll.ini to \u003cgame>/bin64/BSX/plugins. */\n#include \u003cbsx/bsx.h>\n#include \u003cbsx/hotkeys.h>\n#include \u003ccdal/cdal.h>\n\n#include \u003cstddef.h>\n#include \u003cstdio.h>\n#include \u003cstring.h>\n\n/* No CDAL IDs: the plugin only uses BSX events. A plugin that reads or hooks the game lists\n * every ID it can't run without here, and BSX then loads it only when they all resolve. */\nstatic const bsx_plugin_info info = {\n    sizeof(bsx_plugin_info), BSX_API_VERSION, \"Fight Tally\", \"1.0.0\", \"Example author\",\n    NULL, 0,   /* CDAL ids */\n    NULL,      /* plugins it requires */\n    NULL,      /* plugins to load first if they are installed */\n    0,         /* flags: a normal-phase plugin */\n    3,         /* min_api_version: hotkeys, combat events and co-save came with API 3 */\n};\n\n/* What is kept with each save. version lets a later release read older saves. */\ntypedef struct tally {\n    uint32_t version;\n    uint32_t hits, deaths, revives;\n} tally;\nenum { TALLY_VERSION = 1 };\n\nstatic const bsx_interface* bsx;\nstatic tally counts;\nstatic int combat_on, report_on, per_save_on;\nstatic bsx_cosave_handle cosave_handle;\nstatic unsigned waiting_frames; /* frames left for co-save data after a SAVE_LOADED */\nstatic uint32_t last_death_key; /* not kept with the save: keys only last for one session */\n\nstatic void say(bsx_log_level level, const char* text) { bsx->log(bsx->self, level, text); }\n\nstatic void reset(void) {\n    last_death_key = 0;\n    memset(&counts, 0, sizeof counts);\n    counts.version = TALLY_VERSION;\n}\n\nstatic void report(const char* why) {\n    char msg[200];\n    snprintf(msg, sizeof msg, \"%s: %u hits, %u deaths, %u revives since %s\", why, (unsigned)counts.hits,\n             (unsigned)counts.deaths, (unsigned)counts.revives,\n             per_save_on ? \"this save was started (kept with the save)\" : \"the last save load\");\n    say(BSX_LOG_INFO, msg);\n    if (last_death_key) {\n        snprintf(msg, sizeof msg, \"last death: actor key %u\", (unsigned)last_death_key);\n        say(BSX_LOG_INFO, msg);\n    }\n    snprintf(msg, sizeof msg, \"%u hits, %u deaths, %u revives\", (unsigned)counts.hits, (unsigned)counts.deaths,\n             (unsigned)counts.revives);\n    bsx->set_status(bsx->self, msg);\n}\n\n/* --- Feature 1: the combat tally ------------------------------------------------------------- */\n\n/* Copy what you need from an event payload: it is only valid during the callback. Read a field\n * only when struct_size covers it, so a later BSX with a longer payload keeps working. */\nstatic void on_hit(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    counts.hits++;\n}\nstatic void on_death(uint32_t event, const void* data, void* user) {\n    const bsx_death_event* e = (const bsx_death_event*)data;\n    (void)event, (void)user;\n    counts.deaths++;\n    if (e->struct_size >= offsetof(bsx_death_event, actor_key) + sizeof e->actor_key) last_death_key = e->actor_key;\n}\nstatic void on_revive(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    counts.revives++;\n}\n\nstatic void start_combat(void) {\n    static const struct { uint32_t event; bsx_event_fn fn; } events[] = {\n        {BSX_EVENT_HIT, on_hit}, {BSX_EVENT_DEATH, on_death}, {BSX_EVENT_REVIVE, on_revive}};\n    char msg[200];\n    size_t i;\n    for (i = 0; i \u003c sizeof events / sizeof events[0]; i++) {\n        bsx_result r = bsx->subscribe(bsx->self, events[i].event, events[i].fn, NULL);\n        if (r != BSX_OK) {\n            /* All three or none: undo the ones that worked, so the counts never mislead. */\n            while (i-- > 0) bsx->unsubscribe(bsx->self, events[i].event, events[i].fn);\n            snprintf(msg, sizeof msg,\n                     \"combat tally off (BSX result %d): bsx.log says \"\n                     \"why if it is already set\",\n                     (int)r);\n            say(BSX_LOG_WARN, msg);\n            return;\n        }\n    }\n    combat_on = 1;\n}\n\n/* --- Feature 2: the hotkey report ------------------------------------------------------------ */\n\nstatic void on_report_key(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    report(\"tally\");\n}\n\nstatic void start_report(void) {\n    const bsx_hotkeys_service_v1* keys = (const bsx_hotkeys_service_v1*)bsx->get_service(BSX_HOTKEYS_SERVICE);\n    /* Settings come from fight_tally.dll.ini next to the DLL; missing keys use these defaults. */\n    const int32_t vk = bsx->config_int(bsx->self, \"Report\", \"Key\", 0x54);           /* T */\n    const int32_t mods = bsx->config_int(bsx->self, \"Report\", \"Modifiers\", 3);      /* Ctrl+Alt */\n    uint64_t token = 0;\n    bsx_result r;\n    char msg[160];\n    /* A service is a struct of function pointers: check its size before you use a field. */\n    if (!keys || keys->struct_size \u003c sizeof *keys || !keys->register_key) {\n        say(BSX_LOG_WARN, \"hotkey report off: this BSX has no hotkey service\");\n        return;\n    }\n    r = keys->register_key(bsx->self, (uint32_t)vk, (uint32_t)mods, on_report_key, NULL, NULL, &token);\n    if (r != BSX_OK) {\n        snprintf(msg, sizeof msg, \"hotkey report off: key %d with modifiers %d refused (BSX result %d)\", (int)vk,\n                 (int)mods, (int)r);\n        say(BSX_LOG_WARN, msg);\n        return;\n    }\n    report_on = 1;\n}\n\n/* --- Feature 3: per-save data ---------------------------------------------------------------- */\n\nstatic int on_cosave_save(void* user, bsx_cosave_writer* writer) {\n    (void)user;\n    return writer->write(writer->context, &counts, sizeof counts) == BSX_OK;\n}\n\nstatic void on_cosave_load(void* user, const bsx_cosave_reader* reader) {\n    tally loaded;\n    (void)user;\n    waiting_frames = 0;\n    /* Data from disk is not trusted: check status, size and version before you use it. */\n    if (reader->status == BSX_COSAVE_PRESENT && reader->size == sizeof loaded) {\n        memcpy(&loaded, reader->bytes, sizeof loaded);\n        if (loaded.version == TALLY_VERSION) {\n            counts = loaded;\n            report(\"save loaded\");\n            return;\n        }\n    }\n    reset(); /* a new save, an older save without our data, or data we can't read */\n    if (reader->status != BSX_COSAVE_PENDING) report(\"save loaded\");\n}\n\n/* With co-save: a load whose save co-save did not see (for example one BSX could not match to a\n   slot) gets no load callback. Start again then too, so old counts never carry over silently. */\nstatic void on_save_loaded_cosave(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    waiting_frames = 600; /* about 10 s at 60 fps; the co-save callback normally comes a few frames later */\n}\nstatic void on_frame(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    if (waiting_frames && !--waiting_frames) {\n        reset();\n        report(\"save loaded without co-save data\");\n    }\n}\n\n/* Without co-save: start again at every save load. */\nstatic void on_save_loaded(uint32_t event, const void* data, void* user) {\n    (void)event, (void)data, (void)user;\n    reset();\n    report(\"save loaded\");\n}\n\nstatic void start_per_save(void) {\n    static const bsx_cosave_callbacks callbacks = {sizeof(bsx_cosave_callbacks), on_cosave_save, on_cosave_load, NULL};\n    const bsx_cosave_service_v1* service = (const bsx_cosave_service_v1*)bsx->get_service(BSX_COSAVE_SERVICE);\n    char msg[160];\n    bsx_result r = BSX_E_UNAVAILABLE;\n    if (service && service->struct_size >= sizeof *service && service->register_data)\n        r = service->register_data(bsx->self, \"tally\", &callbacks, &cosave_handle);\n    if (r == BSX_OK) {\n        per_save_on = 1;\n        /* Optional: without these two, a load co-save did not see keeps the previous counts. */\n        if (bsx->subscribe(bsx->self, BSX_EVENT_FRAME, on_frame, NULL) == BSX_OK &&\n            bsx->subscribe(bsx->self, BSX_EVENT_SAVE_LOADED, on_save_loaded_cosave, NULL) != BSX_OK)\n            bsx->unsubscribe(bsx->self, BSX_EVENT_FRAME, on_frame);\n        return;\n    }\n    if (service)\n        snprintf(msg, sizeof msg, \"per-save data off (BSX result %d); counts start again at each save load\", (int)r);\n    else\n        snprintf(msg, sizeof msg, \"per-save data off: set [BSX] CoSave=1 in BSX/bsx.ini; counts \"\n                                  \"start again at each save load\");\n    say(BSX_LOG_WARN, msg);\n    if (bsx->subscribe(bsx->self, BSX_EVENT_SAVE_LOADED, on_save_loaded, NULL) != BSX_OK)\n        say(BSX_LOG_WARN, \"no SAVE_LOADED event either: counts run for the whole session\");\n}\n\n/* --- Entry points ---------------------------------------------------------------------------- */\n\nBSX_EXPORT const bsx_plugin_info* bsx_plugin_query(void) { return &info; }\n\nBSX_EXPORT int bsx_plugin_load(const bsx_interface* iface) {\n    char msg[200];\n    bsx = iface;\n    reset();\n    start_combat();\n    start_report();\n    start_per_save();\n    snprintf(msg, sizeof msg, \"Fight Tally 1.0.0 on BSX %s, game build %s: combat tally %s, hotkey report %s, \"\n             \"per-save data %s\", iface->bs\n// ... truncated at 10240 bytes (see fight_tally.c in repo for full file)\n","lang":"c","name":"fight_tally.c"},{"code":"; Fight Tally settings. Copy this file next to fight_tally.dll in BSX/plugins and edit it.\n; BSX reads it once, when the game starts.\n\n[Report]\n; The key that logs the tally to BSX/bsx.log: a Windows virtual-key code in decimal\n; (84 is T, 123 is F12).\nKey=84\n; Modifiers that must be held, added together: 1 Ctrl, 2 Alt, 4 Shift, 8 Windows.\n; 3 is Ctrl+Alt.\nModifiers=3\n","lang":"ini","name":"fight_tally.dll.ini"},{"code":"# Builds Fight Tally on its own from an unzipped CDAL SDK, the way a mod author outside CDAL would.\n# The SDK has this folder at bsx/examples/fight_tally, so from there no path is needed:\n#   cmake -S . -B build -A x64\n#   cmake --build build --config Release\n# From a copy elsewhere, name the SDK folder: cmake -S . -B build -A x64 -DCDAL_SDK=C:/CDAL-SDK-0.7.0\ncmake_minimum_required(VERSION 3.20)\nproject(fight_tally C)\n\nset(CDAL_SDK \"${CMAKE_CURRENT_SOURCE_DIR}/../../..\" CACHE PATH\n    \"Unzipped CDAL SDK folder (it has include/cdal, bsx/include/bsx and lib/cdal.lib)\")\nif(NOT EXISTS \"${CDAL_SDK}/include/cdal/cdal.h\" OR NOT EXISTS \"${CDAL_SDK}/bsx/include/bsx/bsx.h\")\n    message(FATAL_ERROR \"CDAL_SDK=${CDAL_SDK} is not an unzipped CDAL SDK: pass -DCDAL_SDK=\u003cfolder>\")\nendif()\n\nadd_library(fight_tally MODULE fight_tally.c)\ntarget_include_directories(fight_tally PRIVATE \"${CDAL_SDK}/include\" \"${CDAL_SDK}/bsx/include\")\nset_target_properties(fight_tally PROPERTIES PREFIX \"\" C_VISIBILITY_PRESET hidden)\nif(MSVC)\n    target_compile_options(fight_tally PRIVATE /W4 /utf-8)\nelse()\n    target_compile_options(fight_tally PRIVATE -Wall -Wextra -Wpedantic)\nendif()\nif(WIN32)\n    # cdal.dll's import library: the plugin calls cdal_build_name(). Players install cdal.dll\n    # once with CDAL; don't ship it with the plugin.\n    if(NOT EXISTS \"${CDAL_SDK}/lib/cdal.lib\")\n        message(FATAL_ERROR \"${CDAL_SDK}/lib/cdal.lib is missing: use the SDK zip, not a source checkout\")\n    endif()\n    target_link_libraries(fight_tally PRIVATE \"${CDAL_SDK}/lib/cdal.lib\")\nendif()\n","lang":"cli","name":"CMakeLists.txt"}],"id":"fight_tally","kind":"native_cpp","lua_api":0,"path":"bsx/examples/fight_tally","tier":"native_sdk","title":"Fight Tally (BSX C SDK)","uses":["cdal.lib"]},{"category":"Native C / C++","description":"Native C++ BSX plugin reading player coordinates, time-of-day, and weather snapshots.","featured":false,"files":[{"code":"// SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0\n// Native World HUD: sample C++ BSX API 3 plugin consuming BSX.Overlay.UI/1 and BSX.World/1.\n// Build as target `world_hud` and copy world_hud.dll into \u003cgame>/bin64/BSX/plugins.\n#include \u003cbsx/bsx.h>\n#include \u003cbsx/ui.h>\n#include \u003cbsx/world.h>\n\n#include \u003calgorithm>\n#include \u003ccstdio>\n#include \u003ccstring>\n\nnamespace {\nconst bsx_interface* g_bsx = nullptr;\nconst bsx_overlay_ui_service_v1* g_ui = nullptr;\nconst bsx_world_service_v1* g_world = nullptr;\n\nuint64_t g_panel_id = 0;\nuint64_t g_pos_widget = 0;\nuint64_t g_hp_widget = 0;\nuint64_t g_env_widget = 0;\nuint64_t g_heal_widget = 0;\nuint64_t g_frame_counter = 0;\n\nvoid update_status(const char* text) {\n    if (g_bsx && g_bsx->set_status && g_bsx->self) {\n        g_bsx->set_status(g_bsx->self, text);\n    }\n}\n\nvoid refresh_hud() {\n    if (!g_ui || !g_panel_id || !g_world) return;\n\n    bsx_world_player_state_v1 ps{};\n    ps.struct_size = sizeof(ps);\n    char err[256]{};\n    const bsx_result rc = g_world->snapshot_player_state(g_world->context, &ps, err, sizeof(err));\n    if (rc != BSX_OK) {\n        char buf[128]{};\n        std::snprintf(buf, sizeof(buf), \"Pos: %s\", err[0] ? err : \"waiting for world\");\n        g_ui->set_text(g_ui->context, g_panel_id, g_pos_widget, buf);\n        g_ui->set_value(g_ui->context, g_panel_id, g_hp_widget, 0, 0.0f, 0);\n        g_ui->set_text(g_ui->context, g_panel_id, g_hp_widget, \"HP: -- / --\");\n        g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, \"Actors: -- | Zone: --\");\n        return;\n    }\n\n    char pos_buf[128]{};\n    if (ps.has_position) {\n        std::snprintf(pos_buf, sizeof(pos_buf), \"Pos: (%.1f, %.1f, %.1f) yaw=%.0f\",\n                      ps.position[0], ps.position[1], ps.position[2], ps.has_yaw ? ps.yaw_deg : 0.0);\n    } else {\n        std::snprintf(pos_buf, sizeof(pos_buf), \"Pos: unavailable\");\n    }\n    g_ui->set_text(g_ui->context, g_panel_id, g_pos_widget, pos_buf);\n\n    const char* zone = ps.in_town ? \"town\" : (ps.in_safe_zone ? \"safe\" : (ps.in_battle ? \"combat\" : \"open\"));\n    char env_buf[128]{};\n    std::snprintf(env_buf, sizeof(env_buf), \"Actors: %u | Zone: %s | Row: %u\",\n                  ps.actor_total_count, zone, ps.has_character_row ? ps.character_row : 0u);\n    g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, env_buf);\n\n    bsx_world_stat_v1 hp{};\n    hp.struct_size = sizeof(hp);\n    if (g_world->read_stat(g_world->context, 0, 0, &hp, nullptr, 0) == BSX_OK && hp.max > 0) {\n        const float frac = (std::max)(0.0f, (std::min)(1.0f, static_cast\u003cfloat>(hp.current) / static_cast\u003cfloat>(hp.max)));\n        char hp_buf[128]{};\n        std::snprintf(hp_buf, sizeof(hp_buf), \"HP: %lld / %lld\",\n                      static_cast\u003clong long>(hp.current), static_cast\u003clong long>(hp.max));\n        g_ui->set_value(g_ui->context, g_panel_id, g_hp_widget, 0, frac, 0);\n        g_ui->set_text(g_ui->context, g_panel_id, g_hp_widget, hp_buf);\n    }\n}\n\nvoid on_ui_action(uint64_t panel_id, uint64_t widget_id, uint32_t kind,\n                  uint8_t, float, int32_t, const char*, void*) {\n    if (panel_id != g_panel_id || widget_id != g_heal_widget || kind != BSX_OVERLAY_UI_BUTTON) return;\n    if (!g_world) return;\n    bsx_world_stat_v1 hp{};\n    hp.struct_size = sizeof(hp);\n    char err[256]{};\n    if (g_world->read_stat(g_world->context, 0, 0, &hp, err, sizeof(err)) != BSX_OK) {\n        g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, err[0] ? err : \"HP read unavailable\");\n        return;\n    }\n    const int64_t missing = hp.max - hp.current;\n    if (missing \u003c= 0) {\n        g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, \"HP already full\");\n        return;\n    }\n    const int64_t delta = (std::min)(int64_t{1000000}, missing);\n    if (g_world->queue_stat_add(g_world->context, 0, delta, err, sizeof(err)) == BSX_OK) {\n        g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, \"Native heal queued\");\n        refresh_hud();\n    } else {\n        g_ui->set_text(g_ui->context, g_panel_id, g_env_widget, err[0] ? err : \"Heal blocked\");\n    }\n}\n\nvoid ensure_panel_and_services() {\n    if (!g_bsx || !g_bsx->get_service) return;\n    if (!g_world) {\n        const auto* w = static_cast\u003cconst bsx_world_service_v1*>(g_bsx->get_service(BSX_WORLD_SERVICE_V1));\n        if (w && w->struct_size >= sizeof(*w) && w->api_version >= 1) g_world = w;\n    }\n    if (!g_ui) {\n        const auto* u = static_cast\u003cconst bsx_overlay_ui_service_v1*>(g_bsx->get_service(BSX_OVERLAY_UI_SERVICE_V1));\n        if (u && u->struct_size >= sizeof(*u) && u->api_version >= 1) g_ui = u;\n    }\n    if (g_ui && !g_panel_id) {\n        if (g_ui->create_panel(g_ui->context, \"NativeHUD\", \"Native World HUD\", &g_panel_id) == BSX_OK && g_panel_id) {\n            (void)g_ui->add_text(g_ui->context, g_panel_id, \"Pos: waiting for world\", &g_pos_widget);\n            (void)g_ui->add_progress(g_ui->context, g_panel_id, 0.0f, \"HP: -- / --\", &g_hp_widget);\n            (void)g_ui->add_text(g_ui->context, g_panel_id, \"Actors: -- | Zone: --\", &g_env_widget);\n            (void)g_ui->add_button(g_ui->context, g_panel_id, \"Full Heal (Native)\", on_ui_action, nullptr, &g_heal_widget);\n        }\n    }\n    if (g_ui && g_world) {\n        update_status(\"on: overlay panel + world service\");\n    } else if (!g_ui && !g_world) {\n        update_status(\"waiting: enable BSX.Overlay and BSX.Lua\");\n    } else if (!g_ui) {\n        update_status(\"waiting: enable [Overlay] Enabled=1 for panel\");\n    } else {\n        update_status(\"waiting: load BSX.Lua for BSX.World/1\");\n    }\n}\n\nvoid on_plugins_loaded(uint32_t, const void*, void*) {\n    ensure_panel_and_services();\n}\n\nvoid on_frame(uint32_t, const void*, void*) {\n    ++g_frame_counter;\n    if (g_frame_counter == 1 || g_frame_counter % 30 == 0) {\n        refresh_hud();\n    }\n}\n\nvoid on_reset(uint32_t, const void*, void*) {\n    if (g_ui && g_panel_id) {\n        g_ui->set_text(g_ui->context, g_panel_id, g_pos_widget, \"Pos: waiting for world\");\n        g_ui->set_value(g_ui->context, g_panel_id, g_hp_widget, 0, 0.0f, 0);\n        g_ui->set_text(g_ui->context, g_panel_id, g_hp_widget, \"HP: -- / --\");\n    }\n}\n\nconst bsx_plugin_info kInfo = {\n    sizeof(bsx_plugin_info),\n    BSX_API_VERSION,\n    \"Native World HUD\",\n    \"1.0.0\",\n    \"CDAL\",\n    nullptr,\n    0,\n    nullptr,\n    nullptr,\n    0,\n    3,\n};\n} // namespace\n\nextern \"C\" BSX_EXPORT const bsx_plugin_info* bsx_plugin_query(void) {\n    return &kInfo;\n}\n\nextern \"C\" BSX_EXPORT int bsx_plugin_load(const bsx_interface* iface) {\n    if (!iface || iface->struct_size \u003c sizeof(*iface) || iface->api_version \u003c 3) return 0;\n    g_bsx = iface;\n    g_ui = nullptr;\n    g_world = nullptr;\n    g_panel_id = 0;\n    g_frame_counter = 0;\n    ensure_panel_and_services();\n    (void)g_bsx->subscribe(g_bsx->self, BSX_EVENT_PLUGINS_LOADED, on_plugins_loaded, nullptr);\n    (void)g_bsx->subscribe(g_bsx->self, BSX_EVENT_FRAME, on_frame, nullptr);\n    (void)g_bsx->subscribe(g_bsx->self, BSX_EVENT_SAVE_LOAD, on_reset, nullptr);\n    (void)g_bsx->subscribe(g_bsx->self, BSX_EVENT_TITLE_SCREEN, on_reset, nullptr);\n    return 1;\n}\n\nextern \"C\" BSX_EXPORT void bsx_plugin_unload(void) {\n    if (g_ui && g_panel_id && g_ui->remove_panel) {\n        (void)g_ui->remove_panel(g_ui->context, g_panel_id);\n        g_panel_id = 0;\n    }\n}\n","lang":"cpp","name":"world_hud.cpp"}],"id":"world_hud","kind":"native_cpp","lua_api":0,"path":"bsx/examples/world_hud","tier":"native_sdk","title":"World HUD (BSX C++)","uses":["cdal.lib"]},{"category":"Native C / C++","description":"Comprehensive native diagnostic plugin exercising BSX event streams, snapshot reads, and request tracing.","featured":false,"files":[{"code":"/* Read-only BSX API-3 trace plugin. See TRACE.md for the log contract and limits.\n * No game access in DllMain; process detach only writes a final counter snapshot.\n * SPDX-License-Identifier: LicenseRef-CDAL-BSX-Source-Available-1.0 */\n#define WIN32_LEAN_AND_MEAN\n#include \u003cwindows.h>\n#include \u003cbsx/bsx.h>\n#include \u003ccdal/cdal.h>\n#include \u003ccdal/ids.h>\n#include \u003cstddef.h>\n#include \u003cstdio.h>\n#include \u003cstring.h>\n#include \u003cwchar.h>\n\n#ifdef BSX_SELFTEST_EARLY\n#define PLUGIN_NAME \"BSX Selftest Early\"\n#define PHASE \"early\"\n#define LOG_NAME L\"\\\\..\\\\bsx_selftest_early.log\"\n#define PLUGIN_FLAGS BSX_PLUGIN_EARLY\n#else\n#define PLUGIN_NAME \"BSX Selftest\"\n#define PHASE \"normal\"\n#define LOG_NAME L\"\\\\..\\\\bsx_selftest.log\"\n#define PLUGIN_FLAGS 0\n#endif\n\nstatic const bsx_plugin_info info = {\n    sizeof(bsx_plugin_info), BSX_API_VERSION, PLUGIN_NAME, \"0.1.0\", \"CDAL\",\n    NULL, 0, NULL, NULL, PLUGIN_FLAGS\n};\n#define LAST_EVENT BSX_EVENT_REVIVE\nstatic const char* const event_names[] = {\n    \"NONE\", \"PLUGINS_LOADED\", \"FRAME\", \"SAVE_LOAD\", \"EQUIP\", \"UNEQUIP\",\n    \"SAVE_LOADED\", \"EQUIP_APPLIED\", \"UNEQUIP_APPLIED\", \"WORLD_READY\", \"TITLE_SCREEN\",\n    \"LOAD_REQUEST\", \"WEAPON_SWAP\", \"QUICK_SLOT_USE\", \"MOVIE\", \"BATTLE_STATE\",\n    \"STAT_CHANGE\",\n    \"SAVE_LOAD_AFTER\", \"EQUIP_AFTER\", \"UNEQUIP_AFTER\", \"LOAD_REQUEST_AFTER\",\n    \"WEAPON_SWAP_AFTER\", \"QUICK_SLOT_USE_AFTER\", \"MOVIE_AFTER\", \"BATTLE_STATE_AFTER\",\n    \"KEY\", \"HIT\", \"DEATH\", \"REVIVE\"\n};\nstatic HANDLE logfile = INVALID_HANDLE_VALUE;\nstatic SRWLOCK log_lock = SRWLOCK_INIT;\nstatic volatile LONG64 counts[LAST_EVENT + 1];\nstatic volatile LONG64 sequence;\nstatic volatile LONG64 write_errors;\nstatic ULONGLONG load_tick;\nstatic DWORD main_tid; /* First FRAME callback, never the plugin-loading thread. */\nstatic uintptr_t expected_vtable;\n/* WorldSystem::sInstance and the offsets of IDs 193 and 194: the controlled actor as\n * BSX's player_flags read it, logged beside the actor a payload carries. */\nstatic uintptr_t world_global, manager_offset, actor_offset;\nstatic volatile LONG loaded;\n\n/* One append per record. No CRT, loader/BSX calls, allocation or locks here: also\n * used during process detach, when a terminated thread could own those locks. */\nstatic void write_record(const char* line, DWORD length) {\n    DWORD written = 0;\n    if (!WriteFile(logfile, line, length, &written, NULL) || written != length)\n        InterlockedIncrement64(&write_errors);\n}\n\n/* Bounded by the fixed names and at most 20 digits per counter (\u003c 1280 bytes).\n * These tiny formatters keep the detach summary independent of the CRT. */\nstatic char* append_text(char* out, const char* text) {\n    while (*text) *out++ = *text++;\n    return out;\n}\nstatic char* append_number(char* out, ULONGLONG value) {\n    char digits[20];\n    unsigned n = 0;\n    do { digits[n++] = (char)('0' + value % 10); value /= 10; } while (value);\n    while (n) *out++ = digits[--n];\n    return out;\n}\nstatic void summary(const char* reason) {\n    char line[1280];\n    char* p = append_text(line, \"SUMMARY reason=\");\n    unsigned i;\n    p = append_text(p, reason);\n    p = append_text(p, \" ms=\");\n    p = append_number(p, GetTickCount64() - load_tick);\n    p = append_text(p, \" seq=\");\n    p = append_number(p, (ULONGLONG)InterlockedCompareExchange64(&sequence, 0, 0));\n    p = append_text(p, \" write_errors=\");\n    p = append_number(p, (ULONGLONG)InterlockedCompareExchange64(&write_errors, 0, 0));\n    for (i = BSX_EVENT_PLUGINS_LOADED; i \u003c= LAST_EVENT; ++i) {\n        if (!event_names[i]) continue;\n        *p++ = ' ';\n        p = append_text(p, event_names[i]);\n        *p++ = '=';\n        p = append_number(p, (ULONGLONG)InterlockedCompareExchange64(&counts[i], 0, 0));\n    }\n    *p++ = '\\n';\n    write_record(line, (DWORD)(p - line));\n}\n\n/* Check the complete range and read via the kernel, so a concurrent unmap after\n * VirtualQuery fails the copy instead of faulting in this plugin. Only one word\n * of equipment is read; neither that vtable nor any actor/item is followed. */\nstatic int guarded_copy(void* to, const void* from, SIZE_T size) {\n    MEMORY_BASIC_INFORMATION mbi;\n    SIZE_T copied = 0;\n    uintptr_t offset;\n    DWORD protection;\n    if (!from || !VirtualQuery(from, &mbi, sizeof mbi) || mbi.State != MEM_COMMIT)\n        return 0;\n    protection = mbi.Protect & 0xff;\n    if ((mbi.Protect & PAGE_GUARD) ||\n        (protection != PAGE_READONLY && protection != PAGE_READWRITE &&\n         protection != PAGE_WRITECOPY && protection != PAGE_EXECUTE_READ &&\n         protection != PAGE_EXECUTE_READWRITE && protection != PAGE_EXECUTE_WRITECOPY))\n        return 0;\n    offset = (uintptr_t)from - (uintptr_t)mbi.BaseAddress;\n    if (offset > mbi.RegionSize || size > mbi.RegionSize - offset) return 0;\n    return ReadProcessMemory(GetCurrentProcess(), from, to, size, &copied) && copied == size;\n}\n\nstatic void vtable_fields(char* out, size_t size, const void* equipment) {\n    uintptr_t actual = 0;\n    const char* result;\n    if (!expected_vtable) result = \"unavailable\";\n    else if (!guarded_copy(&actual, equipment, sizeof actual)) result = \"unreadable\";\n    else result = actual == expected_vtable ? \"match\" : \"mismatch\";\n    snprintf(out, size, \" vtable=0x%llX expected_vtable=0x%llX vtable_check=%s\",\n             (unsigned long long)actual, (unsigned long long)expected_vtable, result);\n}\n\n/* Follows only the documented member chain, each word through guarded_copy. */\nstatic void controlled_fields(char* out, size_t size, const void* payload_actor) {\n    uintptr_t world = 0, manager = 0, actor = 0;\n    const char* result = \"unavailable\";\n    if (world_global) {\n        if (guarded_copy(&world, (const void*)world_global, sizeof world) && world &&\n            guarded_copy(&manager, (const void*)(world + manager_offset), sizeof manager) && manager &&\n            guarded_copy(&actor, (const void*)(manager + actor_offset), sizeof actor) && actor)\n            result = actor == (uintptr_t)payload_actor ? \"same\" : \"different\";\n        else\n            result = \"unreadable\";\n    }\n    snprintf(out, size, \" controlled=0x%llX controlled_check=%s\", (unsigned long long)actor, result);\n}\n\n#include \"world_ready_trace.h\"\n#include \"request_trace.h\"\n#include \"sleep_trace.h\"\n#include \"snapshot_trace.h\"\nstatic ULONGLONG last_frame_seen; /* completion callbacks precede the next FRAME callback */\n\nstatic DWORD WINAPI report_periodically(LPVOID unused) {\n    ULONGLONG last_summary = 0;\n    (void)unused;\n    for (;;) {\n        ULONGLONG ms;\n        Sleep(rt_enabled || st_enabled ? 1000 : 60000);\n        AcquireSRWLockExclusive(&log_lock);\n        ms = GetTickCount64() - load_tick;\n        rt_summary_locked(ms);\n        st_flush_locked();\n        st_summary_locked(ms);\n        if (ms - last_summary >= 60000) { summary(\"periodic\"); last_summary = ms; }\n        ReleaseSRWLockExclusive(&log_lock);\n    }\n}\n\nstatic void on_event(uint32_t event, const void* data, void* user) {\n    union {\n        bsx_frame_event frame;\n        bsx_save_load_event save;\n        bsx_equip_event equip;\n        bsx_save_loaded_event saved;\n        bsx_world_ready_event world;\n        bsx_equipment_applied_event applied;\n        bsx_title_screen_event title;\n        bsx_load_request_event load;\n        bsx_weapon_swap_event swap;\n        bsx_quick_slot_use_event use;\n        bsx_movie_event movie;\n        bsx_battle_state_event battle;\n        bsx_stat_change_event stat;\n        bsx_save_load_after_event save_after;\n        bsx_equip_after_event equip_after;\n        bsx_unequip_after_event unequip_after;\n        bsx_load_request_after_event load_after;\n        bsx_weapon_swap_after_event swap_after;\n        bsx_quick_slot_use_after_event use_after;\n        bsx_movie_after_event movie_after;\n        bsx_battle_state_after_event battle_after;\n        bsx_key_event keyboard;\n        bsx_hit_event hit;\n        bsx_death_event death;\n        bsx_revive_event revive;\n    } payload = {0};\n    static const size_t sizes[] = {\n        0, 0, sizeof(bsx_frame_event), sizeof(bsx_save_load_event), sizeof(bsx_equip_event),\n        sizeof(bsx_equip_event), sizeof(bsx_save_loaded_event),\n        offsetof(bsx_equipment_applied_event, player_flags), offsetof(bsx_equipment_applied_event, player_flags),\n        sizeof(bsx_world_ready_event), sizeof(bsx_title_screen_event), sizeof(bsx_load_request_event),\n        sizeof(bsx_weapon_swap_event), sizeof(bsx_quick_slot_use_event), sizeof(bsx_movie_event),\n        sizeof(bsx_battle_state_event), sizeof(bsx_stat_change_event),\n        sizeof(bsx_save_load_after_event), sizeof(bsx_equip_after_event), sizeof(bsx_unequip_after_event),\n        sizeof(bsx_load_request_after_event), sizeof(bsx_weapon_swap_after_event), sizeof(bsx_quick_slot_use_after_event),\n        sizeof(bsx_movie_after_event), sizeof(bsx_battle_state_after_event),\n        sizeof(bsx_key_event), sizeof(bsx_hit_event), sizeof(bsx_death_event), sizeof(bsx_revive_event)\n    };\n    char fields[1024] = \"\", vtable[160] = \"\", controlled[96] = \"\", line[1536];\n    uint32_t struct_size = 0;\n    uint32_t format_event = event;\n    DWORD tid = GetCurrentThreadId();\n    ULONGLONG ordinal, seq, elapsed;\n    int valid = 1;\n    (void)user;\n    if (event \u003c BSX_EVENT_PLUGINS_LOADED || event > LAST_EVENT || !event_names[event]) return;\n    AcquireSRWLockExclusive(&log_lock);\n    ordinal = (ULONGLONG)InterlockedIncrement64(&counts[event]);\n    seq = (ULONGLONG)InterlockedIncrement64(&sequence);\n    elapsed = GetTickCount64() - load_tick;\n    if (event == BSX_EVENT_FRAME && !main_tid) main_tid = tid;\n    if (event == BSX_EVENT_FRAME) wr_frame_locked(data);\n    if (event == BSX_EVENT_FRAME) rt_frame_locked();\n    if (event == BSX_EVENT_FRAME) st_frame_locked();\n    if (event == BSX_EVENT_WORLD_READY) sn_world_ready_locked();\n    if (event == BSX_EVENT_FRAME) sn_frame_locked();\n    if (st_enabled && (event == BSX_EVENT_SAVE_LOAD || event == BSX_EVENT_TITLE_SCREEN ||\n                       event == BSX_EVENT_LOAD_REQUEST)) InterlockedIncrement64(&st_epoch);\n    if (event == BSX_EVENT_FRAME) {\n        bsx_frame_event frame;\n        if (guarded_copy(&frame, data, sizeof frame) && frame.struct_size >= sizeof frame)\n            last_frame_seen = frame.frame;\n    }\n    if (event == BSX_EVENT_FRAME || e\n// ... truncated at 10240 bytes (see bsx_selftest.c in repo for full file)\n","lang":"c","name":"bsx_selftest.c"}],"id":"bsx_selftest","kind":"native_cpp","lua_api":0,"path":"bsx/examples/bsx_selftest","tier":"native_sdk","title":"BSX Selftest (Diagnostics)","uses":["cdal.lib"]}];
